create temporary table import_summary (wikidata_id text primary key, summary text not null, source text not null);

insert into import_summary (wikidata_id, summary, source) values
  ('Q16258871', 'Millennium Soldier: Expendable, known in Japan as Seitai Heiki Expendable, and in North America as just Expendable, is a run and gun video game that was released by Rage Software for Microsoft Windows in 1999. It was later ported to the Dreamcast and PlayStation consoles. A remake of the game, entitled Expendable: Rearmed, was released for Android in 2012. It is in the format of a modern arcade game. The player starts with 7 "credits" and can continue until running out of credits. A second player can join the game at any time by pressing start.', 'https://en.wikipedia.org/wiki/Millennium_Soldier:_Expendable'),
  ('Q10910509', 'Parodius is a series of cute ''em ups developed and published by Konami. The games are tongue-in-cheek parodies of Gradius, and also feature characters from many other Konami franchises.', 'https://en.wikipedia.org/wiki/Parodius'),
  ('Q104535513', 'Interplay Sports Baseball Edition 2000 is a baseball video game developed and published by Interplay Entertainment for PlayStation (as Interplay Sports Baseball 2000) and Microsoft Windows in 1999. This is the first game released after the developer changed its name from VR Sports to Interplay Sports.', 'https://en.wikipedia.org/wiki/Interplay_Sports_Baseball_Edition_2000'),
  ('Q6103733', 'J-League Jikkyō Winning Eleven 2001 (known as World Soccer: Winning Eleven 4) is a sports video game developed by Konami for the PlayStation exclusively in Japan in June 2001. It is an addition to the Winning Eleven J-League series, and the successor to J-League Winning Eleven 2000. The game only features club teams (no national teams) and teams from both tiers of the J. League totalling 28 teams. The game also features seven unlockable European teams (Real Madrid, Barcelona, Manchester United, Arsenal, Juventus, Roma, and Milan). The game uses the Winning Eleven 2000 engine.', 'https://en.wikipedia.org/wiki/J.League_Jikky%C5%8D_Winning_Eleven_2001'),
  ('Q56350490', 'Rock & Roll Racing 2: Red Asphalt is a 1997 racing game developed and published by Interplay for the PlayStation. Rock & Roll Racing 2: Red Asphalt is the sequel to Rock n'' Roll Racing. In North America it was stripped of its association with the series and retitled simply Red Asphalt.', 'https://en.wikipedia.org/wiki/Rock_%26_Roll_Racing_2:_Red_Asphalt'),
  ('Q3617718', 'Anna Kournikova''s Smash Court Tennis, known in Japan as Smash Court 2, is a tennis video game developed by Namco for the PlayStation. It is the second title in Namco''s Smash Court series of games. The game was released in Japan in November 1998 and was later released in Europe in 1999, featuring the likeness of professional tennis player Anna Kournikova.', 'https://en.wikipedia.org/wiki/Anna_Kournikova%27s_Smash_Court_Tennis'),
  ('Q63165269', 'Ys III: Wanderers from Ys is a 1989 action role-playing game developed by Nihon Falcom. It is the third game in the Ys series.

Ys III was initially released for the PC-8801 and PC-9801 in 1989 under the title Wanderers from Ys, and versions for the MSX2 and X68000 soon followed. In 1991, a number of console ports were produced: versions for the TurboGrafx-CD, Famicom, Super NES, and Sega Genesis; all of them aside from the Famicom version were released internationally. A remaster for the PlayStation 2 was released by Taito in 2005. A remake Ys: The Oath in Felghana, was released the same year for Windows.', 'https://en.wikipedia.org/wiki/Ys_III:_Wanderers_from_Ys'),
  ('Q11287908', 'Ys IV: Mask of the Sun is a 1993 action role-playing game developed by Tonkin House for the Super Famicom. It is the fourth game in the Ys video game series.

Mask of the Sun was one of two games released under the title of Ys IV, the other being Hudson Soft''s Ys IV: The Dawn of Ys for the PC Engine CD-ROM. The two games share the same basic story, but many changes were made in the Hudson-produced Dawn of Ys. Of the two, Mask of the Sun was the official Ys IV storyline before the release of Ys: Memories of Celceta.', 'https://en.wikipedia.org/wiki/Ys_IV:_Mask_of_the_Sun'),
  ('Q10381521', 'The King of Fighters ''94 Re-Bout is a 2D fighting game developed by SNK Playmore was released exclusively in Japan for the PlayStation 2 on December 28, 2004. The game is a remake of the first installment of The King of Fighters series, The King of Fighters ''94. Just like the original game, Re-Bout features 24 playable characters taken from multiple SNK IPs as well as multiple original characters that fight each other in the titular worldwide tournament host by the game''s boss Rugal Bernstein who becomes playable alongside the cameo character Saisyu Kusanagi who appeared in a cutscene from the Neo Geo game.', 'https://en.wikipedia.org/wiki/The_King_of_Fighters_%2794_Re-Bout'),
  ('Q602932', 'HoiHoi-san, full title Ichigeki Sacchu!! HoiHoi-san is a manga by Kunihiko Tanaka that spawned a PlayStation 2 game and a ten-minute OVA (sold with the first printing of manga tankōbon).

In the year 20XX, insects have become immune to all pesticides. To combat the rising plague of cockroaches and other household pests, the tiny, doll-like extermination gynoids known as "Hoihoi-san" were created. They can hunt down insects and kill them with such miniaturized weapons as minuscule machine guns and tiny combat knives. They can also (and at the same time) be treated as dolls, by dressing them in costumes and buying accessories for them. The main robot of the anime wears a maid uniform and rabbit ears as accessories.', 'https://en.wikipedia.org/wiki/Ichigeki_Sacchu!!_HoiHoi-san'),
  ('Q588754', 'Nanatsuiro Drops is a Japanese adult visual novel developed by UNiSONSHIFT and released on April 21, 2006 for Windows. The game was later ported to the PlayStation 2 and Nintendo DS. A light novel, written by Tamaki Ichikawa and illustrated by Noizi Ito, was published by Enterbrain in June 2006. Two manga adaptations were published by MediaWorks and later ASCII Media Works. A 12-episode anime produced by Studio Barcelona aired between July and September 2007.', 'https://en.wikipedia.org/wiki/Nanatsuiro_Drops'),
  ('Q8056320', 'Yoshitsune Eiyūden: The Story of Hero Yoshitsune is a hack and slash video game developed and published by FromSoftware for the PlayStation 2, based on the legendary samurai Minamoto no Yoshitsune.

The game was re-released with additional content (such as characters and levels) and two-player cooperative or competitive modes. This new version was titled Yoshitsune Eiyūden Shura (shura meaning "mayhem" or "carnage").', 'https://en.wikipedia.org/wiki/Yoshitsune_Eiy%C5%ABden:_The_Story_of_Hero_Yoshitsune'),
  ('Q56707738', 'Ys V: Lost Kefin, Kingdom of Sand is a 1995 action role-playing game developed by Nihon Falcom. It is the fifth game in the Ys series of video games and was released for the Super Famicom in December 1995. A remake by Access and Taito was released for the PlayStation 2 in 2006.', 'https://en.wikipedia.org/wiki/Ys_V:_Lost_Kefin,_Kingdom_of_Sand'),
  ('Q1571488', 'Déjà Vu is a 1985 point-and-click adventure game developed by ICOM Simulations for the Macintosh as the first entry in the MacVenture series. Set in 1940s Chicago, the story follows detective Ace Harding as he attempts to clear his name and restore his memories after being framed for a murder. It is themed after various hardboiled detective novels and films.

Déjà Vu was first released in October 1985. It was later ported to several other platforms, including the Amiga, MS-DOS, and the Nintendo Entertainment System. Initially, the game featured black and white graphics; later releases introduced color. A sequel, Deja Vu II: Lost in Las Vegas, was released in 1988.', 'https://en.wikipedia.org/wiki/D%C3%A9j%C3%A0_Vu_(video_game)'),
  ('Q1567550', 'Joust is a 1982 action game developed and published by Williams Electronics for arcades. Players assume the role of knights armed with lances and mounted on large birds (an ostrich for Player 1 and a stork for Player 2). They progress through levels, which consist of a single screen filled with floating platforms, by defeating enemy knights riding buzzards and other opponents.

Using the computer hardware from the company''s earlier arcade game, Defender, John Newcomer led the development team: Bill Pfutzenreuter, Janice Woldenberg-Miller (née Hendricks), Python Anghelo, Tim Murphy, and John Kotlarik. Newcomer aimed to create a flying game, with cooperative two-player gameplay, while avoiding the overdone space theme. After deciding to use birds as characters, he forwent the standard eight-direction joystick control scheme and devised collisions as the means of combat.', 'https://en.wikipedia.org/wiki/Joust_(video_game)'),
  ('Q1535509', 'Rampart is a 1990 strategy video game developed and published by Atari Games for North American and European arcades, with distribution in Japan handled by Namco. Presented from a top-down perspective, the game tasks the player with defending their territory from enemy invaders. The gameplay alternates between a building phase, where the player constructs walls around vulnerable castles, and a combat phase, in which cannons are used in an attempt to drive back hostile forces. A trackball is used to control the game.

It had a limited US release in October 1990, followed by a wide release in February 1991. Rampart is a precursor to the tower defense genre, popularized in the 2000s.', 'https://en.wikipedia.org/wiki/Rampart_(video_game)'),
  ('Q1565343', 'Q*bert is a 1982 action video game developed and published by Gottlieb for arcades. It is a 2D action game with puzzle elements that uses isometric graphics to create a pseudo-3D effect. The objective of each level in the game is to change every cube in a pyramid to a target color by letting Q*bert, the on-screen character, hop on top of the cube while avoiding obstacles and enemies. Players use a joystick to control the character.

The game was conceived by Warren Davis and Jeff Lee, the latter of whom designed the titular protagonist and original concept, which was further developed and implemented by Davis. Q*bert was developed under the project name Cubes.', 'https://en.wikipedia.org/wiki/Q*bert'),
  ('Q1648866', 'The Bugs Bunny Birthday Blowout, known in Japan and on the title screen as Happy Birthday Bugs and in Europe as The Bugs Bunny Blowout, is a platform video game developed and published by Kemco for the Nintendo Entertainment System in 1990.', 'https://en.wikipedia.org/wiki/The_Bugs_Bunny_Birthday_Blowout'),
  ('Q1618401', 'King''s Quest V: Absence Makes the Heart Go Yonder! is an adventure game developed by Sierra On-Line. It was published originally for PCs and home computers in 1990 and ported to other computers in 1991 and the Nintendo Entertainment System in 1992. The fifth entry in the King''s Quest series, the game follows King Graham of Daventry as he journeys through the pseudo-medieval fairy tale-inspired realm of Serenia, on a quest to rescue his family from the wizard Mordack. It is presented as an interconnected set of locations, or flip-screens, with a pseudo-3D art style. The player interacts with locations and items using an icon-based point-and-click interface, a first for the series, and must avoid numerous hazards and obstacles in their quest.', 'https://en.wikipedia.org/wiki/King%27s_Quest_V'),
  ('Q1584331', 'Adventure Island II is a 1991 platform game developed by Now Production and published by Hudson Soft for the Nintendo Entertainment System. It is the sequel to Adventure Island and the second game in the series for the NES. While the first game was an adaptation of Sega''s Wonder Boy, Adventure Island II is an original work, as were most of the subsequent Adventure Island games. A portable version was also released for the Game Boy in 1992, titled Takahashi Meijin no Bouken Jima II or Adventure Island outside of Japan.', 'https://en.wikipedia.org/wiki/Adventure_Island_II'),
  ('Q1630875', 'Track & Field (also known as Hyper Olympic in Japan and Europe) is a 1983 sports video game developed and published by Konami for arcades. The Japanese release featured an official license for the 1984 Summer Olympics. In Europe, the game was initially released under the Japanese title Hyper Olympic in 1983, before being re-released under the US title Track & Field in early 1984. Centuri released the game in North America.

Players compete in a series of events, most involving alternately pressing two buttons as quickly as possible to make the onscreen character run faster. The game uses a horizontal side-scrolling format, displaying one or two tracks at a time, a large scoreboard that shows world records and current attempts, and a packed audience in the background.', 'https://en.wikipedia.org/wiki/Track_%26_Field_(video_game)'),
  ('Q1591807', 'Top Management is a multiplatform business simulation video game that turns the player into a highly respected corporate title holder.', 'https://en.wikipedia.org/wiki/Top_Management_(video_game)'),
  ('Q1807428', 'Monster in My Pocket is a media franchise developed by American company Morrison Entertainment Group, headed by Joe Morrison and John Weems, two former senior executives at Mattel.

The focus is on monsters and fantastical and legendary creatures from religion, mythology, folklore, fairy tales, literary fantasy, science fiction, cryptids and other anomalous phenomena. Monster in My Pocket produced trading cards, comic books, books, toys, a board game, a video game, and an animated special, along with music, clothing, kites, stickers, and various other items.', 'https://en.wikipedia.org/wiki/Monster_in_My_Pocket'),
  ('Q2211843', 'All-Pro Basketball, known as Zenbei!! Pro Basketball in Japan, is a basketball video-game developed by Aicom and published by Vic Tokai for the Nintendo Entertainment System. It is played using two teams of five players on a full-length basketball court, and a roster of eight different fictional teams.', 'https://en.wikipedia.org/wiki/All-Pro_Basketball'),
  ('Q1777574', 'Ufouria: The Saga is a 1991 action-adventure video game developed and published in Japan and Europe by Sunsoft for the Nintendo Entertainment System. It is the first entry in the Hebereke franchise, where almost every installment in the series features a completely different playstyle. Controlling a humanoid-looking character called Bop-Louie through an interconnected world, the game focuses on exploration and searching for items and power-ups in vein of Metroid and Blaster Master, fighting bosses and minibosses. During gameplay, the player locates the main character''s three friends, each of which becomes a playable character and have unique skills that allow the player to reach previously inaccessible areas.', 'https://en.wikipedia.org/wiki/Ufouria:_The_Saga'),
  ('Q1804014', 'Rainbow Islands: The Story of Bubble Bobble 2, better known as simply Rainbow Islands, is a 1987 platform video game developed and published by Taito for Japanese arcades. It is the sequel to 1986''s Bubble Bobble, and the second of four arcade games in the Bubble Bobble series (followed by Bubble Symphony and Bubble Memories, but itself has two direct sequels: Parasol Stars and Bubble Bobble Part 2). The game was ported to home computers and home video game consoles.', 'https://en.wikipedia.org/wiki/Rainbow_Islands'),
  ('Q2188282', 'R.C. Pro-Am is a racing game developed by Rare and published by Nintendo for the Nintendo Entertainment System. It was released in North America in February 1988, and then in Europe on 15 April. Presented in an overhead isometric perspective, a single player races a radio-controlled car around a series of tracks in vehicular combat. Each track qualifies its top three racers for the next track. Collectible power-up items improve performance, hazards include rain puddles and oil slicks, and missiles and bombs can temporarily disable opponents. Originally titled Pro Am Racing, it was ported to the Sega Genesis in 1992 as Championship Pro-Am, an enhanced remake with enhanced graphics and additional features. R.C. Pro-Am spawned two sequels: Super R.C. Pro-Am in 1991, and R.C. Pro-Am II in 1992.', 'https://en.wikipedia.org/wiki/R.C._Pro-Am'),
  ('Q1711616', 'Wai Wai World 2: SOS!! Parsley Jō is a 1991 platform game released by Konami for the Famicom only in Japan. It is a sequel to Konami Wai Wai World, and stars various Konami characters.', 'https://en.wikipedia.org/wiki/Wai_Wai_World_2:_SOS!!_Parsley_J%C5%8D'),
  ('Q1766193', 'Star Trek: 25th Anniversary is a 1992 adventure video game developed by Interplay and published by Ultra Games for the Nintendo Entertainment System. A different version was made with the same name (not a port) on the Game Boy.', 'https://en.wikipedia.org/wiki/Star_Trek:_25th_Anniversary_(NES_video_game)'),
  ('Q2182703', 'Pin Bot (stylized as Pin*Bot) is a pinball video game developed by Rare and published by Nintendo for the Nintendo Entertainment System. It was released in North America in April 1990. It is a conversion of the pinball machine by the same name (developed and manufactured by Williams in 1986). The NES version of the game accurately reproduces some of the game-play and aesthetics of the pinball machine, while introducing new features and added challenges.', 'https://en.wikipedia.org/wiki/Pin_Bot_(video_game)'),
  ('Q1790249', 'Winter Games is a 1985 sports video game developed by Epyx and released in Europe by U.S. Gold. A snow-and-ice themed follow-up to the highly successful Summer Games, Winter Games was released in 1985 for the Commodore 64 and later ported to several popular home computers and video game consoles of the 1980s.

Based on sports featured in the Winter Olympic Games, the game was presented as a virtual multi-sport carnival called the "Epyx Winter Games" (there was no official IOC licensing in place) with up to 8 players each choosing a country to represent, and then taking turns competing in various events to try for a medal.', 'https://en.wikipedia.org/wiki/Winter_Games'),
  ('Q1707792', 'Space Harrier is a rail shooter developed by Sega and released in 1985 as an arcade video game. The player navigates surreal landscapes while defeating enemies as a jet-propelled human character. Designed by Yu Suzuki, it was conceived as a realistic military-themed combat flight simulation game, but technical and memory restrictions resulted in Suzuki redesigning it around a fantasy setting. The arcade game is controlled by an analog flight stick while the deluxe arcade cabinet is a cockpit-style linear actuator motion simulator cabinet that pitches and rolls during play, for which it is referred as a taikan or "body sensation" arcade game in Japan.', 'https://en.wikipedia.org/wiki/Space_Harrier'),
  ('Q2204970', 'Racket Attack is a 1988 professional tennis Nintendo Entertainment System game. It was released in Japan as Moero!! Pro Tennis, which is the second game of the Moero!! sports series. The gameplay takes place in a ¼ overhead view tennis court with the score being present at all times and an audience of spectators being shown in multiple colors (white, pink, and red). The North American version features an endorsement from Wilson Sporting Goods. The game was released fairly late in the NES life cycle in Europe and the PAL regions, as available sources show, due to the lengthy process of distributing and the fact that Nintendo have still just started to get into the region by the time of the Japanese release of the game.', 'https://en.wikipedia.org/wiki/Racket_Attack'),
  ('Q1658492', 'Ninja Gaiden II: The Dark Sword of Chaos, known in Europe as Shadow Warriors II: The Dark Sword of Chaos, is a 1990 platform game developed and published by Tecmo for the Nintendo Entertainment System. It is the second instalment in the Ninja Gaiden trilogy for the NES and was released in North America and Japan in 1990, and in Europe in 1994. An arcade version was released by Nintendo for their PlayChoice-10 system in 1990.

The events in Ninja Gaiden II take place one year after the events in the first Ninja Gaiden game. The story involves an evil emperor named Ashtar who, after hearing of Jaquio''s defeat, devises a plan to take over the world and engulf it in darkness through an evil sword called the Dark Sword of Chaos. A U.S. Army agent named Robert T. Sturgeon recruits the game''s protagonist Ryu Hayabusa and tells him that he is the only person who can stop Ashtar.', 'https://en.wikipedia.org/wiki/Ninja_Gaiden_II:_The_Dark_Sword_of_Chaos'),
  ('Q1835554', 'Fester''s Quest (also known as Uncle Fester''s Quest or The Addams Family: Uncle Fester''s Quest) is a video game for the Nintendo Entertainment System based on the 1960s television series The Addams Family. It was released in 1989 in North America and 1990 in Europe.', 'https://en.wikipedia.org/wiki/Fester%27s_Quest'),
  ('Q1837967', 'The Simpsons: Bart vs. the Space Mutants is a 1991 platform video game based on the animated television series The Simpsons. It was originally developed by Imagineering and published by Acclaim Entertainment for the Nintendo Entertainment System, and was later released for the Amiga, Amstrad CPC, Atari ST, Commodore 64, and ZX Spectrum by Ocean Software, and in 1992 for the Sega Genesis, Master System, and Game Gear; all ports were developed by Arc Developments. In the game, the player controls Bart Simpson through five levels as he tries to ruin the aliens'' plan to take over the world, collecting specific items and avoiding enemies.', 'https://en.wikipedia.org/wiki/The_Simpsons:_Bart_vs._the_Space_Mutants'),
  ('Q1668079', 'Smash TV is an arcade video game developed and published by Williams Electronics in 1990. It was designed by Eugene Jarvis and programmed by Mark Turmell with similar twin-stick shooter gameplay to Jarvis'' 1982 game Robotron: 2084. Versions released for the Super Nintendo Entertainment System, Sega Genesis, Master System, and Game Gear were titled Super Smash TV.', 'https://en.wikipedia.org/wiki/Smash_TV'),
  ('Q1759528', 'Snake Rattle ''n'' Roll is a platform video game developed by Rare and published by Nintendo for the Nintendo Entertainment System. It was originally released in North America in July 1990 and in Europe on 27 March 1991. The game features two snakes, Rattle and Roll, as they make their way through eleven 3D isometric levels. A port to the Mega Drive with an extra level was released by Sega in June 1993 exclusively in Europe. Snake Rattle ''n'' Roll was developed by Rare members Tim Stamper and Mark Betteridge. The music was composed by David Wise and was inspired by "Shake, Rattle and Roll" and other 1950s-era songs.', 'https://en.wikipedia.org/wiki/Snake_Rattle_%27n%27_Roll'),
  ('Q1748800', 'Hogan''s Alley is a light gun shooter video game developed and published by Nintendo. It was released for the Family Computer in 1984 and then the arcade Nintendo VS. System and Nintendo Entertainment System in 1985. It was one of the first hit video games to use a light gun as an input device, along with Nintendo''s Duck Hunt (1984). The game presents players with cardboard cutouts of gangsters and innocent civilians; the player must shoot only the former. It was a major arcade hit in the United States and Europe.

The game is named after and based on Hogan''s Alley, a shooting range for law enforcement training somewhat similar in design to the city block rounds, first constructed at Camp Perry in Port Clinton, Ohio in the 1920s and later redesigned for use at the FBI Academy in Quantico, Virginia in 1954. Three years after the release of Hogan''s Alley, a third rendition of the Hogan''s Alley range was constructed at the FBI Academy, resembling a small town, that is still used today.', 'https://en.wikipedia.org/wiki/Hogan%27s_Alley_(video_game)'),
  ('Q2223652', 'R.C. Pro-Am II is a racing video game developed by Rare and released by Tradewest for the Nintendo Entertainment System in December 1992. The game is the sequel to the 1988 R.C. Pro-Am and features similar gameplay with a wider variety of tracks, currency-based vehicle and weapon upgrades, and bonus stages. In R.C. Pro-Am II, four players, either human or artificial intelligence, race on a series of tracks to finish first while avoiding obstacles and hazards. The winner receives race points and money. The game features a multiplayer mode in which up to four human players can compete against each other simultaneously.', 'https://en.wikipedia.org/wiki/R.C._Pro-Am_II'),
  ('Q2231936', 'Silent Assault, also known as Raid, is an unlicensed game created for the NES by Joy Van and published by Color Dreams. Players control the only human who was unaffected by an alien power, as the Earth''s military forces are under control from the deadly alien force.', 'https://en.wikipedia.org/wiki/Silent_Assault'),
  ('Q2219421', 'Top Gun: The Second Mission, released in Japan as Top Gun: Dual Fighters, is the video game sequel to Top Gun, also produced by Konami for the Nintendo Entertainment System. It was released in Japan on December 15, 1989, in North America in January 1990, and in Europe and Australia on October 24, 1991.', 'https://en.wikipedia.org/wiki/Top_Gun:_The_Second_Mission'),
  ('Q2212127', 'Rad Racer, known as Highway Star in Japan, is a racing video game developed and published by Square for the Nintendo Entertainment System (NES) in 1987. In this game, players drive a Ferrari 328 or a generic Formula One racing machine through a racecourse. The game was released in North America and Europe months after its debut. The title became well known for being one of two titles from Square that made use of stereoscopic 3D, which was made possible by wearing a pair of anaglyph glasses. Square president Masafumi Miyamoto initially conceived the game as an opportunity for developer Nasir Gebelli to demonstrate his 3D programming skills. Gebelli developed, and often drew by hand, the graphics for the game''s 3D mode.', 'https://en.wikipedia.org/wiki/Rad_Racer'),
  ('Q2238794', 'Metro-Cross is a 1985 platform video game developed and published by Namco for arcades. It was released in Japan in May 1985 and in North America by Kitkorp in November 1985. It was later ported to the Amstrad CPC, Atari ST, Commodore 64, Family Computer, and ZX Spectrum.', 'https://en.wikipedia.org/wiki/Metro-Cross'),
  ('Q2240236', 'Ultima III: Exodus (originally released as Exodus: Ultima III) is the third game in the series of Ultima role-playing video games. Exodus is also the name of the game''s principal antagonist. It is the final installment in the "Age of Darkness" trilogy. Released in 1983, it was the first Ultima game published by Origin Systems. Originally developed for the Apple II, Exodus was eventually ported to 13 other platforms, including a NES/Famicom remake.

Ultima III revolves around Exodus, the spawn of Mondain and Minax (from Ultima I and Ultima II, respectively), threatening the world of Sosaria. The player character travels to Sosaria to defeat Exodus and restore the world to peace. Ultima III hosts further advances in graphics, particularly in animation, adds a musical score, and increases the player''s options in gameplay with a larger party and more interactivity with the game world.', 'https://en.wikipedia.org/wiki/Ultima_III:_Exodus'),
  ('Q2260930', 'Baseball Stars 2 is a 1992 baseball video game developed and published by SNK for the Neo Geo arcade and home platforms. A console version was released for the NES by Romstar the same year.', 'https://en.wikipedia.org/wiki/Baseball_Stars_2'),
  ('Q2252902', 'StarTropics is a 1990 action-adventure video game developed and published by Nintendo for the Nintendo Entertainment System. Unlike most of Nintendo''s games, it was never released in Japan, and was released only in North America and Europe. The story follows teenager Mike Jones as he embarks on a quest to rescue his uncle. Gameplay involves exploring settlements and navigating dungeons to progress.

The game was produced, written and directed by Genyo Takeda of Nintendo Integrated Research & Development, who also developed the Punch-Out!! series. StarTropics was followed by a sequel, Zoda''s Revenge: StarTropics II, which was released in 1994.', 'https://en.wikipedia.org/wiki/StarTropics'),
  ('Q2264301', 'Donkey Kong Jr. is a 1982 platform game developed and published by Nintendo for arcades. It is the sequel to 1981''s Donkey Kong, but with the roles reversed compared to its predecessor: Mario is now the villain and Donkey Kong Jr. is trying to save his kidnapped father. After its initial release in arcades, the game was ported to a variety of home consoles, including the Famicom/Nintendo Entertainment System (for which the game was released as a launch title in Japan). The game''s title is written as Donkey Kong Junior in the North American arcade version and various conversions to non-Nintendo systems.', 'https://en.wikipedia.org/wiki/Donkey_Kong_Jr.'),
  ('Q2255493', 'The Mutant Virus: Crisis in a Computer World is an action video game released by ASC Games for the NES in April 1992.', 'https://en.wikipedia.org/wiki/The_Mutant_Virus:_Crisis_in_a_Computer_World'),
  ('Q2278537', 'Captain Tsubasa Volume II: Super Striker (キャプテン翼 II スーパーストライカー, Kyaputen Tsubasa II: Sūpā Sutoraikā) is a video game released by Tecmo on the Family Computer in 1990. A sequel to Captain Tsubasa, it features slightly upscaled graphics and improved field radar. It was the last Tsubasa game to be released on the Family Computer, since the series transitioned to the Super Famicom two years later.', 'https://en.wikipedia.org/wiki/Captain_Tsubasa_Vol._II:_Super_Striker'),
  ('Q2292340', 'Chack''n Pop is a 1984 platform video game developed and published by Taito for arcades. It was originally released in Japan in April 1984. It is considered to be a spiritual predecessor of Bubble Bobble due to their shared characters and similar game structure. Home ports were released for the SG-1000, MSX, Family Computer, Sharp X1, NEC PC-6001 and NEC PC-8801.', 'https://en.wikipedia.org/wiki/Chack%27n_Pop'),
  ('Q2300687', 'Toki is a run and gun platform game released in arcades in Japan in 1989 by TAD Corporation. It was published in North America by Fabtek. Designed by Akira Sakuma, the game has tongue-in-cheek humor mixed with the action. The player controls an enchanted ape who must battle hordes of jungle monsters with energy balls from his mouth. The ultimate goal is to destroy the evil wizard who cast a spell on the title protagonist; thereby transforming him from an ape back into a human, and rescuing the kidnapped princess. The game was ported to several video game consoles and home computers.', 'https://en.wikipedia.org/wiki/Toki_(video_game)'),
  ('Q2281747', 'Anticipation is a video board game developed by Rare and released by Nintendo for the Nintendo Entertainment System (NES) in 1988. It is playable in either single-player or multiplayer mode, with up to four players competing against each other and/or computer-controlled opponents.', 'https://en.wikipedia.org/wiki/Anticipation_(video_game)'),
  ('Q2302403', 'Tag Team Wrestling, known as The Big Pro Wrestling! in Japan, is a 1983 wrestling video game developed by Technōs Japan and published by Data East for arcades. It was later ported to the Nintendo Entertainment System, Commodore 64, IBM PC and Apple II.

Hamster Corporation released the game as part of their Arcade Archives series for the Nintendo Switch and PlayStation 4, as well as their Arcade Archives 2 series for the Nintendo Switch 2, PlayStation 5 and Xbox Series X/S in May 2026.', 'https://en.wikipedia.org/wiki/Tag_Team_Wrestling'),
  ('Q2303119', 'Popeye is a 1982 platform game developed and published by Nintendo for arcades. It is based on the comic strip of the same name created by E. C. Segar and licensed from King Features Syndicate. Some sources claim that Ikegami Tsushinki did programming work on the game. As Popeye, the player must collect objects thrown by Olive Oyl from the top of the screen while being chased by Brutus. Popeye can punch bottles thrown at him but can only hurt Brutus after eating the one can of spinach present in each level. Unlike Nintendo''s earlier game Donkey Kong (1981), there is no jump button.

The game was licensed by Atari, Inc. for exclusive release in the United Kingdom and Ireland in an Atari-designed cabinet. Nintendo ported the game to the Famicom, and Parker Brothers published versions for other home systems.', 'https://en.wikipedia.org/wiki/Popeye_(video_game)'),
  ('Q2306270', 'Hillsfar is a role-playing video game for MS-DOS compatible operating systems, Amiga, Atari ST, and Commodore 64. It was developed by Westwood Associates and published by Strategic Simulations in 1989. It combines real-time action with randomly generated quests and includes elements of the Advanced Dungeons & Dragons fantasy role-playing game. A port to the Nintendo Entertainment System was released in 1993. Hillsfar received mixed reviews from critics.', 'https://en.wikipedia.org/wiki/Hillsfar'),
  ('Q907618', 'Ys III: Wanderers from Ys is a 1989 action role-playing game developed by Nihon Falcom. It is the third game in the Ys series.

Ys III was initially released for the PC-8801 and PC-9801 in 1989 under the title Wanderers from Ys, and versions for the MSX2 and X68000 soon followed. In 1991, a number of console ports were produced: versions for the TurboGrafx-CD, Famicom, Super NES, and Sega Genesis; all of them aside from the Famicom version were released internationally. A remaster for the PlayStation 2 was released by Taito in 2005. A remake Ys: The Oath in Felghana, was released the same year for Windows.', 'https://en.wikipedia.org/wiki/Ys_III:_Wanderers_from_Ys'),
  ('Q869558', 'R.O.B. (Robotic Operating Buddy) is a toy robot accessory for the Nintendo Entertainment System (NES). He was a key to the NES''s launch in October 1985, as a redesign of the Family Computer Robot which had been launched in July 1985 in Japan for Famicom and was available as part of the Deluxe Set until 1988. During its short lifespan, only two games in the Robot Series were released: Gyromite and Stack-Up.

Following the North American video game crash of 1983, Nintendo courted a fearful retail market by rebranding its Japanese Famicom video game console as the Nintendo Entertainment System—a new platform focused on R.O.B. to further reclassify the system as a uniquely sophisticated toy experience instead of simply as a video game console. Computer Entertainer called R.O.B. "the world''s only interactive robot".', 'https://en.wikipedia.org/wiki/R.O.B.'),
  ('Q2312762', 'Dragon Quest II: Luminaries of the Legendary Line, titled Dragon Warrior II when initially localized to North America, is a 1987 role-playing video game developed by Chunsoft and published by Enix for the Nintendo Entertainment System as a part of the Dragon Quest series. Enix''s U.S. subsidiary published the American release, Dragon Warrior II, for the Nintendo Entertainment System in 1990. Dragon Quest II is set one hundred years after the events of the first game.

The game''s story centers on the prince of Midenhall, who is ordered to stop an evil wizard named Hargon after Hargon destroys Moonbrooke Castle. On his adventure, he is accompanied by his two cousins, the prince of Cannock and the princess of Moonbrooke (and the princess of Cannock in Dragon Quest I & II HD-2D Remake). Dragon Quest II expands on the first game by having a larger party, more areas to explore, multiple heroes and enemies in a battle, and a sailing ship. The game''s successor, Dragon Quest III, follows the ancestor of the main characters, the legendary hero Erdrick; and the three games are collectively called "The Erdrick Trilogy".', 'https://en.wikipedia.org/wiki/Dragon_Quest_II'),
  ('Q907744', 'Street Fighter 2010: The Final Fight is a 1990 action-platform video game developed and published by Capcom for the Nintendo Entertainment System. It was marketed as a science fiction-themed spin-off of the 1987 arcade game Street Fighter. Its English localization changed the name and backstory of the main character to imply that he is Ken from Street Fighter, whereas the protagonist in the original Japanese version is an unrelated character named Kevin. Street Fighter 2010 is a different genre from the traditional Street Fighter games, which are one-on-one fighting games.', 'https://en.wikipedia.org/wiki/Street_Fighter_2010:_The_Final_Fight'),
  ('Q917503', 'Gyruss is a 1983 tube shooter video game developed and published by Konami for Japanese arcades. It was initially licensed to Centuri in North America for dedicated machines before Konami released their own self-distributed conversion kits for the game. Parker Brothers released ports for the Atari 2600, Atari 5200, Atari 8-bit computers, ColecoVision and Commodore 64 in 1984. An enhanced version for the Famicom Disk System was released in 1988, followed by the Nintendo Entertainment System in 1989.

The gameplay is similar to that of Galaga, albeit in a tube shooter format, with the player''s ship able to move around the perimeter of an implicit circle. Stars come into view at the center of the screen and fly outward, giving the impression of the player''s ship moving through space. Gyruss is the second and last game Yoshiki Okamoto designed for Konami, after Time Pilot. Due to pay disputes, he was fired after the release of this game, and he soon joined Capcom, where he designed 1942 and produced Street Fighter II.', 'https://en.wikipedia.org/wiki/Gyruss'),
  ('Q911802', 'Parodius! From Myth to Laughter, released in Japan as Parodius Da! Shinwa kara Owarai e and outside Japan as Parodius (from "Parody Gradius"), is a shoot ''em up arcade video game and the second title in the Parodius series produced by Konami. The European SNES, Sega Saturn and PlayStation versions are also known as Parodius: Non-Sense Fantasy. The gameplay is stylistically very similar to the Gradius series, but the graphics and music are intentionally absurd.

As a result of its localised title, From Myth to Laughter is often mistaken as the original game of the series. The lesser known original game, Parodius: The Octopus Saves the Earth, was released for the MSX computer in Japan.', 'https://en.wikipedia.org/wiki/Parodius_(1990_video_game)'),
  ('Q81288', 'Dragon Quest III: The Seeds of Salvation, titled Dragon Warrior III when initially localized to North America, is a 1988 role-playing video game developed by Chunsoft and published by Enix. It is the third installment in the Dragon Quest series and was first released for the Family Computer (Famicom) in Japan and later for the Nintendo Entertainment System (NES) in North America. The game saw an enhanced remake for the Super Famicom (the Japanese release of the Super NES) in 1996 and the Game Boy Color in 2001, and a port to mobile phones and the Wii in 2009 and 2011. A version of the game for Android and iOS was released in Japan on September 25, 2014, and worldwide as Dragon Quest III: The Seeds of Salvation on December 4, 2014. It was the first time the game was given an official English subtitle. Later in 2021, another remake of the game titled Dragon Quest III HD-2D Remake, based on the graphical style introduced with Octopath Traveler (2018), was announced to coincide with the franchise''s 35th anniversary. The remake was released worldwide on November 14th, 2024 for Nintendo Switch, PlayStation 5, Windows, and Xbox Series consoles.', 'https://en.wikipedia.org/wiki/Dragon_Quest_III'),
  ('Q912286', 'NES Open Tournament Golf, known in Japan as Mario Open Golf, is a 1991 sports video game developed by HAL Laboratory and Nintendo R&D2 and published by Nintendo for the Nintendo Entertainment System. It is the fourth golf game to feature Mario as a player character, and the first installment of the Mario Golf series. Players control either Mario or Luigi as they play rounds of golf on international courses.

The game incorporates various elements of its gameplay from its predecessors Family Computer Golf: Japan Course and Family Computer Golf: U.S. Course, which were exclusively released in Japan for the Famicom Disk System in 1987. Players take their shots from a third-person perspective, while putting is done from a top-down viewpoint.', 'https://en.wikipedia.org/wiki/NES_Open_Tournament_Golf'),
  ('Q2318803', 'Bases Loaded II: Second Season, known in Japan as Moero!! Pro Yakyū ''88 Kettei Ban, is a baseball video game developed by Tose and released by Jaleco for the Nintendo Entertainment System in 1988 in Japan, and in 1990 in North America. It is the sequel to Bases Loaded and is later followed by Bases Loaded 3. The game is the second installment in the Bases Loaded series. The game was novelized by Peter Lerangis, as part of the Worlds of Power series published by Scholastic Books.', 'https://en.wikipedia.org/wiki/Bases_Loaded_II:_Second_Season'),
  ('Q2323709', 'EarthBound Beginnings, originally released in Japan as Mother, is a 1989 role-playing video game developed by Ape Inc. and Nintendo and published by Nintendo for the Family Computer. It is the first entry in the Mother series and was first released in Japan on July 27, 1989. The game was re-released in Japan along with its sequel on the single-cartridge compilation Mother 1+2 for the Game Boy Advance in 2003. The game follows a young American boy named Ninten as he uses his great-grandfather''s studies on psychic powers to put an end to the paranormal phenomena spiraling the country into disarray.', 'https://en.wikipedia.org/wiki/EarthBound_Beginnings'),
  ('Q2321007', 'Adventures of Lolo 3 is a 1990 puzzle video game developed and published by HAL Laboratory for the Nintendo Entertainment System. It is the ninth installment of the Japanese Eggerland series, as well as the fifth to be released in Europe and the third to be released in North America. The North American version of the game reused new gameplay elements, cutscenes, and graphics from the Japanese-only Adventures of Lolo 2 (unrelated to the American Adventures of Lolo 2).

The Japan-exclusive Adventures of Lolo 2, on the other hand, is a different game. It has a different difficulty curve and featured completely different stages. It was released for the Famicom and it is the eighth installment in the Eggerland series. New gameplay elements, later re-used in the American Adventures of Lolo 3, were added to make the base gameplay deeper than before.', 'https://en.wikipedia.org/wiki/Adventures_of_Lolo_3'),
  ('Q2313869', 'Dragon Quest, titled Dragon Warrior when initially localized to North America, is a 1986 role-playing video game developed by Chunsoft and published by Enix for the Nintendo Entertainment System. It was originally released in Japan in May 1986 and by Nintendo in North America in August 1989. It is the first game in the Dragon Quest video game series. Dragon Quest has been ported and remade for several video game platforms. As of 2019, it has been ported to MSX, MSX2, PC-9801, Super Famicom, Game Boy Color, mobile phones, and Nintendo Switch. The player controls the hero character who is charged with saving the Kingdom of Alefgard and rescuing its princess from the evil Dragonlord. Dragon Quest''s story became the second part in a trilogy, with several spinoff anime and manga series.', 'https://en.wikipedia.org/wiki/Dragon_Quest_(video_game)'),
  ('Q71910', 'Tetris (Russian: Тетрис) is a puzzle video game created by Alexey Pajitnov, a Soviet software engineer, in the mid-1980s. In Tetris, falling pieces made up of four connected blocks, known as tetrominoes, must be arranged into a stack. Once a horizontal line of the playfield is filled with blocks, the line disappears, granting points and clearing space. The objective is to score as many points as possible while keeping the stack from reaching the top, at which point the game ends. Approximately 220 versions of Tetris have been released across at least 70 platforms. Newer versions frequently add game mechanics, some of which have become standard over time, such as the ability to "hold" a tetromino for later use.', 'https://en.wikipedia.org/wiki/Tetris'),
  ('Q2321818', 'Castlevania III: Dracula''s Curse is a 1989 platform game developed and published by Konami for the Nintendo Entertainment System. It was released on December 22, 1989, in Japan, September 19, 1990, in North America and in May 1992 in PAL regions by Konami''s Palcom publishing label.

Despite being the third numbered installment in the Castlevania series, Castlevania III: Dracula''s Curse is a prequel to the original Castlevania (1986), being set a few centuries before its events. The game''s protagonist is Trevor Belmont, an ancestor of Simon Belmont, who is called into action to vanquish the forces of Dracula. Relinquishing the role-playing and action-adventure elements from Castlevania II: Simon''s Quest, the game returns to the action-platforming gameplay of the original Castlevania but also introduces new concepts to the formula such as branching level paths and multiple playable characters.', 'https://en.wikipedia.org/wiki/Castlevania_III:_Dracula%27s_Curse'),
  ('Q2321832', 'Castlevania II: Simon''s Quest is a 1987 action role-playing game developed and published by Konami. It was originally released in Japan in 1987 for the Famicom Disk System, and in North America in 1988 for the Nintendo Entertainment System. It is the second Castlevania game released for the NES, following the original Castlevania (1986). Set seven years after the events of the first installment, the player once again assumes the role of vampire hunter Simon Belmont, who is on a journey to undo a curse placed on him by Dracula at the end of their previous encounter. Dracula''s body was split into five parts, which Simon must find and bring to the ruins of Castle Dracula in order to defeat him. The game deviates from the traditional platforming of its predecessor, incorporating role-playing and open world elements.', 'https://en.wikipedia.org/wiki/Castlevania_II:_Simon%27s_Quest'),
  ('Q1903593', 'Defenders of Dynatron City is a video game released for the Nintendo Entertainment System by JVC Musical Industries and Lucasfilm Games (later, LucasArts) in August 1992. This was Gary Winnick''s first project as sole designer after co-designing Maniac Mansion with Ron Gilbert. It was supported by a brief media franchise consisting of an animated TV pilot and a six-issue comic book series.', 'https://en.wikipedia.org/wiki/Defenders_of_Dynatron_City'),
  ('Q1896803', 'Garfield merchandise is the merchandise based on the "Garfield" comic strip by Jim Davis. Garfield is one of the world''s most prominent and widely syndicated comic strips, and was specifically designed to be marketable. Before the sale of Paws, Inc. in August 2019, all the profits from merchandise went to Paws, Inc., of which Jim Davis is the CEO and founder. The following is a compiled list of selected merchandise based on the franchise.', 'https://en.wikipedia.org/wiki/Garfield_merchandise'),
  ('Q1890670', 'Last Ninja 2: Back with a Vengeance is an action-adventure video game developed and published by System 3 for the Commodore 64, ZX Spectrum and Amstrad CPC in 1988 as a sequel to the 1987 game The Last Ninja. The Acorn Electron, BBC Micro, 1990: Amiga, Atari ST, MS-DOS and NES ports followed in 1989. The NES version of the game was named simply The Last Ninja.

In 1990, the Last Ninja Remix edition of the game was re-released for 8-bit systems, which added a short intro sequence, minor graphic changes and a remixed soundtrack by Reyn Ouwehand.

The Limited Edition of the original release included a ninja mask and a rubber shuriken (not available with the Remix versions of the game).', 'https://en.wikipedia.org/wiki/Last_Ninja_2'),
  ('Q1906269', 'Parasol Stars: The Story of Bubble Bobble III is a 1991 platform video game developed and published by Taito for the TurboGrafx-16. It is a sequel to 1987''s Rainbow Islands, and the third game in the Bubble Bobble series. The game was ported by Ocean Software to the Amiga, Atari ST, Game Boy and Nintendo Entertainment System (with the NES port released under the title Parasol Stars: Rainbow Islands II). On July 11, 2024, the game was digitally re-released for the PlayStation 4, PlayStation 5, Xbox One, Xbox Series X/S, Nintendo Switch, and Windows.', 'https://en.wikipedia.org/wiki/Parasol_Stars'),
  ('Q1865060', 'Gauntlet II is a 1986 dungeon crawl maze video game developed and published by Atari Games for arcades. It is a sequel to the original Gauntlet, which was released the previous year. Like its predecessor, Gauntlet II is a fantasy-themed top down dungeon crawler, and was released as a dedicated cabinet, as well as a conversion kit, both available in two- and four-player versions.', 'https://en.wikipedia.org/wiki/Gauntlet_II'),
  ('Q1888364', 'The Battle of Olympus is a 1988 action role-playing video game for the Nintendo Entertainment System. The game''s story is a retelling of the Greek myth of Orpheus and his retrieval of his wife from the underworld.

It was released in North America in 1990, and released in Europe in 1991. A port for the Game Boy was released.', 'https://en.wikipedia.org/wiki/The_Battle_of_Olympus'),
  ('Q956303', 'Ghosts ''n Goblins, known as Makaimura in Japan, is a 1985 platform game developed and published by Capcom for arcades. It is the first game in the Ghosts ''n Goblins franchise, and has since been ported to numerous home platforms.

It was a major commercial success across arcades and home systems. It was among the top ten highest-grossing arcade games of 1986 in Japan and the US, as well as the year''s sixth best-selling computer game in the UK, with the Nintendo Entertainment System version selling over 1.6 million units worldwide. It initially received generally positive reviews from critics; it is often cited as one of the most difficult games of all time, and has retrospectively been considered one of the greatest video games ever made.', 'https://en.wikipedia.org/wiki/Ghosts_%27n_Goblins_(video_game)'),
  ('Q950084', 'Trojan, released in Japan as Tatakai no Banka, is a 1986 hack and slash video game developed and published by Capcom for arcades; it was released in North America by Romstar. Directed by Takashi Nishiyama, it is a spiritual successor to the beat ''em up Kung-Fu Master (1984), which was designed by Nishiyama at Irem before he left for Capcom, where he evolved its gameplay concepts with Trojan. It has also been likened to Capcom''s Ghosts ''n Goblins (1985), which has similar side-scrolling action gameplay elements.', 'https://en.wikipedia.org/wiki/Trojan_(video_game)'),
  ('Q968020', 'Millipede (stylized as millipede in western releases and as Milli-Pede in Japan) is a 1982 fixed shooter video game developed and published by Atari, Inc. for arcades. It was released by Namco in Japan. It is the sequel to 1981''s Centipede, with more gameplay variety and a wider array of insect enemies. The objective is to score as many points as possible by destroying all segments of a millipede that moves toward the bottom of the screen, as well as eliminating or avoiding other enemies. As with its predecessor, the game is played with a trackball and a single fire button which can be held down for rapid-fire.', 'https://en.wikipedia.org/wiki/Millipede_(video_game)'),
  ('Q947239', 'Many Doraemon video games were released for most video game systems in Japan. The following is a list of these.', 'https://en.wikipedia.org/wiki/List_of_Doraemon_video_games'),
  ('Q945899', 'Spy vs. Spy is a 1984 video game written by Mike Riedel for the Commodore 64 and published by First Star Software. A port for the Atari 8-bit computers was released simultaneously. It is a two-player, split-screen game, based on Mad magazine''s long-running cartoon strip Spy vs. Spy, about the slapstick antics of two spies trying to kill each other with improbably elaborate traps and weapons.

It was ported to the Apple II, ZX Spectrum, Acorn Electron, Atari ST, BBC Micro, Commodore 16, Amstrad CPC, Amiga, Master System, Game Boy, Game Boy Color, and Nintendo Entertainment System. A 3D remake/remaster of the same name was released for the Xbox and PlayStation 2 in 2005.', 'https://en.wikipedia.org/wiki/Spy_vs._Spy_(1984_video_game)'),
  ('Q928439', 'World Games is a sports video game developed by Epyx for the Commodore 64 in 1986. Versions for the Apple IIGS, Amstrad CPC, ZX Spectrum, Master System and other contemporary systems were also released. The NES version was released by Milton Bradley, and ported by Software Creations on behalf of producer Rare. The Master System version was done by Sega.

The game is a continuation of the Epyx sports line that includes Summer Games and Winter Games.

World Games was made available in Europe for the Wii Virtual Console on April 25, 2008.', 'https://en.wikipedia.org/wiki/World_Games_(video_game)'),
  ('Q933328', 'DuckTales is a 1989 platform game developed and published by Capcom and based on the Disney animated TV series of the same name. It was first released in North America for the Nintendo Entertainment System in 1989 and was later ported to the Game Boy in 1990. The story involves Scrooge McDuck traveling around the globe collecting treasure and outwitting his rival Flintheart Glomgold to become the world''s richest duck.

Produced by key personnel from the Mega Man series, DuckTales sold over a million copies worldwide on each system, becoming Capcom''s best-selling title for both platforms. The game was praised for its controls, unique and open-ended gameplay and bright presentation, and is often regarded as one of the best titles for the NES, appearing on numerous "Best of" lists.', 'https://en.wikipedia.org/wiki/DuckTales_(video_game)'),
  ('Q938696', 'Murder on the Mississippi: The Adventures of Sir Charles Foxworth is a 1986 adventure game developed and published by Activision for Commodore 64, Commodore 128, and Apple II personal computers, and licensed by Jaleco exclusively in Japan for the Famicom and MSX2 as Mississippi Satsujin Jiken. It is an adventure game in which the player must solve a murder mystery on the luxury ship "Delta Princess". The story is based loosely on the Agatha Christie novel Death on the Nile.

The Famicom game is known as a kusoge (i.e. a terrible game). in Japan.', 'https://en.wikipedia.org/wiki/Murder_on_the_Mississippi'),
  ('Q923597', 'Bases Loaded 4, known in Japan as MoePro! Saikyō Hen, is a baseball video game developed by Tose and published by Jaleco for the Family Computer in Japan in 1991, as well as the Nintendo Entertainment System in North America in 1993. It is the fourth installment in the Bases Loaded series for the NES.', 'https://en.wikipedia.org/wiki/Bases_Loaded_4'),
  ('Q2627223', 'Friday the 13th is a video game developed by Atlus and published by LJN for the Nintendo Entertainment System. Based on the horror franchise of the same name, the player controls counselors at Camp Crystal Lake as they attempt to defeat Jason Voorhees. The game received generally negative reviews, with criticism centered on its high difficulty and poor gameplay.', 'https://en.wikipedia.org/wiki/Friday_the_13th_(1989_video_game)'),
  ('Q2619973', 'Vindicators is a 1988 multidirectional shooter video game developed and published by Atari Games for arcades. One or two players each control a tank in a multidirectional scrolling level. The game received ports by Tengen to home computers and the Nintendo Entertainment System (the latter version of which was not licensed by Nintendo and used an alternate chip to defeat the 10NES lockout system). Ports were planned for the Atari Lynx and Apple IIGS (with the latter even completed), but were both cancelled. Vindicators was followed by the lesser-known arcade sequel Vindicators Part II.', 'https://en.wikipedia.org/wiki/Vindicators_(video_game)'),
  ('Q2623012', 'Bump ''n'' Jump, also known in Japan as Burnin'' Rubber, is a 1982 vehicular combat video game developed and published by Data East for arcades. Released in North America by Bally Midway, the arcade version was available as both a dedicated board and as part of Data East''s DECO Cassette System. The goal is to drive to the end of a course while knocking enemy vehicles into the sides of the track and jumping over large obstacles like bodies of water.

The arcade game was a commercial success in Japan and North America. It was ported to the Atari 2600, Intellivision, ColecoVision, Nintendo Entertainment System, and Sharp X1. The Famicom version of Burnin'' Rubber was published as Buggy Popper in Japan in October 1986.', 'https://en.wikipedia.org/wiki/Bump_%27n%27_Jump'),
  ('Q2624732', 'Little Nemo: The Dream Master is a 1990 platform game developed and published by Capcom for the Nintendo Entertainment System. It is based on the 1989 animated film Little Nemo: Adventures in Slumberland, which itself is based on the comic strip Little Nemo in Slumberland by Winsor McCay. The music was composed by Junko Tamiya, credited in the game as "Gonzou".

The game revolves around a young boy in his own surreal dreams as he journeys to Slumberland. Nemo can ride certain animals such as a frog, a gorilla, or a mole, by feeding them candy. Every animal has its own skills needed to complete each level. The purpose of the game is to travel to Nightmare land to rescue Morpheus, the king of Slumberland, from the clutches of the evil Nightmare King.', 'https://en.wikipedia.org/wiki/Little_Nemo:_The_Dream_Master'),
  ('Q2626892', 'Krusty''s Fun House, also known as Krusty''s Super Fun House, is a 1992 puzzle video game based on the animated television series The Simpsons. It was developed by Audiogenic and published by Acclaim Entertainment for the Nintendo Entertainment System (NES), Super Nintendo Entertainment System (SNES), Sega Genesis, Master System, Game Gear, and Game Boy; versions for the Amiga and MS-DOS computers were released by Virgin Games. In the game, players control Krusty the Clown as they attempt to exterminate all rats in the various levels, using objects to create a path for the rats towards the machine.', 'https://en.wikipedia.org/wiki/Krusty%27s_Fun_House'),
  ('Q2617004', 'The Black Onyx is a 1984 role-playing video game released in Japan, developed by Bullet-Proof Software, with development led by Henk Rogers. It was originally released for the NEC PC-8801, and ported to several other platforms. The Famicom version featured completely redesigned gameplay, a new map, and was retitled Super Black Onyx. The Game Boy Color port was developed by Atelier Double and published by Taito. The Game Boy Color port added enhanced visuals and included an option to play through the game with the original game''s visual style.

Because of memory limitations, another part of the game was released separately on some platforms as The Fire Crystal (which added a magic system). Two other parts were announced, The Moonstone (which allowed the party to explore the wilderness), and Arena (which allowed the party to take part in Arena battles).', 'https://en.wikipedia.org/wiki/The_Black_Onyx'),
  ('Q2624586', 'Big Nose the Caveman is a side-scrolling platform game developed by Optimus Software and released in 1991 by Camerica for the Nintendo Entertainment System and by Codemasters for the Amiga and the Atari ST. A Master System and Game Gear version called Dinobasher was completed, but never published.

The game was followed by a sequel, Big Nose Freaks Out, in 1992.', 'https://en.wikipedia.org/wiki/Big_Nose_the_Caveman'),
  ('Q2629434', 'Tiny Toon Adventures is a platform video game for the NES. It was developed and published by Konami and released in 1991. It is the first Tiny Toon Adventures video game to be released for a video game console.', 'https://en.wikipedia.org/wiki/Tiny_Toon_Adventures_(video_game)'),
  ('Q2630920', 'DuckTales 2 is a 1993 platform game developed and published by Capcom for the Nintendo Entertainment System. The game was ported to the Game Boy handheld system in Japan and North America the same year. DuckTales 2 is a sequel to DuckTales, and is based on the Disney''s animated TV series of the same name. Just like in the 1989 predecessor, the story involves Scrooge McDuck traveling around the globe collecting treasure. The player can freely choose levels to explore, similar to the Mega Man series. The game also features new elements such as the option to revisit a level and the additional collecting of pieces of a map to the lost treasure of McDuck.', 'https://en.wikipedia.org/wiki/DuckTales_2'),
  ('Q2642768', 'Iron Tank: The Invasion of Normandy, known as Great Tank in Japan, is a 1988 top-view action shooting game produced by SNK for the Nintendo Entertainment System.', 'https://en.wikipedia.org/wiki/Iron_Tank'),
  ('Q2630928', 'Dragon Ball Z Side Story: Plan to Eradicate the Saiyans is a 1993 card battle role-playing game developed by Tose and published by Bandai for the Family Computer game console. Based on the Dragon Ball franchise, the player''s movement and battle choices are dictated by randomly generated playing cards.

The game sold 300,000 copies, and was adapted into a 1993 original video animation (OVA) series that was released in two parts as strategy guides. Footage from the OVA was reused in a 1994 Playdia video game, and the OVA was completely remade in 2010.', 'https://en.wikipedia.org/wiki/Dragon_Ball_Z_Side_Story:_Plan_to_Eradicate_the_Saiyans'),
  ('Q2634600', 'Gumshoe is a light gun shooter video game developed and published by Nintendo for the VS. System arcade hardware and the Nintendo Entertainment System console. It was released in 1986 in North America and in 1988 in Europe. It was not released in Japan, which is unusual for a Nintendo game. It was designed by Yoshio Sakamoto.', 'https://en.wikipedia.org/wiki/Gumshoe_(video_game)'),
  ('Q2644797', 'Super Glove Ball is a game made by Rare in 1990 for the Nintendo Entertainment System, specifically designed to be played with the Power Glove controller. However, it can also be played with a standard NES controller. It was sold separately from the Power Glove.', 'https://en.wikipedia.org/wiki/Super_Glove_Ball'),
  ('Q2660086', 'Little Samson is a 1992 action–platform video game developed by Takeru and published by Taito for the Nintendo Entertainment System (NES). The game stars four heroes summoned to stop the demon king Ta-Keed from wreaking havoc on the kingdom of Forgy. Each hero has different abilities and the player can switch between the four at any time.

Little Samson was directed by Shinichi Yoshimoto, who had worked as a designer on Capcom titles such as Ghouls ''n Ghosts and Strider. Kiyoshi Utata, who also worked on Cocoron and Nostalgia 1907, made the game''s artwork. The game received favorable reviews. Critics praised the audiovisual side and noted that swapping between characters added an element of strategy to the action. The game is considered one of the best NES games in retrospect, and the North American release has become an expensive collector''s item.', 'https://en.wikipedia.org/wiki/Little_Samson'),
  ('Q2659903', 'Jackal, released in North America as Top Gunner, is a run and gun video game developed and published by Konami for arcades. It was released in October 1986 and ported to the Nintendo Entertainment System, Famicom Disk System, ZX Spectrum, Commodore 64, and IBM PC compatibles.', 'https://en.wikipedia.org/wiki/Jackal_(video_game)'),
  ('Q2645897', 'Home Alone 2: Lost in New York is an action video game based loosely on the 1992 film of the same name. It was published in 1992 for the Nintendo Entertainment System and Game Boy, then in 1993 for the Genesis, Super NES and MS-DOS. The game is dedicated to Tom D. Heidt, a programmer who died shortly before it was released.', 'https://en.wikipedia.org/wiki/Home_Alone_2:_Lost_in_New_York_(video_game)'),
  ('Q2658381', 'Ninja Gaiden, released in Japan as Ninja Ryūkenden and as Shadow Warriors in Europe, is a 1988 hack and slash platform game developed and published by Tecmo for the Nintendo Entertainment System. Its development and release coincided with the beat ''em up arcade version of the same name. It was released in December 1988 in Japan, in March 1989 in North America, and in August 1991 in Europe. It has been ported to several other platforms, including the PC Engine, the Super NES, and mobile phones.

Set in a retro-futuristic version of 1988, the story follows a ninja named Ryu Hayabusa as he journeys to America to avenge his murdered father. There, he learns that a person named "the Jaquio" plans to take control of the world by unleashing an ancient demon through the power contained in two statues. Featuring side-scrolling platform gameplay similar to Castlevania, players control Ryu through six "Acts" that comprise 20 levels; they encounter enemies that must be dispatched with Ryu''s katana and other secondary weapons.', 'https://en.wikipedia.org/wiki/Ninja_Gaiden_(NES_video_game)'),
  ('Q2335742', 'Bandai Golf Challenge Pebble Beach is a golf video game released for the Nintendo Entertainment System. It was released by Bandai. The game is named after Pebble Beach, a golf course on California''s Pacific Coast.

The game implements real world physics in addition to the traditional rules of golf, and consistently places players against the notoriously harsh winds of Pebble Beach. As with the game''s real life counterpart, the Pacific Ocean plays a prominent role on the course and adds to the difficulty of play.', 'https://en.wikipedia.org/wiki/Bandai_Golf:_Challenge_Pebble_Beach'),
  ('Q2338283', 'Soccer is a soccer video game developed by Intelligent Systems and published by Nintendo for the Nintendo Entertainment System. It was released in Japan and North America in 1985, and in Europe in 1987. An arcade version for the Nintendo VS. System titled VS. Soccer was released the same year. It was released for the Famicom Disk System in 1986. The NES version was released on the Wii and Wii U Virtual Console on June 12, 2014 and on the Nintendo Classics service in 2018, while the arcade version was released by Hamster Corporation as part of their Arcade Archives series for the Nintendo Switch in 2020.', 'https://en.wikipedia.org/wiki/Soccer_(1985_video_game)'),
  ('Q2332808', 'Metal Max is a role-playing video game developed by Crea-Tech and Data East and published by Data East for the Famicom. It is the first game in the Metal Max series.

Metal Max is set in a futuristic post-apocalyptic world, where the surviving humans cluster in underground villages and ruins while "monster hunters" fight the monsters and outlaws outside. The game received a sequel, Metal Max 2, and was remade for the Super Famicom as Metal Max Returns. A direct sequel, Metal Saga: Season of Steel, was published in 2006 for Nintendo DS.', 'https://en.wikipedia.org/wiki/Metal_Max_(video_game)'),
  ('Q2340591', 'Just Breed is a tactical role-playing game published by Enix for the Famicom. It was published exclusively in Japan in 1992. The game was announced nearly three years before release. It is one of the largest RPGs for the Famicom.', 'https://en.wikipedia.org/wiki/Just_Breed'),
  ('Q2331936', 'Linus Spacehead''s Cosmic Crusade is a video game released in 1992 by Codemasters for the Nintendo Entertainment System. A remake of the game, retitled Cosmic Spacehead, was released in 1993 for Amiga, MS-DOS, Game Gear, Master System, and Genesis. The game features adventure elements, with locations connected by platform sections.

The game is the sequel to Linus Spacehead, which was released exclusively as part of the compilation Quattro Adventure.', 'https://en.wikipedia.org/wiki/Linus_Spacehead%27s_Cosmic_Crusade'),
  ('Q1010202', 'Ghost Lion, known in Japan as White Lion Densetsu: Pyramid no Kanata ni, is a 1989 role-playing video game released by Kemco for the Nintendo Entertainment System. The game is a loose adaptation of the 1988 film of the same name', 'https://en.wikipedia.org/wiki/Ghost_Lion'),
  ('Q968105', 'Wild Gunman is a light gun shooter game developed and published by Nintendo. Based on a 1974 electro-mechanical arcade game by Gunpei Yokoi, it was adapted to a video game for the Famicom console in Japan in 1984. In North America, it was released in 1985 as a launch game for the Nintendo Entertainment System (NES) with the Zapper light gun.

The game from 1974 was formerly known as Gun Fight.', 'https://en.wikipedia.org/wiki/Wild_Gunman'),
  ('Q972995', 'Ganso Saiyūki: Super Monkey Daibōken is an action video game for the Family Computer which was released exclusively in Japan on November 21, 1986. The game is based on the novel Journey to the West.', 'https://en.wikipedia.org/wiki/Ganso_Saiy%C5%ABki:_Super_Monkey_Daib%C5%8Dken'),
  ('Q1011612', 'Golf Grand Slam is a 1991 golf simulation game for the Nintendo Entertainment System. It features all the small details of real golf, such as wind, angle at which the ball is hit, etc. The game uses a password feature and up to four people can play.', 'https://en.wikipedia.org/wiki/Golf_Grand_Slam_(video_game)'),
  ('Q1014915', 'BurgerTime (or Hamburger in Japan) is an arcade video game by Data East released in 1982. According to a former Data East programmer, the game was designed in-house but the development itself was outsourced to another company.

The player controls chef Peter Pepper, who walks across oversized ingredients in a maze of platforms and ladders, causing them to fall and stack on buns below, eventually creating complete burgers. Peter is pursued by anthropomorphic hot dogs, fried eggs, and pickles. A limited supply of pepper can be thrown at aggressors immediately in front of Peter, briefly stunning them.', 'https://en.wikipedia.org/wiki/BurgerTime'),
  ('Q1026656', 'Donkey Kong Jr. Math is a 1983 edutainment platform video game developed and published by Nintendo for the Nintendo Entertainment System. It is a spin-off of the 1982 arcade game Donkey Kong Jr. In the game, players control Donkey Kong Jr. as he solves math problems set up by his father Donkey Kong.

It is the only game in the Education Series of NES games in North America, owing to the game''s lack of success. It was made available in various forms, including in the 2002 GameCube video game Animal Crossing and on the Virtual Console services for Wii and Wii U in 2007 and 2014 respectively, and in 2024 for the Nintendo Classics service. Donkey Kong Jr. Math was a critical and commercial failure. It has received criticism from several publications including IGN staff, who called it one of the worst Virtual Console games.', 'https://en.wikipedia.org/wiki/Donkey_Kong_Jr._Math'),
  ('Q1010211', 'Ghoul School is an action-adventure video game released for the Nintendo Entertainment System in 1992 by Imagineering. It takes place in a high school which has been overrun by ghosts/demons.', 'https://en.wikipedia.org/wiki/Ghoul_School'),
  ('Q2679211', '8 Eyes is a 1988 platform video game developed by Thinking Rabbit and published by SETA for the Nintendo Entertainment System. The game features eight levels, and can be played by one or two players. It also features a large, diverse soundtrack, composed by Kenzou Kumei, consisting of three pieces for each of the eight levels, which are set in different parts of the world.

Piko Interactive acquired the rights to 8 Eyes and released it for Microsoft Windows via Steam on August 14, 2019. 8 Eyes was also released on the Evercade as part of Piko Interactive Collection 1 on May 22, 2020.', 'https://en.wikipedia.org/wiki/8_Eyes'),
  ('Q2669580', '10-Yard Fight is a 1983 American football video game developed and published by Irem for arcades. It was released by Taito in North America, Electrocoin in Europe, and ADP Automaten in West Germany. A port developed by Tose for the Nintendo Entertainment System was released in 1985 by Irem in Japan and Nintendo internationally.', 'https://en.wikipedia.org/wiki/10-Yard_Fight'),
  ('Q2660330', 'Abadox: The Deadly Inner War is a horizontally scrolling shooter for the Nintendo Entertainment System published in Japan in 1989 by Natsume and North America in 1990 by Milton Bradley Company. It features gameplay in the vein of Gradius and R-Type, in which the player must shoot hordes of enemies while collecting power-ups to upgrade their ship. The plot revolves around the player character Nazal attempting to rescue the "beautiful Princess Maria" from being held within the "nightmarish body" of the game''s antagonist Parasitis. The game has often been noted by critics for its difficulty, with the player being instantly killed by a single enemy projectile.', 'https://en.wikipedia.org/wiki/Abadox'),
  ('Q2680533', 'Lot Lot is a multiplatform puzzle video game developed and published by Irem. Tokuma Shoten published the game on home platforms, including the Famicom.

The player controls one arrow and has to move some pellets (which resemble pachinko balls) from the upper cells (with a four-second delay) to the lower ones without having to confront an evil crab. He will grab the player''s pellets and try to prevent the player from scoring with them by cutting the elastic. The crab is forced to leave the board if there are no pellets for him to find.', 'https://en.wikipedia.org/wiki/Lot_Lot'),
  ('Q2684056', 'Indiana Jones and the Last Crusade: The Action Game was published in 1989 by Lucasfilm Games, based on the film of the same name. The game was released for the ZX Spectrum, Amstrad CPC, Commodore 64, Atari ST, Amiga, IBM PC, MSX, Master System, NES, Game Boy, Sega Genesis and Game Gear.

It is a different game from Indiana Jones and the Last Crusade: The Graphic Adventure, also released in 1989. There is also a different game for the Nintendo Entertainment System titled Indiana Jones and the Last Crusade, released by Taito in 1991.', 'https://en.wikipedia.org/wiki/Indiana_Jones_and_the_Last_Crusade:_The_Action_Game'),
  ('Q1058037', 'Super Pitfall is a 1986 side-scrolling non-linear platform game for the Nintendo Entertainment System (NES). Despite the title screen stating that it was reprogrammed by Pony Inc., the development of the NES version was handled by Micronics, a Japanese developer who mostly ported arcade games to the NES.

Super Pitfall was the first game that Activision published as a third-party developer for the NES. Following the original release of the game, ports were made in Japan by Makoto Ichinoseki for the PC-8800 series line of computers and by Steve Bjork for the Color Computer 3. The game initially received positive reviews from VideoGames & Computer Entertainment and Computer Entertainer while Bill Kunkel wrote in Computer Gaming World that the game did not control well and did not stand out well in a market of Super Mario Bros. clones. Retrospective reviews of the NES game from game critic Brett Weiss and Stuart Hunt of Retro Gamer found the game a step down from the previous Pitfall games on the Atari 2600, with both faulting low quality graphics and game design.', 'https://en.wikipedia.org/wiki/Super_Pitfall'),
  ('Q1066035', 'Gradius II, retitled Vulcan Venture in North American arcades, is a 1988 horizontally scrolling shooter video game developed and published by Konami. It is the sequel to Gradius and was succeeded by Gradius III. Initially released in arcades, ports of Gradius II were released for the Family Computer (under the shortened title of Gradius II), PC Engine Super CD-ROM², and the X68000 in Japan. The original arcade version is also included in the Gradius Deluxe Pack compilation for the PlayStation and Sega Saturn and in Gradius Collection for the PlayStation Portable.', 'https://en.wikipedia.org/wiki/Gradius_II'),
  ('Q1066657', 'Ice Climber is a 1985 platform video game developed and published by Nintendo. It was released for both the arcade VS. System and the Famicom/Nintendo Entertainment System console. The main protagonists, Popo and Nana, collectively known as the Ice Climbers, scale 32 vertically scrolling, ice-covered mountains to recover stolen vegetables from a giant condor. In some European countries, Ice Climber was bundled with the Nintendo Entertainment System.

The arcade expansion, VS. Ice Climber, features exclusive content from the traditional NES release; including an animated title screen, a stage select menu at the start of the game and between levels, 16 more mountains, occasional blizzard and wind effects, more enemies and vegetables, and bonus multiplier items.', 'https://en.wikipedia.org/wiki/Ice_Climber'),
  ('Q1049020', 'Tenchi wo Kurau II: Shokatsu Kōmei Den is a role-playing video game released in Japan by Capcom for the Famicom in 1991. It is the sequel to Destiny of an Emperor, originally based upon the manga Tenchi wo Kurau by Hiroshi Motomiya.', 'https://en.wikipedia.org/wiki/Tenchi_wo_Kurau_II:_Shokatsu_K%C5%8Dmei_Den'),
  ('Q2700588', 'Tennis is a 1984 tennis video game developed and published by Nintendo for the Nintendo Entertainment System. It was originally released in Japan for the Family Computer on January 14, 1984, a few months after the launch of the Famicom on July 15, 1983. An arcade version titled VS. Tennis released for the Nintendo VS. System the same year, becoming a hit at Japanese and American arcades that year; it was the sixth top-performing arcade game of 1984 in the United States. Tennis is one of 17 launch games for the console in North America and Europe. It was also ported to the Game Boy in 1989, going on sale about a month after the launch of the handheld console in Japan, and becoming one of the five launch titles for North America.', 'https://en.wikipedia.org/wiki/Tennis_(1984_video_game)'),
  ('Q2705496', 'Punch-Out!!, originally titled Mike Tyson''s Punch-Out!!, is a 1987 boxing video game developed and published by Nintendo for the Nintendo Entertainment System (NES). Part of the Punch-Out!! series, it is an adaptation of the arcade video games Punch-Out!! (1984) and Super Punch-Out!! (1984). Differences from the arcades include the addition of former undisputed world heavyweight champion Mike Tyson as the final boss. It received critical acclaim, and is retrospectively considered one of the greatest video games of all time.', 'https://en.wikipedia.org/wiki/Punch-Out!!_(1987_video_game)'),
  ('Q2705249', 'The Addams Family: Pugsley''s Scavenger Hunt is a platform game released by Ocean in 1992 in Europe and 1993 in North America. It is based on the 1992 animated series. It was released in North America for the Super Nintendo Entertainment System in February 1993, Game Boy in July 1993, and the Nintendo Entertainment System in August 1993.

The Game Boy and NES versions were ported by Enigma Variations.', 'https://en.wikipedia.org/wiki/The_Addams_Family:_Pugsley%27s_Scavenger_Hunt'),
  ('Q2701304', 'Mario''s Time Machine is an educational video game originally released for MS-DOS and then for the Nintendo Entertainment System and Super Nintendo Entertainment System consoles. The Software Toolworks both developed and published the MS-DOS and Super NES versions in 1993, while the NES version was developed by Radical Entertainment and published by The Software Toolworks in 1994. The Microsoft Windows version was re-released as Mario''s Time Machine Deluxe in 1996.

Mario''s Time Machine is one of several educational Mario video games that were released during the early 1990s; the game focuses on teaching human history. While the gameplay and engine vary between the three different versions, the story is roughly the same: the player assumes the role of Mario, who uses a time machine to return various artifacts, which had been stolen by Bowser, to their correct points in time.', 'https://en.wikipedia.org/wiki/Mario%27s_Time_Machine'),
  ('Q2710703', 'Blades of Steel, later released in Japan as Konamic Ice Hockey, is an ice hockey video game released by Konami for North American arcades in 1987, and ported to the Family Computer Disk System and Nintendo Entertainment System in 1988. All teams are fictional but based out of real Canadian and American cities. The game is known for its fast-paced hockey action and especially for the fighting. It is a one or two player game. When playing against the computer, there are three difficulty levels to choose from: Junior, College, and Pro (with Pro being the most difficult and Junior being the easiest). Each team consists of three forwards, two defencemen, and a goaltender.', 'https://en.wikipedia.org/wiki/Blades_of_Steel'),
  ('Q2717834', 'Wizardry II: The Knight of Diamonds (originally known as Wizardry: Knight of Diamonds - The Second Scenario) is the second game in the Wizardry series of role-playing video games. It was published in 1982 by Sir-Tech.', 'https://en.wikipedia.org/wiki/Wizardry_II:_The_Knight_of_Diamonds'),
  ('Q2716205', 'Wario''s Woods, known in Japan as Wario''s Forest, is a 1994 puzzle video game developed by Nintendo R&D1 and Intelligent Systems and published by Nintendo for the Nintendo Entertainment System (NES) and Super Nintendo Entertainment System (Super NES). A spin-off of the Mario series, players control Toad in his mission to defeat Wario, who has taken control of the Peaceful Woods. Gameplay revolves around clearing each level by using bombs to destroy groups of enemies. The game also features a multiplayer mode that allows two players to compete against each other.

The NES version is noteworthy for being the last officially-licensed game as well as the final first-party game for the system in North America, due to its release at the end of the console''s lifespan. It is also the only NES game to receive a rating from the Entertainment Software Rating Board (ESRB), which was inducted almost three months before the game''s American release. In Japan, the game was released alongside a re-release of The Legend of Zelda to coincide with the release of the AV Famicom.', 'https://en.wikipedia.org/wiki/Wario%27s_Woods'),
  ('Q2731595', 'Golf is a golf video game developed by Nintendo and HAL Laboratory and published by Nintendo for the Nintendo Entertainment System. It was originally released for the Famicom in Japan in 1984, with a port to the Nintendo VS. System as VS. Golf or Stroke and Match Golf, released in arcades internationally, followed by another arcade version called VS. Ladies Golf. The original was re-released for the NES in North America in 1985, and for the Famicom Disk System in 1986 in Japan.

Golf became the best-selling sports game for the NES/Famicom, and was re-released for different Nintendo consoles over several years. It was hidden in the Nintendo Switch firmware as an Easter egg as a tribute to the game''s programmer, the late Satoru Iwata.', 'https://en.wikipedia.org/wiki/Golf_(1984_video_game)'),
  ('Q2726277', 'Hoops is an NES basketball video game that was released in 1988 for a Japanese audience and in 1989 for a North American audience. In Japan, the game is known as Moero!! Junior Basket - Two on Two, which a part of "Moero!!" sports series.

The game is done in a half court style with the player having a choice to disable or enable winners outs. No fouls are called. There is also an around the world mode that allows players to focus on making baskets without worrying about the charging, pushing, and traveling fouls that are found in the standard mode of play. Similar to Double Dribble the game features slow-motion sequences when the player goes for a dunk, though these can be blocked.', 'https://en.wikipedia.org/wiki/Hoops_(1988_video_game)'),
  ('Q1040033', 'Front Line is a 1982 run and gun video game developed and published by Taito for arcades. It was one of the first overhead run and gun games, a precursor to many similarly-themed games of the mid-to-late 1980s. Front Line is controlled with a joystick, a single button, and a rotary dial that can be pushed in like a button. The single button is used to throw grenades and to enter and exit tanks, while the rotary dial aims and fires the player''s gun.

The game was a commercial success in Japan, where it was the seventh highest-grossing arcade game of 1982. However, it received a mixed critical and commercial reception in Western markets, with praise for its originality but criticism for its difficulty. The game''s overhead run and gun formula preceded Capcom''s Commando (1985) by several years. The SNK shooters TNK III (1985) and Ikari Warriors (1986) follow conventions established by Front Line, including the vertically scrolling levels, entering/exiting tanks, and not dying when an occupied tank is destroyed.', 'https://en.wikipedia.org/wiki/Front_Line_(video_game)'),
  ('Q1041292', 'Baseball is a baseball video game developed and published by Nintendo for the Family Computer (Famicom). It was originally released in Japan on December 7, 1983, a few months after the July 15 launch of the Famicom.

An arcade version titled VS. Baseball released for the Nintendo VS. System in 1984, featuring enhanced graphics and speech, becoming a hit at Japanese and American arcades. The game was later released as launch title for the Nintendo Entertainment System in North America in 1985, and in Europe in 1986. It was also ported to the Game Boy in 1989 as one of the handheld''s four launch titles.', 'https://en.wikipedia.org/wiki/Baseball_(1983_video_game)'),
  ('Q1043375', 'Castlevania, known in Japan as Akumajō Dracula, is a 1986 platform game developed and published by Konami. It was originally released in Japan for the Famicom Disk System in September 1986, before being ported to cartridge format and released in North America for the Nintendo Entertainment System (NES) in 1987 and in Europe in 1988. It was also re-issued for the Family Computer in cartridge format in 1993. It is the first installment in the Castlevania series.

Players control Simon Belmont, descendant of a legendary vampire hunter, who enters the castle of Count Dracula to destroy him when he suddenly reappears 100 years after Simon''s ancestor vanquished him. Castlevania was developed in tandem with Konami''s MSX2 game Vampire Killer, which was released a month later and uses the same premise, characters and settings, but features different gameplay mechanics. It was followed by a sequel, Castlevania II: Simon''s Quest, and a prequel, Castlevania III: Dracula''s Curse, both of which were also released for the NES. Super Castlevania IV was released in 1991 for the Super NES and follows the same story. A remake for the X68000 was released in 1993, and was later re-released for the PlayStation as Castlevania Chronicles in 2001.', 'https://en.wikipedia.org/wiki/Castlevania_(1986_video_game)'),
  ('Q1043534', 'Galaga is a 1981 fixed shooter video game developed and published by Namco for arcades. It was released by Midway Manufacturing in North America. It is the sequel to 1979''s Galaxian, and the second game in the Galaxian series. Controlling a starship, the player is tasked with destroying the Galaga forces in each stage while avoiding enemies and projectiles. "Boss Galaga" enemies can capture a player''s ship via a tractor beam, which can be rescued by another ship to give the player a "dual fighter" with additional firepower.

Shigeru Yokoyama led development with a small team. Initial planning took about two months to finish. Originally developed for the Namco Galaxian arcade board, it was instead shifted to a new system as suggested by Namco''s Research and Development division. Inspiration for the dual fighter mechanic was taken from a film that Yokoyama had seen prior to development, in which a ship was captured using a large circular beam. The project became immensely popular around the company, with Namco''s president Masaya Nakamura even taking interest.', 'https://en.wikipedia.org/wiki/Galaga'),
  ('Q1076255', 'Choplifter (stylized as Choplifter!) is a 1982 horizontally scrolling shooter video game developed by Dan Gorlin and published by Broderbund for the Apple II. It was ported to the Atari 8-bit computers the same year, and later to the VIC-20, Commodore 64, Atari 5200, ColecoVision, MSX, and Thomson computers. In 1985, Sega released a remake for arcades, with subsequent ports published for the Master System and Famicom in 1986. Graphically enhanced versions for the Atari 8-bit computers and the Atari 7800 were also released in 1988 by Atari Corporation.', 'https://en.wikipedia.org/wiki/Choplifter'),
  ('Q1081036', 'Rocket Ranger is a 1988 action-adventure game developed and published by Cinemaware. The game''s setting is based in the World War II era, allowing the player to control a US Army scientist and setting out to stop Nazi Germany from winning the war. The Rocket Ranger moniker stems from the rocket pack the player uses over the course of the game.

Like many Cinemaware games, Rocket Ranger draws its inspiration from Hollywood, and likely The Rocketeer comics. This title pays homage to the many 1950s science fiction serials, using the look and feel of the serials, including action-packed cut-scenes and an art treatment loyal to the futuristic visions of that era. It also features the cliché elements of that era, including a dashing, courageous hero and a beautiful, voluptuous damsel in distress in need of rescue.', 'https://en.wikipedia.org/wiki/Rocket_Ranger'),
  ('Q1075814', 'Solomon''s Key is a 1986 puzzle video game developed and published by Tecmo for arcades. It was ported to multiple systems, including the Nintendo Entertainment System and Commodore 64. The PC Engine version was known as Zipang and the Game Boy version as Solomon''s Club. A prequel, Solomon''s Key 2, was released in 1992 for the NES. The NES version of the game was also released in emulated form on Virtual Console for the Wii in 2006, Nintendo 3DS and Wii U in 2013 and later to the Nintendo Classics service in 2018.', 'https://en.wikipedia.org/wiki/Solomon%27s_Key'),
  ('Q150146', 'Fire Emblem: Shadow Dragon and the Blade of Light, originally promoted simply as Fire Emblem, is a 1990 tactical role-playing video game developed by Intelligent Systems and Nintendo and published by Nintendo for the Family Computer. It is the first installment in the Fire Emblem series and was originally released in Japan. Set on the fictional continent of Archanea, the story follows the tale of Marth, prince of the kingdom of Altea, who is sent on a quest to reclaim his throne after being forced into exile by the evil sorcerer Gharnef and his dark master Medeus, the titular Shadow Dragon. Forming new alliances with neighboring kingdoms, Marth must gather a new army to help him retrieve the sacred sword Falchion and the Fire Emblem shield in order to defeat Gharnef and Medeus and save his kingdom. The gameplay revolves around turn-based battles on grid-based maps, with defeated units being subject to permanent death.', 'https://en.wikipedia.org/wiki/Fire_Emblem:_Shadow_Dragon_and_the_Blade_of_Light'),
  ('Q2015406', 'WWF WrestleMania Challenge is a 1990 professional wrestling video game based on the World Wrestling Federation (WWF), released for the Nintendo Entertainment System by LJN. The game features nine wrestlers: Hulk Hogan, André the Giant, "Macho King" Randy Savage, Ultimate Warrior, Big Boss Man, Brutus Beefcake, "Ravishing" Rick Rude, Jim Duggan, and "Yourself" (a generic character). In a two-player game, both players can choose a differently-shaded version of Yourself, each having a unique theme song.

The game was originally developed under the title WWF Survivor Series. After this release, development of games under the WrestleMania name shifted to Sculptured Software, which developed WWF Super WrestleMania and WWF WrestleMania: Steel Cage Challenge.', 'https://en.wikipedia.org/wiki/WWF_WrestleMania_Challenge'),
  ('Q2017429', 'American Gladiators is a video game developed by Incredible Technologies and released in 1991 by GameTek for the Nintendo Entertainment System. Ports were published in 1992 for Amiga and MS-DOS compatible operating systems, and then in 1993 for Genesis and Super NES, by Imagitec Design. It is based on the 1989 television game show American Gladiators.', 'https://en.wikipedia.org/wiki/American_Gladiators_(video_game)'),
  ('Q2022792', 'Spy Hunter is a 1983 vehicular combat video game developed and published by Bally Midway for arcades. The game draws inspiration from the James Bond films and was originally supposed to carry the James Bond brand. The object of the game is to drive down roads in the technologically advanced "Interceptor" car and destroy various enemy vehicles with a variety of onboard weapons. The game was produced in both sit-down and standard upright versions, with the latter being more common. The controls consist of a steering wheel in the form of a futuristic aircraft-style yoke with several special-purpose buttons, a two-position stick shift (offering "low" and "high" gears), and a pedal used for acceleration.', 'https://en.wikipedia.org/wiki/Spy_Hunter'),
  ('Q2015463', 'WWF WrestleMania: Steel Cage Challenge is a professional wrestling video game based on the World Wrestling Federation (WWF), released in 1992 by Acclaim Entertainment for the Nintendo Entertainment System and in 1993 for the Master System and the Game Gear handheld console. The NES version was subsequently released as a handheld TV game in 2018 under the name WWE WrestleMania: Steel Cage Challenge, with all references to the "WWF" name and logo replaced by "WWE" (and with two changes to the roster). A second update was released in 2025 as a "mini arcade game," with further roster changes.', 'https://en.wikipedia.org/wiki/WWF_WrestleMania:_Steel_Cage_Challenge'),
  ('Q2017774', 'Ivan ''Ironman'' Stewart''s Super Off Road is a 1989 racing video game developed and published by Leland Corporation for arcades. It was designed and managed by John Morgan, who was also lead programmer, and endorsed by professional off-road racer Ivan Stewart. Virgin Games produced several home computer versions in 1990, with a version for the Nintendo Entertainment System released by Leland''s Tradewest subsidiary the same year. It was followed by versions for most major home consoles, including the Master System, Sega Genesis, and Super Nintendo Entertainment System. A port for the Atari Jaguar was announced but never released. Some ports lack the Ivan Stewart branding because of licensing issues, and are known simply as Super Off Road.', 'https://en.wikipedia.org/wiki/Super_Off_Road'),
  ('Q2016893', 'Touchdown Fever is a 1987 American football video game developed and published by SNK for arcades. It was later ported to the Nintendo Entertainment System and was released in Japan by K. Amusement Leasing on November 11, 1988 and in North America by SNK in February 1991. A sequel, Touchdown Fever II, was released in 1988.

Hamster Corporation released the game as part of their Arcade Archives series for the Nintendo Switch and PlayStation 4, as well as their Arcade Archives 2 series for the PlayStation 5 and Xbox Series X/S in January 2026.', 'https://en.wikipedia.org/wiki/Touchdown_Fever'),
  ('Q1967469', 'RoadBlasters is a 1987 vehicular combat video game developed and published by Atari Games for arcades. The player navigates an armed sports car through 50 different rally races, getting to the finish line before running out of fuel. Ports were released for a variety of home systems by Tengen and U.S. Gold.', 'https://en.wikipedia.org/wiki/RoadBlasters'),
  ('Q1953575', 'Qix ( KIKS) is a 1981 puzzle video game developed and published by Taito for arcades. Designed by husband and wife team Randy and Sandy Pfeiffer, Qix is one of a handful of games made by Taito''s American division (another is Zoo Keeper). At the start of each level, the playing field is a large, empty rectangle, containing the Qix, an abstract stick-like entity that performs graceful but unpredictable motions within the confines of the rectangle. The objective is to draw lines that close off parts of the rectangle to fill in a set amount of the playfield.

Qix was ported to the contemporary Atari 5200 (1982), Atari 8-bit computers (1983), and Commodore 64 (1983), then was brought to a wide variety of systems in the late 1980s and early 1990s: MS-DOS (1989), Amiga (1989), another version for the C64 (1989), Apple IIGS (1990), Game Boy (1990), Nintendo Entertainment System (1991), and Atari Lynx (1991).', 'https://en.wikipedia.org/wiki/Qix'),
  ('Q1973612', 'Nebulus is a vertically scrolling platform game created by John M. Phillips and published by Hewson Consultants in the late 1980s for home computer systems. International releases and ports were known by various other names: Castelian, Kyorochan Land, Subline, and Tower Toppler. The player climbs a cylindrical tower studded with platforms. The tower rotates as the player moves horizontally, giving a 3D effect.

The game''s original 8-bit release received some critical acclaim, in particular the Commodore 64 release, which garnered a Gold Medal award from UK magazine Zzap!64.

Nebulus was followed by the lesser-known Nebulus 2 for the Amiga in the 1990s.', 'https://en.wikipedia.org/wiki/Nebulus_(video_game)'),
  ('Q1950716', 'The Guardian Legend is a 1988 hybrid action-adventure and shoot ''em up video game developed by Compile for the Nintendo Entertainment System (NES). It is the sequel to the 1986 MSX game Guardic, and was published and released in Japan by Irem in 1988, in North America by Broderbund in 1989, and in Europe by Nintendo in 1991.

It incorporates gameplay elements from other games such as The Legend of Zelda, Metroid, and 1942. In the game, the player controls a lone protagonist, the Guardian, who is on a quest to destroy a large alien-infested world named Naju before it reaches the planet Earth. The player must deactivate ten safety devices scattered throughout Naju, thus activating the alien world''s self-destruct sequence. The player explores Naju in a non-linear fashion and can acquire different weapons during the course of the game.', 'https://en.wikipedia.org/wiki/The_Guardian_Legend'),
  ('Q2449283', 'Transformers: Mystery of Convoy is a 1986 video game developed by ISCO and published by Takara in Japan for the Famicom. It is based on the Transformers toyline. The game was made available on the Wii''s Virtual Console service on June 10, 2008.

The game stars Autobot protagonist Ultra Magnus. The titular Mystery is the identity of Optimus Prime''s (known as "Convoy" in Japan) killer; the 1986 film did not see a Japanese theatrical release until 1989, and Mystery of Convoy was created to provide an explanation for Prime''s death for the Japanese audience.

Upon release, Mystery of Convoy received negative reviews from critics for its level design and difficulty. Retrospective reviews have been similarly negative, and the game has garnered a reputation among retro gaming enthusiasts as a kusoge.', 'https://en.wikipedia.org/wiki/Transformers:_Mystery_of_Convoy'),
  ('Q2442526', 'Astérix is the name of three 1993 platform games for the Nintendo Entertainment System, Super NES and Game Boy. The games are based on the comic book series Asterix, and are part of a series of games based on this license. These games were only made available in PAL format due to their exclusive European release.', 'https://en.wikipedia.org/wiki/Asterix_(1993_video_game)'),
  ('Q2441363', 'A Nightmare on Elm Street is a video game released on the Nintendo Entertainment System in 1990 based on Wes Craven''s slasher film of the same name. The game was developed by Rare and published by LJN.', 'https://en.wikipedia.org/wiki/A_Nightmare_on_Elm_Street_(video_game)'),
  ('Q2414730', 'Joe & Mac, also known as Caveman Ninja or Caveman Ninja: Joe & Mac, is a 1991 platform video game developed and published by Data East for arcades. It was later ported to the Super Nintendo Entertainment System, MS-DOS, Amiga, Nintendo Entertainment System, Game Boy, Sega Genesis and Zeebo. It was followed by a sequel, Joe & Mac 2: Lost in the Tropics.', 'https://en.wikipedia.org/wiki/Joe_%26_Mac'),
  ('Q187339', 'Zelda II: The Adventure of Link is a 1987 action role-playing game developed and published by Nintendo. It is the second installment in the Legend of Zelda series, and was released in Japan for the Famicom Disk System on January 14, 1987, less than a year after the Japanese release and seven months before the North American release of the original The Legend of Zelda. Zelda II was released in North America and the PAL region for the Nintendo Entertainment System in late 1988, almost two years after its initial release in Japan.

The Adventure of Link is a direct sequel to the original The Legend of Zelda, again involving the protagonist Link, on a quest to save Princess Zelda, who has fallen under a sleeping spell. The game''s emphasis on side-scrolling platform and role-playing elements marked a significant departure from its top-down predecessor.', 'https://en.wikipedia.org/wiki/Zelda_II:_The_Adventure_of_Link'),
  ('Q204105', 'Dig Dug is a 1982 maze video game developed and published by Namco for arcades. It was released by Atari, Inc. in North America. The player digs underground tunnels in each level to escape and attack enemy characters, by either inflating them to bursting or crushing them underneath rocks.

Dig Dug was planned and designed by Masahisa Ikegami with help from Galaga creator Shigeru Yokoyama. It was programmed for the Namco Galaga arcade board by Shouichi Fukatani, who worked on many of Namco''s earlier arcade games, along with Toshio Sakai. Music was composed by Yuriko Keino, including the character movement jingle at executives'' request, as her first Namco game. Namco heavily marketed it as a "strategic digging game".', 'https://en.wikipedia.org/wiki/Dig_Dug'),
  ('Q173626', 'Pac-Man, originally titled Puck Man in Japan, is a 1980 maze video game developed and published by Namco for arcades. It was released in Japan on May 22, 1980 and by Midway Manufacturing in North America in October 1980. The player controls Pac-Man, who must eat all the dots inside an enclosed maze while avoiding four colored ghosts. Eating large flashing dots called "Power Pellets" causes the ghosts to temporarily turn blue and vulnerable, allowing Pac-Man to eat the ghosts for bonus points.

Pac-Man was designed by Toru Iwatani, who led a nine-man team; the game''s development began in early 1979. Iwatani wanted to create a game that could appeal to women as well as men, because most video games of the time had themes that appealed to traditionally masculine interests, such as war or sports. Although the inspiration for the Pac-Man character was the image of a pizza with a slice removed, Iwatani has said he rounded out the Japanese character for mouth, kuchi. The in-game characters were made to be cute and colorful to appeal to younger players. The original Japanese title of Puck Man was derived from the Japanese phrase paku paku taberu, which refers to gobbling something up; the title was changed to Pac-Man for the North American release due to fears of vandals defacing cabinets by converting the P into an F, as in fuck.', 'https://en.wikipedia.org/wiki/Pac-Man'),
  ('Q2470724', 'WWF WrestleMania (named after the annual pay-per-view event) is a Nintendo Entertainment System (NES) video game created by Rare and published by Acclaim Entertainment in 1989. It was the first WWF licensed NES game and the second WWF game overall, the first being MicroLeague Wrestling. WrestleMania also marked the beginning of a long relationship between Acclaim and the WWF, which lasted ten years. Released just months prior to WrestleMania V, it was intended to help build up to that event. The game''s title screen features the tagline for WrestleMania III: "Bigger. Better. Badder".

A Game Boy version started development in 1990 but was cancelled. It was developed by Zippo Games and designed by John Pickford. Rare later developed a follow-up game, WWF WrestleMania Challenge. A contemporary VCR board game version, designed by Interactive VCR Games, was also released around the same time, as well as a handheld version.', 'https://en.wikipedia.org/wiki/WWF_WrestleMania_(1989_video_game)'),
  ('Q2466720', 'Tecmo World Wrestling is a Nintendo Entertainment System professional wrestling game for one or two players released in 1989 where the player can control one of ten fictional international professional wrestlers. This is the first wrestling game to feature a play-by-play announcer, the animated Tom Talker, although his speech was only text bubbles. The game''s text, e.g. Tom Talker''s commentary, was translated from the Japanese game almost directly, leading to instances of Engrish. For example the Northern Lights Suplex is called "Northern Right Suplex". The game was released in Japan under the name Gekitou Pro Wrestling!! Toukon Densetsu', 'https://en.wikipedia.org/wiki/Tecmo_World_Wrestling'),
  ('Q2490098', 'Menace Beach is a video game released for the Nintendo Entertainment System by Color Dreams in 1990. Like all Color Dreams games, Menace Beach was not officially licensed by Nintendo. It was re-released as part of the Maxivision 15-in-1 multicart.', 'https://en.wikipedia.org/wiki/Menace_Beach'),
  ('Q2459946', 'Arkanoid: Revenge of Doh is a 1987 block breaker video game developed and published by Taito for arcades. It is the sequel to Arkanoid. It was ported to the Family Computer and various personal computers. Hamster Corporation released the game as part of their Arcade Archives series for the Nintendo Switch and PlayStation 4, as well as their Arcade Archives 2 series for the Nintendo Switch 2, PlayStation 5 and Xbox Series X/S in September 2026.', 'https://en.wikipedia.org/wiki/Arkanoid:_Revenge_of_Doh'),
  ('Q2465356', 'Silk Worm is a 1988 horizontally scrolling shooter video game developed and published by Tecmo for arcades. In 1989, it was ported to the Amiga, Atari ST, Commodore 64, ZX Spectrum, Amstrad CPC systems by The Sales Curve as Silkworm and released by Virgin Mastertronic. Sammy released a version for the Nintendo Entertainment System in 1990.

Silk Worm inspired the 1991 game SWIV; despite not being a direct sequel, it followed the same core gameplay design of a helicopter/jeep team, albeit as a vertically scrolling shooter instead of a horizontally scrolling one. It was described in several contemporary and retrospective reviews as being "inspired by" and a spiritual successor to Silk Worm.', 'https://en.wikipedia.org/wiki/Silk_Worm'),
  ('Q2468410', 'Shinobi is a 1987 hack and slash video game developed and published by Sega for arcades on the Sega System 16 board. The player controls ninja Joe Musashi, who must stop the Zeed terrorist organization from kidnapping students of his clan.

Shinobi was a commercial success in arcades. It topped the monthly Japanese table arcade charts in December 1987, and became a blockbuster hit in the United States, where it was the highest-grossing conversion kit of 1988 and one of the top five conversion kits of 1989. It was adapted by Sega to its Master System game console, followed by conversions to the Nintendo Entertainment System, PC Engine, and home computers. It was re-released as downloadable emulated versions of the original arcade game for the Wii and Xbox 360. The arcade game was released for the Nintendo Switch in January 2020 through the Sega Ages series. Shinobi''s success inspired various sequels and spin-offs of the Shinobi series.', 'https://en.wikipedia.org/wiki/Shinobi_(1987_video_game)'),
  ('Q2473951', 'The Adventures of Rocky and Bullwinkle and Friends is a video game released by THQ between 1992 and 1993 for Game Boy, NES, SNES, and Sega Genesis adapted from The Adventures of Rocky and Bullwinkle and Friends TV series.', 'https://en.wikipedia.org/wiki/The_Adventures_of_Rocky_and_Bullwinkle_and_Friends_(video_game)'),
  ('Q2495808', 'Crisis Force is a 1991 vertically scrolling shooter video game developed and published by Konami for the Family Computer. It was only released in Japan. The player controls one of two fighter ships piloted by Asuka and Maya, a pair of twin siblings descended from the ancient civilizations of Mu, who must save the world from a breed of artificial monsters from the lost civilization of Atlantis. The main feature of the game system is the player''s ability to transform its ship in one of three different forms, each with its unique attack method.', 'https://en.wikipedia.org/wiki/Crisis_Force'),
  ('Q2491737', 'S.C.A.T.: Special Cybernetic Attack Team, also known as Final Mission in Japan and Action in New York in Europe, is a science fiction side-view shoot-''em-up produced by Natsume for the Nintendo Entertainment System. Within PAL-A regions, the game was only released in the UK. It was released in Japan in 1990, in North America in 1991, and in the PAL region in 1992. It was also later released on the Virtual Console in the PAL region on February 4, 2011, and in North America on February 7 for the Wii and in the PAL region on December 4, 2014 for the Nintendo 3DS and Wii U and was released on the Nintendo Switch via the Nintendo Classics service on September 23, 2020. On September 1, 2026, Tengo Project has announced that a remake is under development under the title Cybernetic Attack: Final Mission.', 'https://en.wikipedia.org/wiki/S.C.A.T.:_Special_Cybernetic_Attack_Team'),
  ('Q2513509', 'Pro Wrestling is a pro wrestling video game developed and published by Nintendo. It was released originally for the Famicom Disk System in Japan in 1986. It was later released in North America and Europe on the Nintendo Entertainment System. The game was the third wrestling game on the Nintendo Entertainment System (after Tag Team Match: M.U.S.C.L.E. and Tag Team Wrestling).', 'https://en.wikipedia.org/wiki/Pro_Wrestling_(NES_video_game)'),
  ('Q2513837', 'High Speed is a pinball simulation video game developed by Rare for the Nintendo Entertainment System, and published by Tradewest in 1991. High Speed employs the game engine that Rare previously developed for Pin*Bot (1990).

Rare adapted the game from the pinball machine High Speed, which was designed by Steve Ritchie and released by Williams Electronics in 1986.

In 1995, Williams Entertainment published a sequel, The Getaway, for the Game Boy, based on Ritchie''s pinball machine The Getaway: High Speed II.', 'https://en.wikipedia.org/wiki/High_Speed_(video_game)'),
  ('Q2498075', 'Shadow of the Ninja, originally released in Japan as Yami no Shigotonin Kage (闇の仕事人 KAGE, The Dark Operative: Kage) and later released in Europe and Australia as Blue Shadow, is a 1990 hack and slash platform game developed and published by Natsume for the Nintendo Entertainment System. The game revolves around a pair of ninja sent to assassinate a dictator in a futuristic version of New York City. A port was planned for the Game Boy, but was released in a rebranded form as Ninja Gaiden Shadow. A remake, Shadow of the Ninja: Reborn, was released in 2024.', 'https://en.wikipedia.org/wiki/Shadow_of_the_Ninja'),
  ('Q2517563', 'Mario Is Missing! is a 1993 educational game developed and published by The Software Toolworks for MS-DOS, Nintendo Entertainment System, and Super Nintendo Entertainment System, later released on Macintosh in 1994. The player controls Luigi, who must travel around the world to find and return stolen treasures as part of a quest to locate his brother, Mario, who has been captured by Bowser. Mario Is Missing!, part of a series of educational Mario games, was Luigi''s second starring role in a video game, following the 1990 Game Watch game Luigi''s Hammer Toss and preceding the 2001 GameCube game Luigi''s Mansion.', 'https://en.wikipedia.org/wiki/Mario_Is_Missing!'),
  ('Q2532009', 'Wrecking Crew is an action game developed and published by Nintendo. It was first released for arcades for the Nintendo VS. System in 1984, titled VS. Wrecking Crew with a simultaneous two-player mode. It was released as a single-player game for the Family Computer (Famicom) console in 1985, and as a launch game for the Nintendo Entertainment System (NES) later that year.

It was designed by Yoshio Sakamoto and Makoto Kanoh. It is a spin-off of Nintendo''s Mario franchise, featuring Mario (and, in two-player mode, Luigi) going through levels attempting to destroy certain objects. A sequel, Wrecking Crew ''98, was released only in Japan in 1998 for the Super Famicom, and the game''s legacy would continue beyond with appearances from its antagonist Spike in the Mario spin-off Mobile Golf (2001), the films The Super Mario Bros. Movie (2023) and The Super Mario Galaxy Movie (2026), and its Golden Hammer appearing as an item in the Super Smash Bros. series.', 'https://en.wikipedia.org/wiki/Wrecking_Crew_(video_game)'),
  ('Q2530073', 'Xenophobe is a 1987 action video game developed and published by Bally Midway for arcades. The game sees up to three players attempting to clear an area of as many aliens as possible under a time limit.', 'https://en.wikipedia.org/wiki/Xenophobe_(video_game)'),
  ('Q2521832', 'Ultima V: Warriors of Destiny is the fifth entry in the role-playing video game series Ultima released in March 1988. It is the second in the "Age of Enlightenment" trilogy. The game''s story takes a darker turn from its predecessor Ultima IV. Britannia''s king Lord British is missing, replaced by a tyrant named Lord Blackthorn. The player must navigate a totalitarian world bent on enforcing its virtues through draconian means.

Ultima V sports numerous advances from Ultima IV. The game world is larger, with more towns, further detailed dungeons, and an expansive Underworld to explore. Dialog with NPCs hosts more choices to make during the conversation. World interactivity is further increased with new options to search, manipulate, and explore the player''s surroundings.', 'https://en.wikipedia.org/wiki/Ultima_V:_Warriors_of_Destiny'),
  ('Q2530723', 'Metroid is a 1986 action-adventure game developed and published by Nintendo. The first installment in the Metroid series, it was originally released in Japan for the Family Computer Disk System in August 1986. North America received a release in August 1987 on the Nintendo Entertainment System, with the European release following in January 1988. Set on the planet Zebes, the story follows Samus Aran as she attempts to retrieve the predatory Metroid organisms that were stolen by Space Pirates, who plan to replicate the Metroids by exposing them to beta rays and then use them as biological weapons to destroy Samus and all who oppose them.', 'https://en.wikipedia.org/wiki/Metroid_(video_game)'),
  ('Q2358844', 'Bee 52 is an unlicensed side-scrolling video game published by Codemasters for the Nintendo Entertainment System in 1992.

A Commodore 64 version was completed in 1993, but was not published due to Codemasters withdrawing from the C64 market. After reaching an agreement with Codemasters, the programmer sold the game himself via mail order.', 'https://en.wikipedia.org/wiki/Bee_52'),
  ('Q2354748', 'Yo! Noid, known in Japan as Kamen no Ninja Hanamaru, is a platform video game developed by Now Production and published by Capcom for the Nintendo Entertainment System. The game was first released in Japan on March 16, 1990, and was localized in the United States to promote the Noid, the mascot of Domino''s Pizza. The game was released for Nintendo''s NES-based PlayChoice-10 arcade system and was featured in the Japanese TV show GameCenter CX.', 'https://en.wikipedia.org/wiki/Yo!_Noid'),
  ('Q2353348', 'Karateka is a 1984 martial arts action game written for the Apple II by Jordan Mechner. It is his first published game and was created while he was attending Yale University. The game was published in North America by Broderbund and in Europe by Ariolasoft. Along with Karate Champ and Yie Ar Kung-Fu (both also released in 1984), Karateka is one of the earliest martial arts fighting games. It was inspired by Japanese culture (Ukiyo-e art, Akira Kurosawa films, and manga comics) and by early Disney animated films and silent pictures. An influential game of its era, it was one of the first to use cinematic storytelling and sound design, and rotoscoped animation.', 'https://en.wikipedia.org/wiki/Karateka_(video_game)'),
  ('Q88921', 'Cabal is a 1988 shooting gallery video game developed by TAD Corporation and published in Japan by Taito, in North America by Fabtek, and in Europe by Capcom. The player controls a commando trying to destroy various enemy military bases. The game was only a moderate success in arcades, and became better known for its various home ports.', 'https://en.wikipedia.org/wiki/Cabal_(video_game)'),
  ('Q88759', 'Bubble Bobble is a 1986 platform video game developed and published by Taito for arcades. It was released in North America by Romstar and in Europe by Electrocoin. Players control Bub and Bob, two dragons who set out to save their girlfriends from a world called the Cave of Monsters. In each level, Bub and Bob must defeat every enemy present by trapping them in bubbles and popping them. The enemies will then turn into bonus items when they hit the ground. There are 100 levels total, each becoming progressively more difficult.

Bubble Bobble was designed by Fukio "MTJ" Mitsuji. When he joined Taito in 1986, he felt that Taito''s game output was of mediocre quality. In response, he decided to make a game that was fun to play and could rejuvenate the company''s presence in the industry. Mitsuji hoped his game would appeal to women, specifically couples that visited arcades. As such, he decided to make Bubble Bobble focus largely on its two player co-operative mode. He made bubbles the core mechanic as he thought they would be a fun element that girls would enjoy.', 'https://en.wikipedia.org/wiki/Bubble_Bobble_(video_game)'),
  ('Q88240', '720° is a 1986 sports video game developed and published by Atari Games for arcades. Based on the sport of skateboarding, the player controls a skateboarder as they compete in various skating competitions, such as ramp jumping and downhill races, to earn cash.

The game has been ported and re-released to various home console and computer platforms.', 'https://en.wikipedia.org/wiki/720%C2%B0'),
  ('Q88855', 'California Games is a 1987 sports video game developed and published by Epyx for the Apple II and Commodore 64. Branching from their Summer Games and Winter Games series, it is a collection of outdoor sports purportedly popular in California. The game was successful and was soon ported to other home computers and video game consoles, and was the pack-in game for the Atari Lynx when that system launched in September 1989. It was followed by the sequel California Games II in 1990.

The events vary slightly per platform, but include half-pipe, footbag, surfing (starring Rippin'' Rick), roller skating, BMX, and flying disc.', 'https://en.wikipedia.org/wiki/California_Games'),
  ('Q88582', 'Advanced Dungeons & Dragons: Heroes of the Lance is a video game released in 1988 for various home computer systems and consoles. The game is based on the first Dragonlance campaign module for the Dungeons & Dragons fantasy role-playing game, Dragons of Despair, and the first Dragonlance novel Dragons of Autumn Twilight.', 'https://en.wikipedia.org/wiki/Advanced_Dungeons_%26_Dragons:_Heroes_of_the_Lance'),
  ('Q88947', 'Nekketsu Kōha Kunio-kun, released as Renegade in the West, is a 1986 beat ''em up video game developed by Technōs Japan and published by Taito for arcades. In the original Japanese version, the game revolves around Kunio, a high school delinquent who must stand up against a series of rival gangs that are targeting his classmate Hiroshi. In the Western version, the player controls a street brawler who must face four different gangs in order to rescue his girlfriend, who is being held captive by a mob boss.

Conceptualized and designed by Yoshihisa Kishimoto, the game was semi-autobiographical, partly based on his own teenage high school years getting into daily fights, with Kunio partly based on himself. He also drew inspiration from the Bruce Lee martial arts film Enter the Dragon (1973), which inspired the game''s "knock-down-drag-out" fights, along with his own altercations as a youth. In order to make the game more appealing for the West, Technos produced a graphically-altered version with a visual style inspired by the 1979 film The Warriors, changing the looks of some of the game''s characters and scenery.', 'https://en.wikipedia.org/wiki/Renegade_(video_game)'),
  ('Q2748771', 'Dr. Chaos, officially known as Dr. Chaos: Hell''s Gate in Japan, is an action-adventure game originally released in Japan for the Family Computer Disk System in 1987 by Pony Inc. An English localization was produced for the Nintendo Entertainment System that was released in North America by FCI in 1988.', 'https://en.wikipedia.org/wiki/Dr._Chaos'),
  ('Q2749049', 'Goal! is a 1988 soccer/football video game published by Jaleco for the Nintendo Entertainment System. The game supports up to two players. It was released in Japan as Moero !! Pro Soccer.', 'https://en.wikipedia.org/wiki/Goal!_(video_game)'),
  ('Q2746198', 'Rolling Thunder is a 1986 run and gun video game developed and published by Namco for arcades. It was released by Atari Games in North America. The player takes control of a secret agent who must rescue his female partner from a terrorist organization. Rolling Thunder was a commercial success in arcades, and was released for various home computer platforms in 1987 and the Nintendo Entertainment System in 1989. The original arcade game has been included in various classic game compilations as well. It influenced later arcade action franchises such as Shinobi and Time Crisis, which borrowed mechanics such as taking cover behind crates.', 'https://en.wikipedia.org/wiki/Rolling_Thunder_(video_game)'),
  ('Q2742194', 'Arch Rivals is a 1989 basketball video game developed and published by Bally Midway for arcades. Billed as "A Basket Brawl", the game features two-on-two full court basketball games in which players are encouraged to punch opposing players and steal the ball from them. Arch Rivals was the second basketball video game released by Midway, sixteen years after TV Basketball (1974). Home versions of the game were released for the Nintendo Entertainment System, Genesis/Mega Drive, and Game Gear.

Arch Rivals allows players to select from a variety of fictional teams (although arcade operators can change the team names to reflect real ones) and players. One playable character, "Tyrone" was also featured in the animated The Power Team segments of the television series Video Power. In turn, the game has been considered a forerunner to Midway''s popular arcade basketball game, NBA Jam. Emulated versions of Arch Rivals are included in the compilations Midway Arcade Treasures 2, Midway Arcade Treasures Deluxe Edition, and Midway Arcade Origins.', 'https://en.wikipedia.org/wiki/Arch_Rivals'),
  ('Q2732183', 'Circus Charlie is a 1984 action video game developed and published by Konami for arcades. It was released in North America by Centuri in March 1984 and in Japan in April 1984. The player controls a circus clown named Charlie in six different circus-themed minigames. It was released for MSX in the same year, followed by ports to the Famicom in 1986 by Soft Pro and the Commodore 64 in 1987.', 'https://en.wikipedia.org/wiki/Circus_Charlie'),
  ('Q2741274', 'D-Pad Hero is a 2009 video game demake of the Guitar Hero series developed for the Nintendo Entertainment System. An unofficial release, the game is a ROM which must be dumped onto a cartridge or played via emulator. A sequel, D-Pad Hero 2, was released in 2010.', 'https://en.wikipedia.org/wiki/D-Pad_Hero'),
  ('Q1935772', 'Chip ''n Dale Rescue Rangers 2 is a platform game released in December 1993 in Japan, and the following month in the United States. It is based on the Disney cartoon Chip ''n Dale Rescue Rangers, about Chip and Dale, two crime-fighting chipmunks. It is a sequel to the 1990 video game.

The game was included in The Disney Afternoon Collection compilation for PlayStation 4, Windows, and Xbox One released in April 2017.', 'https://en.wikipedia.org/wiki/Chip_%27n_Dale_Rescue_Rangers_2'),
  ('Q1920147', 'Super Contra, known as Super Contra: The Alien Strikes Back in Japan, is a run and gun video game developed and published by Konami for arcades. After location testing in December 1987, it had a wide release in January 1988. It is the sequel to Contra and part of the Contra series. The game stars Bill Rizer and Lance Bean as they are sent to thwart another alien invasion from the vicious Red Falcon.

It was ported to the Nintendo Entertainment System under the shortened title of Super C in North America and as Probotector II: Return of the Evil Forces in Europe. Both the arcade version and the NES version have been re-released for various other platforms since their original releases.', 'https://en.wikipedia.org/wiki/Super_Contra'),
  ('Q1925552', 'Ikari III: The Rescue (also known as Ikari Warriors III: The Rescue), simply known as Ikari III in Japan, is a 1989 beat ''em up video game developed and published by SNK for arcades. It was ported to the Nintendo Entertainment System, MS-DOS and Commodore 64. It is the third and final installment of the Ikari Warriors series after Ikari Warriors and Victory Road. The NES version was shown at the 1991 CES.', 'https://en.wikipedia.org/wiki/Ikari_III:_The_Rescue'),
  ('Q1932678', 'Chip ''n Dale Rescue Rangers is a platform video game developed and published by Capcom for the Nintendo Entertainment System. It is based on the Disney animated series of the same name. It was released in North America and Japan in 1990, and Europe in 1991. An arcade version was released by Nintendo in 1990. It sold approximately 1.2 million copies worldwide.

The game was included in The Disney Afternoon Collection compilation for PlayStation 4, Windows, and Xbox One released in April 2017.', 'https://en.wikipedia.org/wiki/Chip_%27n_Dale_Rescue_Rangers_(video_game)'),
  ('Q1942249', 'Back to the Future Part II & III is a 1990 video game for the Nintendo Entertainment System based on the second and third films in the Back to the Future trilogy. The game was produced by Beam Software and published by Acclaim Entertainment under their LJN label.', 'https://en.wikipedia.org/wiki/Back_to_the_Future_Part_II_%26_III'),
  ('Q2774261', 'Golgo 13: Top Secret Episode is an action video game for the Nintendo Entertainment System (NES); it was released in 1988.

In this game, based on a popular manga, the player takes on the role of Golgo 13 (also known as Duke Togo), a hitman whose assignment is to eliminate the leader of the Drek group. The story begins when a helicopter transporting a vial of a deadly bacillus known as "Cassandra G" is destroyed near the Statue of Liberty, but the vial is nowhere to be found in the wreckage. On the way, Golgo 13 must pass through several acts, including East Berlin, Athens, Rio de Janeiro, and Alexander Island, which is located off the coast of Antarctica.', 'https://en.wikipedia.org/wiki/Golgo_13:_Top_Secret_Episode'),
  ('Q2795318', 'Crystal Mines II is a puzzle video game developed by Color Dreams and published by Atari Corporation in 1992 for the Atari Lynx handheld console. The game is a sequel to Crystal Mines for the Nintendo Entertainment System. Both releases are similar to Boulder Dash, a genre which has since become known as "rocks and diamonds" games.', 'https://en.wikipedia.org/wiki/Crystal_Mines_II'),
  ('Q2757019', 'Volleyball is a 1986 volleyball video game developed by Nintendo and Pax Softnica and published by Nintendo for the Family Computer Disk System. It was ported to the Nintendo Entertainment System and released in North America and Europe in 1987. It is a remake of Pax Softnica''s previous MSX game Attack Four.

It was later re-released for the Wii''s Virtual Console in Europe and North America in August 2007 as well as on Nintendo Classics in June 2018.', 'https://en.wikipedia.org/wiki/Volleyball_(video_game)'),
  ('Q2752616', 'Pac-Land is a 1984 platform game developed and published by Namco for arcades. It was released in North America by Bally Midway, and in Europe by Atari Games. Controlling Pac-Man, the player must make it to the end of each stage to return a lost fairy back to its home in Fairyland. Pac-Man will need to avoid obstacles, such as falling logs and water-spewing fire hydrants, alongside his enemies, the Ghost Gang. Eating large flashing Power Pellets will cause the ghosts to turn blue, allowing Pac-Man to eat them for points.

Pac-Land was conceptualized by Namco Research and Development 1 programmer Yoshihiro Kishimoto, who was tasked with creating an arcade game based on the American Pac-Man cartoon television series by Hanna-Barbera. The backgrounds were made to be vibrant and colorful, and the characters to be detailed and move smoothly to match the show''s animation style. The control scheme was inspired by Konami''s Track & Field (1983), using buttons instead of a traditional joystick to make it stand out among other games at the time. A new Namco Pac-Land arcade system was created to make it easier to develop the game and was used for several later Namco games, including Baraduke (1985) and Metro-Cross (1985).', 'https://en.wikipedia.org/wiki/Pac-Land'),
  ('Q2764442', 'Bad News Baseball, originally released as Gekitō!! Stadium in Japan, is a baseball video game released by Tecmo for the Japanese Family Computer in 1989, and North America in 1990 for the NES. The goal for players is to defeat every other team in the game. Gameplay can continue indefinitely until this occurs.', 'https://en.wikipedia.org/wiki/Bad_News_Baseball');

insert into import_summary (wikidata_id, summary, source) values
  ('Q2783606', 'Impossible Mission II is a video game developed by Novotrade and published by Epyx in 1988. It was released for the Commodore 64, ZX Spectrum, Amstrad CPC, Enterprise 128, Nintendo Entertainment System, MS-DOS, Atari ST, Apple II with at least 128K, Apple IIGS, and Amiga.

Impossible Mission II is a direct sequel to Epyx''s 1984 Impossible Mission. It follows directly from the same plot, with Elvin Atombender seeking revenge and the player having to stop him. The overall game structure and basic gameplay is mostly similar, but there are a few differences and new features.', 'https://en.wikipedia.org/wiki/Impossible_Mission_II'),
  ('Q2786897', 'Victory Road, released as Dogō Sōken in Japan and also known as Ikari Warriors II: Victory Road, is a run and gun video game developed and published by SNK for arcades. It was released in Japan in 1986 and North America in 1987 by Tradewest. The game is a sequel to Ikari Warriors, released earlier on that same year.', 'https://en.wikipedia.org/wiki/Victory_Road_(video_game)'),
  ('Q2780594', 'Baseball Stars is a 1989 baseball video game developed and published by SNK for the Nintendo Entertainment System. It was also released in arcades by Nintendo through their PlayChoice-10 arcade system. Baseball Stars was the first baseball game to have battery save backup, which would become the norm across NES games. This allowed players to create a team, configure baseball league & play a season, and the game''s memory chip stored cumulative statistics.', 'https://en.wikipedia.org/wiki/Baseball_Stars'),
  ('Q2774283', 'Tecmo Baseball is a baseball video game developed by Tecmo for the Nintendo Entertainment System. It was released in January 1989 exclusively for the North American market.', 'https://en.wikipedia.org/wiki/Tecmo_Baseball'),
  ('Q2364135', 'Zoda''s Revenge: StarTropics II is an action-adventure video game developed and published by Nintendo for the Nintendo Entertainment System, and the sequel to StarTropics. It was released in North America in 1994, making it the second-to-last first-party game released on the NES, with Wario''s Woods being the last, and the final game developed by Nintendo exclusively for the NES, with Wario''s Woods having also been released for the Super NES, excluding re-releases and international distributions of other games by Nintendo.

It was released on the Wii Virtual Console in December 2008 in North America and on July 10, 2009, in the PAL regions. It was released on the Wii U Virtual Console in Europe on September 3, 2015, in Australia on September 4, 2015, and in North America on May 26, 2016.', 'https://en.wikipedia.org/wiki/Zoda%27s_Revenge:_StarTropics_II'),
  ('Q2364724', 'Blaster Master, known in Japan as Super Planetary War Chronicle: Metafight or simply Metafight, is a 1988 platform/run and gun video game developed and published by Sunsoft for the Nintendo Entertainment System. The game is the first in the Blaster Master series, and spawned two spin-off games as well as two sequels. The game follows Jason as he discovers a tank known as Sophia the 3rd, which he uses to battle radioactive mutants. The player controls Jason and the tank through eight levels of gameplay in order to find the whereabouts of Jason''s pet frog Fred, and to defeat the mutants and their leader, the Plutonium Boss.', 'https://en.wikipedia.org/wiki/Blaster_Master_(video_game)'),
  ('Q2361559', 'To the Earth is a light gun shooter video game developed by Cirque Verte and published by Nintendo for the Nintendo Entertainment System. It was released in November 1989 in North America and in Europe on February 23, 1990. It uses the NES Zapper to destroy ships and gain power-ups. The enemy spacecraft require good reflexes and aiming.', 'https://en.wikipedia.org/wiki/To_the_Earth'),
  ('Q2381494', 'Darkwing Duck is a platform video game developed and published by Capcom for the Nintendo Entertainment System in 1992. It was based on the Disney animated television series Darkwing Duck. It was ported to the Game Boy in 1993.', 'https://en.wikipedia.org/wiki/Darkwing_Duck_(Capcom_video_game)'),
  ('Q1995635', 'Gun.Smoke is a 1985 vertically scrolling shooter video game developed and published by Capcom for arcades. Unique from other scrolling shooters games, Gun.Smoke features a human as the shooter instead of a spacecraft, in this case a character named Billie Bob, a bounty hunter going after the criminals of the Wild West. It was designed by Yoshiki Okamoto.', 'https://en.wikipedia.org/wiki/Gun.Smoke'),
  ('Q2001519', 'TwinBee is a 1985 vertically scrolling shooter developed and published by Konami as an arcade video game. Along with Sega''s Fantasy Zone (1986), it is credited as an early archetype of the "cute ''em up" subgenre. It was the first game to run on Konami''s Bubble System hardware. TwinBee was ported to the Family Computer and MSX in 1986, and has been included in numerous compilations released in later years. The original arcade game was released outside Japan for the first time as part of the Nintendo DS compilation Konami Classics Series: Arcade Hits. A mobile phone version with edited graphics was released for Japanese i-mode mobile phones in 2003.', 'https://en.wikipedia.org/wiki/TwinBee'),
  ('Q2000330', 'North & South is a strategy action game released in 1989 for the Amiga, and Atari ST and ported to the Nintendo Entertainment System, Amstrad CPC, MSX, MS-DOS, Commodore 64 and ZX Spectrum. It was developed and published by Infogrames.

North & South is an offshoot of the Belgian comic series Les Tuniques Bleues (by Raoul Cauvin and Louis Salverius/Willy Lambillotte, from Dupuis) which is based on the American Civil War. The player acts out the Civil War, choosing to play as either the North or the South. The player may choose to start the game year from 1861 (the year the Civil War erupted) to 1864. Each year has a different array of armies and states that each side starts with.', 'https://en.wikipedia.org/wiki/North_%26_South_(video_game)'),
  ('Q1992811', 'The Adventures of Bayou Billy, known in Japan as Mad City, is a 1988 beat ''em up video game developed and published by Konami for the Nintendo Entertainment System.', 'https://en.wikipedia.org/wiki/The_Adventures_of_Bayou_Billy'),
  ('Q2386654', 'Jordan vs. Bird: One on One is a basketball video game developed by Electronic Arts as the sequel to One on One: Dr. J vs. Larry Bird from 1983. Jordan vs. Bird was initially published in 1988 for the Commodore 64 and MS-DOS, then versions were released for the Game Boy, Genesis, and Nintendo Entertainment System. The NES port was done by Rare and published by the Milton Bradley Company. There is also a handheld electronic game from Tiger Electronics.', 'https://en.wikipedia.org/wiki/Jordan_vs._Bird:_One_on_One'),
  ('Q2398028', 'Gemfire is a 1991 role-playing strategy video game developed and published by Koei for the Nintendo Entertainment System and later ported to Japanese home computers, Super NES, Genesis, MS-DOS, and Windows. The object in the game is to unify a fictional island by force. Players use a variety of units, such as archers, infantry and dragons, in order to capture the castle needed to control that particular territory.

A sequel, Royal Blood II: Chronicles of the Kingdom of Dinar, was released in Japan for Windows.', 'https://en.wikipedia.org/wiki/Gemfire'),
  ('Q2399220', 'Adventures in the Magic Kingdom is an action video game released in 1990 by Capcom for the Nintendo Entertainment System. Its soundtrack was composed by Yoko Shimomura. The game was released in five different regions (British Isles, North America, France, Scandinavia, and Australasia), using three different retail covers. The game places the player as a nameless main character, for whom the player can enter a name at the start of the game, into a hub-and-spoke Disney park heavily based on the company''s Disneyland, Magic Kingdom, and Tokyo Disneyland parks. Goofy left the golden key for the castle gate inside, and Mickey Mouse asks for the player''s help to find six silver keys needed to open the Cinderella Castle gate and allow the Disney parade to begin. After completing this task, Mickey congratulates the player and the parade begins.', 'https://en.wikipedia.org/wiki/Adventures_in_the_Magic_Kingdom'),
  ('Q2394261', 'Demon Sword is a 1988 platform game developed by TOSE and published by Taito for the Nintendo Entertainment System.', 'https://en.wikipedia.org/wiki/Demon_Sword'),
  ('Q2383859', 'The Goonies II is a 1987 action-adventure game developed and published by Konami for the Nintendo Entertainment System. It is a sequel to a prior Goonies video game released on the Family Computer in Japan, which was only available in North America on Nintendo VS. System arcade units.', 'https://en.wikipedia.org/wiki/The_Goonies_II'),
  ('Q2002828', 'Bomberman II, released in Europe and Australia as Dynablaster, is an action game developed and published by Hudson Soft for the Nintendo Entertainment System originally in Japan in 1991, Europe in 1992 and later in North America in March 1993.', 'https://en.wikipedia.org/wiki/Bomberman_II'),
  ('Q2008603', 'Konami Hyper Soccer is a 1992 soccer video game developed and published by Konami in Europe and Australia for the Nintendo Entertainment System. Part of the Hyper Sports series, which included Hyper Olympic (Track & Field outside Japan), its sequel Hyper Sports and Hyper Athlete (International Track & Field outside Japan), it is the second soccer game by Konami following Konami''s Soccer (Konami''s Football outside Japan) on the MSX, and their first soccer game on a Nintendo platform.

Konami Hyper Soccer received mixed reception from critics at release; reviewers noted the lack of on-screen display of the game''s score or time remaining during gameplay, and felt divided regarding aspects such as the audiovisual presentation and playability, while criticism was geared at its technical shortcomings but the controls, range of available options and addition of a two-player mode were commended. Some named it one of the best soccer titles on the Nintendo Entertainment System. Retrospective commentary has been more positive, and is considered to be the predecessor to Konami''s International Superstar Soccer and Pro Evolution Soccer franchises.', 'https://en.wikipedia.org/wiki/Konami_Hyper_Soccer'),
  ('Q2008751', 'The Simpsons: Bartman Meets Radioactive Man is a 1992 platform game based on the Fox animated television series The Simpsons. Released by Acclaim Entertainment for the Nintendo Entertainment System and Game Gear, it follows Bart Simpson as he embarks on a comic book quest to rescue his kidnapped idol, superhero Radioactive Man. The game received mixed reviews from critics, with criticism being directed at the gameplay control.', 'https://en.wikipedia.org/wiki/The_Simpsons:_Bartman_Meets_Radioactive_Man'),
  ('Q91268', 'Archon: The Light and the Dark is a 1983 strategy/action video game developed by Free Fall Associates and one of the first five games published by Electronic Arts. It is superficially similar to chess, in that it takes place on a board with alternating black and white squares, but instead of fixed rules when landing on another player''s piece, an arcade-style fight takes place to determine the victor, and each piece has different combat abilities. The health of the player''s piece is enhanced when landing on a square of one''s own color.

Archon was originally written for Atari 8-bit computers and then ported to the Apple II, Commodore 64, Amstrad CPC, ZX Spectrum, Amiga, IBM PC (as a self-booting disk), Macintosh, PC-88, Sharp X1, FM-7, and Nintendo Entertainment System. It was designed by Paul Reiche III (who also created the graphics for the game) and Jon Freeman and programmed by Anne Westfall.', 'https://en.wikipedia.org/wiki/Archon:_The_Light_and_the_Dark'),
  ('Q134138', 'The Lion King is a 1994 platform game based on Disney''s 1994 animated film of the same name. It was originally developed by Westwood Studios and published by Virgin Interactive Entertainment for the Super NES and Sega Genesis, and was ported to MS-DOS, Amiga, Game Gear, Master System, and Nintendo Entertainment System; the Amiga, Master System, and NES versions were only released in the PAL region. The game follows Simba''s journey from a young cub to the battle with his uncle Scar as an adult.', 'https://en.wikipedia.org/wiki/The_Lion_King_(video_game)'),
  ('Q90994', 'Chase H.Q. is a 1988 vehicular combat video game developed and published by Taito for arcades. The player assumes the role of a police officer named Tony Gibson, member of the "Chase Special Investigation Department". Along with his partner, Raymond Broady, he must stop fleeing criminals in high-speed pursuits in a black Porsche 928.

Chase H.Q. was ported to many home computers by Ocean Software in 1989, including versions for the ZX Spectrum, Amstrad CPC, Commodore 64, MSX, Amiga and Atari ST. Taito produced versions for the Family Computer (1989), Game Boy (1990), Master System (1990), TurboGrafx-16 (1990), Game Gear (1991), and Saturn (1996). It was released for PlayStation 2 in Japan in 2007 as part of Taito Memories II Volume 2.', 'https://en.wikipedia.org/wiki/Chase_H.Q.'),
  ('Q130641', 'Baby Boomer is a 1989 light gun shooter developed by Color Dreams for the Nintendo Entertainment System (NES). As the first game released by Color Dreams, its cartridge is not approved or licensed by Nintendo. To bypass the console''s 10NES lockout chip, the game uses a distinct baby blue cartridge casing with a voltage-spike circuit. The player uses the Zapper to protect a crawling infant from hazards across scrolling levels that range from suburban backyards to the pits of Hell.

Retrospective reception has been heavily negative, citing broken hit detection, unfair difficulty, and polarized comparisons to Nintendo''s early Zapper game, Gumshoe (1986). The A.V. Club ranked it as the worst Zapper game ever released. A sequel titled Baby Boomer 2: 35 Years Too Soon was released in 2024 for modern platforms.', 'https://en.wikipedia.org/wiki/Baby_Boomer_(video_game)'),
  ('Q91501', 'Back to the Future is a 1989 video game released by LJN for the Nintendo Entertainment System. The game is loosely based on the 1985 film of the same name. A sequel, Back to the Future Part II & III, was released in 1990.', 'https://en.wikipedia.org/wiki/Back_to_the_Future_(1989_video_game)'),
  ('Q91282', 'Arkanoid is a 1986 block breaker video game developed and published by Taito for arcades. It was released in North America by Romstar. The game revitalized the concept established by Atari, Inc.''s successful Breakout from a decade earlier and established the model for numerous games to follow. Arkanoid was ported to many home systems, including the Commodore 64, Nintendo Entertainment System, and ZX Spectrum.

Controlling a paddle-like craft known as the Vaus, the player is tasked with clearing a formation of colorful blocks by deflecting a ball towards it without letting the ball leave the bottom edge of the playfield. Some blocks contain power-ups with various effects, such as increasing the length of the Vaus, creating several additional balls, or equipping the Vaus with cannons. Other blocks may be indestructible or require multiple hits to break.', 'https://en.wikipedia.org/wiki/Arkanoid'),
  ('Q91220', 'Yie Ar Kung-Fu is a fighting game developed and published by Konami for arcades. It first had a limited Japanese release in October 1984, before having a wide release nationwide in January 1985 and then internationally in March. Along with Data East''s Karate Champ (1984), which influenced Yie Ar Kung-Fu, it is one of the games that established the basis for modern fighting games.

The game was inspired by Bruce Lee''s Hong Kong martial arts films, with the main player character Oolong modelled after Lee (like Bruceploitation films). In contrast to the grounded realism of Karate Champ, Yie Ar Kung-Fu moved the genre towards more fantastical, fast-paced action, with various different characters having a variety of special moves and high jumps, establishing the template for subsequent fighting games. It also introduced the health meter system to the genre, in contrast to the point-scoring system of Karate Champ.', 'https://en.wikipedia.org/wiki/Yie_Ar_Kung-Fu'),
  ('Q146124', 'Excitebike is a 1984 racing video game developed and published by Nintendo for the Nintendo Entertainment System. It was ported to arcades for the Nintendo VS. System later that year and Famicom Disk System in 1988. In North America, it became one of the best-selling games on the console. It was the first game in the Excite series.

Designed and directed by Shigeru Miyamoto, the smooth side-scrolling game engine his team developed for Excitebike was later used to develop Super Mario Bros. (1985), which had the effect of Mario smoothly accelerating from a walk to a run, rather than move at a constant speed.', 'https://en.wikipedia.org/wiki/Excitebike'),
  ('Q2042716', 'Guerrilla War, released in Japan as Guevara, is a 1987 run and gun video game developed and published by SNK for arcades. It was ported to the Amstrad CPC, Commodore 64, MS-DOS, Nintendo Entertainment System, and ZX Spectrum.', 'https://en.wikipedia.org/wiki/Guerrilla_War_(video_game)'),
  ('Q2044254', 'Solar Jetman: Hunt for the Golden Warpship is a multidirectional shooter video game developed by Zippo Games and Rare and published by Tradewest for the Nintendo Entertainment System. It was released in North America in September 1990 and in Europe by Nintendo on 26 September 1991. The game is the third installment of the Jetman series and the sequel to Lunar Jetman (1983). was later re-released by Nintendo for their NES-based PlayChoice-10 arcade system in the United States in 1990.

In the game, series protagonist Jetman must manoeuvre his small craft through caverns of various planets whilst searching for pieces of the Golden Warpship. The game is presented in a horizontal side-view environment and has ranging gravitational pulls for each planet, which subjects Jetman''s craft to various forms of inertia. Similar to its predecessors, Jetman must keep his craft topped up with fuel in order to progress through levels.', 'https://en.wikipedia.org/wiki/Solar_Jetman'),
  ('Q2045651', 'Tag Team Match: M.U.S.C.L.E., known in Japan as Kinnikuman: Muscle Tag Match, is a fighting game developed by Tose and published by Bandai for the Nintendo Entertainment System. The Japanese edition is based on Yudetamago''s manga and anime series Kinnikuman, but the North American edition was not due to the source material being not well-known outside Japan. Instead, the game was released as a tie-in with Mattel’s M.U.S.C.L.E. toy line, itself a rebranding of the Kinkeshi line of Kinnikuman toys.

It has eight playable characters, each with his own special move. The game was followed by a 1987 Japan-only sequel for the Famicom Disk System titled Kinnikuman: Kinniku-sei Ōi Sōdatsusen.', 'https://en.wikipedia.org/wiki/Tag_Team_Match:_M.U.S.C.L.E.'),
  ('Q2034914', 'Cyber Stadium Series—Base Wars is a baseball video game for the Nintendo Entertainment System (NES).

Developed by Konami for the NES, and published by Ultra Games, Cyber Stadium Series—Base Wars was released in May or June 1991 in the United States; the game did not receive a European release. A baseball video game for one or two players, the ROM cartridge features the ability to save games, whether playing either an individual game or the ten-game pennant race.', 'https://en.wikipedia.org/wiki/Cyber_Stadium_Series%E2%80%94Base_Wars'),
  ('Q2045111', 'Micro Machines is a racing game developed by Codemasters and originally published by Camerica for the Nintendo Entertainment System in 1991. Themed around Galoob''s Micro Machines toys, players race in miniaturised toy vehicles around various environments. The game is the first installment in the Micro Machines video game series.

Micro Machines was developed because Galoob wanted Codemasters to develop a game based on their toy brand, although Galoob and Codemasters encountered legal issues with Nintendo over the game being unlicensed. Micro Machines was ported to several systems, and received reboots for the Xbox, PlayStation 2, and GameCube in 2002. A sequel, Micro Machines 2: Turbo Tournament, was released in 1994, and the series was revived in 2016 with the release of a title for iOS and Android. Micro Machines received critical acclaim, with reviewers praising the originality and two-player mode, although some criticised the sprites on some versions. Retrospectively, it has been considered one of the greatest video games of all time.', 'https://en.wikipedia.org/wiki/Micro_Machines_(video_game)'),
  ('Q2047507', 'Metal Fighter is a side-scrolling shooter game developed in Taiwan by Joy Van and published by Color Dreams and Sachen. It was later published as Metal Fighter μ in Japan by Kinema Music in 1991.', 'https://en.wikipedia.org/wiki/Metal_Fighter'),
  ('Q1980593', 'Road Fighter is a 1984 racing video game developed and published by Konami for arcades. The goal is to reach the finish line within the stages without running out of time, hitting other cars or running out of fuel (which is refilled by hitting a special type of car). The game spawned a spiritual successor, Konami GT (1986), and two sequels, Midnight Run: Road Fighter 2 (1995) and Winding Heat (1996). A Japan-only sequel was also released 14 years later, Road Fighters (2010).', 'https://en.wikipedia.org/wiki/Road_Fighter'),
  ('Q1990991', 'Toobin'' is a 1988 action game developed and published by Tengen for Atari Games and arcades. Based on the recreational activity of tubing, it sees players traveling down the Colorado, Yukon, Nile, Styx, Canals of Mars and Jurassic, steering around obstacles (whirlpools, dinosaur tails, bullets, and more) and throwing cans at such enemies as alligators, hunters, and cavemen.

The game has been ported to various home consoles and computers, and later emulated as part of other video games.', 'https://en.wikipedia.org/wiki/Toobin%27'),
  ('Q1985756', 'RoboCop is a 1988 video game developed and published by Data East for arcades and Ocean Software for home computers, based on the 1987 film of the same name. It was sub-licensed to Data East by Ocean Software, who obtained the game rights from Orion Pictures during the film''s script stage. Data East and Ocean Software worked in conjunction with each other to release games for the arcade and home computers respectively for a joint release, with the home computer versions translating the sections that Data East had shown Ocean from an early unfinished build of the game which Ocean then had to expand upon.', 'https://en.wikipedia.org/wiki/RoboCop_(1988_video_game)'),
  ('Q1974580', 'Disney''s The Jungle Book is a series of platform video games based on the 1967 Disney animated film of the same name. The game was released by Virgin Interactive Entertainment for the Game Boy, Nintendo Entertainment System, Master System, Genesis/Mega Drive, Game Gear, Super Nintendo Entertainment System, and MS-DOS. While gameplay is the same on all versions, technological differences between the systems forced changes – in some case drastic – in level design, resulting in six fairly different versions of the ''same'' game. This article is largely based upon the Genesis/Mega Drive version.', 'https://en.wikipedia.org/wiki/The_Jungle_Book_(video_game)'),
  ('Q1977905', 'Mighty Final Fight is a 1993 beat ''em up game developed and published by Capcom for the Nintendo Entertainment System. It is a spinoff of Capcom''s 1989 arcade game Final Fight, which was previously ported to the Super NES. Unlike the CP System arcade classic and its SNES ports, the characters in this edition are depicted in a comical childlike "super deformed" or "chibi" art style in the same spirit as Famicom games such as both Konami''s Kid Dracula and Namco''s Splatterhouse: Wanpaku Graffiti.

The game''s plot is a comical re-telling of the story from the first game. Like the SNES ports, Mighty Final Fight is a single-player game. However, unlike the SNES versions, it retains all three playable characters from the arcade version. The game also has various features which were taken from the Famicom port of Technos Japan''s Double Dragon, including an experience points system allowing players to earn new fighting maneuvers.', 'https://en.wikipedia.org/wiki/Mighty_Final_Fight'),
  ('Q1982008', 'Karnov is a 1987 platform video game developed and published by Data East for arcades. A Nintendo Entertainment System port followed, which was released in Japan by Namco the same year and in North America by Data East in 1988. Players take control of the title character Jinborov Karnovski, or "Karnov" for short. Karnov is a strongman popularly illustrated as being from an unspecified part of the Soviet Union''s Central Asian republics, as shown on the arcade flyer.

As a character created by Data East, Karnov was reintroduced in several other games from the company, including Bad Dudes Vs. DragonNinja in which he is a boss in the first level. Karnov later appeared in the 1993 fighting game Fighter''s History, in which he is the final boss, and as a playable character in its sequels, Karnov''s Revenge, also known as Fighter''s History Dynamite and Fighter''s History: Mizoguchi Kiki Ippatsu!!.', 'https://en.wikipedia.org/wiki/Karnov'),
  ('Q1194412', 'Downtown Nekketsu Monogatari, released as River City Ransom in North America and Street Gangs in PAL regions, is a 1989 action-adventure beat ''em up video game developed and published by Technōs Japan for the Nintendo Entertainment System. It is the third installment of the Kunio-kun series released for the NES, preceded by Renegade and Super Dodge Ball, and the first to be developed specifically for the system.

Gameplay is similar to that of Renegade, but set in a non-linear open world, a first for the series. It was the first console game published by the developer''s North American subsidiary American Technos.', 'https://en.wikipedia.org/wiki/River_City_Ransom'),
  ('Q2881381', 'Balloon Kid is a 1990 platform game developed and published by Nintendo for the Game Boy. It was released in October 1990 in North America and in January 1991 in Europe. It is the sequel to Balloon Fight. It was never released in Japan for the original Game Boy, but two years after its original release, a licensed Family Computer port titled Hello Kitty World was reprogrammed and released by Sanrio''s subsidiary Character Soft exclusively in Japan on March 27, 1992. A Game Boy Color edition with a few new features titled Balloon Fight GB was released in Japan on July 31, 2000.', 'https://en.wikipedia.org/wiki/Balloon_Kid'),
  ('Q2565163', 'The Flintstones: The Rescue of Dino & Hoppy is a 1991 platform video game by Taito for the Nintendo Entertainment System and based on the animated series The Flintstones. Taito would later release another Flintstones game for the NES titled The Flintstones: The Surprise at Dinosaur Peak in 1993.

An unauthorised ROM hack of the game featuring the head of Mario superimposed over Fred Flintstone''s, titled 7 Grand Dad, gained notoriety online after it was played on a 2014 livestream by Joel "Vargskelethor" Johansson of the Vinesauce streaming collective. The ROM hack, as well as Johansson''s shocked reaction to its title screen, later became long-standing memes both within Johannson''s community and on the wider Internet.', 'https://en.wikipedia.org/wiki/The_Flintstones:_The_Rescue_of_Dino_%26_Hoppy'),
  ('Q1133627', 'Pool of Radiance is a role-playing video game developed and published by Strategic Simulations, Inc (SSI) in 1988. It was the first adaptation of TSR''s Advanced Dungeons & Dragons (AD&D) fantasy role-playing game for home computers, becoming the first episode in a four-part series of D&D computer adventure games. The other games in the "Gold Box" series used the game engine pioneered in Pool of Radiance, as did later D&D titles such as the Neverwinter Nights online game. Pool of Radiance takes place in the Forgotten Realms fantasy setting, with the action centered in and around the port city of Phlan.', 'https://en.wikipedia.org/wiki/Pool_of_Radiance'),
  ('Q2881676', 'Baltron is a horizontally scrolling shooter for the Family Computer that was released exclusively for the Japanese market on March 19, 1986.', 'https://en.wikipedia.org/wiki/Baltron'),
  ('Q205508', 'Ballblazer is a futuristic sports game created by Lucasfilm Games and published in 1985 by Epyx. Along with Rescue on Fractalus!, it was one of the initial pair of releases from Lucasfilm Games, Ballblazer was developed and first published for the Atari 8-bit computers. The principal creator and programmer was David Levine. The game was called Ballblaster during development; some pirated versions bear this name.

It was ported to the Apple II, ZX Spectrum, Amstrad CPC, Commodore 64, and MSX. Atari 5200 and Atari 7800 ports were published by Atari Corporation. A version for the Famicom was released by Pony Canyon.', 'https://en.wikipedia.org/wiki/Ballblazer'),
  ('Q2533175', 'The Blues Brothers is a platform game based on the band The Blues Brothers, where the object is to evade police and other vigilantes to get to a blues concert. The game was released for IBM PC, Amstrad CPC, Amiga, Commodore 64, and Atari ST in 1991, and for the NES and Game Boy in 1992. It was created by Titus France. A sequel, The Blues Brothers: Jukebox Adventure, was released for the SNES in 1993 (as The Blues Brothers) and for IBM PC compatibles and the Game Boy in 1994. The theme music of the video game is an electronic arrangement of Peter Gunn. Zzap!64 ranked the Commodore 64 port the eighth-best all-time Commodore 64 game in 1993, and the game was the best platformer for PC, Atari ST and Amiga consoles of 1991 of Zero journalist David Wilson.', 'https://en.wikipedia.org/wiki/The_Blues_Brothers_(video_game)'),
  ('Q1142493', 'Kid Icarus is a 1986 action-platform game developed and published by Nintendo for the Family Computer Disk System in Japan and the Nintendo Entertainment System in Europe and North America. It was released in Japan in December 1986, in Europe in February 1987, and in North America in July.

The plot of Kid Icarus revolves around protagonist Pit''s quest for three sacred treasures, which he must equip to rescue the Greek-inspired fantasy world Angel Land and its ruler, the goddess Palutena. The player controls Pit through platform areas while fighting monsters and collecting items. The objective is to reach the end of the levels, and to find and defeat boss monsters that guard the three treasures. The game was developed by Nintendo''s Research and Development 1 division with assistance with an external company (later identified to be Tose), which helped with testing. It was designed by Toru Osawa and Yoshio Sakamoto, directed by Satoru Okada, and produced by Gunpei Yokoi.', 'https://en.wikipedia.org/wiki/Kid_Icarus'),
  ('Q1194285', 'Yoshi, known as Mario & Yoshi in PAL regions, is a 1991 puzzle video game developed by Game Freak and published by Nintendo for the Nintendo Entertainment System and Game Boy. Both versions were first released simultaneously in Japan on December 14, 1991, and released in all other regions the following year.

In Yoshi, the player is tasked with clearing monsters from the on-screen playing field. The monsters fall in from the top of the screen to build vertical stacks; the player must prevent a stack from growing too high such that it exits the play field. In order to do so, the player swaps and moves the stacks about such that falling monsters collide with identical monsters stationed atop the stacks, causing them to be removed from play. Yoshi offers both a scoring-focused single-player mode and a competitive two-player mode.', 'https://en.wikipedia.org/wiki/Yoshi_(video_game)'),
  ('Q1141199', 'Super Sprint is a 1986 racing video game developed and published by Atari Games for arcades. Up to three players drive Formula One-like cars on a circuit that is viewed from above. The game is a successor to Gran Trak 10 and the Sprint series, which were originally produced by Atari, Inc. during the 1970s. Later in 1986, the game was revised and re-released as Championship Sprint with different tracks; this version was ported to the Amstrad CPC, Atari ST, Commodore 64 and ZX Spectrum in 1987. The 1990 game Badlands adds vehicular combat to Super Sprint-style racing.', 'https://en.wikipedia.org/wiki/Super_Sprint'),
  ('Q2885286', 'Low G Man: The Low Gravity Man is a platform game developed by KID and published in 1990 by Taxan in North America and by Nintendo in Europe for the Nintendo Entertainment System.

Low G Man was met with mixed reception from critics since its initial release; many felt divided in regards to the graphics, sound and gameplay, while common complaints were geared towards the jerky background scrolling, choppy animations, small character sprites and color scheme but praise was given to the fast-paced soundtrack and large bosses. Retrospective commentary has been mostly positive.', 'https://en.wikipedia.org/wiki/Low_G_Man:_The_Low_Gravity_Man'),
  ('Q2886732', 'Bases Loaded 3, known in Japan as MoePro! Yakyū ''90 Kandō Hen, is a baseball video game released in 1990 by Jaleco for the Nintendo Entertainment System. The game is the third installment of the Bases Loaded series.', 'https://en.wikipedia.org/wiki/Bases_Loaded_3'),
  ('Q2542131', 'Bucky O''Hare is a 1992 platform game for the Nintendo Entertainment System based on the comic book series of the same name. The game was developed, under the direction of Masato Maegawa, by Konami, which also published it in North America in February 1992 and in Europe on February 18, 1993. Graphics were created by Kaname Shindoh, Madonna Taira, and Toshiharu Furukawa, and the music was composed by Tomoko Sumiyama.

Bucky O''Hare stars the titular rabbit as the captain of the Righteous Indignation, which protects the parallel universe of the Aniverse. His other crew members, duck Dead-Eye, cat Jenny, android Blinky, and human Willy, have been captured by the Toad Air Marshall. The first four levels take place on the Green, Red, Blue, and Yellow Planets, where the crew members are imprisoned. The player starts out with Bucky, and the other kidnapped crew members are playable once rescued and have different abilities and weapons. After all the members are saved, the Toad Air Marshall then kidnap the Righteous Indignation again in the Magma Tanker. The remainder of the game involves the crew members saving each other, blowing up the Magma Tanker and escaping.', 'https://en.wikipedia.org/wiki/Bucky_O%27Hare_(NES_video_game)'),
  ('Q210271', 'The Karate Kid is a 1987 licensed action game developed by Atlus and published by LJN for the Nintendo Entertainment System (NES) exclusively in North America despite being developed by a Japanese developer. It is based on The Karate Kid Part II (1986) and follows the player, as the karate student Danial LaRusso, progressing through four levels loosely based on events from the film. The gameplay is split between traversing through side-scrolling areas and fighting opponents one on one; the latter of which can be played separately with a second player.', 'https://en.wikipedia.org/wiki/The_Karate_Kid_(video_game)'),
  ('Q2557573', 'Plotting, released as Flipull in Japan, is a 1989 tile-matching puzzle video game developed and published by Taito for arcades. It was released in Japan in June 1989 and North America in August 1989. It was ported to the Famicom and Game Boy. As Plotting it was ported to the Atari ST, Amiga, Commodore 64, Amstrad CPC, GX4000, and ZX Spectrum. The game bears strong graphical and some gameplay similarities to Puzznic.', 'https://en.wikipedia.org/wiki/Plotting_(video_game)'),
  ('Q1139287', 'Lunar Pool (known as Lunar Ball in Japan) is a sports video game. It was developed in 1985 by Compile for the NEC PC-8000 series (in Japan), the Nintendo Entertainment System (NES, in Japan, North America, and Europe), and the MSX (in Japan), and re-released for the Wii on the North American Virtual Console on October 22, 2007. The game combines pool (pocket billiards) with aspects of miniature golf. The object is to use a cue ball to knock each object ball into one of the pockets on pool tables of various shapes. The game offers sixty levels, and the friction of the table is adjustable. Lunar Pool was distributed by Pony Canyon in Japan and Fujisankei Communications International for the rest of the world.', 'https://en.wikipedia.org/wiki/Lunar_Pool'),
  ('Q2836804', 'Alien 3 (stylized as ALIEN3) is a 1992 run and gun video game based on the film of the same name. It was released for the Sega Genesis and Amiga in 1992, then for the Commodore 64, Game Boy, Game Gear, Nintendo Entertainment System, Super Nintendo Entertainment System, and Master System.

Each version was developed by Probe Software, except for the Game Boy version, which was developed by Bits Studios. The versions on all platforms differ in gameplay and graphics, the level layouts are most similar in the Amiga, Genesis and Master System versions.', 'https://en.wikipedia.org/wiki/Alien_3_(video_game)'),
  ('Q2544020', 'Cybernoid: The Fighting Machine is a shoot ''em up developed and published in 1988 by Hewson Consultants for the ZX Spectrum. It was ported to the Amstrad CPC, Atari ST, Commodore 64, Amiga, and Nintendo Entertainment System. It was programmed by Raffaele Cecco. The ZX Spectrum, Amstrad, and Atari ST versions have a main theme by Dave Rogers, while the Commodore C64 version has a different theme by Jeroen Tel.', 'https://en.wikipedia.org/wiki/Cybernoid'),
  ('Q2891548', 'Batman Returns is a 1993 beat ''em up video game developed and published by Konami for the Nintendo Entertainment System. Based on the DC Comics superhero Batman, it is inspired by the Warner Bros.''s 1992 film of the same name. In the main storyline, Batman must confront both Catwoman and the Penguin.

Batman Returns on the NES was produced by Kuniaki Kinoshita and designed by Teisaku Seki, who had worked on Lagrange Point (1991). The music was scored by Shigemasa Matsuo and Takashi Tateishi, best known for his work in Mega Man 2. The game garnered average reception from critics, whom praised the soundtrack but most were divided regarding the visuals, controls, and gameplay.', 'https://en.wikipedia.org/wiki/Batman_Returns_(NES_video_game)'),
  ('Q1188338', 'Mappy is a 1983 platform video game developed and published by Namco for arcades. It was released in Japan in March 1983 and in North America by Bally Midway in April 1983. It runs on Namco''s Mappy hardware (which is a modified/revised version of the Super Pac-Man hardware to support horizontal scrolling). The name "Mappy" is likely derived from mappo, a slightly pejorative Japanese slang term for policeman. The game has been re-released in several Namco arcade compilations. It spawned a handful of sequels and a 2013 animated web series developed by cartoonists Scott Kurtz and Kris Straub.', 'https://en.wikipedia.org/wiki/Mappy'),
  ('Q1192514', 'Galaxian is a 1979 fixed shooter video game developed and published by Namco for arcades. It is the first game in the Galaxian series. The player assumes control of the starfighter Galaxip in its mission to protect Earth from waves of aliens. Gameplay involves destroying each formation of aliens, who dive down towards the player in an attempt to hit them.

Designed by company engineer Kazunori Sawano, Galaxian was Namco''s response to Space Invaders, a similar space shooter released the previous year by rival developer Taito. Space Invaders was a sensation in Japan, and Namco wanted a game that could compete against it. Sawano strove to make the game simple and easy to understand. He was inspired by the space combat scenes in Star Wars, with enemies originally being in the shape of the film''s TIE Fighters. Galaxian is one of the first video games to feature RGB color graphics, and the first to use a tile-based hardware system, which was capable of animated multi-color sprites as well as scrolling; the latter was limited to the starfield background while the game itself remained a fixed shooter.', 'https://en.wikipedia.org/wiki/Galaxian'),
  ('Q2534019', 'The Simpsons: Bart vs. the World is a 1991 platform game based on the animated television series The Simpsons. It was originally developed by Imagineering and published by Acclaim Entertainment for the Nintendo Entertainment System, and was later ported by Arc Developments to Amiga, Atari ST, Game Gear and Master System in 1993. The player controls Bart Simpson as he travels around the world on a scavenger hunt while facing off against Mr. Burns'' family and agents. The game has received mixed reviews from critics.', 'https://en.wikipedia.org/wiki/The_Simpsons:_Bart_vs._the_World'),
  ('Q2891857', 'Battleship is a 1993 Nintendo Entertainment System and Game Gear video game based on the eponymous board game.', 'https://en.wikipedia.org/wiki/Battleship_(1993_video_game)'),
  ('Q2547021', 'Godzilla: Monster of Monsters! is a Nintendo Entertainment System video game released in Japan in 1988 and in 1989 in the US by Toho Co., Ltd. The North American version removes all references to Toho Cenfile-Soft Library and Compile, crediting the game to Toho Eizo on the title screen instead.', 'https://en.wikipedia.org/wiki/Godzilla:_Monster_of_Monsters!'),
  ('Q2877818', 'Tower of Babel is a 1986 puzzle-platform video game developed and published by Namco for the Family Computer. It was released in Japan on July 18, 1986. The game''s goal is to solve the puzzle of each of the 64 levels of the ancient Tower of Babel and reach the top of the tower. The player controls the protagonist, Indy Borgnine, who must avoid enemies while rearranging L-shaped blocks in order to reach each level''s exit.

Development was done by Namco, and the project was planned by Hiroshima Nagashima, who had worked on the company''s arcade game Sky Kid (1985), the music was by Norio Nakagata, and the character design was by Hiroshi Fuji. A port to arcades for the Nintendo VS. System, VS. Tower of Babel, was released in 1986 only in Japan.', 'https://en.wikipedia.org/wiki/Tower_of_Babel_(1986_video_game)'),
  ('Q2532676', 'Battletoads/Double Dragon (fully titled Battletoads & Double Dragon - The Ultimate Team) is a 1993 beat ''em up developed by Rare and published by Tradewest. It was originally released for the Nintendo Entertainment System and later ported to the Mega Drive/Genesis, Super NES, and Game Boy. The SNES version was released on the Nintendo Classics service in September 2024; it was the game''s first re-release as it was not released on the Rare Replay collection.

The Ultimate Team is a crossover of Technos Japan''s Double Dragon and Rare''s Battletoads game franchises, although Technos had little or no credited involvement in production beyond providing the Double Dragon license. The game features the characters from the Double Dragon series, Billy and Jimmy Lee, two young martial arts experts; also included are the three humanoid toad protagonists from the Battletoads game. It is also the first Battletoads game to feature all three toads as playable characters. The game''s engine and design are directly based upon the Battletoads series.', 'https://en.wikipedia.org/wiki/Battletoads/Double_Dragon'),
  ('Q1094360', 'Destiny of an Emperor, known in Japan as Tenchi wo Kurau, is a tactical role-playing video game developed and published by Capcom for the Nintendo Entertainment System. It is based on the Tenchi wo Kurau manga by Hiroshi Motomiya. It was originally released in Japan in 1989, with an English language localization released for the North American market in 1990.', 'https://en.wikipedia.org/wiki/Destiny_of_an_Emperor'),
  ('Q1115150', 'Commando, released as Senjō no Ōkami in Japan, is a 1985 run and gun video game developed and published by Capcom for arcades. The game was designed by Tokuro Fujiwara. It was distributed in North America by Data East, and in Europe by several companies including Capcom, Deith Leisure and Sega, S.A. SONIC. Versions were released for various home computers and video game consoles. It is unrelated to the 1985 film of the same name, which was released six months after the game.

Commando was a critical and commercial success, becoming one of the highest-grossing arcade video games of 1985 and one of the bestselling home video games of 1986. Though not the first military-themed run and gun video game, it spawned numerous clones following its release while popularizing the genre. Its influence can be seen in many shooter games during the late 1980s to early 1990s.', 'https://en.wikipedia.org/wiki/Commando_(video_game)'),
  ('Q1098180', 'Battle Kid: Fortress of Peril is a platform game for the Nintendo Entertainment System released in February 2010 by American developer Sivak Games. It is published through Retrozone with the cover art designed by Larry Bundy Jr. Battle Kid is available for purchase on the Xbox store, the Nintendo Switch eShop, and as a game ROM or physical cartridge for the NES.', 'https://en.wikipedia.org/wiki/Battle_Kid:_Fortress_of_Peril'),
  ('Q1131067', 'Pipe Mania is a puzzle video game developed by The Assembly Line for the Amiga and published in 1989. It was ported to several other platforms by LucasArts as Pipe Dream; the company distributed the game in the US. The player must connect randomly appearing pieces of pipe on a grid to a given length within a limited time.

The Windows version of the game was included in the MS Windows Entertainment Pack. In 1990, it was released as an arcade video game by Japanese manufacturer Video System Co. Ltd., though with slightly altered gameplay, giving the player the task to connect a source and drain with the random pipe pieces.', 'https://en.wikipedia.org/wiki/Pipe_Mania'),
  ('Q1098202', 'Block Hole, released in Japan as Quarth, is a 1989 puzzle video game developed and published by Konami for arcades. It was released in Japan on October 9, 1989 and internationally the same year. It was ported to the MSX2, Famicom and Game Boy as Quarth, with the exception of the European Game Boy Color release of Konami GB Collection Vol.2, where the game was renamed to the generic title Block Game for unknown reasons.

A sequel, Block Quarth, released on the Konami Net i-mode service, with an updated Block Quarth DX in 2001. It was released internationally without the "DX" suffix in 2005.', 'https://en.wikipedia.org/wiki/Block_Hole'),
  ('Q1090190', 'F1 Race is a racing video game developed by HAL Laboratory and published by Nintendo for the Famicom in 1984. It had two "Grand Prix" Famicom Disk System sequels and a Game Boy version.', 'https://en.wikipedia.org/wiki/F1_Race'),
  ('Q1198580', 'Dr. Mario (stylized as D℞ MARIO) is a 1990 puzzle video game developed and published by Nintendo for the Nintendo Entertainment System and Game Boy. A spin-off of the Mario series, it is a falling block puzzle game in which the player''s objective is to destroy the viruses populating the on-screen playing field by using colored capsules that are automatically tossed into the field by Dr. Mario. The player manipulates the falling capsules, to align the same colors, which destroys viruses. The player progresses through the game by eliminating all the viruses on the screen in each level. The game was produced by Gunpei Yokoi and programmed by Takahiro Harada, with the soundtrack composed by Hirokazu Tanaka.', 'https://en.wikipedia.org/wiki/Dr._Mario'),
  ('Q1214813', 'Challenger is an action-platform video game developed and published by Hudson Soft for the Famicom in 1985.', 'https://en.wikipedia.org/wiki/Challenger_(video_game)'),
  ('Q1201014', 'Balloon Fight is a 1984 action video game developed by Nintendo and HAL Laboratory and published by Nintendo for the Nintendo Entertainment System. It was originally released for arcades as VS. Balloon Fight, with the console version releasing in Japan in 1985 and internationally in 1986.

The gameplay is similar to the 1982 game Joust from Williams Electronics. The home Nintendo Entertainment System version was ported to the NEC PC-8801 in October 1985, the Sharp X1 in November 1985, the Game Boy Advance as Balloon Fight-e for the e-Reader in the United States on September 16, 2002, and as part of the Famicom Mini Series in Japan on May 21, 2004.', 'https://en.wikipedia.org/wiki/Balloon_Fight'),
  ('Q1217906', 'Niji no Silk Road is a role-playing video game for the Family Computer. It was developed by Advance Communication Company and published by Victor Musical Industries in 1991. The game was only released in Japan.', 'https://en.wikipedia.org/wiki/Niji_no_Silkroad'),
  ('Q1199765', 'Pooyan is a 1982 fixed shooter video game developed and published by Konami for arcades. It was released in North America by Stern Electronics. The player controls "Mama", a pig whose babies have been kidnapped by a group of wolves. It was later ported to home consoles and personal computers.', 'https://en.wikipedia.org/wiki/Pooyan'),
  ('Q2579866', 'Noah''s Ark is a platform game for the Nintendo Entertainment System produced by British studio Source R&D and published in 1992 by Konami. It was only released in Europe. Unlike most other games based on biblical content released around the same time, this one was officially approved by Nintendo. It is based on the biblical story with the same name. The game was re-released on Steam in 2021.', 'https://en.wikipedia.org/wiki/Noah%27s_Ark_(video_game)'),
  ('Q2585558', 'The Legend of Kage is a 1985 hack and slash platform game developed and published by Taito for arcades. The player controls the ninja Kage, with the objective being to get through five stages in order to save the princess Kirihime. These stages are littered with enemies in the form of ninjas and monks, but Kage has various skills and weapons on his hands in order to get through them.

The arcade release was considered a success for Taito, and exceeded sales expectations at the time of its release. It has been ported to a variety of home systems, has had sequels and spinoffs, and has been featured on various Taito compilations.', 'https://en.wikipedia.org/wiki/The_Legend_of_Kage'),
  ('Q2568153', 'Raid on Bungeling Bay is a shoot ''em up for the Commodore 64 published by Broderbund in 1984 and by Ariolasoft in the UK in 1985. It was the first video game developed by Will Wright and inspired him to create the 1989 game SimCity.', 'https://en.wikipedia.org/wiki/Raid_on_Bungeling_Bay'),
  ('Q2592213', 'The Immortal is a 1990 action-adventure game developed by Will Harvey and released by Electronic Arts in 1990 for the Apple IIGS. It was ported to the Amiga, Atari ST, MS-DOS, Nintendo Entertainment System, and Genesis. A wizard is attempting to find his mentor in a large and dangerous labyrinth. The game has a high degree of graphic violence.

In 2020, the NES port was re-released on the Nintendo Classics service, while the Genesis port was re-released on the Piko Collection Collection 1 cartridge for the Evercade.', 'https://en.wikipedia.org/wiki/The_Immortal_(video_game)'),
  ('Q1153074', 'City Connection is a 1985 platform video game developed and published by Jaleco for arcades. It was released in North America by Kitkorp as Cruisin''. The player controls Clarice in her Honda City hatchback and must drive over elevated roads to paint them. Clarice is pursued by police cars, which she can stun by hitting them with oil cans. The design was inspired by maze chase games like Pac-Man (1980) and Make Trax (1981).

City Connection was ported to the Famicom/Nintendo Entertainment System, MSX and ZX Spectrum. It was re-released in several Jaleco game collections and services such as the Wii''s Virtual Console. These received mixed responses in North America, with critics disliking its simplicity, lack of replay value, and poor controls. Some felt it possessed a cute aesthetic and unique concept and was entertaining. Clarice is one of the first female protagonists in a console game. In Japan, the game has maintained a loyal following, and the NES version is seen as a classic for the platform; Jaleco''s successor, City Connection Co., Ltd., was named after the game.', 'https://en.wikipedia.org/wiki/City_Connection'),
  ('Q1182594', 'Defender of the Crown is a strategy video game designed by Kellyn Beeck. It was Cinemaware''s first game, and was originally released for the Commodore Amiga in 1986, setting a new standard for graphic quality in home computer games.

In 1987 it was ported to MS-DOS, the Atari ST and the Macintosh and a conversion was done for the Commodore 64. Later it was ported to the CDTV, CD-i and Atari Jaguar and conversions were made for the Nintendo Entertainment System (NES), Amstrad CPC, Apple IIGS and Intellivision. Unofficially a ZX Spectrum version was also made. A sequel, Defender of the Crown II, was released in 1993 for the CDTV and Amiga CD32. Two remakes have been released: Robin Hood: Defender of the Crown in 2003 and Defender of the Crown: Heroes Live Forever in 2007.', 'https://en.wikipedia.org/wiki/Defender_of_the_Crown'),
  ('Q1152426', 'Snake''s Revenge (also known as Snake''s Revenge: Metal Gear 2) is a 1990 action-adventure stealth game developed and published by Konami for the Nintendo Entertainment System. It is a stand-alone sequel to Metal Gear that was released in North America (under the Ultra Games brand) and the PAL region following the international commercial success of the NES version. The game was produced without the involvement of series creator Hideo Kojima, who went on to develop a separate sequel for the MSX2 titled Metal Gear 2: Solid Snake, which was released later during the same year in Japan.', 'https://en.wikipedia.org/wiki/Snake%27s_Revenge'),
  ('Q1154059', 'Kirby''s Adventure is a 1993 platform game developed by HAL Laboratory and published by Nintendo for the Nintendo Entertainment System (NES). It is the second game in the Kirby series after Kirby''s Dream Land (1992) on the Game Boy and the first to include the Copy Ability, which allows the main character Kirby to gain new powers by eating certain enemies. The game centers around Kirby traveling across Dream Land to repair the Star Rod after King Dedede breaks it apart and gives the pieces to his minions.

Masahiro Sakurai returned as director after serving the same role for Kirby''s Dream Land. He conceived the copy ability to add more challenge and replay value after the last game received criticism for its simplicity. Because the NES hardware had greater graphical power than the Game Boy and programmers were skilled with the now antiquated hardware, HAL Laboratory was able to create impressive visuals. Kirby''s Adventure is the first game to depict Kirby in color. Sakurai had always planned him to be pink, much to the surprise of other staff.', 'https://en.wikipedia.org/wiki/Kirby%27s_Adventure'),
  ('Q1184959', 'Spelunker is a platform game developed by Timothy G. Martin of MicroGraphicImage and published for Atari 8-bit computers in 1983. It is set in a cave, with the player starting at the cave''s entrance at the top. The objective is to get to the treasure at the bottom.

Spelunker was ported to the Commodore 64, then re-released by Broderbund in 1984, with European publishing rights licensed to Ariolasoft. It was released as an arcade video game in 1985, on the Nintendo Entertainment System on December 7, 1985 in Japan and September 1987 in North America, and MSX in 1986. An arcade sequel was released in 1986 as Spelunker II: 23 no Kagi, and a different sequel for the NES on September 18, 1987 called Spelunker II: Yūja e no Chōsen, both by Irem and in Japan only.', 'https://en.wikipedia.org/wiki/Spelunker_(video_game)'),
  ('Q1152295', 'Snow Bros. is a 1990 platform video game developed and published by Toaplan for Japanese arcades; it was distributed by Romstar in North America and Europe. Players control snowman twins Nick and Tom as they travel through 50 stages, using snowballs as weapons while navigating obstacles and battling monsters in order to rescue the princesses Puripuri and Puchipuchi. The game was later ported to multiple platforms, each one by different third-party developers and featuring several changes or additions. Versions for various microcomputers were in development, but were never officially released.

Snow Bros. was met with mostly positive reception from critics and players alike, earning an award from Gamest magazine and gaining a cult following since its initial release. In 1994, a sequel titled Snow Bros. 2: With New Elves was released by Hanafram, serving as the last game by Toaplan prior to their closure. The rights to Snow Bros. are currently owned by Tatsujin, a Japanese company formed by Masahiro Yuge. A modernized version of the game, titled Snow Bros Special, was developed by CRT Games and published by Daewon Media Game Lab and Clear River Games for Nintendo Switch, and was released in May 2022. A third installment in the series, Snow Bros. Wonderland, was released in 2024.', 'https://en.wikipedia.org/wiki/Snow_Bros.'),
  ('Q1143274', 'Wizards & Warriors, titled Densetsu no Kishi Elrond in Japan, is an action platform video game developed by Rare and published by Acclaim Entertainment for the Nintendo Entertainment System. It was released in North America in December 1987, in Japan on 15 July 1988, and in Europe on 7 January 1990. The player controls Kuros, "Knight Warrior of the Books of Excalibur", as he sets out in the Kingdom of Elrond to defeat the evil wizard Malkil. Malkil holds the princess of Elrond captive in Castle IronSpire, deep within the forests of Elrond. The player fights through forests, tunnels, and caves, while collecting keys, treasure, weapons, and magic items.', 'https://en.wikipedia.org/wiki/Wizards_%26_Warriors'),
  ('Q1145485', 'Nintendo World Cup, released in Japan as Nekketsu High School Dodgeball Club: Soccer Story, is a 1990 soccer video game developed by Technōs Japan for the Nintendo Entertainment System. It was localized and released outside Japan by Nintendo, with a Game Boy port also being released. It is the fourth installment of the Kunio-kun series. Ports for the PC Engine and Mega Drive were also released in Japan.', 'https://en.wikipedia.org/wiki/Nintendo_World_Cup'),
  ('Q1151856', 'Rygar is a 1986 platform game developed and published by Tecmo for arcades. The player assumes the role of a "Legendary Warrior" who must navigate numerous levels and defeat enemies with a weapon called the "Diskarmor", a razor-sharp shield with a long chain attached to it that operates like a yo-yo. The warrior intends to defeat Ligar, an evil "dominator". Later ports, particularly the NES and Lynx versions, expanded on the near non-existent story from the original.

The game was subsequently ported to the NES (1987), Commodore 64 (1987), ZX Spectrum (1987), Amstrad CPC (1987), Master System (1988), Atari Lynx (1990), and X68000 (1994); Nintendo released the NES version in arcades in 1987. Emulated re-releases of different versions have also been released for Xbox (2005), Sprint mobile phones (2005), Wii (2009), PlayStation 4 (2014), Nintendo Switch (2018) and Android (2023). A remake, Rygar: The Legendary Adventure, was released for PlayStation 2 in 2002. The Legendary Adventure was remastered for the Wii in 2008 as Rygar: The Battle of Argus.', 'https://en.wikipedia.org/wiki/Rygar'),
  ('Q2904335', 'Super Dimension Fortress Macross is a side-scrolling shooter video game released by Namco for the Famicom in 1985. Based on the popular anime television series of the same name, the player controls a transformable VF-1 Valkyrie variable fighter in an unending battle against an invading race of giant humanoid aliens known as the Zentradi.

It is one of the earliest known collaborations between Namco and Bandai, both of which would eventually merge into Bandai Namco Entertainment in 2005.', 'https://en.wikipedia.org/wiki/The_Super_Dimension_Fortress_Macross_(1985_video_game)'),
  ('Q2933783', 'Clash at Demonhead, known in Japan as Dengeki Big Bang!, is an action-adventure platform game released by Vic Tokai for the Nintendo Entertainment System on January 27, 1989 in Japan and December 1989 in North America.', 'https://en.wikipedia.org/wiki/Clash_at_Demonhead'),
  ('Q2914658', 'Godzilla: Monster of Monsters! is a Nintendo Entertainment System video game released in Japan in 1988 and in 1989 in the US by Toho Co., Ltd. The North American version removes all references to Toho Cenfile-Soft Library and Compile, crediting the game to Toho Eizo on the title screen instead.', 'https://en.wikipedia.org/wiki/Godzilla:_Monster_of_Monsters!'),
  ('Q2955894', 'Championship Pool is a 1993 sports simulation video game released for Nintendo Entertainment System, Super Nintendo Entertainment System, Game Boy, Mega Drive/Genesis, and MS-DOS. The pool (pocket billiards) game was developed by Bitmasters and released by Mindscape. The game was officially endorsed by the Billiard Congress of America.', 'https://en.wikipedia.org/wiki/Championship_Pool'),
  ('Q2937645', 'Captain Planet and the Planeteers is a 1991 video game released for various platforms in the early 1990s, loosely based on the environmentalist animated series Captain Planet and the Planeteers. Three versions were developed to suit three different platform capabilities, each with markedly different gameplay.', 'https://en.wikipedia.org/wiki/Captain_Planet_and_the_Planeteers_(video_game)'),
  ('Q2944565', 'The Jetsons: Cogswell''s Caper! is a 1993 video game based on the animated sitcom The Jetsons. It was developed by Natsume and published by Taito for the Nintendo Entertainment System/Family Computer, and was released in the United States in 1992 and in other territories in 1993.', 'https://en.wikipedia.org/wiki/The_Jetsons:_Cogswell%27s_Caper!'),
  ('Q2924799', 'Ring King, known as King of Boxer in Japan and Europe, is an arcade boxing game developed by Woodplace. It was published in 1985 by Woodplace in Japan and Europe, and by Data East in North America.', 'https://en.wikipedia.org/wiki/Ring_King'),
  ('Q285402', 'Panic Restaurant, known in Japan as Wanpaku Kokkun no Gourmet World, is a 1992 platform game developed by EIM and published by Taito for the Nintendo Entertainment System.

Panic Restaurant stars a chef named Cookie who must navigate through his own restaurant, which has been cursed by a rival chef named Ohdove. Cookie has to battle evil food monsters with kitchen utensil weapons in six levels before taking on Ohdove in a final battle.', 'https://en.wikipedia.org/wiki/Panic_Restaurant'),
  ('Q240143', 'Maniac Mansion is a 1987 graphic adventure video game developed and published by Lucasfilm Games. It follows teenage protagonist Dave Miller as he attempts to rescue his girlfriend Sandy Pantz from a mad scientist, whose mind has been enslaved by a sentient meteor. The player uses a point-and-click interface to guide Dave and two of his six playable friends through the scientist''s mansion while solving puzzles and avoiding dangers. Gameplay is non-linear, and the game must be completed in different ways based on the player''s choice of characters. Initially released for the Commodore 64 and Apple II, Maniac Mansion was Lucasfilm Games'' first self-published product.', 'https://en.wikipedia.org/wiki/Maniac_Mansion'),
  ('Q281924', 'Garry Kitchen''s Battletank is an action video game released by Absolute Entertainment in September 1990 for the Nintendo Entertainment System. The game is similar to the Atari game Battlezone, and supports one player. Code from its development was meant for a space flight game for the Commodore 64.', 'https://en.wikipedia.org/wiki/Battletank'),
  ('Q248241', 'Armadillo is a platform video game, published by IGS for the Family Computer. It was released in Japan on August 9, 1991 for the Family Computer. The game was not released in other countries.', 'https://en.wikipedia.org/wiki/Armadillo_(video_game)'),
  ('Q288754', 'Dragon Buster is a 1985 action role-playing video game developed and published by Namco for arcades. It was released in Japan in January 1985 and Europe in May 1985. It was ported to the Family Computer (Famicom), MSX, and X68000; the latter version was later released for the Virtual Console in the same region on November 18, 2008. Dragon Buster has been ported for the PSP and is available as part of Namco Museum Battle Collection. It was followed by a Japan-only Famicom sequel, Dragon Buster II: Yami no Fūin, and was later followed by the PlayStation game Dragon Valor, which was both a remake and a sequel.', 'https://en.wikipedia.org/wiki/Dragon_Buster'),
  ('Q2592852', 'Big Nose the Caveman is a side-scrolling platform game developed by Optimus Software and released in 1991 by Camerica for the Nintendo Entertainment System and by Codemasters for the Amiga and the Atari ST. A Master System and Game Gear version called Dinobasher was completed, but never published.

The game was followed by a sequel, Big Nose Freaks Out, in 1992.', 'https://en.wikipedia.org/wiki/Big_Nose_the_Caveman'),
  ('Q2799054', 'Baseball Simulator 1.000 is a baseball sports video game released on the NES. It was released in 1989 in Japan and in 1990 in North America.', 'https://en.wikipedia.org/wiki/Baseball_Simulator_1.000'),
  ('Q2800857', 'Flight of the Intruder is a flight simulation video game developed by Rowan Software and published by Spectrum HoloByte in 1990 for MS-DOS, Amiga, and Atari ST. A conversion to the Nintendo Entertainment System by Imagineering was published by Mindscape in 1991. The game is based on the novel of the same name and received as the successor of the first game of the Falcon video game series.', 'https://en.wikipedia.org/wiki/Flight_of_the_Intruder_(video_game)'),
  ('Q2613588', 'The Untouchables is an action video game released by Ocean Software in 1989 on ZX Spectrum, Amstrad CPC, Commodore 64, MSX, Atari ST, Amiga, MS-DOS, Nintendo Entertainment System, and Super NES. It is based on the 1987 film The Untouchables.', 'https://en.wikipedia.org/wiki/The_Untouchables_(video_game)'),
  ('Q2615980', 'V''Ball is a 1988 volleyball video game developed and published by Technōs Japan for arcades. It was released in North America by Taito. A Nintendo Entertainment System version was published by Technōs in Japan and by Nintendo in North America and PAL regions under the title Super Spike V''Ball. A version for the X68000 computer was developed and released by SPS exclusively in Japan.', 'https://en.wikipedia.org/wiki/V%27Ball'),
  ('Q2604860', 'Fire Emblem Gaiden is a 1992 tactical role-playing game developed by Intelligent Systems and published by Nintendo for the Family Computer. It is the second installment in the Fire Emblem series and the last to be developed for the Famicom. It builds upon the basic turn-based strategy gameplay of the previous title, while including new elements such as a navigable overworld. Set in the same world as its predecessor, Fire Emblem: Shadow Dragon and the Blade of Light, Gaiden follows the battles of two opposing armies on the continent of Valentia, which is torn apart by political strife involving the princess Celica and her childhood friend Alm.', 'https://en.wikipedia.org/wiki/Fire_Emblem_Gaiden'),
  ('Q2796607', 'Ikari Warriors, known as Ikari in Japan, is a 1986 run and gun video game developed and published by SNK for arcades. It was released in North America by Tradewest. Amongst the numerous Commando clones on the market, Ikari Warriors was distinguished by its unique control style with rotary joysticks and a two-player cooperative mode. The rotary joystick controls were in turn based on SNK''s earlier TNK III (1985). Ikari was originally intended to be an official licensed adaptation of the film Rambo: First Blood Part II (1985), but SNK were initially unable to acquire the rights to the film.

The game was a major commercial success in arcades. It was Japan''s second highest-grossing table arcade in 1986, and London''s third highest-grossing arcade game that year. It was also a major breakthrough US release for SNK, ranking among America''s top five highest-grossing dedicated arcade games for two years in a row, in 1986 and 1987.', 'https://en.wikipedia.org/wiki/Ikari_Warriors'),
  ('Q1308649', 'Skate or Die! is a skateboarding video game released by Electronic Arts (EA) in 1987 for the Commodore 64. It is EA''s first internally developed game. Versions for the Apple IIGS, MS-DOS, Amstrad CPC, and ZX Spectrum followed. It was ported to the Nintendo Entertainment System by Konami, published under the company''s Ultra Games branding.', 'https://en.wikipedia.org/wiki/Skate_or_Die!'),
  ('Q2815984', 'The 3-D Battles of WorldRunner (shortened to 3-D WorldRunner on the North American box art), originally released in Japan as Tobidase Daisakusen, is a 1987 third-person rail shooter platform video game developed and published by Square for the Family Computer Disk System. It was later ported to cartridge format and published by Acclaim for the Nintendo Entertainment System.

For its time, the game was technically advanced; the game''s three-dimensional scrolling effect is very similar to the linescroll effects used by Pole Position and many racing games of the day as well as the forward-scrolling effect of Sega''s 1985 third-person rail shooter Space Harrier. 3-D WorldRunner was an early forward-scrolling pseudo-3D third-person platform-action game where players were free to move in any forward-scrolling direction and had to leap over obstacles and chasms. It was also one of the first stereoscopic 3-D games. WorldRunner was designed by Hironobu Sakaguchi and Nasir Gebelli, with music composed by Nobuo Uematsu. All were later core members of the team behind the Final Fantasy role-playing video game series.', 'https://en.wikipedia.org/wiki/The_3-D_Battles_of_WorldRunner'),
  ('Q2606702', 'Donkey Kong is a 1981 platform game developed and published by Nintendo for arcades. As Mario (occasionally referred to as "Jumpman" at the time), the player runs and jumps onto platforms and climbs ladders to ascend a construction site and rescue Pauline (occasionally referred to as "The Lady" at the time) from the giant gorilla Donkey Kong. It is the first game in the Donkey Kong series and Mario''s first appearance in a video game.

Donkey Kong was created to salvage unsold arcade cabinets following the failure of Nintendo''s Radar Scope (1980), and was designed for Nintendo of America''s audience. Hiroshi Yamauchi, Nintendo''s president at the time, assigned the project to first-time video game designer Shigeru Miyamoto. Drawing inspiration from "Beauty and the Beast" and American media such as Popeye and King Kong, Miyamoto developed the characters and scenario and designed the game alongside chief engineer Gunpei Yokoi. Donkey Kong was the most complex arcade game released at that point, using graphics for characterization, including cutscenes to illustrate a plot, and integrating multiple unique stages into the gameplay. The game pioneered the platform genre before the term existed, is the first to feature jumping, and is one of the first video games with a damsel in distress narrative, after Sheriff. It had a limited release in Japan on July 9, 1981, before receiving a wide release in the region some weeks later.', 'https://en.wikipedia.org/wiki/Donkey_Kong_(1981_video_game)'),
  ('Q2593819', 'Mickey Mousecapade, released in Japan as Mickey Mouse: Adventures in Wonderland, is a platform video game based on Disney''s Mickey Mouse franchise. It was developed and published by Hudson Soft originally in 1987 for the Family Computer in Japan. Capcom published the game for the Nintendo Entertainment System in the United States in 1988.', 'https://en.wikipedia.org/wiki/Mickey_Mousecapade'),
  ('Q1284570', 'M.U.L.E. is a 1983 strategy video game written for Atari 8-bit computers by Ozark Softscape. Designer Danielle Bunten Berry (credited as Dan Bunten) takes advantage of the four joystick ports of the Atari 400 and 800 to allow four-player simultaneous play. Published in 1983, M.U.L.E. was one of the first five games from Electronic Arts, alongside Axis Assassin, Archon: The Light and the Dark, Worms?, and Hard Hat Mack. M.U.L.E. is primarily a turn-based strategy game, but also incorporates real-time elements where players compete directly, as well as aspects that simulate economics.

The game was ported to the Commodore 64, Nintendo Entertainment System, and IBM PC compatibles (as a self-booting disk). Japanese versions were also released for the PC-88, Sharp X1, and MSX2 computers. Like the subsequent Atari 8-bit models, none of these systems allow four players with separate joysticks. The Commodore 64 version lets four players share joysticks, with two players using the keyboard during action portions.', 'https://en.wikipedia.org/wiki/M.U.L.E.'),
  ('Q1319139', 'Kung-Fu Master, known as Spartan X in Japan, is a 1984 beat ''em up game developed and published by Irem for arcades. It was distributed by Data East in North America. Designed by Takashi Nishiyama, the game was based on Hong Kong martial arts films. It is a loose adaptation of the Jackie Chan, Sammo Hung and Yuen Biao film Wheels on Meals (1984), called Spartan X in Japan. The protagonist Thomas is named after Jackie Chan''s character in the film. It is also heavily inspired by the Bruce Lee film Game of Death (1972), which was the basis for the game''s concept. Nishiyama, who had previously designed the side-scrolling shooter Moon Patrol (1982), combined fighting elements with a shoot ''em up gameplay rhythm. Irem and Data East exported the game to the West without the Spartan X license.', 'https://en.wikipedia.org/wiki/Kung-Fu_Master_(video_game)'),
  ('Q2803175', 'Chaos World is a role-playing video game developed and published by Natsume for the Family Computer in Japan in 1991.', 'https://en.wikipedia.org/wiki/Chaos_World'),
  ('Q2829419', 'Al Unser Jr.''s Turbo Racing is a racing video game released by Data East for the Nintendo Entertainment System in 1990. It is an adaptation of the 1989 Japanese-market Famicom game World Grand Prix - Pole to Finish, with the most notable changes being the addition of Unser as an in-game coach, the number of laps, sound and interface design. Therefore, the game remains based on the Formula 1 World Championship, despite Unser having never competed in it. This game features a season mode and two time trial modes. In season mode the player uses either Al Unser Jr. or a make-their-own-driver.

Versions released outside North America were simply titled Turbo Racing with all references to Al Unser Jr removed, due to the relative obscurity of CART and Al Unser Jr outside of North America.', 'https://en.wikipedia.org/wiki/Al_Unser_Jr.%27s_Turbo_Racing'),
  ('Q1224575', 'Dig Dug II is a 1985 action video game developed and published by Namco for arcades. It was initially only released in Japanese arcades in March 1985. It is a sequel to 1982''s Dig Dug. Pookas and fire-breathing Fygars return as the enemies, but the side view tunneling of the original is replaced with an overhead view of an island maze.', 'https://en.wikipedia.org/wiki/Dig_Dug_II'),
  ('Q2609577', 'Top Players'' Tennis (called World Super Tennis in Japan and Four Players'' Tennis in Europe) is a tennis video game developed by Home Data for the Nintendo Entertainment System. It was released in Japan in 1989 and North America in 1990 by Asmik and Europe in 1992 by Nintendo.

The game cover prominently features tennis champions Chris Evert and Ivan Lendl, both of whom are former number 1 ranked singles players.', 'https://en.wikipedia.org/wiki/Top_Players%27_Tennis'),
  ('Q2819439', 'Alpha Mission, known as ASO: Armored Scrum Object in Japan, is a 1985 vertically scrolling shooter video game developed and published by SNK for arcades. It was released by Tradewest in North America. It was later ported to the Famicom in 1986 and released for the Nintendo Entertainment System in 1987.

The arcade game was a commercial success in Japan, where it was the seventh highest-grossing table arcade game of 1986. A sequel, Alpha Mission II, was released for the Neo Geo arcade system in 1991.', 'https://en.wikipedia.org/wiki/Alpha_Mission'),
  ('Q2098302', 'Target: Renegade (stylized as TARGET; RENEGADE) is a beat''em up video game released on the Amstrad CPC, Commodore 64 and ZX Spectrum systems in the late 1980s by Ocean Software on their "Imagine" label, as well as a Nintendo Entertainment System version developed by Software Creations and published by Taito. The game is a sequel to Renegade and was followed by Renegade III: The Final Chapter.', 'https://en.wikipedia.org/wiki/Target:_Renegade'),
  ('Q1327963', 'Xevious is a vertical scrolling shooter video game developed and published by Namco for arcades. Following location tests in December 1982, it had a wide release in February 1983 for Japan and for North America by Atari, Inc. Controlling the Solvalou starship, the player attacks Xevious forces before they destroy all of mankind. The Solvalou has two weapons at its disposal: a zapper to destroy flying craft, and a blaster to bomb ground installations and enemies. It runs on the Namco Galaga arcade system. An upgraded version, Super Xevious, was released in December 1984.

The game was designed by Masanobu Endō and a small team. Created to rival the success of Scramble, it was originally themed around the Vietnam War and titled Cheyenne. Endō wanted the game to have a detailed, integral storyline and a comprehensive world, and to be welcoming for newer players. Several enemies and characters were made to pay homage to other popular science fiction works, including Star Wars, UFO, Alien and Battlestar Galactica.', 'https://en.wikipedia.org/wiki/Xevious'),
  ('Q2096756', 'Sid Meier''s Pirates! is a 1987 action-adventure strategy video game developed and published by MicroProse for the Commodore 64. It was designed by Sid Meier, and was the first game to include his name in its title as an effort by MicroProse to attract fans of Meier''s earlier games, most of which were combat vehicle simulation games. The game was later ported to several other platforms, including the Amstrad CPC, Apple II, Macintosh, IBM PC, Atari ST, Amiga and Nintendo Entertainment System.

Set in the Caribbean, the game is a simulation of the life of a pirate, a privateer, or a pirate hunter in the 16th, 17th and 18th centuries. The Pirates! playing field includes the Spanish Main (namely the northern coast of South America), Central America and the Yucatán Peninsula, the entire Gulf of Mexico, Florida, and all Caribbean islands, plus Bermuda in the PC version. The player is free to sail to any part of the above-mentioned lands, stopped by an invisible barrier southeast of Trinidad, all the way north to just northeast of Bermuda.', 'https://en.wikipedia.org/wiki/Sid_Meier%27s_Pirates!'),
  ('Q2088772', 'Legendary Wings, released in Japan as Aresu no Tsubasa, is a 1986 vertically scrolling shooter and run and gun video game developed and published by Capcom for arcades. The player takes control of a young soldier equipped with magical wings who must save the world from a malfunctioning supercomputer. A home version for the Nintendo Entertainment System was released exclusively in North America in 1988. The original coin-op version is included in Capcom Classics Collection for PlayStation 2 and Xbox and in Capcom Classics Collection Remixed for PlayStation Portable.', 'https://en.wikipedia.org/wiki/Legendary_Wings'),
  ('Q1321796', 'Doraemon is a 1986 action video game developed and published by Hudson Soft for the Family Computer exclusively in Japan. It is based on Fujiko F. Fujio''s (the pen name of Hiroshi Fujimoto) Japanese manga series of the same name, which later became an anime series and Asian franchise. It was the tenth best selling Famicom game released in 1986, selling approximately 1,150,000 copies in its lifetime. It is the third game created for the Doraemon license after the versions created for the Arcadia 2001 and the Epoch Cassette Vision. Even though the game is playable without any knowledge of Japanese, fan translations are available.', 'https://en.wikipedia.org/wiki/Doraemon_(1986_video_game)'),
  ('Q2103276', 'R.B.I. Baseball 2 is a sports video game released for the Nintendo Entertainment System in 1990 by Tengen. It is the second game in the R.B.I. Baseball series.', 'https://en.wikipedia.org/wiki/R.B.I._Baseball_2'),
  ('Q2083880', 'Ikki is a 1985 top-down shooter video game developed and published by Sunsoft for arcades. A port developed by Tose for the Famicom was negatively received.

The game was re-released as part of multiple compilations. A mobile phone version was published in September 2003. A renewed version titled Ikki Mobile was released over the SoftBank Mobile and EZweb networks in July 2006. A revival of the game, titled Ikki Unite, was released in 2023.', 'https://en.wikipedia.org/wiki/Ikki_(video_game)'),
  ('Q1324646', 'Gradius is a 1985 horizontally scrolling shooter video game developed and published by Konami for arcades. It is the first installment in the Gradius series. The player maneuvers a spacecraft known as the Vic Viper that must defend itself from the various alien enemies. The game uses a power-up system called the "power meter", based upon collecting capsules to acquire additional weapons.

The arcade version of Gradius was initially released internationally outside Japan under the title of Nemesis, but subsequent home releases have since used the original title. During development, it had the working title Scramble 2, as it was originally intended to be a follow-up to Konami''s earlier shooter Scramble (1981). Home versions were released for various platforms, such as the Nintendo Entertainment System, the MSX home computer, and the PC Engine. It was a major success in 1986, becoming the year''s highest-grossing arcade game in London and one of Japan''s top five table arcade games, while the Famicom port sold over a million copies in Japan that year. Nintendo released the NES version in arcades for the Nintendo VS. System as VS. Gradius and PlayChoice-10 in November 1986.', 'https://en.wikipedia.org/wiki/Gradius_(video_game)'),
  ('Q1323953', 'Antarctic Adventure is a video game developed by Konami in 1983 for the MSX, and later for video game consoles, such as the Family Computer and ColecoVision. The player takes the role of an Antarctic penguin, racing to various research stations owned by different countries in Antarctica (excluding the USSR).

The gameplay is similar to Sega''s Turbo, but plays at a much slower pace, and features platform game elements. The penguin, later named Penta, must reach the next station before time runs out while avoiding sea lions and breaks in the ice. Throughout the levels, fish jump out of ice holes and can be caught for bonus points. The game, like many early video games, has no ending – when the player reaches the last station, the game starts from the first level again, but with increased difficulty.', 'https://en.wikipedia.org/wiki/Antarctic_Adventure'),
  ('Q1353918', 'Thexder is a run and gun video game from Game Arts, originally released for the NEC PC-8801 in 1985. It was ported to many systems, including the Famicom, MSX, Apple II, and MS-DOS. It was a commercial success, selling over one million units worldwide.', 'https://en.wikipedia.org/wiki/Thexder'),
  ('Q1330641', 'Adventures of Lolo is a 1989 puzzle video game developed and published by HAL Laboratory for the Nintendo Entertainment System. It is a compilation of puzzles from Eggerland: Meikyū no Fukkatsu and Eggerland: Sōzō he no Tabidachi. It is the fifth game in the Eggerland series, the third one released in Europe, but the first one released in North America. It was available on the Wii''s and Wii U''s Virtual Console in North America and in PAL regions, as well as on the Nintendo Switch''s Nintendo Classics service.

The game received two direct sequels: the Japanese Adventures of Lolo, which consists entirely of new stages, and the American Adventures of Lolo 2, another collection of stages from earlier Japanese games. However, in 1994, a game titled Adventures of Lolo was released for Game Boy in Europe and Japan, which was not the same game as the original NES version, but rather the tenth installment in the series, with continued additions to the base gameplay.', 'https://en.wikipedia.org/wiki/Adventures_of_Lolo'),
  ('Q1328124', 'Yoshi''s Cookie is a 1992 tile-matching puzzle video game developed by Tose and published by Nintendo for the NES and Game Boy platforms in 1992. A SNES version was released the following year, developed and published by Bullet-Proof Software. The game received generally positive reviews from critics, with praise for its simple but addictive gameplay and its presentation.', 'https://en.wikipedia.org/wiki/Yoshi%27s_Cookie'),
  ('Q1330205', 'Paperboy is a 1985 action video game developed and published by Atari Games for arcades. The player takes the role of a paperboy who delivers a fictional newspaper called The Daily Sun to houses on a street while riding his bicycle. The arcade version featured bike handlebars as the controller.

The game was widely ported to home systems beginning in 1986, and was followed by the computer and console-exclusive sequel Paperboy 2 in 1991.', 'https://en.wikipedia.org/wiki/Paperboy_(video_game)'),
  ('Q2081556', 'Tiny Toon Adventures 2: Trouble in Wackyland (originally released in Japan as Tiny Toon Adventures 2: Montana Land e Yōkoso) is a Tiny Toon Adventures-based video game, released on the Nintendo Entertainment System in 1993, and developed and published by Konami. The story involves Montana Max inviting everyone to a new amusement park in Acme Acres, under the alias of a "secret admirer".', 'https://en.wikipedia.org/wiki/Tiny_Toon_Adventures_2:_Trouble_in_Wackyland'),
  ('Q2081247', 'Insector X is a horizontally scrolling shooter developed by Hot-B and released in arcades by Taito in 1989. It was ported to the Mega Drive and Famicom.', 'https://en.wikipedia.org/wiki/Insector_X'),
  ('Q2079498', 'Binary Land is a puzzle video game developed by Hudson Soft in 1983 for the MSX, FM-7, PC-6001mkII, NEC PC-8801, Sharp MZ-2200, Sharp MZ-5500, Sharp X1 and in 1985 for the Famicom. The MSX version saw release in Japan by Hudson Soft and in Europe by Kuma Computers Ltd in 1984.

While the Famicom version has 99 levels, there is no ending screen implemented in the game.', 'https://en.wikipedia.org/wiki/Binary_Land'),
  ('Q2079413', 'MotoRace USA (also known as Traverse USA, in Japan as Zippy Race, and in Spain as Mototour) is a 1983 racing video game developed and published by Irem for Japanese arcades; it was released in North America by Williams Electronics and in Europe by Comercial Electronica. The player controls a racer who must travel on a motorcycle from Los Angeles to New York City.', 'https://en.wikipedia.org/wiki/MotoRace_USA'),
  ('Q2078681', 'Air Fortress is an action-adventure video game developed and published by HAL Laboratory for the Nintendo Entertainment System. It was released in Japan in August 1987, in North America in September 1989 after an initial test release of 385 copies in 1987, and an Australian release in 1989.', 'https://en.wikipedia.org/wiki/Air_Fortress'),
  ('Q2068615', 'Attack of the Killer Tomatoes is a 2D platform game developed by Imagineering and released in 1991 for the NES. A Game Boy version was released in 1992 and although it uses the same cover as the original NES game, it is not a port of that version. The Game Boy version was developed by Equilibrium and published by THQ in Europe and the US. It was also released in Japan, where it was published by Altron in 1993.

The game is based on the children''s cartoon Attack of the Killer Tomatoes: The Animated Series, which itself was based on the movie franchise Attack of the Killer Tomatoes.', 'https://en.wikipedia.org/wiki/Attack_of_the_Killer_Tomatoes_(1991_video_game)'),
  ('Q2995918', 'Contra Force is a 1992 run and gun game developed and published by Konami for the Nintendo Entertainment System in North America. It is part of the Contra series, being the third game in the series released for the NES following the original Contra and Super Contra. However, the game''s plot and setting are unrelated to both previous and succeeding entries, as the villains in the game are human terrorists instead of an alien menace. The game was scheduled to be released in Japan under the title of Arc Hound, with no ties to the Contra series, but was cancelled.', 'https://en.wikipedia.org/wiki/Contra_Force'),
  ('Q2998156', 'Alex DeMeo''s Race America (also known in Europe as Corvette ZR-1 Challenge) is a racing video game developed by Imagineering and published by Absolute Entertainment for the Nintendo Entertainment System in 1990 in Europe and 1992 in North America. The European version received the Chevrolet license to use its Corvette ZR-1 vehicles while those in the North American version had to be redesigned into vehicles that strongly resembled Dodge Vipers.', 'https://en.wikipedia.org/wiki/Race_America'),
  ('Q2979079', 'Two beat ''em up platform video games based on the film Cliffhanger (1993) were released in 1993. One was developed by Spidersoft for the Nintendo Entertainment System (NES), Game Boy, Game Gear and Amiga. Another was developed by Malibu Interactive for the Super Nintendo Entertainment System (SNES), Sega Genesis, and Sega CD. Sony Imagesoft published all except the Amiga version, which was published by Psygnosis.', 'https://en.wikipedia.org/wiki/Cliffhanger_(video_game)'),
  ('Q2982608', 'Ski or Die is a 1990 winter sports game by Electronic Arts for the Amiga, NES, MS-DOS, and Commodore 64. It consists of five minigames which can be played individually or in a set sequentially. Up to six players can compete against each other via hotseat in four of the minigames, and semi-hotseat in one of them (up to two players at a time). The minigames are halfpipe-snowboarding, inflatable sled racing, aerial skiing, downhill skiing, and snowball fights. The shopkeeper was represented by Rodney Dangerfield.

The MS-DOS port supports Roland MT-32 and AdLib audio.', 'https://en.wikipedia.org/wiki/Ski_or_Die'),
  ('Q2984372', 'Color a Dinosaur is a 1993 coloring book video game developed by FarSight Studios for the Nintendo Entertainment System. It was created with a budget of $30,000 and, according to producer Stephen Clarke-Wilson, "produced on the cheapest cartridge that Nintendo made". It was only sold at Walmart.', 'https://en.wikipedia.org/wiki/Color_a_Dinosaur'),
  ('Q2981165', 'Cobra Command is a horizontally scrolling shooter released as an arcade video game by Data East in 1988. A port was published for the Nintendo Entertainment System later the same year.', 'https://en.wikipedia.org/wiki/Cobra_Command_(1988_video_game)'),
  ('Q3001743', 'The Mafat Conspiracy is a Nintendo Entertainment System video game released in 1990. It is the sequel to Golgo 13: Top Secret Episode. It was published by Vic Tokai, which went defunct in 1997.

The Mafat Conspiracy follows professional hitman Golgo 13, who is hired to stop the mysterious terrorist organization Mafat, an organization working to provoke war between the United States and Soviet Union.', 'https://en.wikipedia.org/wiki/The_Mafat_Conspiracy'),
  ('Q2962094', 'Fantasy Zone is a 1986 horizontally scrolling shooter video game developed and published by Sega for arcades. It is the first game in the Fantasy Zone series, and was later ported to several home consoles, including Sega''s Master System. The player controls a sentient spaceship named Opa-Opa who fights an enemy invasion in the titular group of planets. The game contains a number of features atypical of the traditional scrolling shooter. The main character, Opa-Opa, is sometimes referred to as Sega''s first mascot character.

The game''s design and main character have similarities to Konami''s TwinBee, and both games are credited with establishing the cute ''em up subgenre. Fantasy Zone also popularized the concept of a boss rush, a stage where the player faces multiple previous bosses again in succession. The game was followed by several sequels, beginning with Fantasy Zone II: The Tears of Opa-Opa in 1987.', 'https://en.wikipedia.org/wiki/Fantasy_Zone'),
  ('Q3029726', 'Dirty Harry is a 1990 video game based on the Dirty Harry film franchise starring Clint Eastwood. It was developed by Canadian studio Gray Matter and released exclusively for the Nintendo Entertainment System (NES).', 'https://en.wikipedia.org/wiki/Dirty_Harry_(1990_video_game)'),
  ('Q3031530', 'Little League Baseball: Championship Series is a 1990 video game for the Nintendo Entertainment System.', 'https://en.wikipedia.org/wiki/Little_League_Baseball:_Championship_Series'),
  ('Q3006152', 'Metal Slader Glory is an adventure game developed and published by HAL Laboratory for the Family Computer in 1991. The game is set in 2062 after humans have colonized the Moon and established several space stations. Earth-based mechanic Tadashi and his girlfriend Elina discover a mech from a war eight years past with an ominous message stored in its memory suggesting Earth is in danger. Tadashi decides to venture to nearby space colonies along with Elina and his younger sister Azusa to investigate the origins of the mech. As Tadashi, the player speaks with other characters and picks dialogue and action commands to advance the narrative.', 'https://en.wikipedia.org/wiki/Metal_Slader_Glory'),
  ('Q3001971', 'Crackout is a video game by Konami that was released in Japan for the Family Computer Disk System on December 13, 1986, and in Europe and Australia for the Nintendo Entertainment System in 1991. It is a Breakout clone, with some additional elements not normally found in other games in the genre.', 'https://en.wikipedia.org/wiki/Crackout_(video_game)'),
  ('Q3008142', 'Cyberball is a 1988 sports video game developed and published by Atari Games for arcades. Set in the year 2022, the game is a 7-man variation of American football using robotic avatars of different speeds, sizes, and skill sets. Cyberball was ported to several home consoles and computers, including the Sega Genesis, Atari Lynx, and Nintendo Entertainment System.

The original Cyberball arcade game was released as a large cabinet with two monitors, each with two sets of controls for one or two players. Players on each side could play against computer opponents or head-to-head on opposing monitors for a maximum of four players. In 1989, Atari Games released a sequel to the original Cyberball in both the same large dual-monitor cabinet, titled Tournament Cyberball 2072, as well as a standalone two-player cabinet titled Cyberball 2072. The sequel included improved gameplay, which included refined player movements and more offensive plays and defensive formations, and changed its setting to 2072. Also shipped in 1989 were several conversion kits to modify existing cabinets to Tournament Cyberball 2072 or the two-player-only Cyberball 2072.', 'https://en.wikipedia.org/wiki/Cyberball'),
  ('Q3073362', 'Flappy is a puzzle video game released in 1983 by dB-SOFT in the same vein as the Eggerland series and Sokoban that is obscure outside Japan. It stars Flappy, a somewhat mole-like character who must complete each level by pushing a blue stone from its starting place to the blue tile destination.

Flappy first appeared on the Sharp X1 home computer in 1983. This debut was soon followed by conversions to a number of popular Japanese computers in the early 1980s, including the NEC''s line of PCs and the Fujitsu FM series. Ports for the MSX computer line and the Family Computer were released in 1985. dB-SOFT produced a sequel with more difficult puzzles called King Flappy for the benefit of anyone who managed to clear the original 200 levels (or "sides" or "scenes" as the game calls them). A Nintendo Game Boy port was released exclusively in Japan in 1990 and was published by Victor Musical Industries.', 'https://en.wikipedia.org/wiki/Flappy'),
  ('Q3098364', 'Gargoyle''s Quest II: The Demon Darkness is a 1992 action-adventure platform game developed and published by Capcom for the Nintendo Entertainment System. It is the prequel to Gargoyle''s Quest (part of the Ghosts ''n Goblins franchise) and features a similar gameplay style, which combines adventure elements with side-scrolling action in a macabre fantasy setting. It was followed by Demon''s Crest for the Super Nintendo Entertainment System in 1994.', 'https://en.wikipedia.org/wiki/Gargoyle%27s_Quest_II'),
  ('Q3047948', 'SonSon is a 1984 platform video game developed and published by Capcom for arcades. It is loosely based on the Chinese novel Journey to the West. The player assumes the role of a monkey boy (who is patterned after Sun Wukong from the story) and fights their way from one side to another, eventually reaching the statue of Buddha. One battles bats, rats, and mad bombers along the way with his fighting rod that shoots balls of fire.

The game was ported from the arcade to the Family Computer in Japan. It is considered one of the greatest games of all time. A sequel, titled SonSon II, heavily based on Black Tiger, was released for the PC Engine, published by NEC Avenue. According to composer Manami Matsumae, the PC Engine title was made by Capcom, one of the few games that they developed for the console themselves.', 'https://en.wikipedia.org/wiki/SonSon'),
  ('Q3073061', 'Fist of the North Star is an action video game produced by Toei Animation and developed by Shouei System for the Nintendo Entertainment System (NES). It was first released in Japan under the title Hokuto no Ken 2 on April 17, 1987, being the second Hokuto no Ken video game released for the Family Computer (Famicom) by the anime production company (which briefly entered the video game publishing business after their success with the original Hokuto no Ken game for the Famicom in 1986), while also serving as a tie-in to the Hokuto no Ken 2 anime series which began airing on Fuji TV a few weeks earlier. Taxan published the localized NES version in April 1989, making it one of the earliest Fist of the North Star products released in the U.S. alongside Viz Communications'' English adaptation of the manga.', 'https://en.wikipedia.org/wiki/Fist_of_the_North_Star_(NES_video_game)'),
  ('Q3038826', 'Dragons of Flame is a video game released in 1989 for various home computer systems and consoles. It is a sequel to Heroes of the Lance.', 'https://en.wikipedia.org/wiki/Dragons_of_Flame_(video_game)'),
  ('Q3072372', 'Final Lap is a 1987 racing simulation video game developed and published by Namco. Atari Games released the game in North America in 1988. It was the first game to run on Namco''s then-new System 2 hardware and is a direct successor to Namco''s Pole Position (1982) and Pole Position II (1983). It was ported to the Famicom by Arc System Works, making it Arc System Works'' debut game.

Final Lap was the first racing game to allow up to eight players to simultaneously race on the Suzuka Circuit in a Formula One race. This was, at the time, considered a revolutionary feature, and was implemented by linking together up to four two-player sitdown-style arcade cabinets.', 'https://en.wikipedia.org/wiki/Final_Lap'),
  ('Q3049161', 'The Eggerland series consists of several puzzle games developed by HAL Laboratory. Its first release was in 1985 for MSX computer systems. The gameplay is almost exactly the same across the series, with only a few changes over the years, mainly graphical.

The hero of most games is Lolo, a blue, spherical character with eyes, arms, and legs. The story mainly deals with King Egger, the villain, capturing princess Lala, who is similar to Lolo, only colored pink or red, and wearing a bow. Lolo must rescue Lala by travelling through Egger''s domain and solving the puzzle rooms laid out before him.', 'https://en.wikipedia.org/wiki/Eggerland'),
  ('Q3108305', 'Yōkai Dōchūki is a 1987 platform video game developed and published by Namco for arcades. It was released in Japan in April 1987 and other parts of Asia the same year.

The game was later ported to the PC Engine, and Family Computer consoles with several additions and different level design; the PC Engine version and the arcade version were both later re-released for the Wii''s Virtual Console. Hamster Corporation released the game as part of their Arcade Archives series for the Nintendo Switch and PlayStation 4 in April 2022.

It was followed by a Japan-only spin-off in 1990 named Kyūkai Dōchūki, which is a "yakyū" (baseball) video game that plays similar to the entirety of Namco''s own World Stadium series.', 'https://en.wikipedia.org/wiki/Y%C5%8Dkai_Dochuki'),
  ('Q3148872', 'Image Fight, also stylized as ImageFight, is a 1988 vertically scrolling shooter video game developed and published by Irem for Japanese arcades. It was ported to the Nintendo Entertainment System, PC Engine, X68000 and FM Towns in 1990. The NES version was the only version that was released in North America. It was followed by Image Fight II: Operation Deepstriker.', 'https://en.wikipedia.org/wiki/Image_Fight'),
  ('Q3112891', 'Terra Cresta is a 1985 vertically scrolling shooter video game developed and published by Nichibutsu for arcades. The player controls a flying craft to destroy the Mandler army before they destroy all of humanity. Gameplay involves shooting enemies and collecting different ship parts that each provide their own unique weapon, such as a wave gun or a double shot. It is the sequel to the 1980 fixed shooter Moon Cresta, Nichibutsu''s first big hit in arcades, and the second installment of the Cresta series.', 'https://en.wikipedia.org/wiki/Terra_Cresta'),
  ('Q3129137', 'Heavy Barrel is an overhead run and gun video game released for arcades in 1987 by Data East.', 'https://en.wikipedia.org/wiki/Heavy_Barrel'),
  ('Q3181429', 'John Elway''s Quarterback, also known as John Elway''s Quarterback Challenge and John Elway''s Team Quarterback, is a 1987 American football video game.', 'https://en.wikipedia.org/wiki/John_Elway%27s_Quarterback'),
  ('Q3120808', 'Gun-Nac is a 1990 scrolling shooter video game developed by Compile for the Nintendo Entertainment System. The game was released in Japan by Tonkin House on October 5, 1990 and in North America by ASCII Corporation in September 1991.', 'https://en.wikipedia.org/wiki/Gun-Nac'),
  ('Q2106124', 'Cobra Triangle is a 1989 racing video game developed by Rare and published by Nintendo for the Nintendo Entertainment System. The player controls a weapon-equipped speedboat through 25 levels. Objectives include winning races, saving swimmers, and defusing bombs. The game also includes vehicular combat, power-ups and is displayed from a 3D isometric perspective with automatic scrolling that follows the player''s movement. The Stamper brothers designed the game and David Wise wrote its soundtrack. Computer and Video Games highly recommended the game and praised its graphics and gameplay. Later reviewers lauded its level diversity and noted its graphical similarities to previous Rare game R.C. Pro-Am. IGN and GamesRadar ranked Cobra Triangle among their top NES games. The latter considered Cobra Triangle emblematic of the NES era''s aesthetic. It is included in Rare''s 2015 Rare Replay compilation for Xbox One, and was re-released on the Nintendo Classics service on July 4, 2024.', 'https://en.wikipedia.org/wiki/Cobra_Triangle'),
  ('Q2115150', 'Exodus: Journey to the Promised Land is a video game released for the Nintendo Entertainment System by Color Dreams through its Wisdom Tree label in 1991. Like all Wisdom Tree games, Exodus was not officially licensed by Nintendo. It was ported to the Game Boy. Exodus is based on Crystal Mines, an earlier game from the company when it was known as Color Dreams.

According to the instruction manual, the player controls the biblical figure Moses as he leads the Israelites to the Promised Land, meaning he goes through a labyrinth. Moses has the ability to shoot glowing "W"s, which signify the word of God, to defeat enemies and remove obstacles. To finish each level, Moses must acquire five question marks as well as a certain amount of manna while avoiding enemies such as magicians and soldiers. After a level is completed, the player must answer five multiple choice Bible-related questions before advancing to the next level. After answering enough questions correctly, the player is rewarded with an extra life. The final 50 levels are a mirror of the first 50 with tougher enemies. At the intro screen, players can skip ahead in intervals of five levels until level 81.', 'https://en.wikipedia.org/wiki/Exodus:_Journey_to_the_Promised_Land'),
  ('Q2117391', 'The Last Ninja is an action-adventure game developed and published by System 3 in 1987 for the Commodore 64. It was converted to the Apple IIGS, MS-DOS, BBC Micro and Acorn Electron in 1988, the Apple II in 1989, the Amiga and Atari ST (as Last Ninja Remix) in 1990, and the Acorn Archimedes in 1991.

It was followed by two sequels: Last Ninja 2 and Last Ninja 3.', 'https://en.wikipedia.org/wiki/The_Last_Ninja'),
  ('Q2107567', 'Clu Clu Land is a 1984 puzzle video game developed and published by Nintendo for the Nintendo Entertainment System. It was released in 1984 in Japan for the Family Computer, in North America in 1985 as a launch title for the NES, and in Europe in 1987. It was ported to the Famicom Disk System in Japan and to arcades via the Nintendo VS. System as VS. Clu Clu Land. The game was later re-released on the Virtual Console for the Nintendo 3DS and Wii U, as well as the Nintendo Classics service.', 'https://en.wikipedia.org/wiki/Clu_Clu_Land'),
  ('Q372774', 'Xexyz (pronounced ZEKS-iz, -⁠eez), known in Japan as Kame no Ongaeshi - Urashima Densetsu, is a 1988 video game published by Hudson Soft for the Nintendo Entertainment System. The game was released in Japan on August 26, 1988, and saw a North American release sometime in April 1990. The game was never released in Europe and the game is not playable on PAL consoles.

The story takes place in the post-apocalyptic year of 2777, after Earth has been devastated by nuclear war and natural disasters, with the island nation of Xexyz now being threatened by alien robots.

The Japanese Famicom version is based on the tales of Urashima Tarō, features cutscenes throughout the game, a choice of three endings and has graphical differences in some of the NPCs.', 'https://en.wikipedia.org/wiki/Xexyz'),
  ('Q333477', 'Jaws is a video game for the Nintendo Entertainment System that is loosely based on the film franchise of the same name, specifically Jaws: The Revenge, the fourth and final film in the series. The box art is modeled heavily after the theatrical poster, and the back of the box mentions "...like it''s personal", perhaps as a reference to said movie''s tagline. However, the game does take elements from the first film. It is one of several LJN-published titles produced by the Japanese company Atlus, although Westone was subcontracted to actually develop it.

There was a separate computer adaptation of the original Jaws movie called Jaws: The Computer Game, released in 1989 by Screen 7 for the Amiga and for the Commodore 64 as simply Jaws by Box Office Software.', 'https://en.wikipedia.org/wiki/Jaws_(video_game)'),
  ('Q300339', 'A Boy and His Blob: Trouble on Blobolonia is a puzzle-platform game developed by Imagineering and published by Absolute Entertainment for the Nintendo Entertainment System (NES). The video game was released in North America in 1989, in Japan by Jaleco in 1990 and in Europe by Nintendo in 1991. A Boy and His Blob follows an unnamed male protagonist and his shapeshifting blob friend, Blobert, on their adventure to save the planet of Blobolonia from the clutches of an evil emperor.

A Boy and His Blob is a puzzle-platform game that puts the player in control of the boy; its gameplay revolves around feeding his blob companion different flavored jelly beans to alter its shape into various tools in order to overcome obstacles and traverse the game''s world. A Boy and His Blob was designed and programmed by David Crane. Licensed by Nintendo in the summer of 1989, development began and was completed in an intense six-week period. Crane has described the game''s overall concept of a boy accompanied by a morphing blob as unconventional and wanted to try his own hand at implementing useful tools for the player.', 'https://en.wikipedia.org/wiki/A_Boy_and_His_Blob:_Trouble_on_Blobolonia'),
  ('Q349327', 'The Adventures of Tom Sawyer is an action video game for the Nintendo Entertainment System developed by Winkysoft and published in 1989 by SETA. It is based upon the 1876 book The Adventures of Tom Sawyer by Mark Twain.', 'https://en.wikipedia.org/wiki/The_Adventures_of_Tom_Sawyer_(video_game)'),
  ('Q288958', 'Operation Wolf is a 1987 light gun shooter video game developed and published by Taito for arcades. It was ported to many home systems.

The game was critically and commercially successful. It was one of the highest-grossing arcade games of 1988 and won the Golden Joystick Award for Game of the Year. Operation Wolf popularized military-themed first-person light gun rail shooters and inspired numerous clones, imitators, and others in the genre over the next decade. It spawned three sequels: Operation Thunderbolt (1988), Operation Wolf 3 (1994) and Operation Tiger (1998). A remake, Operation Wolf Returns: First Mission, was released in 2023.', 'https://en.wikipedia.org/wiki/Operation_Wolf'),
  ('Q1415070', 'The Bard''s Tale is a 1985 fantasy role-playing video game designed and programmed by Michael Cranford for Interplay Productions and published by Electronic Arts for the Apple II. Set in the fictional city of Skara Brae, which has been engulfed in eternal winter and overrun by monsters due to a spell cast by the evil wizard, Mangar the Dark, the game tasks players with assembling and leading a party of up to six adventurers to navigate the city''s streets, sewers, and multi-level dungeons to confront and defeat him. The game was ported to the Commodore 64, Apple IIGS, ZX Spectrum, Amstrad CPC, Amiga, Atari ST, MS-DOS, Mac, and NES. It spawned The Bard''s Tale series of games and books. The earliest editions of the game used a series title of Tales of the Unknown, but this title was dropped for later ports of The Bard''s Tale and subsequent games in the series.', 'https://en.wikipedia.org/wiki/The_Bard%27s_Tale_(1985_video_game)'),
  ('Q1421178', 'Super Cars is a top-view racing game from Gremlin Interactive, who later produced the Lotus series of games. Stylistically, the game is influenced by Super Sprint.

There are endless tracks on each of the four difficulty levels, which can be raced in any order (although the last track is made harder than usual). In the races, the player wins money which can be spent on temporary handling and power upgrades, plus armour plating and front/rear shooting missiles that can knock out other racers. The player must finish in the top three of each race to advance; initially there are four computer opponents, but more are added as the game progresses.', 'https://en.wikipedia.org/wiki/Super_Cars'),
  ('Q1436430', 'Don Doko Don is a 1989 platform video game developed and published by Taito for arcades. In the game, the player(s) control two lumberjacks, Bob and Jim, with the objective being to clear the screen of all the enemies. Bob and Jim use their mallets to stun the enemies, pick up the enemies, then throw them at a wall, or other enemies to kill them off, resulting in bonus points. Bonus items also appear during stages that will have varying effects on the players.

Taito and ITL ported the game to both the Family Computer and PC Engine in 1990, both of which remained exclusive to Japan. A sequel game, aptly named Don Doko Don 2, was released in 1992 for the Family Computer in Japan, developed by Natsume Co., Ltd. The gameplay has been often compared to Taito''s earlier platform games, specifically Bubble Bobble and The NewZealand Story.', 'https://en.wikipedia.org/wiki/Don_Doko_Don'),
  ('Q1439988', 'Karate Champ is a 1984 fighting game developed and published by Data East for arcades. The player utilizes dual-joystick controls to input various moves, in order to defeat enemies in a best-of-three matches format. The game was commercially successful, especially in the United States where it was the highest-grossing arcade game of 1985 and the best-selling home computer game up until 1989. It established and popularized the one-on-one fighting game genre, for which it is considered one of the most influential games of all time.

An updated version that allows two players the option to compete against each other was released in 1984 under the title Karate Champ — Player vs Player, featuring a multiplayer mode and more varied gameplay. It was released for the arcades shortly after the original during the same year, also published by Data East. This version was released internationally as Karate Champ (the original single-player version was exclusive to Japan), and would serve as the basis for the home versions of Karate Champ.', 'https://en.wikipedia.org/wiki/Karate_Champ'),
  ('Q1418928', 'Silent Service is a submarine simulator video game designed by Sid Meier and published in 1985 by MicroProse for the Apple II, Atari 8-bit computers, Commodore 64, and IBM PC compatibles, then ported to other home computers. A Nintendo Entertainment System version developed by Rare was published in 1989 by Konami in Europe and by Konami''s Ultra Games subsidiary in North America. Silent Service II was released in 1990. Tommo purchased the rights to this game and published it online through its Retroism brand in 2015.', 'https://en.wikipedia.org/wiki/Silent_Service_(video_game)'),
  ('Q1439706', 'Famicom Wars is a turn-based strategy video game developed by Nintendo and Intelligent Systems and published by Nintendo for the Family Computer. It was released on August 12, 1988, in Japan. It was later re-released on Virtual Console and for the Nintendo Switch as a part of the Nintendo Classics service. It is the first game in the Wars series.', 'https://en.wikipedia.org/wiki/Famicom_Wars'),
  ('Q1406611', 'Bram Stoker''s Dracula is a 1993 video game released for the Mega Drive/Genesis, Nintendo Entertainment System, Super NES, Master System, Sega CD, Game Gear, MS-DOS, and Amiga. It is based on the 1992 film of the same name, which in turn is based on the 1897 novel Dracula by Bram Stoker. Most versions are platform games, while the Sega CD and Amiga releases are beat ''em ups, and the MS-DOS version is a first-person shooter. A separate version for the Game Boy was released in 1993, followed by an Amiga version in 1994 for North America and Europe. A CD-ROM version for MS-DOS compatible operating systems was released in 1995.', 'https://en.wikipedia.org/wiki/Bram_Stoker%27s_Dracula_(video_game)'),
  ('Q1355850', 'Altered Beast is a 1988 beat ''em up video game developed by Team Shinobi and published by Sega for arcades. Set in Ancient Greece, the game follows a Roman centurion who is resurrected by the Olympian god Zeus to rescue his daughter Athena from Neff, the demonic ruler of the underworld. By collecting three power-ups in a level, the player character can transform into one of five mythical beasts.

The game''s development was led by Makoto Uchida, and marked his first role as a project lead. Uchida and his team used the System 16 arcade system board. Altered Beast was ported to several consoles and home computers, and was the original pack-in game for the Sega Genesis/Mega Drive when the console was launched in North America in 1989 and Europe in 1990.', 'https://en.wikipedia.org/wiki/Altered_Beast'),
  ('Q1398972', 'Faxanadu is an action role-playing platform video game for the Nintendo Entertainment System. The name was licensed by computer game developer Falcom and was developed and released in Japan by Hudson Soft in 1987. Nintendo released the game in the United States and Europe as a first-party title under license from Hudson Soft.

Faxanadu is a spin-off or side-story of Xanadu, which is the second installment of Falcom''s long-running RPG series, Dragon Slayer. The title Faxanadu is a portmanteau formed from the names Famicom and Xanadu. The game uses side-scrolling and platforming gameplay, while employing role-playing elements with an expansive story and medieval setting. Hudson originally licensed Xanadu after seeing its commercial success on the computer platforms, desiring to port it to the home console. However, because of technical difficulties, rushed production, and the lack of assistance from Falcom, the original plan was aborted in favor of creating a new game unrelated to Xanadu. Faxanadu was designed by Hudson programmer Hitoshi Okuno, and the soundtrack was composed by Jun Chikuma.', 'https://en.wikipedia.org/wiki/Faxanadu'),
  ('Q1399011', 'Bonk''s Adventure, known as PC Genjin in Japan, PC Kid and B.C. Kid in Europe, is a scrolling platform game for the PC Engine/TurboGrafx-16 released in 1989 in Japan by Hudson Soft and 1990 in North America by NEC.

Red Company designed the original PC Engine/TurboGrafx-16 version and created its characters whereas Atlus handled most of the game''s development, with A.I being responsible of the background details. Hudson Soft supervised and provided the work. Red Company and A.I Company would each later be involved in the development of separate ports for the Game Boy and NES respectively, both of which were published by Hudson Soft.', 'https://en.wikipedia.org/wiki/Bonk%27s_Adventure'),
  ('Q1514023', 'Rush''n Attack, also known as Green Beret in Japan and Europe, is a 1985 action-platform video game developed and published by Konami for arcades. It was later ported to the Nintendo Entertainment System and various home computers. Its North American title is a play on the phrase "Russian attack" due to its Cold War setting. It became a critical and commercial success for arcades and home computers. It was followed by a sequel, Rush''n Attack: Ex-Patriot, in 2010.', 'https://en.wikipedia.org/wiki/Rush%27n_Attack'),
  ('Q1440134', 'Rod Land is a 1990 platform video game developed and published by Jaleco for arcades. Originally only released in Japan in April 1990, it was ported to various home consoles and personal computers, which were released internationally. A spin-off, Soldam, was released in 1992.', 'https://en.wikipedia.org/wiki/Rod_Land'),
  ('Q1450279', 'Flying Shark, known as Sky Shark in North America, is a vertically scrolling shooter arcade video game originally developed by Toaplan and published in 1987 by Taito in Japan, Romstar in North America and Electrocoin in Europe. Controlling the titular biplane, the players must fight endless waves of military vehicles while avoiding collision with their projectiles and other obstacles. The plane has a powerful bomb at its disposal that can clear a portion of the screen of bullets and damage enemies when fired. It was the third shoot ''em up game from Toaplan, and their eighth video game overall.', 'https://en.wikipedia.org/wiki/Flying_Shark'),
  ('Q1531134', 'Die Hard is the name of four video games, one released for MS-DOS systems in 1989, one released for the Commodore 64 in 1990, one released for the PC Engine in 1990 and the other for the NES in 1991 by Activision. Its gameplay is based on the 1988 film of the same name. During the game, the player rescues hostages and battles with terrorists from a top view perspective at Nakatomi Plaza in Los Angeles.', 'https://en.wikipedia.org/wiki/Die_Hard_(video_game)'),
  ('Q1523204', 'Uninvited is a 1986 point-and-click adventure game developed by ICOM Simulations and published by Mindscape for the Macintosh as part of the MacVenture series. The game was ported to the Amiga, Atari ST, MS-DOS, Apple IIGS, Commodore 64 and Nintendo Entertainment System.', 'https://en.wikipedia.org/wiki/Uninvited_(video_game)'),
  ('Q2129938', 'Rescue: The Embassy Mission (NES version), released on PC as Hostages is a 1988 tactical shooter video game developed and published by Infogrames for the Acorn Electron, Archimedes, Atari ST, Amiga, Apple IIGS, Amstrad CPC, BBC Micro, Commodore 64, MS-DOS, MSX, Nintendo Entertainment System, and ZX Spectrum. The game depicts a terrorist attack and hostage crisis at an embassy in Paris, with the player controlling a six-man [counterterrorist team as they are deployed to defeat the terrorists and free their hostages.

An indirect sequel, Alcatraz, was released for the Amiga, Atari ST, and MS-DOS in 1992.', 'https://en.wikipedia.org/wiki/Rescue:_The_Embassy_Mission'),
  ('Q2121419', 'The NewZealand Story is a 1988 platform video game developed and published by Taito for arcades. The concept and setting were inspired by a holiday trip in New Zealand by one of the Taito programmers. The player controls Tiki, a kiwi who must save his girlfriend and several of his other kiwi chick friends who have been kidnapped by a large blue leopard seal. While avoiding enemies, the player has to navigate a scrolling maze-like level, at the end of which they release one of Tiki''s kiwi chick friends trapped in a cage. It was followed by two remakes.', 'https://en.wikipedia.org/wiki/The_NewZealand_Story'),
  ('Q2138242', 'Infiltrator is a combat flight simulation game published in North America in 1986 by Mindscape and in Europe by U.S. Gold. It was developed for the Commodore 64, MS-DOS, Apple II, and Atari 8-bit computers by Chris Gray Enterprises. Paragon Programming ported it to the Amstrad CPC and ZX Spectrum.

The player takes on the role of a master-of-all-trades hero named Johnny "Jimbo Baby" McGibbits. The player''s objective is to fly an Airwolf-like helicopter named the Gizmo DHX-3, land at enemy bases, and infiltrate compounds to stop the mad leader.', 'https://en.wikipedia.org/wiki/Infiltrator_(video_game)'),
  ('Q2128100', 'Adventure Island 3

is a side-scrolling platform game published by Hudson Soft that was originally released for the Nintendo Entertainment System in 1992. It is the third game in the Adventure Island series released for the NES. Like Adventure Island II (1991), it was developed by Now Production. Adventure Island 3 involves Master Higgins rescuing Jeannie Jungle who has been captured by Aliens. He seeks the kidnappers out through various islands with the help of his dinosaur friends.

Adventure Island 3 was released in Japan on July 31, 1992 for the Famicom. A port was also released for the Game Boy in 1993 as Adventure Island II: Aliens in Paradise.', 'https://en.wikipedia.org/wiki/Adventure_Island_3'),
  ('Q2152260', 'R.O.B. (Robotic Operating Buddy) is a toy robot accessory for the Nintendo Entertainment System (NES). He was a key to the NES''s launch in October 1985, as a redesign of the Family Computer Robot which had been launched in July 1985 in Japan for Famicom and was available as part of the Deluxe Set until 1988. During its short lifespan, only two games in the Robot Series were released: Gyromite and Stack-Up.

Following the North American video game crash of 1983, Nintendo courted a fearful retail market by rebranding its Japanese Famicom video game console as the Nintendo Entertainment System—a new platform focused on R.O.B. to further reclassify the system as a uniquely sophisticated toy experience instead of simply as a video game console. Computer Entertainer called R.O.B. "the world''s only interactive robot".', 'https://en.wikipedia.org/wiki/R.O.B.'),
  ('Q2141683', 'Ms. Pac-Man is a 1982 maze video game developed by General Computer Corporation (GCC) and published by Midway Manufacturing for arcades. It is a sequel to Pac-Man (1980), and the first entry in the series to not be made by Namco. Controlling the title character, Pac-Man''s wife, the player is tasked with eating all of the pellets in an enclosed maze while avoiding four colored ghosts. Eating the larger "power pellets" lets the player eat the ghosts, which turn blue and flee.

General Computer made the game as a modification kit for the original Pac-Man, titled Crazy Otto. However, due to previous legal action with Atari, Inc., GCC was forced to present the project to Midway Manufacturing, the North American distributor of Pac-Man. Midway purchased the project and enlisted GCC to use the game as a basis for the sequel to Pac-Man. Multiple names were considered for the game, including Miss Pac-Man and Mrs. Pac-Man, before the final name Ms. Pac-Man was chosen for being easier to pronounce. While development had started without Namco''s consent, company president Masaya Nakamura was brought in and provided feedback on the player character''s design. Namco ultimately collected the same royalties on each Ms. Pac-Man cabinet as it had with Pac-Man.', 'https://en.wikipedia.org/wiki/Ms._Pac-Man'),
  ('Q445221', 'Stargate is a 1981 horizontally scrolling shooter video game developed by Vid Kidz and published by Williams Electronics for arcades. Designed by Eugene Jarvis and Larry DeMar, it is a sequel to Defender, which was released earlier in the year. It was the first of only three productions by Vid Kidz, an independent development house formed by Jarvis and DeMar. Some home ports of Stargate were renamed Defender II for legal reasons.

This sequel adds new ships to the alien fleet, including Firebombers, Yllabian Space Guppies, Dynamos, Phreds, Big Reds, Munchies and Space Hums. The Defender ship is now equipped with an Inviso cloaking device, which renders the ship invulnerable when activated, but has a limited charge. A Stargate transports the ship to any humanoid in trouble. There are two special stages: the Yllabian Dogfight, first appearing at wave 5 and recurring every 10 waves; and the Firebomber Showdown, first appearing at wave 10 and also recurring every 10 waves.', 'https://en.wikipedia.org/wiki/Stargate_(1981_video_game)'),
  ('Q507742', 'Amagon, known in Japan as Totsuzen! Machoman, is a side-scrolling platform action game for the Nintendo Entertainment System developed by Aicom.', 'https://en.wikipedia.org/wiki/Amagon'),
  ('Q511995', 'Pinball is a pinball video game developed by Nintendo and HAL Laboratory and published by Nintendo for the Nintendo Entertainment System. It is based on a Game & Watch unit of the same name, and was first released for the Famicom in Japan in 1984. It was later released for arcades on the Nintendo VS. System in Japan and North America in 1984. In 1985, it was a launch game for the Nintendo Entertainment System in North America.', 'https://en.wikipedia.org/wiki/Pinball_(1984_video_game)'),
  ('Q512624', 'Loopz is a 1990 puzzle video game developed by Audiogenic and published by Mindscape for the Atari ST. It was designed and programmed by Ian Upton.

The Nintendo Entertainment System version (programmed by Bits Studios) and the Game Boy version (programmed by Argonaut Software) were released in 1990. Audiogenic published versions of the original game for the Acorn Archimedes, Acorn Electron, BBC Micro, ZX Spectrum, Amstrad CPC, Commodore 64, Atari ST, Amiga, and IBM PC in 1990 and 1991.', 'https://en.wikipedia.org/wiki/Loopz'),
  ('Q537381', 'Shadowgate is a 1987 point-and-click adventure game developed by ICOM Simulations and published by Mindscape for the Macintosh as part of the MacVenture series. The game takes place in the Castle Shadowgate, residence of the evil Warlock Lord. The player, as the "last of a great line of hero-kings", is tasked with saving the world by defeating the Warlock Lord, who is attempting to summon the demon Behemoth out of Hell. The original Macintosh version was only in black-and-white, but color versions of the game were later released for the Amiga and Atari ST, and in 1989 for the Nintendo Entertainment System. The game was generally well-received, and was followed by several sequels and remakes for various systems.', 'https://en.wikipedia.org/wiki/Shadowgate');

insert into import_summary (wikidata_id, summary, source) values
  ('Q518547', 'Bases Loaded is a baseball video game originally developed by Tose and published by Jaleco for the Nintendo Entertainment System. It was first released in 1987 in Japan and in 1988 in North America, and a Game Boy port was released in July of 1990. For the Virtual Console, Bases Loaded was released on September 11, 2007, in Japan and on April 7, 2008, in North America for the Wii, and on May 15, 2013, in Japan and on July 10, 2014, in North America for Nintendo 3DS. The Wii U version in North America (which later released in Japan on October 22, 2014) was also released at the same time as the Nintendo 3DS version. A port by Mebius and Clarice Games for the PlayStation 4 was released in Japan in 2015.', 'https://en.wikipedia.org/wiki/Bases_Loaded_(video_game)'),
  ('Q532200', 'Hyper Sports, known in Japan as Hyper Olympic ''84, is a 1984 sports video game developed and published by Konami for arcades in 1984. It is the sequel to 1983''s Track & Field and features seven new Olympic events. Like its predecessor, Hyper Sports has two run buttons and one action button per player. The Japanese release of the game sported an official license for the 1984 Summer Olympics, which was not applicable for its western releases.', 'https://en.wikipedia.org/wiki/Hyper_Sports'),
  ('Q521272', 'Digital Devil Story: Megami Tensei II is a 1990 role-playing video game developed by Atlus and published by Namco for the Famicom. An enhanced Super Famicom port was developed by Opera House and released by Atlus in 1995. The second entry in the Megami Tensei series, the gameplay features the unnamed protagonist exploring a post-apocalyptic wasteland, battling and recruiting demons as they are pushed into taking part in a conflict between the demonic forces of Lucifer and the army of the One True God.

Development began in 1987 following the release of Digital Devil Story: Megami Tensei. While the first game was an adaptation the Digital Devil Story novels, Megami Tensei II has an original story that examines preconceptions surrounding the portrayal of order and chaos. Kouji Okada and Tsukasa Masuko returned as director and composer, while artwork was designed by Kazuma Kaneko. The game received critical acclaim upon release, was partially remade in the 1992 Super Famicom title Shin Megami Tensei, and is regarded as an influential entry in the series.', 'https://en.wikipedia.org/wiki/Digital_Devil_Story:_Megami_Tensei_II'),
  ('Q515649', 'Adventures of Lolo 2 is a 1990 puzzle video game developed and published by HAL Laboratory for the Nintendo Entertainment System. It is the seventh installment of the Japanese Eggerland video game series, as well as the fourth in the series to be released in European countries and the second to be released in North America.', 'https://en.wikipedia.org/wiki/Adventures_of_Lolo_2'),
  ('Q2157521', 'Fantasy Zone II: The Tears of Opa-Opa is a 1987 horizontally scrolling shooter video game developed and published by Sega for the Master System. It was ported to the arcade, Famicom, and MSX2, and was remade for the System 16 hardware on a PlayStation 2 compilation in 2008. It was re-released on the Wii Virtual Console in North America on June 29, 2009. The player controls a sentient spaceship named Opa-opa who fights surreal invader enemies. Like the first Fantasy Zone, Fantasy Zone II departs from scrolling shooter themes with its bright colors and whimsical designs. For this reason, it is occasionally dubbed a "cute ''em up".', 'https://en.wikipedia.org/wiki/Fantasy_Zone_II:_The_Tears_of_Opa-Opa'),
  ('Q2160214', 'Aighina no Yogen: From the Legend of Balubalouk is a Japan-exclusive video game for multiple platforms in 1986. This video game is the spiritual sequel to an arcade game known as Baluba-Louk No Densetsu, which was also only released in Japan.', 'https://en.wikipedia.org/wiki/Aighina_no_Yogen:_From_the_Legend_of_Balubalouk'),
  ('Q2163504', 'Bad Street Brawler is a beat ''em up video game published by Mattel in 1989 for the Nintendo Entertainment System. It was originally released for home computers as Bop''n Rumble in North America and as Street Hassle in Europe.

Versions were released in 1987 for the ZX Spectrum and Commodore 64 by Melbourne House in Europe and for the C64 and MS-DOS by Mindscape in North America. The Nintendo Entertainment System conversion from Mattel followed in September 1989. It is one of only two games specifically designed for use with Mattel''s Power Glove.', 'https://en.wikipedia.org/wiki/Bad_Street_Brawler'),
  ('Q2172154', 'Teenage Mutant Ninja Turtles is a 1989 action-platform game developed and published by Konami for the Nintendo Entertainment System. In North America it was published under Konami''s Ultra Games imprint in the US and the equivalent PALCOM brand in Europe and Australia.

Alongside the arcade game (also developed by Konami), it was one of the first video games based on the 1987 Teenage Mutant Ninja Turtles animated series, being released after the show''s second season. The game sold more than 4 million cartridges worldwide.', 'https://en.wikipedia.org/wiki/Teenage_Mutant_Ninja_Turtles_(NES_video_game)'),
  ('Q388168', 'Bokosuka Wars is a 1983 action-strategy role-playing video game developed by Kōji Sumii and published by ASCII for the Sharp X1 computer, followed by ports to the MSX, FM-7, NEC PC-6001, NEC PC-8801, and NEC PC-9801 computers, as well as an altered version released for the Famicom. It revolves around a leader who must lead an army in phalanx formation across a battlefield in real-time against overwhelming enemy forces while freeing and recruiting soldiers along the way, with each unit able to gain experience and level up through battle. The player must make sure that the leader stays alive, until the army reaches the enemy castle to defeat the leader of the opposing forces.', 'https://en.wikipedia.org/wiki/Bokosuka_Wars'),
  ('Q390291', 'Donkey Kong 3 is a 1983 shoot ''em up video game developed and published by Nintendo for arcades. It is the third installment in the Donkey Kong series, following 1982''s Donkey Kong Jr. It was ported to the Family Computer in 1984, then in North America for the Nintendo Entertainment System in 1986. The gameplay departs from previous Donkey Kong games, and it stars an exterminator named Stanley instead of Mario. The game was a modest financial success in Japan, but its commercial failure in the United States was later cited by commentators as contributing to a period of reduced activity for the series until the release of Donkey Kong and Donkey Kong Country (both 1994).', 'https://en.wikipedia.org/wiki/Donkey_Kong_3'),
  ('Q376785', 'Nakajima Satoru Kanshū F1 Hero MD is a racing video game that was released in 1992 for the Mega Drive/Genesis, Nintendo Entertainment System, and Game Boy. It is endorsed by Formula One driver Satoru Nakajima. The North American and European versions of the game are known as Ferrari Grand Prix Challenge in reference to Ferrari, specifically their Formula One team.', 'https://en.wikipedia.org/wiki/Nakajima_Satoru_Kansh%C5%AB_F1_Hero_MD'),
  ('Q386925', 'Empire City: 1931 (known as Street Fight in Germany and the Benelux Union) is a 1986 shooting gallery video game developed by Seibu Kaihatsu and published by Taito for arcades. It was released in North America by Romstar. The game has players taking on the mafia in 1931 New York City by gunning down mobsters one by one.

Versions of the game were released for the Family Computer (1987) and MSX (1988) as Magnum Kiki Ippatsu: Empire City 1931. Acclaim advertised a release for the Nintendo Entertainment System in Western regions, but the console version remained exclusive to Japan.

Seibu Kaihatsu eventually released a follow-up game, Dead Angle.', 'https://en.wikipedia.org/wiki/Empire_City:_1931'),
  ('Q423722', 'Akuma-kun is a Japanese manga series written and illustrated by Shigeru Mizuki. Several versions of the manga exist, one of which was adapted into a live-action television series which aired on NET and its affiliates from October 1966 to March 1967, a television film which aired on Fuji Television in 1985 and an anime television series titled in English as Devil Boy which aired from April 1989 to March 1990 on the same network, by this point renamed to TV Asahi.

In addition, two movies were spawned from the anime television series: Akuma-kun: The Movie released in 1989 and Akuma-kun: Yōkoso Akuma Land e!! released in 1990.', 'https://en.wikipedia.org/wiki/Akuma-kun'),
  ('Q3273389', 'Alien Syndrome is a 1987 run and gun video game developed and published by Sega for arcades. The game utilizes a side-scrolling feature that allows the player to take control of either a male (Ricky) or female (Mary) soldier whilst hunting aliens and saving hostages before they run out of time.

Alien Syndrome was released to commercial success and positive reviews, with praise towards its gameplay, character designs, sound design and horror themes. It was ported to various home computers and consoles, including Sega''s own Master System, becoming one of the best-selling titles for that console. It was included as a bonus title in the 2009 compilation Sonic''s Ultimate Genesis Collection.', 'https://en.wikipedia.org/wiki/Alien_Syndrome'),
  ('Q3271336', 'Batman: The Video Game is a platformer developed by Sunsoft for the Nintendo Entertainment System featuring the DC Comics character Batman, tying into the 1989 film of the same name.', 'https://en.wikipedia.org/wiki/Batman:_The_Video_Game'),
  ('Q3228947', 'Fighting Golf is a 1988 golf video game developed and published by SNK for arcades. It was ported to the Nintendo Entertainment System the same year, which was titled Lee Trevino''s Fighting Golf in North America.', 'https://en.wikipedia.org/wiki/Fighting_Golf'),
  ('Q3218370', 'Last Action Hero is a series of action video games based on the 1993 film Last Action Hero. Versions were released for the NES, Super NES, Sega Genesis, Game Boy, Game Gear, and MS-DOS. Versions were also planned for the Sega CD and Master System, but ultimately were not released.

A separate version was released on the Amiga and was developed by The Dome. The MS-DOS version was developed by Psygnosis and offers full-motion video cut scenes from the film; the never-released Sega CD version was planned to include this feature as well.', 'https://en.wikipedia.org/wiki/Last_Action_Hero_(video_game)'),
  ('Q541988', 'Ultima IV: Quest of the Avatar, first released in 1985 for the Apple II, is the fourth in the series of Ultima role-playing video games. It is the first in the "Age of Enlightenment" trilogy, shifting the series from the hack and slash, dungeon crawl gameplay of its "Age of Darkness" predecessors towards an ethically nuanced, story-driven approach. Ultima IV has a much larger game world than its predecessors, with an overworld map sixteen times the size of Ultima III and puzzle-filled dungeon rooms to explore. Ultima IV further advances the franchise with dialog improvements, new means of travel and exploration, and world interactivity.', 'https://en.wikipedia.org/wiki/Ultima_IV:_Quest_of_the_Avatar'),
  ('Q545211', 'Holy Diver is a platform video game released in 1989 by Irem for the Family Computer.

The game would remain Japan-exclusive until 2018, when Retro-Bit published the game for the Nintendo Entertainment System worldwide. It is widely considered the most difficult game for the NES and one of the most difficult games ever made.', 'https://en.wikipedia.org/wiki/Holy_Diver_(video_game)'),
  ('Q3275676', 'Konami Wai Wai World is a 1988 platformer video game developed and published by Konami for the Family Computer. Released only in Japan, the name, "wai wai" is a Japanese onomatopoeia expressing a noisy or boisterous atmosphere. The game starred a variety of characters pulled from other Konami games and franchises of the time. A sequel, Wai Wai World 2: SOS!! Parsley Jō, was released for the Famicom in 1991.', 'https://en.wikipedia.org/wiki/Konami_Wai_Wai_World'),
  ('Q3280214', 'Arabian is a 1983 platform video game developed and published by Sun Electronics for arcades. It was released in North America in May 1983 by Atari, Inc. and in Japan in June 1983. A Famicom version was developed and released by Sunsoft only in Japan as Super Arabian. A distinct port for home computers developed by Interceptor Software was released as Tales of the Arabian Nights.', 'https://en.wikipedia.org/wiki/Arabian_(video_game)'),
  ('Q3276866', 'Bubble Bath Babes is a 1991 adult-oriented puzzle video game developed by C&E for the NES. Due to its adult nature, it was not licensed by Nintendo, and released via mail-order by Panesian—along with Hot Slots and Peek-A-Boo Poker.

The U.S. licensed version from American Video Entertainment, was released in 1991 as Mermaids of Atlantis, with all adult elements removed or obscured. In the same year, a localized version leaving intact those contents was released by Hacker International in Japan as Soap Panic, and still in the U.S. by Panesian.

A Genesis / Mega Drive version was released under the name Magic Bubble in 1993 which is more suitable for all ages.', 'https://en.wikipedia.org/wiki/Bubble_Bath_Babes'),
  ('Q3274230', 'Mach Rider is a vehicular combat racing video game developed by HAL Laboratory and published by Nintendo. It was first released for the Famicom console and Nintendo VS. System arcade board in Japan in 1985, then in North America for the VS. System in 1985 and Nintendo Entertainment System in 1986, and then for the PAL region in 1987. It was released on the Virtual Console for the Wii (2007), Nintendo 3DS (2013), Wii U (2014), and for the Nintendo Switch on the Nintendo Classics service (2024).

The Japanese Famicom release can use the Famicom Data Recorder to save custom tracks. The feature was missing from the American and European releases, but was retained in all versions of the Virtual Console release except for the 3DS version.', 'https://en.wikipedia.org/wiki/Mach_Rider'),
  ('Q3196363', 'Kickle Cubicle is a puzzle game developed by Irem for the arcades in 1988 and later ported to the Nintendo Entertainment System.', 'https://en.wikipedia.org/wiki/Kickle_Cubicle'),
  ('Q3196441', 'Kidō Senshi Z Gundam: Hot Scramble, also known as Mobile Suit Z Gundam: Hot Scramble, is a 1986 rail shooter video game developed by Game Studio and published by Bandai for the Family Computer (also known as Famicom in Japan and Nintendo Entertainment System internationally). It is based on the anime Mobile Suit Z Gundam, and is one of the first Gundam video games.

The game sold over 400,000 copies, helping to launch the Gundam video game franchise. Aside from the much later Famicom Mini release, there were two versions of the game: the original release; and a special release of the central location test version, sometimes dubbed Final Version. Only 1,000 copies of this second version were ever released, making it among the rarest video games in history.', 'https://en.wikipedia.org/wiki/Mobile_Suit_Z_Gundam:_Hot_Scramble'),
  ('Q3191691', 'Kabuki: Quantum Fighter is a 2D platform game developed by Human Entertainment and published by HAL Laboratory for the Nintendo Entertainment System. It was originally released on December 21, 1990, in Japan and was released in January 1991 for the North American market before being released in Europe on February 20, 1992.', 'https://en.wikipedia.org/wiki/Kabuki:_Quantum_Fighter'),
  ('Q555897', 'Batman: Return of the Joker is a 1991 run and gun video game, the follow-up to Sunsoft''s first Batman game on the Nintendo Entertainment System. Unlike that game, which was based on the 1989 Batman film directed by Tim Burton, Return of the Joker is entirely self-contained and based more on the modern comic book iteration of Batman, but the Batmobile and the Batwing are featured from the 1989 film. A remake of Return of the Joker, titled Batman: Revenge of the Joker, was released on the Sega Genesis by Ringler Studios in 1992. A Super NES version of Revenge of the Joker was completed but never officially released; a ROM image surfaced online in later years.', 'https://en.wikipedia.org/wiki/Batman:_Return_of_the_Joker'),
  ('Q3186013', 'Joshua & the Battle of Jericho is a 1992 Christian video game developed and published by Wisdom Tree. The game is themed on the Battle of Jericho described in the Book of Joshua, in which the Israelites topple the defensive wall of the city of Jericho by encircling it and blowing their trumpets.

As a tile-based action puzzle game, Joshua & the Battle of Jericho was one of the few Christian video games of its day that did not adhere strictly to a Bible quiz format. However, the player is asked five multiple choice questions about the Book of Joshua between levels.

In 1992, Wisdom Tree published the game in the United States for the Nintendo Entertainment System, and later ported it to Game Boy (1993), MS-DOS (1994), and Sega Genesis (1994).', 'https://en.wikipedia.org/wiki/Joshua_%26_the_Battle_of_Jericho'),
  ('Q3282425', 'Vice: Project Doom is a 1991 action video game developed by Aicom and published by Sammy Corporation for the Nintendo Entertainment System. The game was released in Japan on April 26, 1991, and in North America in November 1991. Vice: Project Doom is a side-scrolling platformer with noticeable similarities to the Ninja Gaiden series for the NES, with the addition of gun shooting and driving segments as well. The player assumes the role of a secret agent who must uncover a conspiracy involving a new kind of alien substance. A Sega Mega Drive conversion titled Deep Scanner was in development, but never released. It was released on the Nintendo Classics service in August 2019 by Sega, as Sammy had retained the rights to the game prior to merging with Sega.', 'https://en.wikipedia.org/wiki/Vice:_Project_Doom'),
  ('Q3280387', 'Chubby Cherub (known in Japan as Obake no Q-Tarō: WanWan Panic) is an action video game developed by Tose and published by Bandai for the Nintendo Entertainment System. It is about a flying cupid-like character who attacks enemies with hearts. It is one of the first third-party games developed for the Nintendo Entertainment System in North America.

The original Japanese version of the game is based on Obake no Q-Tarō, a manga series by Fujiko Fujio. It was retitled and modified for its North American release since its source material was relatively unknown outside Japan.', 'https://en.wikipedia.org/wiki/Chubby_Cherub'),
  ('Q3281751', 'Metal Storm is an action-platform video game developed by Tamtex and published by Irem for the Nintendo Entertainment System (NES). Irem released it in North America in February 1991 and in Japan on April 24, 1992. The game is defined by its central mechanic of the player''s ability to reverse gravity at will, upon which all of its levels and challenges are built.

Its release garnered positive reviews and significant promotional support, including a cover feature in Nintendo Power. However, it was a commercial failure, largely attributed to its release at the end of the NES''s lifecycle, as the market shifted to highly-anticipated 16-bit consoles like the Super Nintendo Entertainment System launching later that year.', 'https://en.wikipedia.org/wiki/Metal_Storm_(video_game)'),
  ('Q3281100', 'WWF King of the Ring is a professional wrestling video game based on the World Wrestling Federation (WWF), released in 1993 for the Game Boy and Nintendo Entertainment System. It was the final WWF game released for the NES, and third WWF game released for the Game Boy.

In this game, players can vie for the title of King of the Ring by competing in an eight-man single elimination tournament. Additionally, players can battle the entire roster through a string of singles matches to become WWF Champion. Also available are exhibition matches in singles and tag team modes for one or two players.', 'https://en.wikipedia.org/wiki/WWF_King_of_the_Ring_(video_game)'),
  ('Q3281783', 'Kick Master (sometimes KickMaster) is an action game developed by KID and published by Taito for the Nintendo Entertainment System in 1992. The game has some role-play elements, such as leveling up.', 'https://en.wikipedia.org/wiki/Kick_Master'),
  ('Q3280693', 'Visco Corporation is a Japanese video game developer. They originally developed video games for several platforms from the arcades and NES, to the Nintendo 64 and Neo Geo in the past. Alongside Toaplan and other developers, Visco was closely associated with Taito, who released their games without any credit; Visco eventually bought back the rights to every game they had developed.', 'https://en.wikipedia.org/wiki/Visco_Corporation'),
  ('Q591171', 'Elevator Action is a 1983 platform shooter video game developed and published by Taito for arcades. The player assumes the role of a secret agent infiltrating a 30-story building from the roof, then descending to ground level via elevators and stairways. Enemy agents emerge from closed doors and shoot at the player. The goal is to collect secret documents from specially marked rooms, then exit to a waiting getaway car. It runs on the Taito SJ System arcade system.

The game was a critical success and was the top-grossing game on the Japanese arcade charts for three months in late 1983. It has been ported to a variety of home systems and appeared on Taito compilations. An arcade sequel, Elevator Action Returns, was released in 1994.', 'https://en.wikipedia.org/wiki/Elevator_Action'),
  ('Q582642', 'Marble Madness is a 1984 platform game designed by Mark Cerny and published by Atari Games Inc. for arcades. Set in an isometric perspective, the game tasks the player with guiding a marble through six courses, populated with obstacles and enemies, within a time limit. The player controls the marble by using a trackball. Marble Madness is known for using innovative game technologies: it was Atari''s first to use the Atari System 1 hardware, the first to be programmed in the C programming language, and one of the first to use true stereo sound (previous games used either monaural sound or simulated stereo).', 'https://en.wikipedia.org/wiki/Marble_Madness'),
  ('Q597005', 'Yume Penguin Monogatari (夢ペンギン物語; "Story of the Dream Penguin") is a hybrid platform/shooter video game developed by Konami in 1991 for the Family Computer and 2006 for i-Revo.', 'https://en.wikipedia.org/wiki/Yume_Penguin_Monogatari'),
  ('Q581614', 'Track & Field II, known in Japan as Konami Sports in Seoul, is a sequel to Track & Field created by Konami for the NES in 1988. It still continues the Olympic-themed sports events, but adds more realism by choosing a country for the player to represent. The series boasted 15 sporting events, with two of them available as bonus stages between rounds of the "Olympic" mode.

The game was profiled in the November–December 1988 issue of Nintendo Power and slated for a December 1988 release in North America; however, it was delayed to February 1989.', 'https://en.wikipedia.org/wiki/Track_%26_Field_II'),
  ('Q568489', 'Hudson''s Adventure Island, known as Takahashi Meijin no Bōken Jima in Japan and also known as Adventure Island, is a platform game produced by Hudson Soft that was released in Japan for the Famicom and MSX on September 12, 1986. It was released in North America for the Nintendo Entertainment System in 1988 and in the PAL region in 1992.

Adventure Island is an adaptation of the arcade game Wonder Boy, developed by Escape for Sega. It was followed by a series of sequels with no connection to the Wonder Boy series.', 'https://en.wikipedia.org/wiki/Adventure_Island_(video_game)'),
  ('Q3282642', 'F-1 Sensation, released in Europe as Formula 1 Sensation, is a 1993 racing video game by Konami for the Family Computer, and a Formula One licensed product. It is heavily based on their 1988 MSX2+ title, F-1 Spirit 3D Special. It was Konami''s final original Famicom game before re-releases.', 'https://en.wikipedia.org/wiki/F-1_Sensation'),
  ('Q3284062', 'The Datach or Datach Joint ROM System, is an enhancement accessory by Bandai for the Family Computer, allowing the system to play select compatible games. Released on December 29, 1992, it is packaged with one game, Dragon Ball Z: Gekitō Tenkaichi Budokai. Six other games were released for it, including one of the final games for the Famicom system in 1994. It is one of two mini systems compatible with the NES or Famicom, the other being the Aladdin Deck Enhancer.', 'https://en.wikipedia.org/wiki/Datach'),
  ('Q3283927', 'Wally Bear and the NO! Gang is an educational Nintendo Entertainment System game that was released in 1992 exclusively for a North American audience. It was not licensed by Nintendo. The game teaches children to say no to potentially harmful drugs like tobacco, alcohol and marijuana. Wally Bear and the NO! Gang was designed in cooperation with, and endorsed by, the American Medical Association and the National Clearinghouse for Alcohol and Drug Information.', 'https://en.wikipedia.org/wiki/Wally_Bear_and_the_NO!_Gang'),
  ('Q3282885', 'Zombie Nation is a 1990 shoot ''em up game developed by KAZe and published by Meldac.', 'https://en.wikipedia.org/wiki/Zombie_Nation_(video_game)'),
  ('Q3283252', 'Paperboy 2 is an action video game, the sequel to the arcade video game Paperboy. It was released in 1991–1992 for Amiga, Amstrad CPC, MS-DOS, Game Boy, Game Gear, Genesis, Nintendo Entertainment System, Super NES, and ZX Spectrum. While Paperboy debuted in arcades and was subsequently ported to personal computers and consoles, the sequel was only released for home systems.', 'https://en.wikipedia.org/wiki/Paperboy_2'),
  ('Q3282919', 'Argus is a 1986 vertically scrolling shooter video game developed by NMK and published by Jaleco for arcades. A port to the Famicom was released the same year. An emulated version of the original arcade game is included as part of their Arcade Archives series by Hamster Corporation for the Nintendo Switch and PlayStation 4 on August 30, 2018, as the game''s first release outside Japan.', 'https://en.wikipedia.org/wiki/Argus_(video_game)'),
  ('Q603874', 'Ice Hockey is a 1988 ice hockey video game developed by Nintendo and Pax Softnica and published by Nintendo for the Famicom Disk System and Nintendo Entertainment System. Ice Hockey is based on the sport of the same name, with the objective of the game being to get more points than the opposing player by hitting round, black pucks into the opposing goal with a hockey stick.

Ice Hockey received positive reviews from critics, and has been often cited as one of the best games for the NES. It was re-released for the Wii''s Virtual Console service in 2006, as well as the Nintendo Classics service for the Nintendo Switch in September 2018.', 'https://en.wikipedia.org/wiki/Ice_Hockey_(1988_video_game)'),
  ('Q597781', 'Battletoads is a 1991 beat ''em up platform video game developed by Rare and published by Tradewest for the Nintendo Entertainment System. The first installment of the Battletoads series, it was released in North America and Japan in 1991 and in Europe in 1993. Ports without Rare''s involvement were released on the Mega Drive and Game Gear in 1993, and on the Amiga and Amiga CD32 in 1994 (despite the former having been developed in 1992); a port developed by Rare for the Game Boy was released in 1993 as Battletoads in Ragnarok''s World. In the game, three space humanoid warrior toads form a group known as the Battletoads. Two of the Battletoads, Rash and Zitz, embark on a mission to defeat the evil Dark Queen on her planet and rescue their kidnapped friends: Pimple, the third member of the Battletoads, and Princess Angelica.', 'https://en.wikipedia.org/wiki/Battletoads_(1991_video_game)'),
  ('Q608480', 'Knight Rider is a 1988 racing video game for the Nintendo Entertainment System that is very loosely based on the television show of the same name.', 'https://en.wikipedia.org/wiki/Knight_Rider_(1988_video_game)'),
  ('Q625283', 'Double Dribble is a 1986 basketball video game developed and published by Konami for arcades. It was the second basketball game by Konami, following Super Basketball. It was considered the most realistic basketball sports game upon release, with fast-paced action, detailed players, a large side-scrolling court, innovative cinematic slam dunks, and detailed sound effects, beginning a trend where presentation would play an increasingly important role in sports games.

Much of the game''s popularity came from its animation sequences showing basketball players performing slam dunks, as well as "The Star-Spangled Banner" theme during the attract mode. These were uncommon in video games at the time of Double Dribble''s release. It was successful in the arcades, while the 1987 Nintendo Entertainment System port sold 2 million units.', 'https://en.wikipedia.org/wiki/Double_Dribble_(video_game)'),
  ('Q610968', 'Mario Bros. is a 1983 platform game developed and published by Nintendo for arcades. It was designed by Shigeru Miyamoto and Gunpei Yokoi, Nintendo''s chief engineer. Players control Italian twin brother plumbers Mario and Luigi as they exterminate turtle-like creatures, giant flies, and crabs emerging from the sewers of New York City by knocking them upside-down and kicking them away. The Famicom/NES version was the first game to be developed by Intelligent Systems. It is part of the Mario franchise and the first spin-off of the Donkey Kong series.

The arcade and Famicom/NES versions were received positively by critics. Elements introduced in Mario Bros., such as floating coins, enemy turtles, and Luigi, were carried over to Super Mario Bros. (1985) and became staples of the Mario series.', 'https://en.wikipedia.org/wiki/Mario_Bros.'),
  ('Q630393', 'Wacky Races is a platform game for the Nintendo Entertainment System, developed and published by Atlus. The game is based on the Hanna-Barbera cartoon Wacky Races and features Muttley and Dick Dastardly as the main characters.

An unrelated Amiga, Amstrad CPC, Atari ST, Commodore 64 and ZX Spectrum game of the same name was released in 1991 and a racing game of the same name released in 2000.', 'https://en.wikipedia.org/wiki/Wacky_Races_(1991_video_game)'),
  ('Q3415769', 'Cloud Master is a horizontally scrolling shooter released as an arcade video game by Taito in 1988. Home versions were released for the Master System, PC Engine, and Famicom and, excluding the Master System version, were released only in Japan. The PC Engine version of the game is titled Gokuraku! Chūka Taisen. The Famicom version is titled Chūka Taisen.', 'https://en.wikipedia.org/wiki/Cloud_Master'),
  ('Q3392005', 'Platoon is an action game developed and published by Ocean Software for the Amiga, Amstrad CPC, Apple II, Atari ST, Commodore 64, MS-DOS, and ZX Spectrum in 1988. It was licensed by Data East and Erbe Software for release in North America and Spain, and by Sunsoft for the Nintendo Entertainment System.', 'https://en.wikipedia.org/wiki/Platoon_(1988_video_game)'),
  ('Q3456898', 'Super Xevious: The Mystery of GAMP is a 1986 vertically scrolling shooter video game developed and published by Namco for the Family Computer. It is the sequel to Xevious and the fourth installment in the Xevious franchise overall. The player controls a spaceship named the Solvalou in its mission to destroy a powerful supercomputer named GAMP, which took over Earth during an ice age. GAMP no Nazo features a heavy focus on puzzle-solving, with each of the game''s 21 levels posing a puzzle that must be solved to progress.

Created in response to the overwhelming success of the Family Computer port of Xevious, GAMP no Nazo was developed by a separate team from the original game. Series creator Masanobu Endo, opposed the idea of a sequel to his creation and was not involved as he had left Namco in 1985 to form Game Studio. Though they share a similar title and gameplay, GAMP no Nazo is not the same as the arcade game Super Xevious.', 'https://en.wikipedia.org/wiki/Super_Xevious:_GAMP_no_Nazo'),
  ('Q3440477', 'Rollerball is a video game produced by HAL Laboratory in 1984 for the MSX. A Nintendo Entertainment System version of the game was released in 1988. It is designed to be played by one to four players, in turn. It is an emulation of a pinball machine.

The pinball machine rendered in Rollerball is composed of four screens, which, by proportion, would be about as long as two standard pinball tables if it were a real table. The graphics on two of the four screens are based on various aspects of the New York City skyline. The topmost screen (hereafter called the bonus screen) merely shows some clouds and a blimp. The second screen (the main screen) shows the top of the Empire State Building, while the third screen (intermediate) shows the lower skyline and the Statue of Liberty. The lowest (final) screen shows only a blue backdrop, representing the Ocean.', 'https://en.wikipedia.org/wiki/Rollerball_(video_game)'),
  ('Q3438819', 'Roger Clemens'' MVP Baseball is a baseball video game released in North America in 1991 and 1992 for the NES, Game Boy, Super NES, and Sega Genesis. All of the players featured in the game have the likenesses and abilities of the 1991 Major League Baseball players they represent. However, since the game is not licensed by the Major League Baseball Players Association, the only player whose name appears in the game is the titular AL Cy Young Award Winner Roger Clemens. The 26 teams featured in the game correspond to the 1991 MLB teams as well, though team nicknames have been changed due to the lack of an MLB license.', 'https://en.wikipedia.org/wiki/Roger_Clemens%27_MVP_Baseball'),
  ('Q3398873', 'The Adventures of Rad Gravity is a 1991 platform video game developed by Interplay and published by Activision for the Nintendo Entertainment System.', 'https://en.wikipedia.org/wiki/The_Adventures_of_Rad_Gravity'),
  ('Q636411', 'Might and Magic Book One: Secret of the Inner Sanctum (also known as simply Might and Magic) is an early role-playing video game, first in the popular and influential Might and Magic franchise. It was released in 1986 as New World Computing''s debut, ported to numerous platforms and re-released continuously through the early 1990s.', 'https://en.wikipedia.org/wiki/Might_and_Magic_Book_One:_The_Secret_of_the_Inner_Sanctum'),
  ('Q639619', 'Super Mario Bros. 3 is a 1988 platform game developed and published by Nintendo for the Nintendo Entertainment System (NES). It was released in Japan on October 23, 1988, in North America on February 12, 1990, and in Europe on August 29, 1991. It was developed by Nintendo Entertainment Analysis and Development, led by Shigeru Miyamoto and Takashi Tezuka.

Players control brothers Mario or Luigi, who must save Princess Toadstool and the rulers of seven different kingdoms from the villain, Bowser. As in previous Super Mario games, they defeat enemies by stomping on them or using items that bestow magical powers; they also have new abilities, including flight and sliding down slopes. Super Mario Bros. 3 introduced Super Mario staples such as Bowser''s children (the Koopalings) and a world map to transition between levels.', 'https://en.wikipedia.org/wiki/Super_Mario_Bros._3'),
  ('Q634502', 'Takahashi Meijin no Bōken Jima IV sometimes referred to as Adventure Island IV, is a 1994 video game released by Hudson Soft for the Family Computer.

The game follows Takahashi Meijin in his quest to rescue his dinosaur companions, who have been kidnapped by a mysterious entity. Adventure Island IV add new gameplay elements to the series. Instead of a series of explicitly separate stages, it features a complex scrolling map connecting its various levels. The player progresses through these levels by solving puzzles, using various items, and defeating the boss enemies.

The sales department at Hudson Soft suggested that the company create a new game for the Famicom. They believed it could potentially perform well, as games for the system were still sold in the Japanese market. This led to the development of a new Adventure Island game, as the company felt it would require the shortest amount of development time. Now Production, who developed Adventure Island II (1991) and Adventure Island 3 (1992), created the game. Upon its release in Japan on June 24, 1994, the game became the final licensed title for the Famicom. Takahashi Meijin said that of the 36 titles that Hudson Soft released for the Famicom, Adventure Island IV sold the least amount of copies.', 'https://en.wikipedia.org/wiki/Adventure_Island_IV'),
  ('Q638828', 'Dr. Jekyll and Mr. Hyde is a 1988 side-scrolling action video game for the Nintendo Entertainment System based on the 1886 novella Strange Case of Dr Jekyll and Mr Hyde by Robert Louis Stevenson. Gameplay alternates between the characters of Dr. Jekyll and Mr. Hyde based on the player''s ability to either avoid or cause damage.', 'https://en.wikipedia.org/wiki/Dr._Jekyll_and_Mr._Hyde_(video_game)'),
  ('Q3359482', 'P.O.W.: Prisoners of War, released in Japan as Prisoners of War, is a 1988 beat ''em up video game developed and published by SNK for arcades. A port to the Nintendo Entertainment System on June 30, 1989, in Japan and in September in North America. The game takes place during the Cold War where the player or players control a duo of military prisoners, Snake and Bart, who break free from their cell to relentlessly fight their way into the main base of their adversaries in order to eliminate their enemy''s general and escape with their lives.', 'https://en.wikipedia.org/wiki/P.O.W.:_Prisoners_of_War'),
  ('Q3302188', 'Sky Destroyer is a rail shooter video game released by Taito in 1985 as an arcade game as well as for the Family Computer. Controlling a Japanese World War II monoplane, the player assumes the role of the pilot of the respective naval aircraft who is required to destroy enemies to clear stages.', 'https://en.wikipedia.org/wiki/Sky_Destroyer'),
  ('Q3341362', 'Nigel Mansell''s World Championship Racing is an arcade-style Formula One racing video game developed by Gremlin Graphics and released for various systems. The game was largely successful on Amiga and DOS platforms, and was consequently ported to home consoles.', 'https://en.wikipedia.org/wiki/Nigel_Mansell%27s_World_Championship_Racing'),
  ('Q3362541', 'Best of the Best: Championship Karate is a 1992 kick boxing game that features black belt kick boxing masters. The object is to win the kick boxing championship by defeating an array of kick boxing masters in a series of fighting matches. The Sega Genesis version is one of the few games to offer support for the Sega Activator motion controller.

Best of the Best is an updated version of Panza Kick Boxing which was released in 1990 in Europe for various computers as well as the TurboGrafx-16.

Martial artist/actor Ron Yuan stated in a 1994 interview that "I know a lot of pure gamers will disagree, but the best SNES fighting game from a purely technical martial arts point of view is Best of the Best. It didn''t get much notoriety, but my friends and I know martial arts, and they go nuts whenever we play."', 'https://en.wikipedia.org/wiki/Best_of_the_Best:_Championship_Karate'),
  ('Q3328277', 'Musashi no Bōken is a role-playing video game for the Family Computer produced by Sigma Ent. Inc., and released in Japan on December 22, 1990.

The game is inspired by the legendary Japanese figure Miyamoto Musashi and is an RPG in the vein of Dragon Quest. The player only controls Musashi, son of Miyamoto Musashi, although a computer-controlled partner assists in battle.

There is a fan translation patch available for this game which allows it to be played in English.', 'https://en.wikipedia.org/wiki/Musashi_no_B%C5%8Dken'),
  ('Q3391045', 'Sherlock Holmes: Hakushaku Reijō Yūkai Jiken is an action video game that was released exclusively in Japan for the Family Computer. An unofficial English translation patch for the game was released on December 9, 2018.', 'https://en.wikipedia.org/wiki/Sherlock_Holmes:_Hakushaku_Reij%C5%8D_Y%C5%ABkai_Jiken'),
  ('Q3500399', 'Strider is a 1989 action-adventure game developed and published by Capcom for the Nintendo Entertainment System. While the development of the NES version of Strider was produced in tandem with the arcade version, the Japanese version for the Famicom was never released. The NES version of Strider is included in the 2006 Game Boy Advance compilation Capcom Classics Mini-Mix.', 'https://en.wikipedia.org/wiki/Strider_(1989_NES_video_game)'),
  ('Q3493437', 'Spider-Man: Return of the Sinister Six is a 1992 action-adventure video game featuring the Marvel Comics characters Spider-Man and the Sinister Six. It was developed by Bits Studios and published by Acclaim Entertainment under the LJN banner for the Nintendo Entertainment System in 1992. Versions of the game were also released for the Master System and Game Gear by Acclaim''s Flying Edge division. The game is loosely based on the story arc of the same name, which was published in The Amazing Spider-Man #334-339 in the early 1990s.', 'https://en.wikipedia.org/wiki/Spider-Man:_Return_of_the_Sinister_Six'),
  ('Q3489627', 'Solstice: The Quest for the Staff of Demnos, or simply Solstice, is a 1990 puzzle video game developed by Software Creations. It was published by CSG Imagesoft in North America and Nintendo in Europe, for the Nintendo Entertainment System. The game focuses on the wizard Shadax''s bid to defeat the evil baron Morbius and rescue Princess Eleanor, whom Morbius plans to sacrifice. Shadax aims to gather the six pieces of the titular Staff of Demnos hidden within the fortress of Kâstleröck. The setting is non-linear, and consists of 250 rooms, each with a particular puzzle to solve.

Solstice is the first original game to be developed by Software Creations, which had previously only worked on converted titles between 8-bit consoles. The game features a musical score by Tim Follin, who has named the title track as his favourite among his compositions. Solstice was received positively by critics for its puzzles and graphics, and the audio was also praised. A sequel, titled Equinox, was released for the Super NES in 1993.', 'https://en.wikipedia.org/wiki/Solstice_(1990_video_game)'),
  ('Q3482630', 'Shufflepuck Café is an air hockey video game developed by Christopher Gross, Gene Portwood and Lauren Elliott for Broderbund (not a table shuffleboard video game, as the name would suggest—though that was the intention when the name was coined by Christopher Gross). Originally developed for the Macintosh, it was later adapted for the Amiga, Atari ST, Amstrad CPC, Famicom, X68000, PC-98, and MS-DOS.', 'https://en.wikipedia.org/wiki/Shufflepuck_Caf%C3%A9'),
  ('Q3496966', 'Star Luster is a 1985 space combat simulator video game developed and published by Namco for the Family Computer. It was only released in Japan. An arcade version for the Nintendo VS. System was released the same year as VS. Star Luster. Star Luster is set in the same universe as Namco''s Bosconian (1981), and the gameplay has strong similarities to Atari, Inc.''s Star Raiders from 1979.

An enhanced version of Star Luster was published for the X68000 in August 1994. A sequel, Star Ixiom, was released for the PlayStation in 1999.

Star Luster was initially met with mixed reviews and poor sales. The game''s reliance on obtuse level objectives and random enemy encounters have been blamed for its lack of popularity, in addition to the Famicom''s userbase being primarily children that didn''t understand its design. Retrospectively, Star Luster has received more positive reviews for its 3D perspective and presentation.', 'https://en.wikipedia.org/wiki/Star_Luster'),
  ('Q3477465', 'Section Z is a 1985 scrolling shooter video game developed and published by Capcom for arcades. A home version was published for the Nintendo Entertainment System in 1987.

The arcade version was re-released as part of Capcom Classics Collection Vol. 1 for PlayStation 2 and Xbox, Capcom Classics Collection Remixed for PlayStation Portable, and Capcom Arcade Cabinet for Xbox 360 and PlayStation 3.', 'https://en.wikipedia.org/wiki/Section_Z'),
  ('Q646691', 'Teenage Mutant Ninja Turtles III: The Manhattan Project is a 1991 beat ''em up game developed and published by Konami for the Family Computer (Famicom) in Japan and for the Nintendo Entertainment System in North America in 1992. It is the third video game iteration of the Teenage Mutant Ninja Turtles for the NES. The game features play mechanics similar to the previous game, Teenage Mutant Ninja Turtles II: The Arcade Game, but it is an original title for the NES without any preceding arcade version. It is based on the 1987 Teenage Mutant Ninja Turtles animated series, being released after the show''s 5th season. The game was re-released as part of Teenage Mutant Ninja Turtles: The Cowabunga Collection in 2022.', 'https://en.wikipedia.org/wiki/Teenage_Mutant_Ninja_Turtles_III:_The_Manhattan_Project'),
  ('Q650278', 'Mighty Bomb Jack is a 1986 platform video game developed and published by Tecmo for the Nintendo Entertainment System. It was later ported to the Amiga, Atari ST and Commodore 64. Mighty Bomb Jack is a sequel to Tecmo''s 1984 arcade game Bomb Jack.', 'https://en.wikipedia.org/wiki/Mighty_Bomb_Jack'),
  ('Q674227', 'Ninja Gaiden III: The Ancient Ship of Doom is a 1991 platform game developed and published by Tecmo for the Nintendo Entertainment System (NES). It was later ported to the Atari Lynx by Atari Corporation in 1993, and was also re-released as part of Tecmo''s Ninja Gaiden Trilogy Super NES compilation in 1995. It was designed by Masato Kato, who took over for Hideo Yoshizawa, the designer of the first two games in the NES series.

The game is the third installment of the Ninja Gaiden trilogy in terms of release, but is chronologically set between the first two games in the series, Ninja Gaiden and Ninja Gaiden II: The Dark Sword of Chaos. Although the American box art and in-game dialogue suggests that the game takes place years after the first game, The Dark Sword of Chaos supposedly takes place one year after the first, while the Japanese version takes place in between the first two games; the ending screen briefly makes mention of this. The player controls Ryu Hayabusa as he is framed for the murder of Irene Lew and investigates the circumstances behind her death. He eventually discovers a plan by CIA agent Foster and another person named Clancy to utilize an interdimensional rift to create and control a race of energy-infused superhuman mutants. The game features similar gameplay to its previous two Ninja Gaiden titles and includes some new features such as the ability to hang overhead from pipes and sword power-ups.', 'https://en.wikipedia.org/wiki/Ninja_Gaiden_III:_The_Ancient_Ship_of_Doom'),
  ('Q668757', 'Urban Champion is a fighting video game developed and published by Nintendo for the Nintendo Entertainment System. It was first released for the Famicom and Nintendo VS. System for arcades in 1984, and later released for the NES in North America and Europe in 1986. It is Nintendo''s first 2D fighting game, eventually followed by the 1993 Famicom game Joy Mech Fight. The game was poorly received, and has been retroactively regarded as one of the weaker Nintendo-published games for the NES.', 'https://en.wikipedia.org/wiki/Urban_Champion'),
  ('Q677353', 'Stinger is a 1986 scrolling shooter video game developed and published by Konami. It was originally released for the Family Computer Disk System (FDS) in Japan in 1986, and later for the Nintendo Entertainment System in North America in late 1987, making it one of the few games in the series to have a release outside of Japan. As with Konami''s other FDS titles, Castlevania and Bio Miracle Bokutte Upa, it was later re-released in 1993 as a standard Famicom game with some minor changes. Stinger was the second game in the TwinBee series, as well as the first of two TwinBee sequels released for the Famicom, followed by TwinBee 3: Poko Poko Daimaō in 1989.', 'https://en.wikipedia.org/wiki/Stinger_(1986_video_game)'),
  ('Q669784', 'Digital Devil Story: Megami Tensei refers to two distinct role-playing video games based on the Digital Devil Story trilogy of science fiction novels by Japanese author Aya Nishitani. One version was developed by Atlus and published by Namco in 1987 for the Famicom—Atlus would go on to create further games in the Megami Tensei franchise. A separate version for personal computers was developed and published by Telenet Japan with assistance from Atlus during the same year.

The story sees Japanese high school students Akemi Nakajima and Yumiko Shirasagi combat the forces of Lucifer, unleashed by a demon summoning program created by Nakajima. The gameplay features first-person dungeon crawling and turn-based battles or negotiation with demons in the Famicom version, and a journey through a hostile labyrinth as Nakajima featuring real-time combat in the Telenet version.', 'https://en.wikipedia.org/wiki/Digital_Devil_Story:_Megami_Tensei'),
  ('Q3521337', 'The Hunt for Red October is a video game based on the 1990 film The Hunt for Red October. It was first released in 1991 for the Nintendo Entertainment System. Versions for the Game Boy and Super NES were subsequently released.', 'https://en.wikipedia.org/wiki/The_Hunt_for_Red_October_(console_game)'),
  ('Q3553822', 'Valis: The Fantasm Soldier is a 1986 action-platform video game originally developed by Wolf Team and published by Telenet Japan for the MSX, PC-8801, X1, FM-7, and PC-9801 home computers. It is the first entry in the Valis series. It stars Yuko Asou, a Japanese teenage schoolgirl chosen as the Valis warrior and wielder of the mystical Valis sword to protect the Earth, the land of spirits, and the dream world Vecanti from demon lord Rogles. Throughout the journey, the player explores and search for items and power-ups, while fighting enemies and defeating bosses to increase Yuko''s attributes.

Programmers Masahiro Akishino and Osamu Ikegame began planning on a side-scrolling action game featuring a customed delinquent heroine, an idea originated from Sukeban Deka to compete in a contest sponsored by Japanese computer magazine Login, being kept secret within Telenet until they approved development to continue when the company learned of its existence. After a Telenet superior expressed disliking towards its graphics, writer Hiroki Hayashi was ordered to take action and fix it, leading to the conception of Valis. Akishino and Hayashi used Ikegame''s work as basis to introduce their own story and character ideas, which were based on an unfinished personal novel Hayashi wrote prior to the game''s production.', 'https://en.wikipedia.org/wiki/Valis:_The_Fantasm_Soldier'),
  ('Q3540750', 'Bio-Senshi Dan: Increaser to no Tatakai is a 1987 action-adventure game that was released exclusively in Japan for the Nintendo Famicom.

Initially, there were plans to bring the game to the English market under the title Bashi Bazook: Morphoid Masher, but they fell through due to the game''s similarity to Xexyz. English-translated ROMs of the game later became widely circulated on the Internet.', 'https://en.wikipedia.org/wiki/Bio_Senshi_Dan:_Increaser_to_no_Tatakai'),
  ('Q3521145', 'The Great Waldo Search is a video game released in 1992. It is based on the third Waldo book, which was originally released under the same name in North America.', 'https://en.wikipedia.org/wiki/The_Great_Waldo_Search_(video_game)'),
  ('Q3569964', 'Stadium Events is a sports fitness game developed by Human Entertainment and published by Bandai for the Nintendo Entertainment System (NES). This and Athletic World are the two games in the Family Fun Fitness series, designed and branded for the short-lived Family Fun Fitness mat accessory for the NES. Stadium Events allows players to compete in four different Olympic inspired sporting events, using the mat to move as they compete in running and jumping focused gameplay.

The North American version was rebranded by Nintendo after its 1987 release. The game was re-released as World Class Track Meet and the new mat was titled the Power Pad. Original North American copies of Stadium Events are now considered to be among the rarest video games, leading to high prices in the secondary video game collecting market.', 'https://en.wikipedia.org/wiki/Stadium_Events'),
  ('Q3634758', 'Barbie is a 1991 platform video game developed by Imagineering and published by Hi Tech Expressions for the Nintendo Entertainment System and MS-DOS. It is based on Mattel Inc.''s doll of the same name. The game takes place in a dream where Barbie must travel through three different worlds (Mall, Underwater and Soda Shop) to gather accessories before attending a ball to meet Ken.

Barbie was created in an attempt to get more girls to play video games. Despite it having been of little interest to typical gamers at the time of its release, critics including staff writers for Velikij Drakon and Allgame have praised it as "not bad" for a generic platformer. Others including Justine Cassell and Nathanael Ng of the Georgia Institute of Technology have advanced the view that its genre is not appropriate for its content.', 'https://en.wikipedia.org/wiki/Barbie_(1991_video_game)'),
  ('Q3628242', 'Atlantis no Nazo is a 1986 platform game developed and published by Sunsoft for the Family Computer. The game is set in the mythical land of Atlantis. The player controls an amateur adventurer named Wynn, whose objective is to save his master being held captive in the final level.', 'https://en.wikipedia.org/wiki/Atlantis_no_Nazo'),
  ('Q3564653', 'WCW Wrestling (a.k.a. WCW World Championship Wrestling) is a professional wrestling video game developed by Nichibutsu for the Nintendo Entertainment System. It was originally released in Japan by Pony Canyon in 1989 under the name Super Star Pro Wrestling. It was later released in North America by FCI in 1990 with a World Championship Wrestling license.

It was the first (and, to date, only) video game based on the National Wrestling Alliance (at the time, WCW was a member of NWA). After The Road Warriors joined the World Wrestling Federation, WCW continued to advertise the game in their own catalogs with a mock-up cartridge showing Sting on the label, though no such copies of the game with an alternate label are known to exist or believed to have ever been manufactured. To date, the game has sold over 100,000 copies.', 'https://en.wikipedia.org/wiki/WCW_Wrestling'),
  ('Q3612233', 'Erika to Satoru no Yume Bōken is a 1988 adventure video game developed by Atlus and published by Namco for the Family Computer. The game is set in 20th century Japan.

Two-player adventure games were considered very rare at the time of the game''s release, even in Japan. However, only one person could partake in the animal quiz portion. Failing the quiz would force the player(s) to start from the beginning.

It is one of the few games for the Family Computer to use the Namco 163 wavetable sound chip, and is also one of the games that enables all eight sound channels provided by the chip, the other being King of Kings.', 'https://en.wikipedia.org/wiki/Erika_to_Satoru_no_Yume_B%C5%8Dken'),
  ('Q3565019', 'Tose Co., Ltd. (also called Tose Software) is a Japanese video game developer based in Kyoto. It is mostly known for developing Nintendo''s Game & Watch Gallery series, various Dragon Ball games, as well as contract work or assistance to other developers. Tose has developed or co-developed thousands of games since the company''s inception in 1979, but is virtually never credited in the games themselves. It is considered the largest non-publishing game developer in the world.

Tose maintains a policy of having no creative input in the games it works on, going so far as to refuse to put the studio''s name in the credits and employees using pseudonyms in its early days. As such, Tose has gained a reputation for being a "ghost developer." Representatives of the company have described it as a "ninja developer," because it works in the shadows, as well as the "unsung hero" of the video game industry. When talking to the press, representatives of the company ask not to be identified by name. Exceptions to this include Game & Watch Gallery 4 and The Legendary Starfy series, as Tose shares the copyright with Nintendo.', 'https://en.wikipedia.org/wiki/Tose'),
  ('Q3663351', 'Moon Crystal is a 1992 video game for the Family Computer. It is a side scrolling action game, published and developed by Hect. It was well received by critics, who praised the smooth animations and graphics, however it sold poorly. It has never been released outside of Japan.', 'https://en.wikipedia.org/wiki/Moon_Crystal'),
  ('Q687559', 'Final Fantasy III is a 1990 role-playing video game developed and published by Square for the Family Computer. The third installment in the Final Fantasy series, it follows four orphans from the village of Ur who are chosen by the world''s crystals to defeat a great evil and return balance to the world. The gameplay returns to the traditional combat system of the original game, and adds a job system allowing players to switch between character classes with unique abilities.

Development of Final Fantasy III was handled by multiple series veterans including director Hironobu Sakaguchi, designers Hiromichi Tanaka and Kazuhiko Aoki, writer Kenji Terada, composer Nobuo Uematsu, and programmer Nasir Gebelli in his final contribution to the series. Production was a struggle due to data management, and new elements were added to encourage player experimentation. The artwork was a collaborative effort between Koichi Ishii as character and job designer, Yoshitaka Amano as monster designer, and Kazuko Shibuya as main sprite artist. When it completed development, it was described as one of the largest games on the system.', 'https://en.wikipedia.org/wiki/Final_Fantasy_III'),
  ('Q684629', 'F-15 Strike Eagle is an F-15 Strike Eagle combat flight simulation game released by MicroProse for the Atari 8-bit computers in 1984 then ported to other systems. It is the first in the F-15 Strike Eagle series followed by F-15 Strike Eagle II and F-15 Strike Eagle III. An arcade version of the game was released simply as F-15 Strike Eagle in 1991, which uses higher-end hardware than was available in home systems, including the TMS34010 graphics-oriented CPU.', 'https://en.wikipedia.org/wiki/F-15_Strike_Eagle_(video_game)'),
  ('Q677764', 'Klax is a 1990 puzzle video game developed and published by Atari Games for arcades; in Japan, it was distributed by Namco. The game was designed and animated by Mark Stephen Pierce, with software engineering by Dave Akers. The object of the game is to catch colored tiles moving down a conveyor belt, and arrange them in matching rows and patterns to make them disappear.

Klax was originally released in February 1990 as an arcade follow-up to Tetris (1989), about which Atari Games had been in a legal dispute. It was later ported to several home and handheld systems, including the Nintendo Entertainment System, Genesis, Master System, TurboGrafx-16, Game Boy, and Lynx. The Atari 2600 version of the game, released in the UK in mid-1990, was one of the final licensed games for the console, which was discontinued in early 1992.', 'https://en.wikipedia.org/wiki/Klax_(video_game)'),
  ('Q3910069', 'Predator is a 1987 side-scrolling action game based on the 1987 film Predator, and the first game based on the franchise.', 'https://en.wikipedia.org/wiki/Predator_(video_game)'),
  ('Q3845209', 'Mappy Kids is a 1989 platform video game developed and published by Namco for the Family Computer. It is a sequel to the 1983 video game Mappy. It was released in Japan on December 22, 1989.', 'https://en.wikipedia.org/wiki/Mappy_Kids'),
  ('Q3736507', 'F1 Circus is a Formula One-based racing game developed and published by Nichibutsu for the PC Engine. It was ported to the Family Computer.

The game features British motor racing team Team Lotus, which they approved due to Nichibutsu''s sponsorship of the team from 1991 to 1993.', 'https://en.wikipedia.org/wiki/F1_Circus_(video_game)'),
  ('Q3805702', 'Jackie Chan''s Action Kung Fu is an action-platform video game developed by Now Production and published by Hudson Soft. It was released for the Nintendo Entertainment System in 1990 and for the TurboGrafx-16 in 1991.', 'https://en.wikipedia.org/wiki/Jackie_Chan%27s_Action_Kung_Fu'),
  ('Q3786900', 'Hot Slots, or AV Pachisuro, is a slot machine simulation video game for the Nintendo Entertainment System developed by Idea-Tek, and published by Hacker International/Panesian in 1991.

AV Pachisuro is the title of the Japanese release for the Family Computer (or Famicom); Hot Slots (titled Hot Slot in-game) is the English-language version of the game published for the NES. The title AV Pachisuro combines the Japanese-coined English initialism AV (adult video) with the Japanese contracted word pachisuro (a portmanteau of pachinko and slot).', 'https://en.wikipedia.org/wiki/Hot_Slots'),
  ('Q3815495', 'Kings of the Beach is a beach volleyball computer game released by Electronic Arts in 1988 for the Commodore 64 and MS-DOS. A version for the Nintendo Entertainment System was produced by Konami (under the Ultra Games label) in 1990.', 'https://en.wikipedia.org/wiki/Kings_of_the_Beach'),
  ('Q3818164', 'The Nintendo Entertainment System has a library of 1370 officially licensed games released during their lifespans, plus 7 official multicarts and 2 championship cartridges. Of these, 672 were released exclusively in Japan, 187 were released exclusively in North America, and 19 were released exclusively in Phase Alternating Line (PAL) countries. Worldwide, 521 games were released.

Its launch games for the Famicom were Donkey Kong, Donkey Kong Jr., and Popeye. Only first-party titles were available upon launch, but Nintendo started a licensing program the following year that allowed third-party companies such as Namco, Hudson Soft, Taito, Konami, Bandai, and Capcom to create titles and produce their own cartridges for the Famicom in exchange for royalty payments; Nintendo later revised the program to mandate itself as the manufacturer of all cartridges while carrying it with the console outside Japan. The launch games for North America were: 10-Yard Fight, Baseball, Clu Clu Land, Duck Hunt, Excitebike, Golf, Gyromite, Hogan''s Alley, Ice Climber, Kung Fu, Pinball, Soccer, Stack-Up, Super Mario Bros., Tennis, Wild Gunman, and Wrecking Crew. The final licensed game released is the PAL-exclusive The Lion King on May 25, 1995.', 'https://en.wikipedia.org/wiki/List_of_Nintendo_Entertainment_System_games'),
  ('Q3810637', 'Journey to Silius, known in Japan as Rough World, is a side-scrolling run and gun video game developed and published by Sunsoft for the Nintendo Entertainment System in 1990.

Journey to Silius was originally based on the 1984 film The Terminator, but the licensing rights to the film were lost during development. The graphics and storyline were altered to accommodate this change.', 'https://en.wikipedia.org/wiki/Journey_to_Silius'),
  ('Q3758947', 'Gauntlet is a 1985 dungeon crawl maze video game developed and published by Atari Games for arcades. It is one of the first multiplayer dungeon crawl arcade games. The core design of Gauntlet comes from the 1983 game Dandy for the Atari 8-bit computers, which resulted in a threat of legal action. It also has similarities to the 1983 maze game Time Bandit.

The arcade version of Gauntlet was released in October 1985, initially available only as a dedicated four-player cabinet. Atari distributed a total of 7,848 arcade units. In Japan, the game was released by Namco in February 1986. Atari later released a two-player cabinet variant in June 1986, aimed at operators who could not afford or did not have sufficient space for the four-player version.', 'https://en.wikipedia.org/wiki/Gauntlet_(1985_video_game)'),
  ('Q745044', 'Devil World is a maze video game developed by Nintendo and Intelligent Systems and published by Nintendo for the Family Computer and Nintendo Entertainment System. It was released for the Famicom in Japan on October 5, 1984, and for the Nintendo Entertainment System in Europe on July 15, 1987. It was re-released on the Wii''s Virtual Console in Japan on January 22, 2008, and in PAL regions on October 31, 2008. Nintendo of America''s content policies prohibiting religious icons prevented the game''s release in North America. It is Shigeru Miyamoto''s first console-exclusive game after a legacy of arcade development, and for many years was his only game not to be localized to North America until it was released as part of the Nintendo Classics service for Nintendo Switch on October 31, 2023.', 'https://en.wikipedia.org/wiki/Devil_World'),
  ('Q698705', 'Double Dragon is a 1987 beat ''em up video game developed by Technōs Japan and published by Taito for arcades. The game''s development was led by Yoshihisa Kishimoto, and it is a spiritual and technological successor to Technos'' earlier beat ''em up, Nekketsu Kōha Kunio-kun (1986), released outside of Japan by Taito as Renegade; Kishimoto originally envisioned it as a direct sequel and part of the Kunio-kun series, before making it a new game with a different cast and setting.

Double Dragon introduced several additions to the Kunio-kun belt scroll beat ''em up formula, such as a continuous side-scrolling world adding a sense of progression, two-player cooperative gameplay, the ability to arm oneself with an enemy''s weapon after disarming them, and the use of cutscenes to give it a cinematic look and feel. The game''s title is a reference to the two-player gameplay and Bruce Lee''s martial arts film Enter the Dragon (1973), which was a major inspiration behind Kunio-kun and Double Dragon, while the game''s art style and setting were influenced by the Mad Max films and the Fist of the North Star manga and anime series.', 'https://en.wikipedia.org/wiki/Double_Dragon_(video_game)'),
  ('Q716880', 'The Miracle Piano Teaching System is educational software which uses a MIDI keyboard to teach how to play the piano. It was published in 1990 by The Software Toolworks for the Nintendo Entertainment System, Super NES, Macintosh, Amiga, Sega Genesis, and MS-DOS compatible operating systems.', 'https://en.wikipedia.org/wiki/Miracle_Piano_Teaching_System'),
  ('Q748636', 'Peek-A-Boo Poker, is a video game made by the company Idea-Tek and distributed by Hacker International/Panesian in 1991 as one of their three pornographic video games for NES, the other two being Magic Bubble and Hot Slots.', 'https://en.wikipedia.org/wiki/Peek-A-Boo_Poker'),
  ('Q769834', 'Between 1992 and 1994, Acclaim Entertainment, under various subsidiaries, published three video games named The Incredible Crash Dummies, based on the line of toys of the same name developed by Tyco Toys.

Software Creations developed two of these. One was on the NES, and another was originally on the Game Boy before being ported by Teeny Weeny Games to Sega''s Master System and Game Gear consoles. Gray Matter developed another one that was released for the SNES, Sega Genesis and Amiga. The Nintendo releases were published under LJN, the Sega releases under Flying Edge.', 'https://en.wikipedia.org/wiki/The_Incredible_Crash_Dummies_(video_game)'),
  ('Q764069', 'Duck Hunt is a 1984 light gun shooter video game developed and published by Nintendo for the Nintendo Entertainment System (NES). The game was first released in April 1984 in Japan for the Family Computer (Famicom) console and in North America as an arcade game for the Nintendo VS. System. It became a launch game for the NES in North America in October 1985, and was re-released in Europe two years later. Players fire the NES Zapper at a CRT television, with three attempts per round to shoot ducks and clay pigeons.

The game initially received a positive reception in the mid-1980s, but was later given mild praise in retrospective reviews. The game was inspired by Nintendo''s previous electro-mechanical arcade game which was based on the Laser Clay Shooting System released in 1976. Upon release as a video game, Duck Hunt became a major commercial success both for arcades and consoles in the 1980s, helping to popularize light gun video games with over 28 million copies sold worldwide.', 'https://en.wikipedia.org/wiki/Duck_Hunt'),
  ('Q3952040', 'The Little Mermaid is an action video game released in 1991 by Capcom for the NES and Game Boy based on the 1989 Disney film of the same name.', 'https://en.wikipedia.org/wiki/The_Little_Mermaid_(video_game)'),
  ('Q3929863', 'Rambo is an action-adventure video game produced by Pack-In-Video for the Nintendo Entertainment System (NES). It was released on December 4, 1987 in Japan, and May 1988 in North America. It is based on the film Rambo: First Blood Part II (1985).', 'https://en.wikipedia.org/wiki/Rambo_(1987_video_game)'),
  ('Q3939296', 'RoboWarrior is an action video game developed by Hudson Soft and EXA Planning for the Nintendo Entertainment System. A follow-up to Bomberman (1985), it was released in Japan on August 7, 1987. Internationally, Jaleco published the game in North America in December 1988 and Europe in November 1989.

The player controls ZED, a cyborg on his mission to protect the planet Altile from the invasion of the Xantho Empire. The objective is to make way through the game''s eight levels while overcoming enemies and obstacles. ZED uses his bombs and laser gun to create pathway and eliminate his foes. The player is able to utilize numerous items collected throughout the game, giving ZED additional tools and other beneficial effects.', 'https://en.wikipedia.org/wiki/RoboWarrior'),
  ('Q3913710', 'Dusty Diamond''s All-Star Softball (released in Japan as Softball Tengoku) is a one or two player Nintendo Entertainment System video game where players can select various fictional softball players and customize their own team to take to the championship.', 'https://en.wikipedia.org/wiki/Dusty_Diamond%27s_All-Star_Softball'),
  ('Q3939307', 'RoboCop 2 is a 1990 platform shooter video game based on the film of the same name. The game was released for several platforms, including Amiga, GX4000, Atari ST, Commodore 64, Game Boy, Nintendo Entertainment System, and ZX Spectrum. Ocean Software developed and published several versions, and Data East manufactured an arcade version.

A sequel, RoboCop 3, was released in 1991, itself based on the film of the same name.', 'https://en.wikipedia.org/wiki/RoboCop_2_(video_game)'),
  ('Q849328', 'Contra is a 1987 run and gun video game developed and published by Konami for arcades. A home version was released for the Nintendo Entertainment System in 1988, along with ports for various home computer formats, including the MSX2. The arcade and computer versions were localized as Gryzor in Europe, and the NES version as Probotector in the PAL region.

The arcade game was a commercial success worldwide, becoming one of the top four highest-grossing dedicated arcade games of 1987 in the United States. The NES version was also a critical and commercial success, with Electronic Gaming Monthly awarding it for being the Best Action Game of 1988. Several Contra sequels were produced following the original game.', 'https://en.wikipedia.org/wiki/Contra_(video_game)'),
  ('Q798676', 'Bad Dudes Vs. DragonNinja, also known simply as either Bad Dudes (on the American NES port) or DragonNinja (in Japan and Europe), is a 1988 beat ''em up video game developed and published by Data East for arcades. It was ported to computer and game console home systems.

In Bad Dudes, the players are tasked with rescuing "President Ronnie" from ninja kidnappers. The game was a commercial success, becoming one of America''s top five highest-grossing games in 1988. The arcade version received generally positive reviews from critics, while the home conversions received also a positive critical reception. It has since become widely known for its general premise and introductory cutscene.', 'https://en.wikipedia.org/wiki/Bad_Dudes_Vs._DragonNinja'),
  ('Q810986', 'Battle Chess is a 1988 chess video game developed and published by Interplay Productions for the Amiga. It was ported to many other systems, including the 3DO Interactive Multiplayer, Acorn Archimedes, Amiga CD32, Amiga CDTV, Apple IIGS, Apple II, Atari ST, Commodore 64, MS-DOS, FM Towns, Nintendo Entertainment System, MacOS, PC-98, X68000, and Microsoft Windows. In 1991, Battle Chess Enhanced was released by Interplay for IBM PC compatibles and Macintosh with improved VGA graphics and a symphonic musical score played from the CD-ROM.

Battle Chess was critically acclaimed and commercially successful, resulting in two official follow-ups as well as several inspired games. A remake, Battle Chess: Game of Kings, was released on Steam on December 11, 2015.', 'https://en.wikipedia.org/wiki/Battle_Chess'),
  ('Q810990', 'Battle City is a 1985 multidirectional shooter video game developed and published by Namco for the Family Computer. Released only in Japan, it is the sequel to the arcade video game Tank Battalion.

An arcade version for the Nintendo VS. System, titled VS. Battle City, would follow, along with a Game Boy version in 1991, which was developed and published by Nova Games. The Famicom version was later included as an unlockable in the Japanese release of Star Fox: Assault, and would eventually be digitally re-released via the Virtual Console for Wii and Wii U. Hamster Corporation released the arcade version as part of their Arcade Archives series for the Nintendo Switch and PlayStation 4 on September 12, 2024.', 'https://en.wikipedia.org/wiki/Battle_City'),
  ('Q785278', 'Pac-Mania is a 1987 maze video game developed and published by Namco for arcades. It was released by Atari Games in North America. In the game, the player controls Pac-Man as he must eat all of the dots while avoiding the colored ghosts that chase him in the maze. Eating large flashing "Power Pellets" will allow Pac-Man to eat the ghosts for bonus points, which lasts for a short period of time. A new feature to this game allows Pac-Man to jump over the ghosts to evade capture. It is the ninth title in the Pac-Man video game series and was the last one developed for arcades up until the release of Pac-Man Arrangement in 1996. Development was directed by Pac-Man creator Tōru Iwatani.', 'https://en.wikipedia.org/wiki/Pac-Mania'),
  ('Q798519', 'Mission: Impossible is a 1990 overhead action-adventure video game developed by Konami and published by Ultra Games for the Nintendo Entertainment System (NES) based on the 1988 Mission: Impossible TV series.', 'https://en.wikipedia.org/wiki/Mission:_Impossible_(1990_video_game)'),
  ('Q3516981', 'Tecmo Bowl is a 1987 American football video game developed and published by Tecmo for arcades. The game features a large dual screen cabinet with up to four players between two fictitious teams. A port for the Nintendo Entertainment System (NES) was released in 1989 and was the first console game to include real National Football League players, via a license from the NFL Players Association. A Game Boy version developed by Sculptured Software followed in 1991.

The NES version was extremely popular, spawning various sequels, starting with 1991''s Tecmo Super Bowl. The NES original has been cited as one of the best sports video games ever made. The NES and arcade versions have been re-released (without the NFLPA license) for various platforms.', 'https://en.wikipedia.org/wiki/Tecmo_Bowl'),
  ('Q3520704', 'The Earth Fighter Rayieza is a role-playing video game developed and published by Enix. It was originally published in 1985 for the PC-8801, FM-7, X1, and MSX personal computer systems. The game was ported to the Famicom on December 15, 1987 by Nintendo under the title Ginga no Sannin. The programming was done by Pax Softnica.

The game takes place in a sci-fi setting instead of a fantasy world. The characters from Ginga no Sannin were designed by Go Nagai, who also drew the illustrations for the game''s package. The background music from Ginga no Sannin was composed by Yukihiro Takahashi. Takahashi included an arranged version of Yellow Magic Orchestra''s "Rydeen" as the battle theme.', 'https://en.wikipedia.org/wiki/The_Earth_Fighter_Rayieza'),
  ('Q3516985', 'Tecmo Cup Soccer Game, known as Captain Tsubasa in Japan and Tecmo Cup Football Game in Europe, is an association football sports video game released in 1992 by Tecmo for the Nintendo Entertainment System. The objective of the game is for the player to fight his way from junior league all the way to the finals of the World Cup.

Based on the Captain Tsubasa manga series, Tecmo Cup Soccer Game is a Westernized version of the Japanese Captain Tsubasa game released for the Family Computer system, featuring a different main character, a different introduction and more western-looking players. The game contains elements from role-playing games as the players have skill levels and are mostly controlled by different kinds of text commands.', 'https://en.wikipedia.org/wiki/Tecmo_Cup_Soccer_Game'),
  ('Q3514327', 'Takeshi no Chōsenjō, popularly known as Takeshi''s Challenge, is a 1986 action-adventure video game developed by Nova and published by Taito for the Family Computer. The game was designed by Japanese entertainer Takeshi Kitano and is centered on a salaryman who seeks a treasure on a remote island in the South Seas. Takeshi no Chōsenjō has been negatively received in retrospect due to its unreasonable gameplay requirements that are difficult to clear without foresight.', 'https://en.wikipedia.org/wiki/Takeshi%27s_Challenge'),
  ('Q3521086', 'The Goonies is a 1986 platform game developed and published by Konami for the Family Computer, based on the 1985 film of the same name.', 'https://en.wikipedia.org/wiki/The_Goonies_(Famicom_video_game)'),
  ('Q3954615', 'Idol Hakkenden is a Japan-exclusive adventure game developed by Natsume and published by Towa Chiki in 1989 for the Family Computer.', 'https://en.wikipedia.org/wiki/Idol_Hakkenden'),
  ('Q3985728', 'The Astyanax, known in Japan as The Lord of King, is a 1989 platform video game developed by Aicom and released for arcades by Jaleco. A port to the Nintendo Entertainment System, simply titled Astyanax, was released in 1989 in Japan and in Western regions in 1990, shortly after the arcade version, but is decidedly different from its arcade predecessor in terms of story. Hamster Corporation released the game as part of their Arcade Archives series for the Nintendo Switch and PlayStation 4 in May 2021.', 'https://en.wikipedia.org/wiki/The_Astyanax'),
  ('Q3989775', 'The Uncanny X-Men, sometimes referred to as Marvel''s X-Men, is a 1989 action-platform video game released by LJN for the Nintendo Entertainment System. It is a licensed game based on the series of X-Men comics of the same name by Marvel Comics. The lineup of characters in the game is very close to those appearing in the 1989 animated pilot X-Men: Pryde of the X-Men. It is the second-to-last game to be released under the Enteractive Video Games label and the last to be released before LJN was sold to Acclaim Entertainment.', 'https://en.wikipedia.org/wiki/The_Uncanny_X-Men_(video_game)'),
  ('Q3965791', 'Space Hunter is a Japan-exclusive video game that was released in 1986 for the Family Computer. The game was developed and published by Kemco, which was then known as Kotobuki System.', 'https://en.wikipedia.org/wiki/Space_Hunter'),
  ('Q4035858', 'Captain Skyhawk is a scrolling shooter video game developed by Rare for the Nintendo Entertainment System. The game was released in North America by Milton Bradley in June 1990 and in Europe by Nintendo in May 1994. It was also released for arcades by Nintendo in 1990. It was based on a concept from Milton Bradley, with Rare being contracted to develop the game.', 'https://en.wikipedia.org/wiki/Captain_Skyhawk'),
  ('Q4006617', 'Ushio to Tora: Shin''en no Daiyō is an RPG (Role-playing game) based on the manga series of the same name about a boy and his uneasy friendship with a demon. Released on the Family Computer in 1993 by Yutaka the game has the player in the main role of Ushio in a standard RPG adventure.

This video game is not to be confused with the Super Famicom action game titled Ushio to Tora.', 'https://en.wikipedia.org/wiki/Ushio_to_Tora:_Shin%27en_no_Daiy%C5%8D'),
  ('Q4033647', 'Akumajō Special: Boku Dracula-kun is a 1990 platform game released by Konami in Japan for the Famicom. It is considered a parody of the Castlevania series. A version for mobile phones was released on 30 June 2006 in Japan.

The game saw ports for the PlayStation 4, Xbox One, Nintendo Switch, and Microsoft Windows as part of the Castlevania Anniversary Collection which was released digitally on May 16, 2019, in all regions, with an English localization as Kid Dracula.', 'https://en.wikipedia.org/wiki/Kid_Dracula_(1990_video_game)'),
  ('Q854479', 'Super Mario Bros. 2 is a platform game developed and published by Nintendo for the Nintendo Entertainment System. After the smash hit Super Mario Bros. in 1985, Nintendo quickly released an adaptation of the original with advanced difficulty titled Super Mario Bros. 2 for its market in Japan on June 3, 1986. However, Nintendo of America found this sequel too similar to its predecessor, and its difficulty too frustrating, for the nascent American market. This prompted a second Super Mario Bros. sequel based on Yume Kōjō: Doki Doki Panic, a Famicom Disk System game that had been based on a prototype platforming game and released as an advergame for Fuji Television''s Yume Kōjō ''87 media technology expo on July 10, 1987. The characters, enemies, and themes in Doki Doki Panic have the mascots and theme of the festival, and were adapted into the Super Mario theme to make a Western Super Mario Bros. sequel. Super Mario Bros. 2 was released on October 9, 1988, in North America, and was later released in Europe and Australia on April 28, 1989.', 'https://en.wikipedia.org/wiki/Super_Mario_Bros._2'),
  ('Q856305', 'Bible Adventures is a Christian video game by Wisdom Tree first released in 1991 for the Nintendo Entertainment System, and ported to the Mega Drive/Genesis in 1995. The game was unusual in that it was never sold in video game outlets. It contains three different games: Noah''s Ark, Baby Moses, and David and Goliath, all of which are based rather loosely on stories from the Bible. The gameplay of these games is sidescroller style similar to that of Super Mario Bros. 2 for the NES. The game also features Jesu, Joy of Man''s Desiring, by J. S. Bach, as the background music for the title screen. The game bypasses the 10NES lockout chip by emitting a voltage spike when the NES control deck is turned on.', 'https://en.wikipedia.org/wiki/Bible_Adventures'),
  ('Q851532', 'Momoko 120% is a 1986 platform game developed and published by Jaleco for arcades. The game was originally intended to be an Urusei Yatsura game, but for an unknown reason the license was not obtained for the arcade version; while the characters were changed, "Lum''s Love Song", the first opening theme of the first anime adaptation, still loops throughout the game. The Family Computer port retained the license and was titled Urusei Yatsura: Lum''s Wedding Bell. The game was re-released for mobile phones in Japan on February 28, 2006. Three mobile phone sequels, Momoko 1200%, Momoko 1200% in Machigai Sagashi and Momoko no Kasei Bowling ~La Mars Cup~, were released in Japan only in 2006.', 'https://en.wikipedia.org/wiki/Momoko_120%25'),
  ('Q4044393', 'Mitsume ga Tooru is a video game for the Family Computer that was developed by Natsume and published by Tomy. It is based on the eponymous manga and anime called The Three-Eyed One. The main character is Hosuke Sharaku. There is also a Mitsume ga Tōru game for the original MSX with the same name, which was released by Natsume two years before it was released for the Famicom.', 'https://en.wikipedia.org/wiki/Mitsume_ga_T%C5%8Dru_(video_game)'),
  ('Q4038693', 'Felix the Cat is a platform video game by Hudson Soft, based on the cartoon character of the same name. It was released for the Nintendo Entertainment System (NES) in 1992, and for the Game Boy in 1993. Although Felix the Cat was developed in Japan, it was only released in North America and Europe.

A compilation of both versions was developed by Limited Run Games and published by Konami for the Nintendo Switch, PlayStation 5, and PlayStation 4, on March 28, 2024.', 'https://en.wikipedia.org/wiki/Felix_the_Cat_(video_game)'),
  ('Q4041647', 'Isolated Warrior is a 1991 video game developed by KID and published in Japan by VAP, in North America by NTVIC, and Europe by Nintendo.

Isolated Warrior received mostly positive reception from critics since its initial release; some drew comparison with Zaxxon due to the use of isometric projection, with praise being given to aspects such as the presentation, visuals and frenetic action, but other felt mixed in regards to the sound, difficulty and replay value, while common complaints were geared towards the amount of flickering that occurs when too many objects are present on-screen. Retrospective commentary has been mixed.', 'https://en.wikipedia.org/wiki/Isolated_Warrior'),
  ('Q4045163', 'Technōs Japan Corp. was a Japanese video game developer based in Tokyo. It was best known for the Double Dragon and Kunio-kun franchises (the latter including Renegade, Super Dodge Ball and River City Ransom) as well as The Combatribes and Voltage Fighter Gowcaizer. Arc System Works owns the intellectual properties of the company.', 'https://en.wikipedia.org/wiki/Techn%C5%8Ds_Japan'),
  ('Q4037526', 'Door Door is a single-screen puzzle-platform game by Enix published in Japan in 1983. Originally released for the NEC PC-8801, it was ported to other platforms, including the Family Computer. Controlling a small character named Chun, the player is tasked with completing each stage by trapping different kinds of aliens behind sliding doors. Chun can jump over the aliens and climb ladders, and must also avoid obstacles such as large nails and bombs.

Door Door was designed and programmed by Koichi Nakamura, known as one of the creators of Dragon Quest. The game was the runner-up in the Enix-sponsored "First Game and Hobby Program Contest" in 1982, winning the Outstanding Program Award with a prize of 500,000 yen. Enix was given the rights to the game and ported it to several Japanese home computers. Chun, the name of the protagonist, was a nickname given to Nakamura by one of his friends. Door Door was a critical and commercial success — the PC-8801 version alone had sold 200,000 copies, and is considered a classic title for the Famicom.', 'https://en.wikipedia.org/wiki/Door_Door'),
  ('Q4038932', 'Formula One: Built to Win is a 1990 racing video game for the Nintendo Entertainment System developed by Winkysoft and published by SETA Corporation.

It was one of the first racing games to feature a career mode, multiple vehicles and an opportunity for the player to increase the performance of their in-game car through car tuning. These were unique elements for a racer of the NES era and a genre only truly revisited during the fifth generation of game consoles where games such as Gran Turismo became popular.

Races start out as single-lap events, but become double-lap events as the player begins racing against more experienced competition in places like Las Vegas, Nevada and Hawaii. With gameplay similar to Rad Racer and Pole Position, the driver races towards the back of the screen.', 'https://en.wikipedia.org/wiki/Formula_One:_Built_to_Win'),
  ('Q4039214', 'Galaxy 5000: Racing in the 51st Century is a racing video game developed by Activision for the Nintendo Entertainment System.', 'https://en.wikipedia.org/wiki/Galaxy_5000'),
  ('Q4041940', 'Jurassic Park is a 1993 action video game based on the film of the same name, itself based on Michael Crichton''s 1990 novel. It was developed and published by Ocean Software and released for the Nintendo Entertainment System (NES). Ocean also ported the game onto the handheld Game Boy console.

The object of the game is to survive in Jurassic Park, a theme park and zoo where genetically engineered dinosaurs have escaped from containment.', 'https://en.wikipedia.org/wiki/Jurassic_Park_(NES_video_game)'),
  ('Q4038478', 'F-117A Stealth Fighter is combat flight simulator for the Nintendo Entertainment System where the player fights enemy aircraft and destroy ground targets.', 'https://en.wikipedia.org/wiki/F-117A_Stealth_Fighter'),
  ('Q4045031', 'Nakajima Satoru F-1 Hero (known in North America as Michael Andretti''s World GP) is a video game developed by Human Entertainment released for the Nintendo Entertainment System in 1990. It starred Japanese Formula One driver Satoru Nakajima, and featured the full sixteen-race schedule of the FIA Formula One World Championship circuit.

In the North American version, Satoru Nakajima was replaced by CART driver Michael Andretti, though Andretti himself would only compete in Formula One in the 1993 season).

F-1 Hero was unique in that it deviated from most console racing games of its time. Instead of being an arcade-style driving game (such as Rad Racer or Al Unser Jr.''s Turbo Racing), F-1 Hero more closely resembled a simulation-style racing game. It was the first NES racing game to feature an entire field of real-life drivers (although all but Andretti had pseudonyms), and rather accurately depicted the sixteen circuits on the Formula One schedule. Four different cars were offered in the game, but there were no car set-ups in the game, a feature most frequently associated with racing simulations.', 'https://en.wikipedia.org/wiki/Nakajima_Satoru_F-1_Hero'),
  ('Q4043880', 'Mechanized Attack is a shooter game developed and published by SNK. It was released in North America for the arcade in 1989, and it was ported to the Nintendo Entertainment System in 1990. It can be played with either the NES controller or the NES Zapper light gun.', 'https://en.wikipedia.org/wiki/Mechanized_Attack'),
  ('Q4037585', 'Dragon Fighter is a fantasy-themed side-scrolling action game developed by Natsume for the Nintendo Entertainment System. It was first published in Japan by Towa Chiki in 1990 and in North America by SOFEL in 1992.', 'https://en.wikipedia.org/wiki/Dragon_Fighter_(video_game)'),
  ('Q4051798', 'Trog is a maze arcade video game developed and published by Midway Manufacturing in 1990 in North America under the "Bally/Midway" label and later by Williams Electronics in Europe. In the game, players control one of four dinosaurs chased by the titular cavemen. Its gameplay includes elements of Pac-Man—collect all items in a maze, eat a special item to turn the tables on pursuers—but supports up to four players at once. Initially envisioned as a hybrid puzzle/strategy game, its original concept was later reworked into a Pac-Man-like title after bad reception from testers and features claymation graphics, advertised as "Playmation" by Midway. Conversions for the Nintendo Entertainment System and MS-DOS were released by Acclaim Entertainment in 1990 and 1991 respectively, reducing the number of simultaneous players to two. Both the arcade and NES versions garnered positive reception from critics.', 'https://en.wikipedia.org/wiki/Trog_(video_game)'),
  ('Q4299798', 'Supremacy: Your Will Be Done, released as Overlord in the United States, is a strategy video game designed by David Perry and Nick Bruty and produced by Probe Software.

The game was initially released for the Amiga and Atari ST computers in the beginning of 1990 and later in the same year it was ported to the Commodore 64 too, but released only in the very beginning of 1991. In late 1991, an MS-DOS version was released.

The game was ported to the Nintendo Entertainment System in 1993. The NES cartridge has an internal battery to retain game saves; the computer versions came on two disks.

The NES version was among the last titles released for the platform and is relatively rare. A Famicom version was planned to be released around late 1993, early 1994 by Altron. However, for unknown reasons, it was cancelled.', 'https://en.wikipedia.org/wiki/Supremacy:_Your_Will_Be_Done'),
  ('Q4051460', 'Thundercade, released in Japan as Tokushu Butai U.A.G., is a 1987 vertically scrolling shooter video game developed by SETA and published by Taito for arcades. A version for the Nintendo Entertainment System from Sammy Corporation was released in 1989.

Hamster Corporation released the arcade version as part of their Arcade Archives series for the Nintendo Switch and PlayStation 4, as well as their Arcade Archives 2 series for the Nintendo Switch 2, PlayStation 5 and Xbox Series X/S in October 2026.', 'https://en.wikipedia.org/wiki/Thundercade'),
  ('Q4051248', 'The Punisher is a 1991 video game developed by Beam Software and released by LJN, which stars the Marvel Comics anti-hero, the Punisher. It is one of the few NES rail shooters.', 'https://en.wikipedia.org/wiki/The_Punisher_(1991_NES_video_game)'),
  ('Q4051082', 'The Flintstones: The Surprise at Dinosaur Peak is a platform game for the Nintendo Entertainment System released by Taito in 1993. The game was never released in Japan unlike its predecessor The Flintstones: The Rescue of Dino & Hoppy.', 'https://en.wikipedia.org/wiki/The_Flintstones:_The_Surprise_at_Dinosaur_Peak'),
  ('Q4051552', 'Shatterhand is a side-scrolling action game for the Nintendo Entertainment System developed by Natsume and published by Jaleco in North America in 1991 and in Europe in 1992. Shatterhand was originally released by Angel (Bandai) in Japan in 1991 as a licensed game for the Family Computer based on the live-action superhero series Super Rescue Solbrain.', 'https://en.wikipedia.org/wiki/Shatterhand'),
  ('Q4053053', 'Werewolf: The Last Warrior is a platform game for the Nintendo Entertainment System. The game was released in November 1990 in North America. It starred a werewolf character named Warwolf.', 'https://en.wikipedia.org/wiki/Werewolf:_The_Last_Warrior'),
  ('Q4184061', 'Ninja Hattori-kun is a 1986 video game software developed and published by Hudson Soft exclusively in Japan for the Nintendo Family Computer. It is based on Fujiko Fujio A''s (pen name of Motoo Abiko) Japanese manga series of the same name, which later became an anime series and Asian franchise. The game was released around the same time the anime was aired. It was among the best selling Famicom games, selling approximately 1,500,000 copies in its lifetime.', 'https://en.wikipedia.org/wiki/Ninja_Hattori-kun_(video_game)'),
  ('Q869113', 'Kid Kool and the Quest for the Seven Wonder Herbs is a 1988 video game by Vic Tokai for the Nintendo Entertainment System. The game''s main character is based on a popular Japanese child actor Kenji Sagara, known for his impersonation of baseball player Masayuki Kakefu.', 'https://en.wikipedia.org/wiki/Kid_Kool'),
  ('Q869138', 'Cosmic Wars is a turn-based strategy video game for the Family Computer produced by Konami in 1989 which is based upon the characters and conflicts of the popular Gradius series. It was released only in Japan. The game received a sequel in 1997, with Paro Wars, which is the Parodius equivalent of this game.

The object of Cosmic Wars is to use an army composed of Gradius characters (Vic Vipers, and Big Cores) and battle enemies in various star systems. The player can be either the Bacterion Empire or the forces of Gradius. There are many different unit types, ranging from small fighters to large capital ships.', 'https://en.wikipedia.org/wiki/Cosmic_Wars'),
  ('Q4049949', 'Splatterhouse: Wanpaku Graffiti is a 1989 action-platform video game developed by Now Production and published by Namco for the Family Computer. It was originally released only in Japan, although it saw a localized Western release in 2020 as part of the Namco Museum Archives Vol. 1 compilation. It is the second game in the Splatterhouse series, and the first to be released for a home console. The game is a parody of the original Splatterhouse, and takes a comical approach to its presentation, featuring super deformed characters as well as parodies of horror films and other pop culture references related to the genre.', 'https://en.wikipedia.org/wiki/Splatterhouse:_Wanpaku_Graffiti'),
  ('Q4049992', 'Square''s Tom Sawyer is a role-playing video game produced by Square that was released exclusively in Japan in 1989 for the Family Computer. The game is directly based on Mark Twain''s renowned 1876 novel, The Adventures of Tom Sawyer, and was developed in the role-playing video game niche that made Square famous with its acclaimed Final Fantasy series of video games.', 'https://en.wikipedia.org/wiki/Square%27s_Tom_Sawyer'),
  ('Q4047361', 'Prince of Persia is a 1989 cinematic platform game developed and published by Broderbund for the Apple II. It was designed and implemented by Jordan Mechner. Taking place in medieval Persia, players control an unnamed protagonist who must venture through a series of dungeons to defeat the evil Grand Vizier Jaffar and save an imprisoned princess.

Much like Karateka, Mechner''s first video game, Prince of Persia used rotoscoping for its fluid and realistic animation. For this process, Mechner used as reference for the characters'' movements videos of his brother doing acrobatic stunts in white clothes and swashbuckler films such as The Adventures of Robin Hood.', 'https://en.wikipedia.org/wiki/Prince_of_Persia_(1989_video_game)'),
  ('Q4048088', 'Recca is a 1992 scrolling shooter video game developed by KID and published by Naxat Soft for the Family Computer. Controlling the titular space fighter craft, the player is sent to counterattack an invading alien armada while avoiding collision with their projectiles and other obstacles. The ship has a powerful bomb at its disposal that can be used as shield and clear the screen of enemies and bullets when fully charged.

Known for pushing the Famicom hardware to the limits with its uncompromising high number of sprites and speed, Recca was created for a shooting game competition hosted by Naxat Soft called "Summer Carnival", which took place on July 17, 1992 and featured alongside the PC Engine CD-ROM² shooter Alzadick. It was programmed by Shinobu Yagawa, whose later works includes Battle Garegga, Ibara, Pink Sweets: Ibara Sorekara and Muchi Muchi Pork!. The game was released in Japan amid focus shifting to the Super Famicom, resulting in few copies sold when released to the market and is considered by gaming journalists as one of the rarest, most valuable and sought-after Famicom titles.', 'https://en.wikipedia.org/wiki/Recca'),
  ('Q4047296', 'Power Blade 2, known in Japan as Captain Saver, is a 1992 platform game published by Taito for the Nintendo Entertainment System/Family Computer. It is the sequel to the game Power Blade.', 'https://en.wikipedia.org/wiki/Power_Blade_2'),
  ('Q4047297', 'Power Blade, known in Japan as Power Blazer, is an action platform video game published by Taito for the Nintendo Entertainment System. It was released in Japan on April 20, 1990, North America in March 1991, and in Europe on January 23, 1992 (1992-01-23). The game spawned a sequel, Power Blade 2, released in 1992.

Power Blade takes place in the colony of New Earth in the year 2191 and follows NOVA, the Chief Security Officer of a supercomputer called the Master Computer. He must restore the Master Computer — which has been taken offline by aliens — by retrieving data tapes located in six sectors. The game features gameplay similar to the Mega Man series, in which players can select any of the six levels to play. Armed with a boomerang, players must complete all six levels, overcoming obstacles and defeating any enemies in the way.', 'https://en.wikipedia.org/wiki/Power_Blade'),
  ('Q4045164', 'Nekketsu Fighting Legend is a 1992 tournament-style fighting game developed and published by Technōs Japan in Japan for the Family Computer on December 23, 1992. It is a spin-off of the Kunio-kun series, as well as Technōs Japan''s first attempt in the genre since their port of their Double Dragon arcade game on the same platform. Technōs Japan later became better known for its Neo Geo titles, such as Double Dragon fighting game and Voltage Fighter Gowcaizer.

It is also the first fighting game to allow up to four players to play simultaneously against each other. In order for more than two players to play, a multitap (like the 4-Players Adaptor by Hori) is required.', 'https://en.wikipedia.org/wiki/Nekketsu_Fighting_Legend'),
  ('Q4353838', 'Superman is a 1987 NES video game by Kemco based on the DC Comics character. The Japanese release featured a synthesized version of the 1978 film''s score, but in the US version, it was replaced by music from another Kemco title, Indora no Hikari, a fantasy-RPG released the same year for the Famicom.', 'https://en.wikipedia.org/wiki/Superman_(1987_video_game)'),
  ('Q5530304', 'Gekitotsu Yonku Battle is a Japan-exclusive video game of the vehicular combat game genre released in 1989 by Irem for the Family Computer.', 'https://en.wikipedia.org/wiki/Gekitotsu_Yonku_Battle'),
  ('Q4594431', 'The Nintendo Entertainment System has a library of 1370 officially licensed games released during their lifespans, plus 7 official multicarts and 2 championship cartridges. Of these, 672 were released exclusively in Japan, 187 were released exclusively in North America, and 19 were released exclusively in Phase Alternating Line (PAL) countries. Worldwide, 521 games were released.

Its launch games for the Famicom were Donkey Kong, Donkey Kong Jr., and Popeye. Only first-party titles were available upon launch, but Nintendo started a licensing program the following year that allowed third-party companies such as Namco, Hudson Soft, Taito, Konami, Bandai, and Capcom to create titles and produce their own cartridges for the Famicom in exchange for royalty payments; Nintendo later revised the program to mandate itself as the manufacturer of all cartridges while carrying it with the console outside Japan. The launch games for North America were: 10-Yard Fight, Baseball, Clu Clu Land, Duck Hunt, Excitebike, Golf, Gyromite, Hogan''s Alley, Ice Climber, Kung Fu, Pinball, Soccer, Stack-Up, Super Mario Bros., Tennis, Wild Gunman, and Wrecking Crew. The final licensed game released is the PAL-exclusive The Lion King on May 25, 1995.', 'https://en.wikipedia.org/wiki/List_of_Nintendo_Entertainment_System_games'),
  ('Q4397217', 'Digger T. Rock: Legend of the Lost City is a platform game developed by Rare and published by the Milton Bradley Company for the Nintendo Entertainment System. It was first released in North America in December 1990 and in Europe in 1991. The game centres around the miner Digger T. Rock, as he spelunks various caves and catacombs whilst searching for the mythical Lost City.

The game received mixed reviews upon release, with praise directed at its playability but was criticised for its poor graphics and presentation. It was later included in Rare''s 2015 Xbox One retrospective compilation, Rare Replay.', 'https://en.wikipedia.org/wiki/Digger_T._Rock'),
  ('Q4549969', 'Eliminator Boat Duel is a powerboat racing video game developed for the Nintendo Entertainment System by Sculptured Software and Radioactive Software. It was published by Electro Brain in 1991.', 'https://en.wikipedia.org/wiki/Eliminator_Boat_Duel'),
  ('Q4639069', '4 Nin Uchi Mahjong is a 1984 mahjong video game developed by Hudson Soft and published by Nintendo for the Family Computer. It was released exclusively in Japan. It is the third mahjong game published by Nintendo, following the handheld electronic game Computer Mah-jong Yakuman and the 1983 video game Mah-Jong.', 'https://en.wikipedia.org/wiki/4_Nin_Uchi_Mahjong'),
  ('Q4696494', 'The following is a list of games developed and/or published by Irem (formerly known as IPM) for a variety of arcade and console platforms. The page may also includes ports from other companies licensed by Irem.', 'https://en.wikipedia.org/wiki/List_of_Irem_games'),
  ('Q4686640', 'Adventures of Dino Riki, known in Japan as Shin Jinrui: The New Type, is a scrolling shooter video game developed by Hudson Soft for the Nintendo Entertainment System. The player takes on the role of the titular Dino Riki in a prehistoric setting, tasked with completing a series of vertically-scrolling stages while contending with various enemies, platforming sections, and bosses. Power-ups that improve the player''s weapons or mobility can be uncovered by hitting boulders scattered about each stage.

Japanese magazines previewed it as an action game with unique mechanics before it was converted into a scrolling shooter just prior to launch. Hudson had desired to release a game similar to Konami''s 1986 MSX shooter Knightmare. The Adventures of Dino Riki development staff has only been revealed through social media posts. Wrestler Riki Choshu lent his name and likeness to the project and was featured prominently in its Japanese advertising.', 'https://en.wikipedia.org/wiki/Adventures_of_Dino_Riki'),
  ('Q4746580', 'Dash Galaxy in the Alien Asylum is a platform game for the Nintendo Entertainment System, developed by Beam Software and published by Data East, released in 1990 exclusively in North America.', 'https://en.wikipedia.org/wiki/Dash_Galaxy_in_the_Alien_Asylum'),
  ('Q4792003', 'Arkista''s Ring is an action-adventure game developed by NMK and published by American Sammy for the Nintendo Entertainment System in 1990. The game is set in a fantasy world where the player controls a female elf named Christine, in her quest to find the titular magic item.', 'https://en.wikipedia.org/wiki/Arkista%27s_Ring'),
  ('Q4797404', 'Artelius is an action role-playing video game developed and published by Nichibutsu for the Family Computer exclusively in Japan on November 13, 1987.', 'https://en.wikipedia.org/wiki/Artelius'),
  ('Q4807433', 'Asmik-kun Land is an action platform video game published by Asmik for the Family Computer in 1991.

A pink dinosaur named Asmik-kun (named "Boomer" in the English release of Boomer''s Adventure in ASMIK World) seeks to recover six fragments so he can wake the dragon ruler of the world and make Asmik Land a paradise.', 'https://en.wikipedia.org/wiki/Asmik-kun_Land'),
  ('Q4701118', 'Akira is a 1988 adventure video game by TOSE for the Family Computer console exclusively in Japan. It is based on Akira, the 1988 animated film version of Katsuhiro Otomo''s manga of the same name.', 'https://en.wikipedia.org/wiki/Akira_(video_game)'),
  ('Q4742751', 'America Daitōryō Senkyo is a government simulation video game released by Hector Playing Interface for the Family Computer in 1988. It is loosely based on the 1988 election campaign for the president of the United States and features characters based on actual candidates and other politicians. The game was conceived and directed by Japanese CNN Daywatch newscaster Shintaro Ito, who would later become a politician himself.', 'https://en.wikipedia.org/wiki/America_Dait%C5%8Dry%C5%8D_Senkyo'),
  ('Q4908891', 'Bill Elliott''s NASCAR Challenge is a video game developed by Distinctive Software and published by Konami and was released for MS-DOS, Amiga, Macintosh and Nintendo Entertainment System in 1991.

A very similar game, Bill Elliott''s NASCAR Fast Tracks, was released for the Game Boy in 1991 by Konami.

This game is the first video game to ever secure the NASCAR license. It features eight real NASCAR tracks in the game, such as Watkins Glen and Talladega. This game is also the first to feature a real NASCAR driver in a PC game, Bill Elliott.', 'https://en.wikipedia.org/wiki/Bill_Elliott%27s_NASCAR_Challenge'),
  ('Q4869623', 'Bats & Terry is a Japanese manga series written and illustrated by Yasuichi Oshima. It was serialized in Kodansha''s Weekly Shōnen Magazine from 1982 to 1987. Batsu & Terī received the 1984 Kodansha Manga Award for the shōnen category. Kodansha published the manga''s 24 tankōbon volumes to December 1987. The manga''s license was transferred to Ichijinsha and was published into four wideban volumes.

The manga was adapted into an animated movie by Sunrise. Directed by Mitsuko Kase and Tetsuro Amino, the movie was released in Japan on March 14, 1987. A VHS was released for the movie on April 21, 1987.', 'https://en.wikipedia.org/wiki/Bats_%26_Terry'),
  ('Q4904863', 'Bigfoot is a racing video game released in July 1990 for the Nintendo Entertainment System. It was developed by Beam Software and published by Acclaim. The game was advertised by the legendary monster truck of the same name in the cartoon segment of the 1990 television show, Video Power, titled The Power Team. The show also often used sound effects for the actions of not only Bigfoot, but others as well.', 'https://en.wikipedia.org/wiki/Bigfoot_(video_game)'),
  ('Q4870108', 'Battle Rush: Build Up Robot Tournament is a Japan-exclusive video game for the Datach Joint ROM System add-on for the Family Computer. The game was one of six that required Bandai''s Datach system in order to operate.', 'https://en.wikipedia.org/wiki/Battle_Rush:_Build_Up_Robot_Tournament'),
  ('Q4907851', 'Bill & Ted''s Excellent Video Game Adventure is an action-adventure video game that is part of the Bill & Ted franchise and is based on the film Bill & Ted''s Excellent Adventure. It was released in North America by LJN for the Nintendo Entertainment System in 1991. The plot is an original continuation to the film''s events.', 'https://en.wikipedia.org/wiki/Bill_%26_Ted%27s_Excellent_Video_Game_Adventure'),
  ('Q4880213', 'Three video games based on the 1988 American film Beetlejuice (as well its animated TV adaptation) were released in 1990, 1991, and 1992. In addition, a Beetlejuice expansion pack featuring maps, playable characters and missions was released in 2017 as part of the Lego Dimensions crossover video game "fun packs" line.', 'https://en.wikipedia.org/wiki/List_of_Beetlejuice_video_games'),
  ('Q4870119', 'Battle Storm is a Family Computer video game that was published by Yonezawa PR21 and released on December 21, 1991. An unofficial English translation patch for Battle Storm was released on October 23, 2015.', 'https://en.wikipedia.org/wiki/Battle_Storm'),
  ('Q4870132', 'B-Wings is an action sci-fi vertical shooter first released as an arcade video game by Data East in 1984. A version was released in 1986 for the Family Computer. It was Data East''s first home release for the console. The Family Computer version is notable for its inclusion in many unofficial Famiclone multicarts.', 'https://en.wikipedia.org/wiki/B-Wings'),
  ('Q4893630', 'Famicom Jump II: Saikyō no Shichinin is an action role-playing game for the Family Computer developed by Chunsoft and published by Bandai on December 2, 1991. The sequel to Famicom Jump: Hero Retsuden 『ファミコンジャンプ 英雄列伝』（published in 1989）, the game features seven main characters from different Weekly Shōnen Jump manga serialized at the time. Only four of the 16 represented titles from the original are brought back, while the remaining three are new to the sequel. There would not be another crossover game until the release of Jump Super Stars and Jump Ultimate Stars.', 'https://en.wikipedia.org/wiki/Famicom_Jump_II:_Saiky%C5%8D_no_Shichinin'),
  ('Q4931103', 'Bo Jackson Baseball is a baseball video game for the Nintendo Entertainment System, Amiga, TurboGrafx-16, and MS-DOS. It features athlete Bo Jackson, then a star in professional baseball and a former professional football player. In Europe, it was released by Mindscape as TV Sports: Baseball, part of the TV Sports series including TV Sports: Basketball and other games based on hockey and American football.', 'https://en.wikipedia.org/wiki/Bo_Jackson_Baseball'),
  ('Q4998084', 'Burai Fighter is a shoot ''em up video game developed by KID for the Nintendo Entertainment System. The game was released in North America by Taxan in March 1990, PAL regions by Nintendo in 1990, and Japan by Taito on July 20, 1990. The game was ported to the Game Boy and retitled as Burai Fighter Deluxe, and was released in Japan on June 27, 1990, in North America in January 1991 and in Europe in 1991; this port was released for the Game Boy Color as Space Marauder, originally released in Japan as Burai Fighter Color, as the original Game Boy version is not compatible with the later models.

The setting for Burai Fighter is to fend off seven bases of Burai, super-intelligent cyborgs. The player starts out with a relatively weak cannon, but can upgrade to ring, laser, and missile weapons, which are much more powerful. The player can initially choose from three difficulty settings: Eagle, Albatross, and Ace; the fourth difficulty setting, Ultimate, must be unlocked. The character can be moved in 8 directions and can shoot in a different direction from the direction he is moving towards.', 'https://en.wikipedia.org/wiki/Burai_Fighter'),
  ('Q4915918', 'Bird Week is a single-player action video game released for the Nintendo Family Computer.', 'https://en.wikipedia.org/wiki/Bird_Week'),
  ('Q4959302', 'Break Time: The National Pool Tour is a pocket billiards (pool) video game released for the Nintendo Entertainment System in 1993 exclusively for a North American audience.', 'https://en.wikipedia.org/wiki/Break_Time:_The_National_Pool_Tour'),
  ('Q4942780', 'Kid''s Horehore Daisakusen is a 1987 action video game developed and published by Nichibutsu for arcades. A port for the Family Computer was released under the name Booby Kids. A port to the TurboGrafx-16 developed by Hudson Soft was released as Cratermaze, which was released outside Japan unlike the other versions.

A sequel named Booby Boys was released by Nichibutsu for the Game Boy in 1993.', 'https://en.wikipedia.org/wiki/Kid%27s_Horehore_Daisakusen'),
  ('Q4922705', 'Super Dodge Ball is a 1989 sports video game developed and published by Technōs Japan for the Nintendo Entertainment System. It is loosely based on the 1987 arcade game of the same name. Like its arcade counterpart, it was released in Japan as part of the Kunio-kun series.

In Japan, a PC port of the Famicom version of Nekketsu Kōkō Dodgeball Bu was released on October 17, 2003, as a budget-priced release. It was also included in the Game Boy Advance compilation Kunio-kun Nekketsu Collection 1, released in 2005. Both the Famicom version and the American NES version were released for the Wii, Nintendo 3DS and Wii U Virtual Console for their respective territories. The game was also released in Europe for the two latter systems, despite the NES version not being released in Europe.', 'https://en.wikipedia.org/wiki/Super_Dodge_Ball_(1988_video_game)'),
  ('Q4982197', 'Bubble Bobble Part 2, known in Japan as Bubble Bobble 2, is a platform video game released by Taito in 1993 for the Nintendo Entertainment System and Game Boy. It is the fourth installment in the Bubble Bobble series, itself a sequel to the 1986 arcade game Bubble Bobble. While it was never released in the arcades, two versions of the game were developed independently from each other (for the NES and Game Boy systems). Both games received a different storyline as a result. The Game Boy version is known in Japan as Bubble Bobble Junior.', 'https://en.wikipedia.org/wiki/Bubble_Bobble_Part_2'),
  ('Q4822548', 'Otaku no Seiza: An Adventure in the Otaku Galaxy is a role-playing video game developed by Advance Communications and published by M&M for the Famicom in 1991. Aurora Quest: Otaku no Seiza in Another World is a remake of the Famicom version for the PC Engine Super CD-ROM by Pack-In-Video in December 1993–which featured updated graphics. Neither version was released outside of Japan. An OVA adaptation of this was also released in Japan in 1994.

The game combines science fiction and comedy. In it, an unnamed hero arrives in the city where women stole the rights of men. The player controls a man as he tries to free other men around the city. Otaku no Seiza features turn-based battles, similar to those of the Dragon Quest series.', 'https://en.wikipedia.org/wiki/Otaku_no_Seiza:_An_Adventure_in_the_Otaku_Galaxy'),
  ('Q4849609', 'Bakushō! Star Monomane Shitennō is a Nintendo Family Computer life simulation video game that portrays the life of either a musician or a famous performer of the monomane style of Japanese theatre. The object is to gain popularity while performing concert tours through the fictional city. Celebrity challenges are included in the game; they are considered to be miniature games like swimming and kicking a giant ball into a goal in a manner similar to soccer. While these games are fun to play, losing results in a loss of popularity points similar to performing terribly at a concert.', 'https://en.wikipedia.org/wiki/Bakush%C5%8D!_Star_Monomane_Shitenn%C5%8D'),
  ('Q4859992', 'Barcode World is a video game developed by Epoch and published by Sunsoft for the Famicom in 1992.', 'https://en.wikipedia.org/wiki/Barcode_World'),
  ('Q4822828', 'Aussie Rules Footy is the first AFL simulation video game for the Nintendo Entertainment System. It was developed by Melbourne-based Beam Software and published under their "Laser Beam" publishing title in 1991. The release was Australian-only, with distribution handled through Mattel''s Australian operations.', 'https://en.wikipedia.org/wiki/Aussie_Rules_Footy'),
  ('Q4860942', 'Barker Bill''s Trick Shooting is a light gun shooter video game developed and published by Nintendo for the Nintendo Entertainment System in 1990.', 'https://en.wikipedia.org/wiki/Barker_Bill%27s_Trick_Shooting'),
  ('Q4811499', 'Astro Fang: Super Machine is a Family Computer video game that was released for an exclusively Japanese market in 1990.', 'https://en.wikipedia.org/wiki/Astro_Fang:_Super_Machine'),
  ('Q4853838', 'Banana Prince is a platform game developed by KID released in Japan by Takara on December 20, 1991 for the Family Computer. The German version was released in February 1992 for the Nintendo Entertainment System, and features slightly different graphics and game show questions.', 'https://en.wikipedia.org/wiki/Banana_Prince');

insert into import_summary (wikidata_id, summary, source) values
  ('Q4849608', 'This is a list of games developed or published by Taito, a Japanese video game developer and publisher. It also includes games released exclusively by its international subsidiaries, such as Taito America and Taito of Brazil.', 'https://en.wikipedia.org/wiki/List_of_Taito_games'),
  ('Q5036800', 'Captain Silver is a side-scrolling hack and slash platform game released as an arcade video game by Data East in 1987. Home versions were published for the Master System by Sega and for the Famicom by Tokuma Shoten.', 'https://en.wikipedia.org/wiki/Captain_Silver'),
  ('Q5048860', 'Casino Kid is a casino video game developed and published by SOFEL for the Nintendo Entertainment System in 1989. In Japan, the game was released as $1,000,000 Kid: Maboroshi no Teiou Hen and is based on the manga series $1,000,000 Kid by Yuki Ishigaki.', 'https://en.wikipedia.org/wiki/Casino_Kid'),
  ('Q5034540', 'Capcom''s Gold Medal Challenge ''92, known in Japan as Capcom Barcelona ''92, is a 1992 video game by Capcom. It was an Olympic sports game loosely based on the 1992 Summer Olympics in Barcelona. It heavily relied on button mashing style games. This game is also notable for its capability to have 8 human competitors to compete in the Olympiad concurrently against each other (although only two at a time).', 'https://en.wikipedia.org/wiki/Capcom%27s_Gold_Medal_Challenge_%2792'),
  ('Q5048851', 'The Nintendo Entertainment System has a library of 1370 officially licensed games released during their lifespans, plus 7 official multicarts and 2 championship cartridges. Of these, 672 were released exclusively in Japan, 187 were released exclusively in North America, and 19 were released exclusively in Phase Alternating Line (PAL) countries. Worldwide, 521 games were released.

Its launch games for the Famicom were Donkey Kong, Donkey Kong Jr., and Popeye. Only first-party titles were available upon launch, but Nintendo started a licensing program the following year that allowed third-party companies such as Namco, Hudson Soft, Taito, Konami, Bandai, and Capcom to create titles and produce their own cartridges for the Famicom in exchange for royalty payments; Nintendo later revised the program to mandate itself as the manufacturer of all cartridges while carrying it with the console outside Japan. The launch games for North America were: 10-Yard Fight, Baseball, Clu Clu Land, Duck Hunt, Excitebike, Golf, Gyromite, Hogan''s Alley, Ice Climber, Kung Fu, Pinball, Soccer, Stack-Up, Super Mario Bros., Tennis, Wild Gunman, and Wrecking Crew. The final licensed game released is the PAL-exclusive The Lion King on May 25, 1995.', 'https://en.wikipedia.org/wiki/List_of_Nintendo_Entertainment_System_games'),
  ('Q5050376', 'Castle of Deceit is a side-scrolling platform game for the Nintendo Entertainment System released in 1990 by Bunch Games. The player controls a wizard trapped in a castle with only one spell to defend himself.', 'https://en.wikipedia.org/wiki/Castle_of_Deceit'),
  ('Q5054142', 'Raid 2020 is a 1989 cyberpunk action video game for the Nintendo Entertainment System (NES). It was developed by Dan Burke and Frank Waung and sold to Color Dreams, a studio known for publishing unlicensed NES games. Raid 2020 was released in North America and Australia.', 'https://en.wikipedia.org/wiki/Raid_2020'),
  ('Q5068928', 'Color Dreams was an American video game developer and publisher formerly known for developing and publishing unlicensed video games for the Nintendo Entertainment System (NES).

At a time when the vast majority of NES games were licensed by Nintendo, Color Dreams discovered how to bypass the 10NES lock-out system that restricted unlicensed software. By avoiding licensing fees, Color Dreams could release a large quantity of games while undercutting the prices of other publishers. The company operated in a legal gray area but was never sued by Nintendo. Color Dreams also developed a reputation for the poor quality of its games and is now infamous for publishing games considered to be some of the worst of all time.', 'https://en.wikipedia.org/wiki/Color_Dreams'),
  ('Q5001815', 'Business Wars is a text adventure video game released for Japan''s Family Computer.', 'https://en.wikipedia.org/wiki/Business_Wars_(video_game)'),
  ('Q5050570', 'Castlequest, known in Japan as Castle Excellent, is a 1985 puzzle-action video game developed and published by ASCII Corporation for the FM-7, PC-88, and Sharp X1. Additional versions followed in 1986 for the Family Computer and MSX, and was subsequently released in 1989 for the Nintendo Entertainment System in the United States by Nexoft Corporation (the American division of ASCII).

It is the sequel to The Castle, released in 1985 for the MSX, SG-1000, and other systems (though not the NES). Like that game, it is an early example of the Metroidvania genre.', 'https://en.wikipedia.org/wiki/Castlequest'),
  ('Q5070108', 'Athena Co. Ltd. was a Japanese video game developer, founded in July 1987.', 'https://en.wikipedia.org/wiki/Athena_(game_developer)'),
  ('Q5054998', 'Caveman Ughlympics or Caveman Ugh-lympics is a 1988 Olympic-themed sports video game set in the Stone Age. It was developed for the Commodore 64 and MS-DOS by Dynamix and published by Electronic Arts. The Nintendo Entertainment System version was released by Data East as Caveman Games.', 'https://en.wikipedia.org/wiki/Caveman_Ughlympics'),
  ('Q5050386', 'Castle of Dragon is a 1989 beat ''em up platform video game developed by Athena and published by SETA Corporation for arcades. It was released in Japan in August 1989 and in North America by Romstar the same month. It was ported the Nintendo Entertainment System in the year of 1990; the Japanese version was released by Athena as Dragon Unit.

Hamster Corporation acquired the game''s rights alongside Athena''s catalogue, releasing the game as part of their Arcade Archives series for the Nintendo Switch and PlayStation 4 in January 2025.', 'https://en.wikipedia.org/wiki/Castle_of_Dragon'),
  ('Q5070123', 'Championship Lode Runner is a sequel to the 1983 puzzle-platform game Lode Runner. It was released in 1984 for the Apple II, Commodore 64, and IBM PC (as a self-booting disk), then ported to the Atari 8-bit computers, Famicom, SG-1000, and MSX. While very similar to Lode Runner, Championship Lode Runner features levels that are much more difficult. Unlike the original, it does not include a level editor.', 'https://en.wikipedia.org/wiki/Championship_Lode_Runner'),
  ('Q5090594', 'NES Play Action Football is a football video game developed by Tose and published by Nintendo for the Nintendo Entertainment System. It was released in 1990 in North America only. The game was also ported to the Game Boy as Play Action Football, and received a follow-up on the Super NES titled Super Play Action Football in 1992 in North America only. It was released on the Wii Virtual Console in North America on September 10, 2007. The Virtual Console version was available as a Club Nintendo bonus download from August 19 to September 2, 2012.', 'https://en.wikipedia.org/wiki/NES_Play_Action_Football'),
  ('Q5160162', 'Conflict is a 1989 hex-based war game developed and published by Vic Tokai for the Nintendo Entertainment System. It was the first NES game to display the battlefield as a hex map.', 'https://en.wikipedia.org/wiki/Conflict_(video_game)'),
  ('Q5102634', 'Arc System Works Co., Ltd., commonly referred to as ArcSys, is a Japanese video game developer and publisher located in Yokohama. Founded by Minoru Kidooka in 1988, the company is known for arcade 2D fighting game franchises, including Guilty Gear and BlazBlue. They have also developed other fighting games using external licenses, including Dragon Ball FighterZ, Persona 4 Arena and Arena Ultimax, Granblue Fantasy Versus and Versus Rising, Marvel Tōkon: Fighting Souls, and others.', 'https://en.wikipedia.org/wiki/Arc_System_Works'),
  ('Q5162455', 'Conquest of the Crystal Palace, known in Japan as Matendōji (魔天童子; "Demon Heaven Boy") is a 1990 platform game developed by Quest and published by Asmik Corporation of America (subsidiary of J:COM) for the Nintendo Entertainment System.', 'https://en.wikipedia.org/wiki/Conquest_of_the_Crystal_Palace'),
  ('Q5121797', 'Circus Caper, known as Moeru! Onīsan in Japan, is the title of a side-scrolling Nintendo Entertainment System video game where the player controls a young boy on a quest to save his sister who has been kidnapped by the circus. The game was released in 1989 by Toho and received poor reviews.', 'https://en.wikipedia.org/wiki/Circus_Caper'),
  ('Q5158103', 'Conan (also known as Conan: The Mysteries of Time) is a side-scrolling action video game for the Nintendo Entertainment System released in 1991. It was developed by Eastridge Technology and published by Mindscape. While it features the Conan the Barbarian character, it is an adaptation of the computer game Myth: History in the Making developed by System 3, not the 1982 film starring Arnold Schwarzenegger.', 'https://en.wikipedia.org/wiki/Conan:_The_Mysteries_of_Time'),
  ('Q5165990', 'Ghostbusters is a video game by Activision based on the the 1984 film of the same name. Designed by David Crane, it was released for several home computer platforms in 1984, and later for consoles, including the Atari 2600, Master System and Nintendo Entertainment System. The primary target was the Commodore 64 and the programmer for the initial version of the game was Adam Bellin. All versions of the game were released in the USA except for the Amstrad CPC and ZX Spectrum versions, which were released only in Europe, and the MSX version, which was released only in Europe, South America, and Japan.', 'https://en.wikipedia.org/wiki/Ghostbusters_(1984_video_game)'),
  ('Q5070142', 'Championship Rally, known as Exciting Rally: World Rally Championship in Japan, is a 1991 racing video game published by HAL Laboratory and made for the Nintendo Entertainment System. This game was not released in North America and is considered semi-rare.', 'https://en.wikipedia.org/wiki/Championship_Rally_(1991_video_game)'),
  ('Q5149054', 'Colorful Dragon, is a maze video game developed and published by Sachen for the Nintendo Entertainment System on 1989 in Asia. Bunch Games later licensed the game for distribution in North America for a 1990 release, and published it as Tagin'' Dragon.

The game was not licensed by Nintendo. Sachen republished Colorful Dragon in the multi-game cartridge Super Cartridge Version 6: 6-in-1.', 'https://en.wikipedia.org/wiki/Colorful_Dragon'),
  ('Q5182325', 'Crash ''n'' the Boys: Street Challenge, released in Japan as Bikkuri Nekketsu Shin Kiroku! Harukanaru Kin Medal, is a 1992 sports video game developed and published by Technōs Japan for the Nintendo Entertainment System. A Game Boy version of the game was also released in Japan only. The game featured Olympic style contests without rules or regulations, between five teams. The games included 400 metres hurdles, Hammer throw, Swimming, Roof Top Jumping, and Fighting Scene. It was re-released for the Wii Virtual Console on September 14, 2009 and later for the Nintendo 3DS on November 28, 2013 and for the Wii U on December 11, 2014. The game was included in the "Double Dragon & Kunio-kun: Retro Brawler Bundle", with the original Japanese version translated and retitled as Surprise! Nekketsu New Records! The Distant Gold Medal, which was released for the Nintendo Switch on February 20, 2020. It was re-released for Nintendo Switch, Xbox One and PlayStation 4 in April the same year.', 'https://en.wikipedia.org/wiki/Crash_%27n%27_the_Boys:_Street_Challenge'),
  ('Q5220859', 'Danny Sullivan''s Indy Heat is a 1991 racing game developed and published in arcades by Leland Corporation. It stars American Indy car driver Danny Sullivan, and features the tracks of the CART series of the early 1990s. Home versions of the game were released for the Nintendo Entertainment System, Amiga, Atari ST, and Commodore 64.', 'https://en.wikipedia.org/wiki/Danny_Sullivan%27s_Indy_Heat'),
  ('Q5183051', 'Crayon Shin-Chan: Ora to Poi Poi is a puzzle video game for the Family Computer based on the series Crayon Shin-chan. It was developed by TOSE and published by Bandai on August 27, 1993, in Japan only. A version of the game was simultaneously released for the Datach Joint ROM System add-on but lacked any features that utilized its barcode card reading capabilities.', 'https://en.wikipedia.org/wiki/Crayon_Shin-Chan:_Ora_to_Poi_Poi'),
  ('Q5167368', 'Cool World is a 1993 action game for the Nintendo Entertainment System that is loosely based on the movie Cool World. Different games based on the film were also released for the SNES and various personal computers.', 'https://en.wikipedia.org/wiki/Cool_World_(NES_video_game)'),
  ('Q5215030', 'Dance Aerobics, released in Japan as Aerobics Studio, is a music video game developed by Human Entertainment for the Nintendo Entertainment System. It was released in Japan by Bandai in February 1987 and North America by Nintendo in March 1989. It is the third game in Bandai''s Family Trainer series, which was designed for use with the NES'' 3x4 dance mat, the Power Pad, making it similar to the rhythm game genre, a genre that would later explode into the mainstream gaming market at the tail end of the 1990s.', 'https://en.wikipedia.org/wiki/Dance_Aerobics'),
  ('Q5191424', 'Crystalis is a 1990 action role-playing video game developed and published by SNK for the Nintendo Entertainment System. A version for the Game Boy Color developed by Nintendo Software Technology and published by Nintendo was released in 2000.

The game begins with a young magician awakening from the cryogenic sleep he was placed in by the villains of the Great War before nuclear war rained down in the year 1997. Even though he is unable to recall his name or who he was, he exits the Mezame Shrine and discovers that he may be the key to save this world from destruction. Aided by four wise sages and a mysterious woman, he rises up against the tyrannical Draygonian Empire to ensure that humanity ultimately does not repeat the Great War.', 'https://en.wikipedia.org/wiki/Crystalis'),
  ('Q5198147', 'Cycle Race: Road Man is a Family Computer video game based on the sport of road bicycle racing.', 'https://en.wikipedia.org/wiki/Cycle_Race:_Road_Man'),
  ('Q5245663', 'Deadly Towers is an action role-playing game co-developed by Lenar and Tamtex for Irem as a software title for the Nintendo Entertainment System (NES). It was released in Japan on December 15, 1986, and in North America in September of the following year.

In Japan, Deadly Towers was titled Mashō, literally meaning "Evil Bell". It is a pun of the word mashō, meaning "devilishness", and in keeping with this theme, the Japanese cartridge contained a red LED at the top which illuminated when turned on. The game''s English-language title was intended to be Hell''s Bells, but that name couldn''t be used. In North America, it was one of Irem''s three titles released in September 1987 on the NES, along with Spelunker and Sqoon.', 'https://en.wikipedia.org/wiki/Deadly_Towers'),
  ('Q5229965', 'The Magic of Scheherazade is an action-adventure/role-playing video game (RPG) developed and released by Culture Brain for the Nintendo Entertainment System (NES). The game was released in 1987 in Japan and 1990 in North America. The plot is based on Middle Eastern folktales from One Thousand and One Nights. It involves an amnesic hero traveling through time in an attempt to rescue the princess Scheherazade from the evil wizard Sabaron, who has summoned a horde of demons to bring chaos to the once peaceful land of Arabia. The Magic of Scheherazade is divided into chapters and incorporates elements of both action-adventure and RPG gameplay styles. In each chapter, the player character can freely explore an overworld in a top-down perspective. The player engages hostile enemies with various weapons and spells through both real-time solo action on the overhead map and random, turn-based battles fought alongside befriended allies.', 'https://en.wikipedia.org/wiki/The_Magic_of_Scheherazade'),
  ('Q5231241', 'The Tower of Druaga is a 1984 action role-playing maze video game developed and published by Namco for arcades. Controlling the golden-armored knight Gilgamesh, the player is tasked with scaling 60 floors of the titular tower in an effort to rescue the maiden Ki from Druaga, a demon with eight arms and four legs, who plans to use an artifact known as the Blue Crystal Rod to enslave all of mankind. The game runs on the Namco Mappy arcade hardware (which is a revised/modified version of the Super Pac-Man hardware with a horizontally scrolling video system previously used in Mappy).

Druaga was designed by Masanobu Endō, best known for creating Xevious (1983). It was conceived as a "fantasy Pac-Man" with combat and puzzle solving, taking inspiration from games such as Wizardry and Dungeons & Dragons, along with Mesopotamian, Sumerian and Babylonian mythology. It began as a prototype game called Quest with interlocking mazes, revised to run on an arcade system; the original concept was scrapped due to Endō disliking the heavy use of role-playing elements, instead becoming a more action-oriented game.', 'https://en.wikipedia.org/wiki/The_Tower_of_Druaga'),
  ('Q5248755', 'Decathlon is a decathlon-themed sports video game developed by C&E for the Nintendo Entertainment System, and published in 1992.', 'https://en.wikipedia.org/wiki/Decathlon_(1992_video_game)'),
  ('Q5243398', 'Days of Thunder is a 1990 NASCAR racing simulation video game loosely based on the 1990 movie Days of Thunder. The game utilized elements from the movie, using a movie license from Paramount Pictures for its graphical elements, plot, and music soundtrack. It was released for the PC, the NES, the Game Boy, and many other formats. It was created by Argonaut Software and distributed by Mindscape Group. In 2009 Freeverse released an updated version for iOS.', 'https://en.wikipedia.org/wiki/Days_of_Thunder_(1990_video_game)'),
  ('Q5226611', 'Princess Tomato in the Salad Kingdom is a video game by Hudson Soft originally released in 1984 for the NEC PC-8801, NEC PC-6001, FM-7 and MSX Japanese home computers.

It was ported on May 27, 1988, to the Famicom, and February 8, 1991 for the Nintendo Entertainment System in North America. It was also released on the Wii''s Virtual Console in Japan on January 19, 2010, and in North America on February 8. Further Japanese Virtual Console releases followed on September 9, 2012 for the Nintendo 3DS, and on May 14, 2014 for the Wii U.

The characters are primarily cartoon-like anthropomorphic fruits and vegetables, though the game does contain some human characters, including Princess Tomato''s sister, Lisa, and the villainous Farmies.', 'https://en.wikipedia.org/wiki/Princess_Tomato_in_the_Salad_Kingdom'),
  ('Q5242819', 'Day Dreamin'' Davey is an action-adventure game developed by Sculptured Software and published by HAL Laboratory for the North American Nintendo Entertainment System in June 1992.', 'https://en.wikipedia.org/wiki/Day_Dreamin%27_Davey'),
  ('Q5225077', 'Joy Mech Fight is a fighting game developed and published by Nintendo for the Family Computer, released in Japan on May 21, 1993. The game was released during the generation shift between the Famicom and the newer Super Famicom, and Joy Mech Fight is counted among the most important late Famicom games for utilizing the console''s audio and visual capabilities to the fullest extent. It is also Nintendo''s first attempt in the fighting game genre since Urban Champion after the success and craze of Capcom''s Street Fighter II, which inspired other companies to create their own 2D fighters. The game was released on Wii Virtual Console in March 2008 in Japan, Nintendo 3DS Virtual Console in September 2013 in Japan, Wii U Virtual Console in May 2014 in Japan, and the Nintendo Classics service in January 2019 in Japan and September 2023 in North America and PAL regions.', 'https://en.wikipedia.org/wiki/Joy_Mech_Fight'),
  ('Q5247184', 'Death Race is a vehicular combat video game developed by American Game Cartridges for the Nintendo Entertainment System (NES), and published in 1990. It is a remake of a 1976 video game of the same name.

Death Race is one of three games that American Game Cartridges published for the NES. The others are Shockwave and a conversion of the 1986 light gun arcade game Chiller. They released all their titles in 1990. In Australia the game was distributed by Home Entertainment Suppliers, and was only available to members of their "HES Game Club".

Nintendo Player described Death Race as the "spiritual predecessor" of the Grand Theft Auto game series developed by DMA Design, which applies major gameplay elements from Death Race. BMG Interactive published the first Grand Theft Auto game in 1997.', 'https://en.wikipedia.org/wiki/Death_Race_(1990_video_game)'),
  ('Q5236657', 'Milon''s Secret Castle, known in Japan as Meikyū Kumikyoku: Milon no Daibōken, is a 1986 action-adventure game released by Hudson Soft for the NES. A Game Boy version was released in 1993.

A sequel, DoReMi Fantasy, was released in 1996 for the Super Famicom.', 'https://en.wikipedia.org/wiki/Milon%27s_Secret_Castle'),
  ('Q5234956', 'Mendel Palace is a 1989 puzzle video game developed by Game Freak for the Nintendo Entertainment System. It was published in Japan by Namco and in North America by Hudson Soft. Mendel Palace is the debut game of Satoshi Tajiri and his company Game Freak. This success inspired him to create the Pokémon series. It was released for the Nintendo Switch as a part of the Nintendo Classics service.', 'https://en.wikipedia.org/wiki/Mendel_Palace'),
  ('Q5292528', 'Don Doko Don 2 is a 1992 side-scrolling 2D platform game developed by Natsume and published by Taito for the Famicom. It was only released in Japan. It is the sequel to the arcade game Don Doko Don.

The game was released as part of the limited edition Pocket Player handheld by My Arcade worldwide in January 2020, alongside its predecessor and Chack''n Pop.', 'https://en.wikipedia.org/wiki/Don_Doko_Don_2'),
  ('Q5263900', 'Desert Commander is a 1988 turn-based strategy video game developed and published by Kemco in Japan and North America for the Nintendo Entertainment System. It is themed after the North African theatre of World War II in the 1940s, where players take command of the Allied Forces led by George S. Patton and Bernard Montgomery to fight against the Axis powers led by Erwin Rommel. Its gameplay consists of moving units into positions to confront enemies in turn-based encounters determined by multiple factors, replenishing units with resources to occupy the enemy headquarters or destroy all enemy forces. The title garnered positive reception from critics; Reviewers praised several aspects such as the presentation, visuals, controls, challenge and balance of strategy and action, though others criticized certain design choices while fan reception proved to be mixed in Japan.', 'https://en.wikipedia.org/wiki/Desert_Commander'),
  ('Q5305275', 'Dragon Scroll is a 1987 video game that was released exclusively in Japan for the Family Computer.', 'https://en.wikipedia.org/wiki/Dragon_Scroll'),
  ('Q5305059', 'Dragon''s Lair is a cinematic platform video game developed by Motivetime and published by CSG Imagesoft for the Nintendo Entertainment System. Based on the LaserDisc game of the same name, it is identical plotwise to the original, but features two-dimensional gameplay. In the years following its release, the game became infamous for its difficulty, attributed to its sluggish gameplay and cryptic progress.', 'https://en.wikipedia.org/wiki/Dragon%27s_Lair_(1990_video_game)'),
  ('Q5294687', 'Donald Land is a 1988 platform video game produced by Data East in association with the McDonald''s Corporation for the Family Computer, based on the McDonaldland franchise.', 'https://en.wikipedia.org/wiki/Donald_Land'),
  ('Q5299706', 'Double Dare is a video game published by GameTek and based on the Nickelodeon game show Double Dare. The game was released by for MS-DOS and Commodore 64 in 1988. A port to the Nintendo Entertainment System by Rare was published in 1990.', 'https://en.wikipedia.org/wiki/Double_Dare_(video_game)'),
  ('Q5265128', 'Destination Earthstar is a futuristic, first-person and side-scrolling, space shooter game developed by Imagineering and published by Acclaim for the Nintendo Entertainment System.', 'https://en.wikipedia.org/wiki/Destination_Earthstar'),
  ('Q5301079', 'Doughboy is a Commodore 64 video game by Ken Coates released in North America in 1984. A port for the Famicom was released in Japan in 1985 with the spelling changed to Dough Boy.

Doughboy is a nickname given to American soldiers during the First World War because they would often rush into battle while wearing white dust on them; this originated in the Mexican–American War of 1848 when they had to march through the deserts of northern Mexico.', 'https://en.wikipedia.org/wiki/Dough_Boy_(video_game)'),
  ('Q5315134', 'Dungeon Magic: Sword of the Elements is a real-time first-person RPG (akin to Dungeon Master and Eye of the Beholder) produced by Taito in 1989, and programmed by Natsume for the Nintendo Entertainment System.', 'https://en.wikipedia.org/wiki/Dungeon_Magic:_Sword_of_the_Elements'),
  ('Q5305286', 'Dragon Spirit: The New Legend is a 1989 vertically scrolling shooter video game developed by Now Production and published by Namco for the Nintendo Entertainment System. It is a sequel and remixed port of the 1987 arcade game Dragon Spirit.', 'https://en.wikipedia.org/wiki/Dragon_Spirit:_The_New_Legend'),
  ('Q5305307', 'Dragon Wars is a fantasy role-playing video game developed by Rebecca Heineman, published by Interplay Productions in 1989, and distributed by Activision.', 'https://en.wikipedia.org/wiki/Dragon_Wars'),
  ('Q5305282', 'Romancia, also known as Dragon Slayer Jr., is an action-adventure game developed by Nihon Falcom. It is the third installment in the Dragon Slayer series, preceded by Xanadu and followed by Dragon Slayer IV.

Romancia is a simpler and brightly colored game in comparison to the other Dragon Slayer titles, hence the name "Dragon Slayer Jr."', 'https://en.wikipedia.org/wiki/Romancia'),
  ('Q5311460', 'Duck Maze is a puzzle-platform game developed and published by Bit Corporation in 1987. The title was later published in 1990 by HES and Dismac, respectively in Australia and Brazil.', 'https://en.wikipedia.org/wiki/Duck_Maze'),
  ('Q5319071', 'Dynamite Bowl is a 1987 video game that simulates the traditional game of bowling. The MSX version was released for both the MSX-1 and the MSX-2 generations of the computer.

Up to five players can play on any of the 30 bowling lanes available; simulating the concept of being in a bowling league. Players can change their lane positioning, determine how strong the throw is, and even make the ball go through various curves (or even through a straight ball into the pins). Each player character can be either male or female with options for bowling ball weights ranging from 7 pounds or 3.2 kilograms to 15 pounds or 6.8 kilograms.', 'https://en.wikipedia.org/wiki/Dynamite_Bowl'),
  ('Q5410234', 'Nuts & Milk is a puzzle-platform game developed and published by Japanese software developer Hudson Soft in 1983. The game was first released on Japanese home computers such as the MSX, NEC PC-6001mkII, Sharp X1, Fujitsu FM-7, Hitachi S1 and later to the Family Computer in Japan. Along with Lode Runner, it was the first third-party video game to be released on a Nintendo console.', 'https://en.wikipedia.org/wiki/Nuts_%26_Milk'),
  ('Q5420074', 'Exerion is a 1983 shoot ''em up video game developed by Kawa Denshi Giken and published by Jaleco for arcades. It was released in North America by Taito. The player controls a starship and must fire at enemies on the screen while avoiding projectiles. The game uses a pseudo-3D scrolling background, giving a sense of depth, and the player''s ship has a sense of inertia while it is being controlled with the joystick.

Exerion was ported to the MSX, Family Computer, and SG-1000. Two sequels were released.', 'https://en.wikipedia.org/wiki/Exerion'),
  ('Q5319237', 'Dynowarz: Destruction of Spondylus is a 1990 platform game developed by Advance Communication Company and published by Bandai for the Nintendo Entertainment System (NES). The plot is set in the artificial Spondylus Solar System, and follows Professor Proteus as he pilots his creation, the Cyborasaurus, to stop a computer virus released by his former partner, Dr. Branius.

The game is known for its dual-gameplay mechanic, which alternates between side-scrolling mecha combat and on-foot platforming stages inside planetary bases. The concept received pre-release attention from Nintendo Power for its ambition, but retrospective reception has been negative, with critics citing poor execution, unbalanced difficulty, and repetitive design.', 'https://en.wikipedia.org/wiki/Dynowarz:_Destruction_of_Spondylus'),
  ('Q5358604', 'Field Combat is a 1985 vertically scrolling shooter video game developed and published by Jaleco for arcades. In Field Combat, the player fights as a commanding officer in a futuristic battlefield. It was ported to the Famicom by Tose, which was later re-released for the Wii''s Virtual Console in 2007. A sequel, Field Combat DX, was released for Japanese mobile phones in 2004.', 'https://en.wikipedia.org/wiki/Field_Combat'),
  ('Q5398840', 'Esper Dream is an action role-playing video game developed and published by Konami for the Family Computer Disk System. It was released in Japan on February 20, 1987. During this time, RPGs had a particular look and feel, primarily utilizing sword and magic motifs. Esper Dream takes place instead in a fairy tale world featuring a young boy with ESP talents who wields a gun.

A sequel, Esper Dream 2: Aratanaru Tatakai (エスパードリーム2 新たなる戦い, lit. "Esper Dream 2: New Battle), was released for the Family Computer on June 26, 1992.', 'https://en.wikipedia.org/wiki/Esper_Dream'),
  ('Q5348316', 'Egypt is a puzzle video game released for the Family Computer in 1991 by Human. It was released only in Japan. It is an object elimination type puzzle game. A player controls a spherical jewel and jumps from tile to tile. Stepping on an arrow shifts a row or column in the direction of the arrow. Placing two or more of the same object next to each other will erase them from the board, and this must be repeated until all the objects have been eliminated from the board.', 'https://en.wikipedia.org/wiki/Egypt_(1991_video_game)'),
  ('Q5500540', 'Freedom Force is a video game developed and published by Sunsoft for the Nintendo Entertainment System in 1988. The player takes the role of a sharpshooter in a counter-terrorist organization. This is one of the few games to require the NES Zapper light gun accessory.', 'https://en.wikipedia.org/wiki/Freedom_Force_(1988_video_game)'),
  ('Q5508662', 'Fun House is a 1991 action video game based on the US version of the television show Fun House. It was released in North America for the Nintendo Entertainment System and MS-DOS with significant differences between the two.', 'https://en.wikipedia.org/wiki/Fun_House_(video_game)'),
  ('Q5492760', 'Rockin'' Kats (originally released in Japan as New York Nyankies) is a platform video game developed and published by Atlus. in 1991 for the Nintendo Entertainment System. The side-scrolling game involves the adventures of an anthropomorphic cat in his quest to defeat a criminal gang of dogs that has taken over New York City.', 'https://en.wikipedia.org/wiki/Rockin%27_Kats'),
  ('Q5451293', 'Solomon''s Key 2, known as Fire ''n Ice in North America, is a puzzle video game released by Tecmo for the Nintendo Entertainment System. It is a prequel to 1986''s Solomon''s Key, and was released in Japan in January 1992, followed by North America and Europe in March 1993. The game was re-released as part of the Nintendo Classics service for the Nintendo Switch in February 2021.', 'https://en.wikipedia.org/wiki/Solomon%27s_Key_2'),
  ('Q5511052', 'Fuzzical Fighter is a horizontally scrolling shooter by Sigma Enterprises that was released only in Japan for Family Computer in 1991. It includes role playing game elements.', 'https://en.wikipedia.org/wiki/Fuzzical_Fighter'),
  ('Q5432912', 'Famicom Jump: Hero Retsuden is a 1989 role-playing video game for the Family Computer published by Bandai. The game commemorates the 20th anniversary of Shueisha''s manga anthology Weekly Shōnen Jump.

The game is set in a world that brings together many of the long-running titles, which include stories of the past and present at the time of their release, that had appeared in the magazine. The game consists of a main character wandering and encountering the many Jump heroes as they try to save the world from an alliance of many of the most powerful and evil of the Jump villains.

The game sold 1.1 million cartridges for the Famicom in Japan. It was the first title in the Jump video game series. It had a sequel, Famicom Jump II: Saikyō no Shichinin.', 'https://en.wikipedia.org/wiki/Famicom_Jump:_Hero_Retsuden'),
  ('Q5470030', 'Formation Z is a 1984 horizontally scrolling shooter video game developed and published by Jaleco for arcades. It was released in North America by Williams Electronics as Aeroboto. It was later ported to the MSX and to the Famicom (by Hect), the latter being included as part of Jaleco Collection Vol. 1 for the PlayStation.

A remake titled FZ: Formation Z and developed by Granzella was released on May 25, 2026 by City Connection, Jaleco''s successor.', 'https://en.wikipedia.org/wiki/Formation_Z'),
  ('Q5451279', 'FireHawk is a 1991 shoot ''em up video game developed by Codemasters and published by Camerica for the Nintendo Entertainment System.

The player character is commissioned by the President of the United States to stop the trafficking of drugs into the United States. The player flies an Apache helicopter to different places around the world and must destroy the drug traffickers'' factories.

The game is very similar to Desert Strike and the rest of the Strike series, and nearly identical to Raid on Bungeling Bay, which was released for the Commodore 64 in 1984 as well as the Nintendo Entertainment System and MSX computers in 1985. In 1993, an unrelated action game Firehawk (Super Nintendo) was shown by Sony.', 'https://en.wikipedia.org/wiki/FireHawk_(video_game)'),
  ('Q5490681', 'Frankenstein: The Monster Returns is an action video game developed by Tose. The game has a player confront the recently resurrected Frankenstein''s monster who had kidnapped Emily, the daughter of the village elder. The game has the player moving through side-scrolling levels collecting fighting monsters while collecting weapon and health upgrades in order to rescue Emily from the monster.

Like other games that draw influence from the characters in Mary Shelley''s Frankenstein; or, The Modern Prometheus (1818), it predominantly is influenced by the iconography of the Universal''s Frankenstein films. It was published by Bandai America on July 1991 for the Nintendo Entertainment System. The game received unenthusiastic response in Electronic Gaming Monthly who found not standing out from various other recent action games, while VideoGame  found it exciting with a challenging final boss.', 'https://en.wikipedia.org/wiki/Frankenstein:_The_Monster_Returns'),
  ('Q5517792', 'Galactic Crusader is an unlicensed vertically scrolling shooter for the Nintendo Entertainment System developed by Joy Van and published by Sachen in 1990. It was released in the US by Bunch Games, and finally in Japan by Kinema Music as Papillon Gals (the latter version contains nudity).', 'https://en.wikipedia.org/wiki/Galactic_Crusader'),
  ('Q5533537', 'Genpei Tōma Den is a 1986 hack and slash video game developed and published by Namco for arcades. It was released only in Japan in October 1986. Over a decade later, the game was released in America and Europe in the video game compilation Namco Museum Vol. 4 under the title of The Genji and the Heike Clans for the PlayStation.', 'https://en.wikipedia.org/wiki/Genpei_T%C5%8Dma_Den'),
  ('Q5512049', 'G.I. Joe: A Real American Hero is a 1991 run and gun game published by Taxan for the Nintendo Entertainment System based on the toyline of the same name. The game was produced by Ken Lobb and developed by the same Japanese team that later formed KID. A sequel developed by the same team, titled G.I. Joe: The Atlantis Factor, was released the following year, but was published by Capcom after Taxan went out of business.

G.I. Joe on the NES garnered positive reception from reviewers since its initial release; praise was given to the colorful graphics, ability to choose between characters and form a team, soundtrack, controls, gameplay and music but the occasional flickering issues was criticized. Retrospective commentary has been positive.', 'https://en.wikipedia.org/wiki/G.I._Joe_(1991_video_game)'),
  ('Q5520531', 'Ganbare Goemon! Karakuri Dōchū is a video game produced by Konami. It is the second game in the Ganbare Goemon series (sometimes known in English as Mystical Ninja) and the first to be released on a video game console and home computer. It was initially released for the Family Computer on July 30, 1986 and later released for the MSX2 a year later. The Famicom version was re-released in Japan only for the Game Boy Advance under the Famicom Mini label and for the Wii, Nintendo 3DS and Wii U under the Virtual Console service. The game is set to be re-released in 2026 via the Ganbare Goemon! Daishūgō compilation. A direct sequel, Ganbare Goemon 2, was released for the Famicom on January 4, 1989.', 'https://en.wikipedia.org/wiki/Ganbare_Goemon!_Karakuri_D%C5%8Dch%C5%AB'),
  ('Q5520540', 'Ganbare Goemon, known as Goemon and Mystical Ninja internationally, is a video game series created and produced by Konami. Etsunobu Ebisu was the joint producer of the franchise.

These games revolve around the main character, Goemon, and his exploits. The games are notable for their humorous tone and parodies of many aspects of pop culture, as well as of other video games. The main character is loosely based on Ishikawa Goemon, the noble thief of Japanese folklore. While the early games emphasized Goemon as a noble thief, he eventually becomes more of a standard video game hero character. His trademarks are his blue bushy hair and weapon of choice, the kiseru. The games are set in a cartoonlike, mystical Feudal Japan, with many references to Japanese folklore. Although the series has its roots in action-adventure, the Ganbare Goemon series has features from genres including role-playing, puzzle video games and board games. Ganbare Goemon is popular in Japan. The series consists of video games, with its success spawning a wide series of merchandise and an anime and manga series.', 'https://en.wikipedia.org/wiki/Ganbare_Goemon'),
  ('Q5512043', 'G.I. Joe: The Atlantis Factor is an action-platform video game developed by KID and published by Capcom''s american division for the Nintendo Entertainment System. It was released only in North America in 1992. It is the sequel to KID''s previous NES G.I. Joe game, G.I. Joe, which was published by Taxan the previous year.

In G.I. Joe: The Atlantis Factor, players control a member of the G.I. Joe team, a group of highly skilled soldiers, as they battle against the evil organization Cobra. The game features multiple levels, each with its own unique environments and enemies. Players can collect power-ups and items to enhance their character''s abilities and weapons, and can also call on other members of the G.I. Joe team for assistance.', 'https://en.wikipedia.org/wiki/G.I._Joe:_The_Atlantis_Factor'),
  ('Q5971725', 'The Nintendo Entertainment System has a library of 1370 officially licensed games released during their lifespans, plus 7 official multicarts and 2 championship cartridges. Of these, 672 were released exclusively in Japan, 187 were released exclusively in North America, and 19 were released exclusively in Phase Alternating Line (PAL) countries. Worldwide, 521 games were released.

Its launch games for the Famicom were Donkey Kong, Donkey Kong Jr., and Popeye. Only first-party titles were available upon launch, but Nintendo started a licensing program the following year that allowed third-party companies such as Namco, Hudson Soft, Taito, Konami, Bandai, and Capcom to create titles and produce their own cartridges for the Famicom in exchange for royalty payments; Nintendo later revised the program to mandate itself as the manufacturer of all cartridges while carrying it with the console outside Japan. The launch games for North America were: 10-Yard Fight, Baseball, Clu Clu Land, Duck Hunt, Excitebike, Golf, Gyromite, Hogan''s Alley, Ice Climber, Kung Fu, Pinball, Soccer, Stack-Up, Super Mario Bros., Tennis, Wild Gunman, and Wrecking Crew. The final licensed game released is the PAL-exclusive The Lion King on May 25, 1995.', 'https://en.wikipedia.org/wiki/List_of_Nintendo_Entertainment_System_games'),
  ('Q5695172', 'Heavy Shreddin'' is a snowboarding video game that was released for the Nintendo Entertainment System in 1990. It was released in Europe with the title Snowboard Challenge.', 'https://en.wikipedia.org/wiki/Heavy_Shreddin%27'),
  ('Q5908008', 'Hoshi Wo Miru Hito is a 1987 role-playing video game developed by Another and published by HOT-B for the Family Computer. It is based on the 1984 video game Psychic City. The game is a science fiction RPG where players use psychic powers to fight enemies.

Reviewers noted the often confusing and highly difficult gameplay, leading to the game being considered one of the worst video games ever made. Japanese gamers have dubbed it "Densetsu no Kusoge".', 'https://en.wikipedia.org/wiki/Hoshi_Wo_Miru_Hito'),
  ('Q5750476', 'Hi no Tori Hououhen: Gaou no Bouken (火の鳥 鳳凰編 我王の冒険, "Phoenix Chronicles: Gaou''s Adventure") is a 1987 video game for the Famicom developed by Konami, produced alongside a similarly named game for the MSX. Both games are based on the manga series Phoenix created by renowned Japanese manga artist Osamu Tezuka.', 'https://en.wikipedia.org/wiki/Hi_no_Tori_Hououhen:_Gaou_no_Bouken'),
  ('Q5960864', 'Code Name: Viper, known in Japan as Ningen Heiki Dead Fox, is an action-platform video game developed by Arc System Works and published by Capcom in 1990 for the Nintendo Entertainment System. The player takes control of a special forces operative who must combat a drug syndicate in South America.', 'https://en.wikipedia.org/wiki/Code_Name:_Viper'),
  ('Q5681947', 'Sqoon is a 1986 side-scrolling shooter game by Irem for the Nintendo Entertainment System. Although published in North America directly by Irem itself, distribution of the game in that region and technical support were handled by Broderbund.', 'https://en.wikipedia.org/wiki/Sqoon'),
  ('Q5708762', 'Hello Kitty no Ohanabatake is a children''s platform game developed by Shimada Kikaku. It was published by Character Soft, a video game publishing subsidiary of Sanrio, for the Nintendo Family Computer. It was released on December 11, 1992 exclusively in Japan.', 'https://en.wikipedia.org/wiki/Hello_Kitty_no_Ohanabatake'),
  ('Q5845047', 'Thin Chen Enterprise (full name Sheng Qian Enterprise Co., Ltd), also known as Sachen, was a Taiwanese company that published several original games for the Nintendo Entertainment System, Mega Drive, Game Boy and other early cartridge-based handheld systems such as the Watara Supervision and Mega Duck. With the exception of the latter two handhelds, all of Thin Chen''s games were produced without license from the console manufacturers. The company produced at least 70 unique games for the NES and Famicom and at least 32 for the Game Boy (compiled into eight 4-in-1 cartridges), making it the most prolific unlicensed publisher for both consoles. The company also produced its own Nintendo Entertainment System hardware clones, such as the Q-Boy. Many of its games were released in an unfinished state, and received largely negative critical response.', 'https://en.wikipedia.org/wiki/Thin_Chen_Enterprise'),
  ('Q6103736', 'J-League Fighting Soccer: The King of Ace Strikers is a Japan-exclusive soccer simulation video game for the Game Boy and Family Computer.

The Game Boy version (released almost 5 months before the start of the inaugural season of the J.League) was the first title officially licensed by the J.League.', 'https://en.wikipedia.org/wiki/J-League_Fighting_Soccer'),
  ('Q6103751', 'J-League Winning Goal is a soccer game released for the Game Boy and Family Computer that revolves around the J-League.

The game''s objective is to win the championship so that the player''s chosen team can be called the greatest in all of Japan. There is an exhibition, a season mode, a playoff mode, and a practice mode.', 'https://en.wikipedia.org/wiki/J-League_Winning_Goal'),
  ('Q6109491', 'JaJaMaru Gekimaden: Maboroshi no Kinmajou is an action role-playing game for the Family Computer. It was released in 1990 by Jaleco to a Japan-exclusive market.

The game is part of the Ninja JaJaMaru-kun series, which had its debut on the Famicom and has had games on several different platforms.', 'https://en.wikipedia.org/wiki/JaJaMaru_Gekimaden:_Maboroshi_no_Kinmajou'),
  ('Q6109493', 'JaJaMaru: Ninpō Chō is a role-playing video game released in Japan on March 28, 1989 by Jaleco for the Family Computer. It is part of Jaleco''s Ninja JaJaMaru-kun series and was originally scheduled for a North American release under the name Taro''s Quest, although it was never released. Ninja Taro, another game in the series, was localized for America instead.', 'https://en.wikipedia.org/wiki/JaJaMaru:_Ninp%C5%8D_Ch%C5%8D'),
  ('Q6106327', 'J.League Super Top Players is a soccer game for the Family Computer, utilizing the Datach Joint ROM System, which was the barcode reader accessory sold separately.', 'https://en.wikipedia.org/wiki/J._League_Super_Top_Players'),
  ('Q6073279', 'Ironsword: Wizards & Warriors II (also known as Wizards and Warriors II: Ironsword) is an action platform video game developed by Zippo Games and published by Acclaim Entertainment for the Nintendo Entertainment System. It was released in North America in December 1989 and in Europe on 27 March 1991. It is the sequel to Rare''s 1987 title Wizards & Warriors. In Ironsword, the player controls the knight warrior Kuros as he ventures in the land of Sindarin. He must defeat the evil wizard Malkil, who has assumed the elemental forms of Earth, Wind, Fire, and Water. Kuros must collect the parts of and assemble the legendary "IronSword" in order to defeat Malkil, who resides at the top of IceFire Mountain.', 'https://en.wikipedia.org/wiki/Ironsword:_Wizards_%26_Warriors_II'),
  ('Q6023274', 'Indiana Jones and the Last Crusade is a 1991 action video game for the NES, developed by Software Creations and published by Taito. The game is based on the 1989 film of the same name.', 'https://en.wikipedia.org/wiki/Indiana_Jones_and_the_Last_Crusade_(1991_video_game)'),
  ('Q5978173', 'The Nintendo Entertainment System has a library of 1370 officially licensed games released during their lifespans, plus 7 official multicarts and 2 championship cartridges. Of these, 672 were released exclusively in Japan, 187 were released exclusively in North America, and 19 were released exclusively in Phase Alternating Line (PAL) countries. Worldwide, 521 games were released.

Its launch games for the Famicom were Donkey Kong, Donkey Kong Jr., and Popeye. Only first-party titles were available upon launch, but Nintendo started a licensing program the following year that allowed third-party companies such as Namco, Hudson Soft, Taito, Konami, Bandai, and Capcom to create titles and produce their own cartridges for the Famicom in exchange for royalty payments; Nintendo later revised the program to mandate itself as the manufacturer of all cartridges while carrying it with the console outside Japan. The launch games for North America were: 10-Yard Fight, Baseball, Clu Clu Land, Duck Hunt, Excitebike, Golf, Gyromite, Hogan''s Alley, Ice Climber, Kung Fu, Pinball, Soccer, Stack-Up, Super Mario Bros., Tennis, Wild Gunman, and Wrecking Crew. The final licensed game released is the PAL-exclusive The Lion King on May 25, 1995.', 'https://en.wikipedia.org/wiki/List_of_Nintendo_Entertainment_System_games'),
  ('Q5587732', 'Gotcha! The Sport! is a 1987 light gun shooter video game developed by Atlus and published by LJN for the Nintendo Entertainment System (NES). It is a licensed adaptation of the 1985 film Gotcha!, adapting the paintball tournament from the film''s opening sequence. The player controls a competitor in a capture-the-flag tournament, using both the Zapper light gun and the D-pad controller to aim and navigate scrolling levels simultaneously.

The game was marketed to support LJN''s Entertech line of paintball and water guns. Critics gave the game mixed to positive reviews, praising its unique control scheme while criticizing its repetitive gameplay loop.', 'https://en.wikipedia.org/wiki/Gotcha!_The_Sport!'),
  ('Q5664513', 'Hatris is a 1990 puzzle video game developed by Alexey Pajitnov and Vladimir Pokhilko of ParaGraph for Bullet-Proof Software. An arcade version was manufactured by Video System.', 'https://en.wikipedia.org/wiki/Hatris'),
  ('Q5584569', 'Gorubī no Paipurain Daisakusen is a falling-block puzzle video game developed by Compile for the MSX2, Famicom, and FM Towns. It was published by Tokuma Shoten in 1991.

In the game, the player assembles water pipe segments for a pipeline from Moscow to Tokyo in order to strengthen Japan–Soviet Union relations. The game was conceived by Masato Wakabayashi.

With permission of the Soviet embassy, the game and its promotional materials feature the name and likeness of Mikhail Gorbachev, who was President of the Soviet Union at the time of the game''s development and release. The cover art of the game featuring Gorbachev was created by Takamasa Shimaura.', 'https://en.wikipedia.org/wiki/Gorby_no_Pipeline_Daisakusen'),
  ('Q5658539', 'Harlem Globetrotters is a sports video game published by GameTek for MS-DOS compatible operating systems in 1990 and the Nintendo Entertainment System in 1991. The player controls the Harlem Globetrotters basketball team. A Sega Genesis conversion was planned but never released.', 'https://en.wikipedia.org/wiki/Harlem_Globetrotters_(video_game)'),
  ('Q5606063', 'Greg Norman''s Golf Power is a golf-simulation video game developed by Gremlin Interactive for the Nintendo Entertainment System (NES), and published by Virgin Games in 1992. It was the final golf title published for the NES. A European release was planned but never occurred.', 'https://en.wikipedia.org/wiki/Greg_Norman%27s_Golf_Power'),
  ('Q5643982', 'Ys II, titled on-screen as Ancient Ys Vanished: The Final Chapter, is a 1988 action role-playing game developed by Nihon Falcom. It is a sequel to Ys I: Ancient Ys Vanished and takes place immediately following it. The game was first released for the PC-8801 and PC-9801 and has seen several ports and remakes since.

Picking up almost immediately after the events of the first game, the story opens with Adol being transported to the titular civilization, which is now a floating island in the heavens. There, Adol learns the truth behind the first game''s events, being part of a larger conspiracy orchestrated by a greater evil, as well as the kingdom of Ys itself.', 'https://en.wikipedia.org/wiki/Ys_II'),
  ('Q5554520', 'Getsu Fūma Den is a 1987 action role-playing game developed and published by Konami for the Famicom exclusively in Japan. It has been referenced in many subsequent Konami titles throughout the years. The game is structurally similar to Castlevania II: Simon''s Quest, The Goonies II and Teenage Mutant Ninja Turtles (NES).

A hack-and-slash "roguevania" sequel, titled Getsu Fūma Den: Undying Moon, was released on the Nintendo Switch on February 9, 2022 and left Early Access on Steam on February 17. Another sequel titled Shin Getsu Fūma Den was planned for the PlayStation 2, but was cancelled.', 'https://en.wikipedia.org/wiki/Getsu_F%C5%ABma_Den'),
  ('Q5625472', 'Gyrodine is a top-down, vertically scrolling shooter developed by Crux and released in arcades by Taito in 1984. Conversions for the Famicom and MSX followed. The player flies a helicopter that can shoot air and ground targets.', 'https://en.wikipedia.org/wiki/Gyrodine'),
  ('Q6188067', 'Jesus is a graphic adventure game developed and published by Enix. It was first released in 1987 on the PC-8801, FM-7, X1, and the MSX2 and was later ported to the Famicom in 1989 as Jesus: Kyōfu no Bio Monster ("Jesus: Bio Monster of Terror"). A sequel, Jesus II, was released on the PC-8801, PC-9801, and X68000 in 1991.

The game''s name refers to a space station called J.E.S.U.S., named after the central Christian figure Jesus. The ship is shaped like a double-edged sword à la Book of Revelation. Its inhabitants go on to fight a mysterious demonic alien from Halley''s Comet.', 'https://en.wikipedia.org/wiki/Jesus_(video_game)'),
  ('Q6147940', 'MagMax is a 1985 horizontally scrolling shooter video game developed and published by Nichibutsu for arcades. It was ported to the Nintendo Entertainment System, released in Japan on March 19, 1986, and by FCI in North America in October 1988. The game was also ported to the Commodore 64, ZX Spectrum, and Amstrad CPC by Ocean Software and released on their Imagine label in 1987.

The three-headed mechanical dragon found as a boss character in the game, known as Babylon, strongly resembles Mecha-King Ghidorah from the Godzilla franchise. Hamster Corporation acquired the rights to the game alongside Nichibutsu''s intellectual property, and released the game as part of their Arcade Archives series for the PlayStation 4 in 2015 and the Nintendo Switch in 2020, as well as the NES version for their Console Archives series for the Nintendo Switch 2 and PlayStation 5 in May 2026.', 'https://en.wikipedia.org/wiki/MagMax'),
  ('Q6131418', 'Wily & Right no RockBoard: That''s Paradise is a business simulator video game developed and published by Capcom for the Family Computer exclusively in Japan in 1993. It is a spin-off video game to the original Mega Man series. It is similar to the board game Monopoly, in which players and the computer AI take turns going around a set of connected circles, buying up property, and charging other participants rent when they land on those spaces.

Critical reception for the game from Western gaming websites has been generally negative. An English translation and a Game Boy version were both in development but never released.', 'https://en.wikipedia.org/wiki/Wily_%26_Right_no_RockBoard:_That%27s_Paradise'),
  ('Q6109496', 'JaJaMaru no Daibouken is a Family Computer video game that was released exclusively for a Japanese market in 1986.

The player controls a red ninja, JaJaMaru, as he progress through a series of Japanesque levels defeating evil spirits that have spread across the land. The player can even ride his faithful frog if he can recover it from hiding.', 'https://en.wikipedia.org/wiki/JaJaMaru_no_Daibouken'),
  ('Q6114335', 'Jack Nicklaus'' Greatest 18 Holes of Major Championship Golf is a golfsimulation video game developed by Sculptured Software, and published by Accolade beginning in 1988. It was released for the Amiga, Amstrad CPC, Apple IIGS, Atari ST, Commodore 64, MS-DOS, Classic Mac OS, MSX, Nintendo Entertainment System, PC-88, X68000, and Game Boy.

During 1990 and 1991, the game was released in HuCard cartridge and CD-ROM formats for the U.S TurboGrafx-16 and its foreign counterpart, PC Engine. The TurboGrafx-16 versions of the game were titled Jack Nicklaus'' Turbo Golf, while the PC Engine version was titled Jack Nicklaus World Golf Tour for the CD-ROM format. The Game Boy version was released as Jack Nicklaus Golf in 1992.', 'https://en.wikipedia.org/wiki/Jack_Nicklaus%27_Greatest_18_Holes_of_Major_Championship_Golf'),
  ('Q6199858', 'Jimmy Connors Tennis is a tennis simulation video game developed by NMS Software and published by Ubi Soft for the Nintendo Entertainment System and the Game Boy. A version for the Atari Lynx console developed by Hand Made Software was released by Atari Corporation the same year. A Sega Genesis version was planned but never released.

The game features the name and likeness of American world-number-one tennis champion Jimmy Connors. Ubisoft published Jimmy Connors Tennis two years after Connors'' late-career comeback in the Men''s Singles division at the 1991 US Open, where he reached the semifinals.', 'https://en.wikipedia.org/wiki/Jimmy_Connors_Tennis'),
  ('Q6296588', 'Slalom, originally released as VS. Slalom, is a skiing sports video game developed by Rare and published by Nintendo for the Nintendo Entertainment System. It was first released in arcades in North America for the Nintendo VS. System in 1986, as with most Nintendo-published games of the era; it was then released for the console in North America in August 1987 and in Europe later that year. The player races in a series of downhill slalom skiing runs while navigating past flags and obstacles before time expires. It was developed by Tim and Chris Stamper and its music was composed by David Wise.

Slalom is the first NES game developed outside Japan (in this case, the United Kingdom), the Stamper brothers'' first game released under the Rare brand and the first non-Japanese game to be published by Nintendo. Reviews from the 1980s found Slalom unrealistic, but largely appreciated its graphics and animations, and the original arcade version received praise for its innovative ski controls. In contrast, AllGame''s retrospective review called the game poorly made and rushed. The rights to Slalom was acquired by Microsoft through their acquisition of Rare, releasing the game in their 2015 Rare Replay compilation for the Xbox One.', 'https://en.wikipedia.org/wiki/Slalom_(video_game)'),
  ('Q6411905', 'King Neptune''s Adventure is an unlicensed sidescroller action game created for the Nintendo Entertainment System that was released in 1990 by Color Dreams. Players play as King Neptune, as they venture through ships, oceans and Atlantis.', 'https://en.wikipedia.org/wiki/King_Neptune%27s_Adventure'),
  ('Q6411818', 'King Kong 2: Ikari no Megaton Punch is a 1986 Family Computer action adventure game by Konami. It was released only in Japan and based on the film of the same year, King Kong Lives (King Kong 2 being the film''s title in Japan).', 'https://en.wikipedia.org/wiki/King_Kong_2:_Ikari_no_Megaton_Punch'),
  ('Q6404521', 'Kid Niki: Radical Ninja, known in Japan as Kaiketsu Yanchamaru, is a 1986 platform video game developed and published by Irem for arcades. Initially released only in Japan, it was later released internationally by Data East in 1987 for the Nintendo Entertainment System. The arcade game runs on Irem-62 Hardware, the same as Kung Fu Master.

The differences between Kid Niki: Radical Ninja and Kaiketsu Yancha Maru are minimal. Aside from text translation, the most glaring difference is the main character''s hair style. Kid Niki''s hair is more "punk rock" with wild spikes and a ponytail in the back. Yancha Maru''s hair has more subdued spikes and a topknot (or chonmage). In the arcade version of the game, the main character''s keikogi is yellow while it is red in the home ports.', 'https://en.wikipedia.org/wiki/Kid_Niki:_Radical_Ninja'),
  ('Q6404503', 'Kid Klown in Night Mayor World is a platform video game for the NES published by Kemco on April 1, 1993 and was the first game in the Kid Klown series. It was a reskin of Mickey Mouse III: Yume Fuusen, a licensed platform video game starring Mickey Mouse that was only released in Japan. Released as part of the Crazy Castle series, Mickey Mouse III was released on September 30, 1992 by Kemco in Japan for the Family Computer.

Other games in the Kid Klown series include Kid Klown in Crazy Chase for the Super NES (later released for the Game Boy Advance as Crazy Chase), the Japan-exclusive Kid Klown in Crazy Chase 2: Love Love Hani Soudatsusen for PlayStation, Soreike! Kid: Go! Go! Kid for the Game Boy (later re-released for the Game Boy Color as Bugs Bunny: Crazy Castle 3) and The Bombing Islands for the PlayStation (also ported to the Nintendo 64 as Charlie Blast''s Territory).', 'https://en.wikipedia.org/wiki/Kid_Klown_in_Night_Mayor_World'),
  ('Q6412262', 'King of Kings is a 1988 turn-based strategy video game with wargaming elements developed by Atlus and published by Namco for the Family Computer only in Japan. Kazuma Kaneko helped to design the characters for this video game, which became the inspiration for the characters in the video game Megami Tensei.

It is one of the few games for the Family Computer to use the Namco 163 wavetable sound chip, and is also one of the games that enables all eight sound channels provided by the chip, the other being Erika to Satoru no Yume Bōken.', 'https://en.wikipedia.org/wiki/King_of_Kings_(1988_video_game)'),
  ('Q6311259', 'Jumpin'' Kid: Jack to Mame no Ki Monogatari was released on December 19, 1990 in Japan for the Family Computer. A North American release was planned but ultimately scrapped. The game was popular in Poland, Russia via Famiclones.', 'https://en.wikipedia.org/wiki/Jumpin%27_Kid:_Jack_to_Mame_no_Ki_Monogatari'),
  ('Q6368551', 'Karaoke Studio is a karaoke music video game designed for Nintendo''s Family Computer, or Famicom. The game is packaged with a hardware expansion subsystem designed to be inserted into the Famicom cartridge slot, and with a microphone peripheral capable of detecting a human voice.', 'https://en.wikipedia.org/wiki/Karaoke_Studio'),
  ('Q6410984', 'King''s Knight is a scrolling shooter video game developed and published by Square for the Nintendo Entertainment System and MSX. The game was released in Japan on September 18, 1986 and in North America in 1989. It was later re-released for the Wii''s Virtual Console in Japan on November 27, 2007 and in North America on March 24, 2008. This would be followed by a release on the Virtual Console in Japan on February 4, 2015, for 3DS and July 6, 2016, for Wii U.

The game became Square''s first North American release under their Redmond subsidiary Squaresoft, and their first release as an independent company. The 1986 release''s title screen credits Workss for programming. King''s Knight saw a second release in 1987 on the NEC PC-8801mkII SR and the Sharp X1. These versions of the game were retitled King''s Knight Special and released exclusively in Japan. It was the first game designed by Hironobu Sakaguchi for the Famicom. Nobuo Uematsu provided the musical score for King''s Knight. It was Uematsu''s third work of video game music composition.', 'https://en.wikipedia.org/wiki/King%27s_Knight'),
  ('Q6472675', 'Lagrange Point is a role-playing video game developed and published by Konami for the Family Computer. The game was released exclusively in Japan on April 26, 1991. The title of the game references Lagrangian points, the five positions in space where a body of negligible mass could be placed which would then maintain its position relative to two existing massive bodies.

Lagrange Point has the distinction of being one of only two games ever released with Konami''s Virtual ROM Controller VII (VRC7) sound generator integrated circuit, which allowed for a drastic improvement in the quality of the music and sound effects used in the game. The game was never localized for Western audiences, however, an unofficial English translation was released in 2014 by Aeon Genesis.', 'https://en.wikipedia.org/wiki/Lagrange_Point_(video_game)'),
  ('Q6505589', 'Layla is a side-scrolling action video game produced by dB-SOFT that was released in 1986 exclusively for the Family Computer.', 'https://en.wikipedia.org/wiki/Layla_(video_game)'),
  ('Q6455660', 'L''Empereur is a 1990 turn-based strategy video game developed and published by Koei for MSX, PC-88, PC-98, and Sharp X1. Nintendo Entertainment System, X68000, and MS-DOS versions were published in 1991.

The user controls Napoleon Bonaparte during the Napoleonic Wars of the late 18th and early 19th Centuries. The goal is to conquer Europe. The game begins with Napoleon as an army officer, but with victories in combat, the user may get promoted to Commander-in-Chief, First Consul, and finally Emperor of the French, with more powers and actions available at each level. As Emperor, the user also controls Napoleon''s brothers, Louis, Jérôme, Lucien, and Joseph, as well as Napoleon''s stepson, Eugene Beauharnais. The game has both military and civilian aspects. The user can lead armies, act as mayor of cities, and depending on the level achieved, engage in diplomacy with other nations. This historically accurate game reproduces many historical figures and the militaries of Europe with great detail.', 'https://en.wikipedia.org/wiki/L%27Empereur'),
  ('Q6503495', 'Law of the West is a 1985 graphic adventure set in the American Old West developed by Accolade for the Commodore 64, Apple II, and Family Computer. It was one of the company''s launch titles and the only game from Accolade designed by co-founder Alan Miller. Graphics are by Mimi Doggett and music by Ed Bogas. It was published by American Action in Scandinavia, by U.S. Gold in other parts of Europe, and by Pony Inc. in Japan.', 'https://en.wikipedia.org/wiki/Law_of_the_West'),
  ('Q6444450', 'Chinese Hero, also known in Japan as Super Chinese, is a 1984 beat ''em up video game developed by Nihon Game and published by Taiyo System and Taito for arcades. Chinese Hero is the first game in the Super Chinese series. It was ported to the Nintendo Entertainment System as Kung-Fu Heroes in Japan by Nihon Game in 1986 and was published in North America in 1989 using the Culture Brain name. The game was included in a 2004 Game Boy Advance collection titled Super Chinese I+II Advance. It was released for the Nintendo Classics service in August 2019.', 'https://en.wikipedia.org/wiki/Chinese_Hero_(video_game)'),
  ('Q6494118', 'Last Armageddon is a 1988 post-apocalyptic role-playing video game for the NEC PC-8801, MSX, X68000, PC-98, PC Engine CD-ROM², and Famicom. The game was exclusively in the Japanese language until an English translation patch was created for the Nintendo Famicom.

The game had a sequel, After Armageddon Gaiden, released for the Sega CD in 1994. Working Designs planned to release the game in North America as A Side Story of Armageddon in 1995, but the localization was cancelled due to the demise of the Sega CD system.', 'https://en.wikipedia.org/wiki/Last_Armageddon'),
  ('Q6493002', 'Laser Invasion, released as Gun Sight in Japan, is a multi-genre first-person action game released by Konami for the Nintendo Entertainment System in 1991. The player takes control of a military operative who pilots an attack helicopter in order to infiltrate various enemy bases and fulfill his mission. The game supports the standard NES controller, as well as the NES Zapper light gun and the LaserScope, a voice-activated headset controller Konami released for the NES that was compatible with all light gun games released for the system. The American version of the game featured a rebate for the LaserScope in the instruction booklet.', 'https://en.wikipedia.org/wiki/Laser_Invasion'),
  ('Q6886363', 'Moai-kun is a puzzle video game developed and published by Konami for the Family Computer in Japan in March 1990, and a spin-off of the Gradius video game series. The game derives its themes from Easter Island; the player controls a sentient moai statue (which is an enemy in the Gradius series) that must rescue other moai and escape each stage via a door before the timer expires. Although platforming elements are present, the primary challenge is to find a way to manipulate the objects in each stage to reach the distressed moai and rescue them while still leaving an avenue of escape to the exit door.', 'https://en.wikipedia.org/wiki/Moai-kun'),
  ('Q6738119', 'Major League Baseball is a 1988 baseball video game developed by Atlus and published by LJN for the Nintendo Entertainment System. It is notable for being one of the first video games licensed by Major League Baseball, although it was not endorsed by the Major League Baseball Players Association. Without the backing of the Players Association, the game could not name the actual players, although it was able to use their numbers, thus accurately portraying the contemporary teams and their rosters. In doing so, it became the first baseball game for the Nintendo Entertainment System to carry official Major League Baseball licensing and lineups.', 'https://en.wikipedia.org/wiki/Major_League_Baseball_(video_game)'),
  ('Q6826906', 'MiG-29: Soviet Fighter is a shoot ''em up game developed by Codemasters in 1989 and released for several contemporary home computers. An unlicensed version was also released for the Nintendo Entertainment System by Camerica.', 'https://en.wikipedia.org/wiki/MiG-29:_Soviet_Fighter'),
  ('Q6712166', 'M.C. Kids (McDonaldland) is a 1992 platform video game developed and published by Virgin Games. It was initially released for the Nintendo Entertainment System in February 1992 in North America, and by Ocean Software in May 1993 in Europe. As a licensed product for the McDonald''s fast food restaurant chain, the game stars two children named Mack and Mick who venture into the fantasy world of McDonaldland in order to return Ronald McDonald''s magical bag which has been stolen by the Hamburglar. The game was created by four people in eight months: Darren Bartlett (art and level design) Gregg Iz-Tavares and Dan Chang (programming) and Charles Deenen (audio).', 'https://en.wikipedia.org/wiki/M.C._Kids'),
  ('Q6784999', 'Master Chu and the Drunkard Hu, is a platform video game released in Asia for the NES by Joy Van in 1989, and was published in the same year by Color Dreams for the North American release. This game was not officially licensed by Nintendo and was manufactured using either non-standard light blue or black cartridges, typical of all games published by Color Dreams.', 'https://en.wikipedia.org/wiki/Master_Chu_and_the_Drunkard_Hu'),
  ('Q6517979', 'Legends of the Diamond is a baseball simulation video game developed by Tose for the Nintendo Entertainment System, and published by Bandai in North America in 1992.

The game features playable simulations of 30 famous Major League Baseball players, including Babe Ruth and Lou Gehrig. Six of the playable characters are pitchers: Bob Gibson, Cy Young, Dizzy Dean, Lefty Gomez, Whitey Ford, and Steve Carlton.', 'https://en.wikipedia.org/wiki/Legends_of_the_Diamond'),
  ('Q6731042', 'Magician is a side-scrolling action role-playing game released for the Nintendo Entertainment System. It was designed by Eurocom Entertainment Software and published by Taxan.', 'https://en.wikipedia.org/wiki/Magician_(video_game)'),
  ('Q6730725', 'Magic Johnson''s Fast Break (alternatively titled Magic Johnson''s Basketball) is a side-scrolling basketball sports game developed by Arcadia Systems and published in 1988. The game features the name and likeness of Los Angeles Lakers point guard Earvin "Magic" Johnson Jr., and was endorsed by PepsiCo.

In 1990 Tradewest published Software Creations'' adaptation of the game for the Nintendo Entertainment System (NES). It was one of several celebrity-endorsed sports games published by Tradewest, and was promoted with a television advertisement campaign. An adaptation to the Apple IIGS was cancelled.', 'https://en.wikipedia.org/wiki/Magic_Johnson%27s_Fast_Break'),
  ('Q6684311', 'Lost Word of Jenny, styled on-screen as Lost Word of JeNnY, is a map-based action video game for the Family Computer which was released in 1987. The game is a licensed tie-in to the Takara doll, Jenny.', 'https://en.wikipedia.org/wiki/Lost_Word_of_Jenny'),
  ('Q6726002', 'Mad Max is a post-apocalyptic action game developed by Canadian studio Gray Matter and published by Mindscape for the Nintendo Entertainment System in 1990. The game is based on the 1981 Australian film Mad Max 2.', 'https://en.wikipedia.org/wiki/Mad_Max_(1990_video_game)'),
  ('Q6730681', 'Magic Darts is a 1991 darts NES game developed by SETA Corporation and published by Romstar in the US and SETA in Japan.', 'https://en.wikipedia.org/wiki/Magic_Darts'),
  ('Q6838523', 'Mickey''s Adventures in Numberland (referred as Mickey''s Adventure in Numberland on its cover) is an educational Nintendo Entertainment System game starring Disney''s Mickey Mouse.', 'https://en.wikipedia.org/wiki/Mickey%27s_Adventures_in_Numberland'),
  ('Q6838562', 'Mickey''s Safari in Letterland is a 1993 educational Nintendo Entertainment System video game starring Disney''s Mickey Mouse. This video game is intended for preschoolers and toddlers. Basic literacy skills are taught in this side-scrolling video game.', 'https://en.wikipedia.org/wiki/Mickey%27s_Safari_in_Letterland'),
  ('Q6864172', 'Minelvaton Saga: Ragon no Fukkatsu is a role playing game published by Taito for the Family Computer. It is the first game in the Minelvaton series, being followed by Silva Saga and ending with Silva Saga II: The Legend of Light and Darkness.

A tribute CD Minelvaton Saga Tribute was published in 2009.', 'https://en.wikipedia.org/wiki/Minelvaton_Saga:_Ragon_no_Fukkatsu'),
  ('Q6878558', 'Mission Cobra (known as Sidewinder in Australia and Asia) is a vertically scrolling shooter for the Nintendo Entertainment System. It was developed by Joy Van and published in Australia by HES Interactive and in Brazil by Milmar. It was later published in the U.S. by Bunch Games.', 'https://en.wikipedia.org/wiki/Mission_Cobra'),
  ('Q6552947', 'Metal Gear is a 1987 action-adventure stealth game developed and published by Konami for the MSX2. Originally released in Japan and parts of Europe in July 1987, it is the first game in the Metal Gear series and the first video game developed by Hideo Kojima. Players control Solid Snake, an operative of the U.S. special forces unit FOXHOUND, who is sent on a solo infiltration mission into the fortified state of Outer Heaven to destroy Metal Gear, a bipedal mecha capable of launching nuclear missiles to anywhere in the world, as well as rescue a number of fellow agents who have been taken hostage by the enemy.', 'https://en.wikipedia.org/wiki/Metal_Gear_(video_game)'),
  ('Q6890275', 'Shin Moero!! Pro Yakyū is a traditional baseball simulation video game released for the Family Computer in 1989 exclusively in Japan.', 'https://en.wikipedia.org/wiki/Shin_Moero!!_Pro_Yaky%C5%AB'),
  ('Q6754192', 'Mappy-Land is a platform game developed by Tose and published by Namco for the Nintendo Entertainment System. It is a sequel to Namco''s 1983 arcade video game Mappy. Originally released in 1986, it was released by Taxan in North America in 1989.', 'https://en.wikipedia.org/wiki/Mappy-Land'),
  ('Q6810352', 'Meitantei Holmes: M-Kara no Chousenjou is a first-person adventure video game for the Family Computer that is based on the stories by Arthur Conan Doyle. It is the sequel to Sherlock Holmes: Hakushaku Reijō Yūkai Jiken and Meitantei Holmes: Kiri no London Satsujin Jiken, the latter having been released on May 13, 1988. In Kiri no London Satsujin Jiken, the player takes control of Holmes and Watson in the streets of London. The player can collect clues and also shillings in order to pay for things such as a coach fare, which allows them to travel London faster. All of these video games were released exclusively in Japan.', 'https://en.wikipedia.org/wiki/Meitantei_Holmes:_M-Kara_no_Chousenjou'),
  ('Q6872441', 'Miracle Ropitt: 2100-Nen no Daibōken, also called Miracle Ropit''s Adventure in 2100 on its title screen, is a Family Computer video game that was released in 1987 exclusively for the Japanese market. The Adventures of Star Saver, also known as Rubble Saver, is a related quasi-sequel for Game Boy.', 'https://en.wikipedia.org/wiki/Miracle_Ropitt:_2100-Nen_no_Daib%C5%8Dken'),
  ('Q6872454', 'Miracle Warriors: Seal of the Dark Lord, known as Haja no Fūin in Japan, is a role-playing video game initially released by Kogado Software Products for the NEC PC-8801 in 1986. It was then ported to various other systems, including a Master System port developed by Sega, which was released internationally. In the game, Demon Queen Terarin has unleashed dark creatures upon the world, and it is up to a young hero, joined by three companions, to restore peace by defeating her and sealing her away once again.', 'https://en.wikipedia.org/wiki/Miracle_Warriors:_Seal_of_the_Dark_Lord'),
  ('Q6651181', 'Little Ninja Brothers, known in Japan as Super Chinese 2, is a 1989 video game developed and published by Culture Brain for the Nintendo Entertainment System in 1989 in Japan and 1991 for the rest of the world. It is the second game in the Super Chinese series.

Little Ninja Brothers is the first game in the Super Chinese series to feature role-playing video game elements, an addition to the series that would continue into the other games. The plot follows two young brothers, Jack and Ryu, attempting to find out the mysterious reason for the invasion of Chinaland.

It was the second game in the series, preceded by Kung-Fu Heroes, and followed up by a sequel Super Ninja Boy, released on the Super NES. There were also two Ninja Boy spin-off games released for the Game Boy in both regions. A manga adaptation of the game was serialized in early issues of video game magazine GamePro. The game was included in a 2004 Game Boy Advance collection titled Super Chinese I+II Advance.', 'https://en.wikipedia.org/wiki/Little_Ninja_Brothers'),
  ('Q6657899', 'TM Network: Live in Power Bowl is a Japanese-only adventure game released for the Family Computer featuring the J-Pop group TM Network. The song used as the background music is "Come On Everybody" from their album Carol -A Day In a Girl''s Life 1991- (using the 8-bit sound chip of the Family Computer). The game uses the Atlus Famicom/NES sound engine by Tsukasa Masuko.', 'https://en.wikipedia.org/wiki/TM_Network:_Live_in_Power_Bowl'),
  ('Q6822676', 'Metal Mech: Man & Machine is a 1990 action video game developed by Sculptured Software and published by Jaleco for the Nintendo Entertainment System.

In May 2023, the game was included via the Piko Interactive Collection 3 compilation for the Evercade by Blaze Entertainment.', 'https://en.wikipedia.org/wiki/Metal_Mech'),
  ('Q7034038', 'Nightshade, entitled Nightshade Part 1: The Claws of Sutekh onscreen, is a 1992 action-adventure game developed by Beam Software and published by Ultra Games for the Nintendo Entertainment System. The game was meant to be the first part in a series, but no sequels were ever made; however, it served as the basis for Beam Software''s video game adaptation of Shadowrun.

It was released on the Nintendo Switch for the Nintendo Classics service in December 2020.', 'https://en.wikipedia.org/wiki/Nightshade_(1992_video_game)'),
  ('Q6902795', 'Monster Party is a platform game for the NES, released in North America in 1989 by Bandai. It was and remains a relatively obscure game for the console, having a small following among some players. The game both pays homage to and parodies horror pop culture, alternately featuring enemies and locations based on classic horror icons, and parodic reinterpretations.

In the 2000s, prototype screenshots of a Japanese Famicom version known as Parody World: Monster Party began circulating showing different bosses and parodies. No version of the game was ever released in Japan. In May 2011, a prototype of the canceled Japanese release was listed on Yahoo! Japan auctions, closing at a high price of ¥483000 (approximately US$6,000). In July 2014, the unreleased Japanese Famicom version was leaked online.', 'https://en.wikipedia.org/wiki/Monster_Party'),
  ('Q7038899', 'Ninja Crusaders is a side-scrolling action game released by Sammy Corporation for the Nintendo Entertainment System in 1990. The player takes control of one of two ninjas who are tasked at thwarting an alien invasion. The game has been compared to Tecmo''s Ninja Gaiden series.', 'https://en.wikipedia.org/wiki/Ninja_Crusaders'),
  ('Q6902826', 'Monster Truck Rally is an off-road racing video game developed by Realtime Associates for the Nintendo Entertainment System (NES), and published by INTV Corp. in 1991.', 'https://en.wikipedia.org/wiki/Monster_Truck_Rally_(video_game)'),
  ('Q6907539', 'Moon Ranger is an action video game that was developed by Odyssey Software and published by Bunch Games. The player must fly through outer space, destroying meteors and aliens along the way.', 'https://en.wikipedia.org/wiki/Moon_Ranger'),
  ('Q6958317', 'Nagagutsu o Haita Neko: Sekai Isshū 80 Nichi Dai Bōken is a 1986 video game based on the third film of The Wonderful World of Puss ''n Boots that was released exclusively in Japan for the Family Computer. Four years later, the game (with several modifications) was released in North America for the Nintendo Entertainment System under the title Puss ''n Boots: Pero''s Great Adventure.

The main character is the Puss in Boots character from the tale; a cat named Pero (Toei Animation''s mascot) is also known as ''Perrault'' in the game, as that was the name of the original author of the Puss in Boots story, Charles Perrault. He is known for helping an impoverished master attain wealth through the use of trickery.', 'https://en.wikipedia.org/wiki/Nagagutsu_o_Haita_Neko:_Sekai_Issh%C5%AB_80_Nichi_Dai_B%C5%8Dken'),
  ('Q6918121', 'Motor City Patrol is a top-down driving game released in 1992 for the Nintendo Entertainment System. It was developed by British studio Source Research & Development and published by Matchbox International Ltd.

Motor City Patrol was shown at the Summer Consumer Electronics Show in 1990 and 1991. The game was released in January 1992, and was Matchbox''s first video game.

Motor City Patrol was one in a line of video games that tied into the Matchbox brand of die-cast model vehicles, like police cars, ambulances, fire trucks, and earth-moving construction machines.', 'https://en.wikipedia.org/wiki/Motor_City_Patrol'),
  ('Q6937117', 'Muppet Adventure: Chaos at the Carnival is a video game released for the Apple II, Commodore 64, and MS-DOS in 1989 by Hi Tech Expressions. A port to the Nintendo Entertainment System was published in 1990. The game features Muppets created by Jim Henson in a series of carnival-inspired mini games searching for enough keys to rescue Miss Piggy from Dr. Grump. These mini games include: Bumper Cars, Funhouse, Tunnel of Love, Duck Hunt and Space Ride. The game was initially released for the Apple IIc with a bug which caused it to be unwinnable. Upon achieving the win condition versus Dr. Grump, the game would enter an endless cycle of taking the player back to a previous level, instead of having Dr. Grump be defeated.', 'https://en.wikipedia.org/wiki/Muppet_Adventure:_Chaos_at_the_Carnival'),
  ('Q6940166', 'Musashi no Ken is a Japanese sports manga series written and illustrated by Motoka Murakami that focuses on kendo. It was serialized by Shogakukan in Weekly Shōnen Sunday between April 1981 and October 1985. Musashi no Ken received the 1984 Shogakukan Manga Award for shōnen manga.

The manga was adapted as a 72-episode anime television series by Eiken.

The manga was also adapted into a Famicom platform game called Musashi no Ken – Tadaima Shugyō Chū. The game was developed and published by Taito. It was released in Japan on August 8, 1986.', 'https://en.wikipedia.org/wiki/Musashi_no_Ken'),
  ('Q6965048', 'Napoleon Senki is a real-time tactics strategy video game developed by Lenar and published by Irem in March 1988 for the Family Computer. In August that same year, Broderbund announced that it would be released for the North American NES console as The Battlefields of Napoleon, which was eventually cancelled.

This video game allows the player to re-enact the Napoleonic Wars using a bird''s-eye view. Starting with earliest battles against the Holy Roman Empire to grab territory for the fledgling French Republic during the French Revolutionary Wars in the year 1796, Napoleon would guide the French Revolutionary Wars until they ended in 1802. All the nations that were a participant in the Napoleonic Wars were included like the Russian Empire, Great Britain, and the Spanish Empire. Napoleon''s first in-game battle would located in present-day Italy, making the battle equally important in Italian history as it was in French history. There are also battles in Egypt against the Ottoman Empire along with various other conquests in Europe.', 'https://en.wikipedia.org/wiki/Napoleon_Senki'),
  ('Q7444091', 'Wisdom Tree, Inc. is an American developer of Christian video games. It was an offshoot of Color Dreams, one of the first companies to work around Nintendo''s 10NES lockout chip technology for the Nintendo Entertainment System. Color Dreams formed the Wisdom Tree subsidiary in 1990 in an effort to circumvent Nintendo''s restrictions against publishers of unlicensed video games for the NES by selling their games at Christian book stores which was not subject to pressure by Nintendo.', 'https://en.wikipedia.org/wiki/Wisdom_Tree'),
  ('Q7501866', 'Tose Co., Ltd. (also called Tose Software) is a Japanese video game developer based in Kyoto. It is mostly known for developing Nintendo''s Game & Watch Gallery series, various Dragon Ball games, as well as contract work or assistance to other developers. Tose has developed or co-developed thousands of games since the company''s inception in 1979, but is virtually never credited in the games themselves. It is considered the largest non-publishing game developer in the world.

Tose maintains a policy of having no creative input in the games it works on, going so far as to refuse to put the studio''s name in the credits and employees using pseudonyms in its early days. As such, Tose has gained a reputation for being a "ghost developer." Representatives of the company have described it as a "ninja developer," because it works in the shadows, as well as the "unsung hero" of the video game industry. When talking to the press, representatives of the company ask not to be identified by name. Exceptions to this include Game & Watch Gallery 4 and The Legendary Starfy series, as Tose shares the copyright with Nintendo.', 'https://en.wikipedia.org/wiki/Tose'),
  ('Q7261912', 'Nagagutsu o Haita Neko: Sekai Isshū 80 Nichi Dai Bōken is a 1986 video game based on the third film of The Wonderful World of Puss ''n Boots that was released exclusively in Japan for the Family Computer. Four years later, the game (with several modifications) was released in North America for the Nintendo Entertainment System under the title Puss ''n Boots: Pero''s Great Adventure.

The main character is the Puss in Boots character from the tale; a cat named Pero (Toei Animation''s mascot) is also known as ''Perrault'' in the game, as that was the name of the original author of the Puss in Boots story, Charles Perrault. He is known for helping an impoverished master attain wealth through the use of trickery.', 'https://en.wikipedia.org/wiki/Nagagutsu_o_Haita_Neko:_Sekai_Issh%C5%AB_80_Nichi_Dai_B%C5%8Dken'),
  ('Q7279015', 'Racer Mini Yonku: Japan Cup is a Family Computer Mini 4WD-based video game developed and published by Konami, which was released exclusively in Japan in 1989.', 'https://en.wikipedia.org/wiki/Racer_Mini_Yonku:_Japan_Cup'),
  ('Q7499941', 'Shockwave is an unlicensed 1990 puzzle game for the Nintendo Entertainment System developed and published by American Game Cartridges.', 'https://en.wikipedia.org/wiki/Shockwave_(video_game)'),
  ('Q7236417', 'The Nintendo Entertainment System has a library of 1370 officially licensed games released during their lifespans, plus 7 official multicarts and 2 championship cartridges. Of these, 672 were released exclusively in Japan, 187 were released exclusively in North America, and 19 were released exclusively in Phase Alternating Line (PAL) countries. Worldwide, 521 games were released.

Its launch games for the Famicom were Donkey Kong, Donkey Kong Jr., and Popeye. Only first-party titles were available upon launch, but Nintendo started a licensing program the following year that allowed third-party companies such as Namco, Hudson Soft, Taito, Konami, Bandai, and Capcom to create titles and produce their own cartridges for the Famicom in exchange for royalty payments; Nintendo later revised the program to mandate itself as the manufacturer of all cartridges while carrying it with the console outside Japan. The launch games for North America were: 10-Yard Fight, Baseball, Clu Clu Land, Duck Hunt, Excitebike, Golf, Gyromite, Hogan''s Alley, Ice Climber, Kung Fu, Pinball, Soccer, Stack-Up, Super Mario Bros., Tennis, Wild Gunman, and Wrecking Crew. The final licensed game released is the PAL-exclusive The Lion King on May 25, 1995.', 'https://en.wikipedia.org/wiki/List_of_Nintendo_Entertainment_System_games'),
  ('Q7354253', 'Rock''n'' Ball, released in Japan as Family Pinball, is a 1989 pinball video game developed by KID and published by Namco for the Nintendo Entertainment System. The video game was released in both Japan and North America. In the North American version, fictional human characters are used instead of the licensed Namco characters, four male characters and two female characters are at the player''s disposal.

Compared to the North American version, the bumpers in the Japanese version are separately further and the players have more room to guide their ball around the playing surface. The Japanese version has a higher overall difficulty compared to the North American version despite the latter having bigger arches.', 'https://en.wikipedia.org/wiki/Rock_%27n_Ball'),
  ('Q7352488', 'Robin Hood: Prince of Thieves is a video game released in 1991 for the Nintendo Entertainment System and Game Boy developed by Sculptured Software, Inc. and Bits Studios, respectively, and published by Virgin Games. Versions for Master System and Game Gear were also announced but cancelled. It was based on the film of the same name.

The game was featured as the cover game for the July 1991 issue of Nintendo Power magazine, but this issue was notorious for the fact that the game was not released until 4 months after the issue was released.', 'https://en.wikipedia.org/wiki/Robin_Hood:_Prince_of_Thieves_(video_game)'),
  ('Q7424955', 'Sasa is an arcade video game released for the MSX1 in 1984, and later for the Family Computer as Astro Robo SASA in 1985.

This video game involved obtaining capsules with an ''E'' on them, sometimes suspended by balloons. The main character could only use bullets to propel himself, and when the bullet count reaches 0, the game ends. A player can also lose bullets by colliding with an enemy, the other player, or the other player''s bullets.', 'https://en.wikipedia.org/wiki/Sasa_(video_game)'),
  ('Q7229294', 'Popeye no Eigo Asobi (English: Popeye''s English Fun) is a 1983 edutainment platform video game developed and published by Nintendo for the Family Computer. The game was based on the comic strip of same name created by E. C. Segar and licensed from King Features Entertainment. It is a spin-off of the Popeye arcade game made by Nintendo. It was released exclusively in Japan. It was followed by the similar Donkey Kong Jr. Math, which was released about one month later. This game was never released in North America because of the majority of English speakers in the United States and Canada and a corresponding version that would teach players Japanese was not created due to the technical limitations of the Nintendo Entertainment System along with the lack of popularity in the West to learn Japanese aside from cultural or business purposes in the 1980s.', 'https://en.wikipedia.org/wiki/Popeye_no_Eigo_Asobi'),
  ('Q7418924', 'Sanrio Cup: Pon Pon Volley is a volleyball video game featuring many of the popular Sanrio characters including Hello Kitty, Keroppi and Minna no Tabo. Matches can be played in with either two, three or four players. Players can choose between three different tracks of background music, or to simply play without the music.

The game is basically a volleyball/tennis game but without the nets, closely resembling four-square. There is an option to increase the difficulty level that modifies the level of intelligence with which computer-controlled play. There are opportunities to commit do-overs. After the end of the game, the player is awarded with a large ostrich trophy.', 'https://en.wikipedia.org/wiki/Sanrio_Cup:_Pon_Pon_Volley'),
  ('Q7446621', 'Seicross, released as Sector Zone in Japan, is a 1984 isometric shooter video game developed by Alice and published by Nichibutsu for arcades. It was released in Japan in April 1984 and North America in June 1984. A port to the Nintendo Entertainment System was released by Nichibutsu in Japan and FCI in North America in 1986. Hamster Corporation released the game as part of their Arcade Archives series for the Nintendo Switch and PlayStation 4 in 2021, as well as their Console Archives series for the Nintendo Switch 2 and PlayStation 5 in April 2026 and their Arcade Archives 2 series in November 2026.', 'https://en.wikipedia.org/wiki/Seicross'),
  ('Q7419041', 'Keisan Game Sansū Series (Calculation Game: Arithmetic series) is a video game series focusing on elementary arithmetic calculation of basic math, featuring addition, subtraction, multiplication, division, decimals, and fractions. The series is only available in Japanese.', 'https://en.wikipedia.org/wiki/Keisan_Game'),
  ('Q7280253', 'Radia Senki: Reimeihen is an action role-playing video game developed by Tecmo and released in Japan for the Nintendo Family Computer on November 15, 1991. Though an English release was at one point planned, it was never released outside Japan, with only a prototype ever made. There is a fan translation patch available for this game which allows the game to be played in English.

Radia Senki follows a cast of characters trying to stop the domination of Lemuria by Gadiss, a political leader. The protagonist suffers from amnesia at the beginning of the game, but he does regain his memories by the conclusion of the story.', 'https://en.wikipedia.org/wiki/Radia_Senki:_Reimeihen'),
  ('Q7194870', 'Pinball Quest is a 1989 pinball video game developed by Tose and published by Jaleco. Released for the Nintendo Entertainment System, Pinball Quest was unusual at the time of its release for its "unique" mash-up of pinball and role-playing game (RPG) mechanics, and it is considered the "first ever RPG pinball game".', 'https://en.wikipedia.org/wiki/Pinball_Quest'),
  ('Q7353274', 'Robocco Wars is a side-scrolling platform video game released for the Family Computer in 1991 exclusively in Japan.', 'https://en.wikipedia.org/wiki/Robocco_Wars'),
  ('Q7191093', 'Pictionary: The Game of Video Quick Draw is a video game developed by Software Creations and published by LJN for the Nintendo Entertainment System.

Based on the board game of the same name, Pictionary has been noted in retrospect for its uncharacteristically enthusiastic soundtrack composed by Tim Follin, which was considered both high quality and unusual for a game of its type.', 'https://en.wikipedia.org/wiki/Pictionary_(video_game)'),
  ('Q7361005', 'RollerGames is the name of two 1990 Konami video games, one a coin-operated arcade game by, the other a Nintendo Entertainment System game, and both based on the television show of the same name. This arcade game is faithful to the show unlike the NES version of RollerGames, which is a side-scrolling game. The game is for two players and features all the skaters and managers from the league.', 'https://en.wikipedia.org/wiki/RollerGames_(video_game)'),
  ('Q7335719', 'Ripple Island is a 1988 adventure game developed and published by Sunsoft for the Family Computer. The game was only released in Japan on January 23, 1988.

The game was translated and released in the Sunsoft Is Back! Retro Game Selection compilation for the Nintendo Switch. Hamster Corporation released the game as part of their Console Archives series for the Nintendo Switch 2 and PlayStation 5 in October 2026. A reimagining, Ripple Island: Kyle and Cal''s Restaurant, was released for the Nintendo Switch 2 and Windows in November 2025.', 'https://en.wikipedia.org/wiki/Ripple_Island_(video_game)'),
  ('Q7180559', 'Phantom Fighter is a beat ''em up video game released for the Family Computer in 1988 in Japan, and for the Nintendo Entertainment System in April 1990 in the United States. The Japanese version is based on the 1985 film, Mr. Vampire (Reigen Dōshi being the Japanese title of the film).', 'https://en.wikipedia.org/wiki/Phantom_Fighter'),
  ('Q7246763', 'Pro Sport Hockey, known in Japan as USA Ice Hockey, is an ice hockey video game that was released for the Nintendo Entertainment System and Super NES in 1993.', 'https://en.wikipedia.org/wiki/Pro_Sport_Hockey'),
  ('Q7162804', 'Penguin-Kun Wars is an action video game developed and published by UPL for arcades. It was ported to numerous platforms by ASCII under the title Penguin Wars. A port developed by ASCII the Game Boy, Penguin-Kun Wars Vs., was the only version to be released outside Japan; it was released in North America as Penguin Wars by Nexoft and in Europe as King of the Zoo by Nintendo. The main background music in most versions of the game is an electronic rendition of "Motto Sekkin Shimasho" a song originally performed by 1980s J-Pop singer Hidemi Ishikawa (in turn a translation of "The Glamorous Life" performed by Sheila E.).', 'https://en.wikipedia.org/wiki/Penguin_Wars'),
  ('Q7176289', 'Peter Pan and the Pirates is a video game for the Nintendo Entertainment System developed by American studio Equilibrium and published by THQ in 1991. It was based on the television animated series of the same name. The game is also known as Fox''s Peter Pan & The Pirates: The Revenge of Captain Hook and was the first game that THQ released.', 'https://en.wikipedia.org/wiki/Peter_Pan_and_the_Pirates_(video_game)'),
  ('Q7500563', 'Shooting Range is a video game for the Nintendo Entertainment System published by Bandai in June 1989.', 'https://en.wikipedia.org/wiki/Shooting_Range_(video_game)'),
  ('Q7426388', 'Nakajima Satoru F-1 Hero 2 is a 1991 Japan-exclusive Family Computer Formula One video game developed by Human Entertainment and published by Varie. It is the sequel to Nakajima Satoru F-1 Hero, and is based on the 1991 Formula One season. There are 16 rounds and only four cars to choose from.', 'https://en.wikipedia.org/wiki/Nakajima_Satoru_F-1_Hero_2'),
  ('Q7277462', 'RPG Jinsei Game is a Japan-only role-playing game for the Family Computer that is similar to Jinsei Game, which is the Japanese version of The Game of Life.', 'https://en.wikipedia.org/wiki/RPG_Jinsei_Game'),
  ('Q7279791', 'The following is a list of games either developed or published by Konami.', 'https://en.wikipedia.org/wiki/List_of_Konami_games'),
  ('Q7353278', 'Robodemons is an action video game with shooting elements that was released for the Nintendo Entertainment System by Color Dreams on December 20, 1989. Like all Color Dreams games, Robodemons was not officially licensed by Nintendo.', 'https://en.wikipedia.org/wiki/Robodemons'),
  ('Q7361080', 'Rollerblade Racer is a video game where the player''s goal is to win the "super rollerblade challenge". The game was released for both the Nintendo Entertainment System and MS-DOS.', 'https://en.wikipedia.org/wiki/Rollerblade_Racer'),
  ('Q7371234', 'Roundball: 2-On-2 Challenge is a two-on-two basketball video game for the Nintendo Entertainment System that is played on a half court.

Games are played in an arena with a scoreboard and crowd.

There is also an option to play a one-on-one game. The game modes contain an exhibition game and a tournament mode. Four teams play against each other in a round-robin format in order to determine the winner. Games can be set for either four, eight, twelve or sixteen minutes. Players can choose from 24 fictional basketball athletes - named after the game developers - who each have their own individual stats. The referee is capable of calling fouls in this game.', 'https://en.wikipedia.org/wiki/Roundball:_2_on_2_Challenge'),
  ('Q7134983', 'Parallel World is a puzzle video game developed by EIM and published by Varie. It was released in Japan for the Family Computer on August 10, 1990.', 'https://en.wikipedia.org/wiki/Parallel_World_(1990_video_game)'),
  ('Q7038930', 'Ninja JaJaMaru-kun is an action-platform video game developed and published by Jaleco for the Family Computer. It was released in Japan on 15 November 1985, and was ported to the MSX in 1986. The MSX version was released in Europe as Ninja II, being marketed as a sequel to Ninja-kun: Majou no Bouken, a game that used the name Ninja for its European MSX release.

The game was a commercial success, selling nearly 1 million units. An arcade video game port for the Nintendo VS. System was released in April 1986. A remake, Ganso JaJaMaru-kun, was released in 1999 for the WonderSwan. Ninja JaJaMaru-kun was released for Nintendo''s Japanese Virtual Console on 26 December 2006, and in PAL regions on 21 September 2007, as part of Ninja Week for the Hanabi Festival promotion. It was released on the North American Virtual Console on 22 October the same year. The game was released on the Nintendo Switch through the Nintendo Classics service in May 2021.', 'https://en.wikipedia.org/wiki/Ninja_JaJaMaru-kun'),
  ('Q7122035', 'Pachicom is a parlor video game released for multiple platforms that is themed around pachinko. It was released in 1985 exclusively to the Japanese market.

The game of pachinko is hugely popular in Japan, since it involves playing pinball with an element of slot machines mixed in along with gambling. There are four different gameplay modes to choose from (two of them assign a player with a pachinko machine while the other two allow players to choose their own machine).', 'https://en.wikipedia.org/wiki/Pachicom'),
  ('Q7097527', 'Operation Secret Storm is an action-oriented video game released in 1992 for the NES platform. Players control a secret agent named George B.—widely seen as a caricature of then-United States President George H. W. Bush—as he fights the Iraqi army. The game uses beat-''em-up combat mechanics on a 2D plane. The character collects ammunition and grenades while travelling through Iraq and defeating stereotypical Arabic enemies.', 'https://en.wikipedia.org/wiki/Operation_Secret_Storm'),
  ('Q7108566', 'Othello is a 1986 strategy video game developed by HAL Laboratory for the Nintendo Entertainment System and Game Boy. It was published by the toy company Kawada in Japan and Acclaim Entertainment in North America. The Game Boy version was published by Nintendo in Europe. It is based on the board game Othello, a version of Reversi sold by Tsukuda Original. The video game is seen as a solid rendition of the board game with good controls but a lack of features.', 'https://en.wikipedia.org/wiki/Othello_(1986_video_game)'),
  ('Q7113402', 'Over Horizon is a 1991 horizontally scrolling shooter co-developed by Pixel and Hot-B, published in Japan by Hot-B and in Germany by Takara for the Nintendo Entertainment System. Controlling the space fighter craft Michael, the player must destroy numerous enemies to stop the Gamma organization from using the alien creature Kassandra to take over the Alpharos star system.

Over Horizon was conceived as a "create your own shoot ''em up" game during a proposal with Pixel to re-use their engine from Dungeon Kid before being reworked into a standard shooter and Hot-B took over development of the project, with Steel Empire co-director Yoshinori Satake at the helm overseeing the process. The title received positive reception from reviewers; criticism was geared towards its short length and low difficulty, with some regarding it as a clone of Gradius and R-Type but praise was given to the atmospheric and colorful visual presentation, use of environmental stage gimmicks, ability to customize the ship, sound design and gameplay.', 'https://en.wikipedia.org/wiki/Over_Horizon'),
  ('Q7600719', 'Star Force, released in North America as Mega Force, is a 1984 vertically scrolling shooter video game developed and published by Tehkan for arcades. It was ported to the Famicom by Hudson Soft, with Tehkan''s successor Tecmo releasing a different version for the Nintendo Entertainment System outside of Japan.', 'https://en.wikipedia.org/wiki/Star_Force'),
  ('Q7548016', 'Snoopy''s Silly Sports Spectacular!, known in Japan as Donald Duck and based on the British home computer game Alternative World Games, is a child-oriented sports game that was released by Kemco for the Nintendo Entertainment System on September 22, 1988 (April 1990 in North America).', 'https://en.wikipedia.org/wiki/Snoopy%27s_Silly_Sports_Spectacular'),
  ('Q7572495', 'Space Shuttle Project is an action video game released in 1991 by Absolute Entertainment for the Nintendo Entertainment System. It was one of the few vehicle simulators not to be released for the personal computer.', 'https://en.wikipedia.org/wiki/Space_Shuttle_Project'),
  ('Q7575926', 'Spelunker II: Yūja e no Chōsen (スペランカーII 勇者への挑戦; lit. ''Spelunker II: A Challenge for the Brave'') is an action platformer video game developed by Now Production and released by Irem for the Family Computer in 1987.

Despite being titled as a sequel to Spelunker, Yūja e no Chōsen features vastly different gameplay. There was a separate arcade sequel, titled Spelunker II: 23 no Kagi, which features similar gameplay to the first Spelunker game as well. The two Spelunker II games are separate entries in the series and are not related.

There is confusion about the game title, where the word "yūja" is often replaced by "yūsha". The word 勇者 (lit. ''hero'' or ''brave one'') in the original title is almost always read as "ゆうしゃ" (yūsha) in Japanese, not "ゆうじゃ" (yūja). However the package of the game indeed reads it as "ゆうじゃ" (yūja). Many sites cite the game by the normal reading "yūsha".', 'https://en.wikipedia.org/wiki/Spelunker_II:_Y%C5%ABja_e_no_Ch%C5%8Dsen'),
  ('Q7599408', 'Stanley: The Search for Dr. Livingston (after "David Livingstone") is a side-scrolling action-adventure game developed by Sculptured Software and released in 1992 by Electro Brain for the Nintendo Entertainment System. It appeared in one of the first 50 issues of Nintendo Power magazine.', 'https://en.wikipedia.org/wiki/Stanley:_The_Search_for_Dr._Livingston'),
  ('Q7537365', 'Sky Kid is a 1985 horizontally scrolling shooter video game developed and published by Namco for arcades. It was released in Japan in December 1985 and in North America by Kitkorp in July 1986. A port to the Nintendo Entertainment System was released in Japan in August 22, 1986 and in North America in September 1987 by Sun Corporation, which acquired and absorbed Kitkorp; it was also ported to arcades for the Nintendo VS. System as VS. Super Sky Kid in 1987. A sequel named Sky Kid Deluxe was released in 1986. At least one version was also imported into the UK at this time.', 'https://en.wikipedia.org/wiki/Sky_Kid'),
  ('Q7580028', 'Spot: The Video Game is a video game developed and produced by Virgin Mastertronic in 1990/1991 for the Amiga, Atari ST, MS-DOS computers, Game Boy and Nintendo Entertainment System. It is the first video game to feature the then-current 7 Up mascot "Spot", and was later followed up by platformers Cool Spot and Spot Goes To Hollywood.', 'https://en.wikipedia.org/wiki/Spot:_The_Video_Game'),
  ('Q7534119', 'Skate or Die 2: The Search for Double Trouble is a skateboarding themed action/adventure video game for the Nintendo Entertainment System. The game is a sequel to Skate or Die!.

The skater seen on the cover art is Jef Whitehead, who would years later become known for being the sole member of the black metal project Leviathan.', 'https://en.wikipedia.org/wiki/Skate_or_Die_2:_The_Search_for_Double_Trouble');

insert into import_summary (wikidata_id, summary, source) values
  ('Q7516444', 'Silver Surfer is a 1990 scrolling shoot ''em up video game developed by Software Creations and published by Arcadia Systems. It was released in November 1990 in the United States exclusively for the Nintendo Entertainment System. The game is based on the Marvel Comics character Silver Surfer, and is primarily known for its high difficulty and highly praised music. It was re-released as part of the Marvel MaXimum Collection compilation in 2026.', 'https://en.wikipedia.org/wiki/Silver_Surfer_(video_game)'),
  ('Q7601015', 'Star Trek: The Next Generation is a large spaceship simulation video game based on the Star Trek follow-up series of the same name. It was released in 1993 to the North American and European markets for both the Nintendo Entertainment System (NES), Game Boy, and Game Gear.', 'https://en.wikipedia.org/wiki/Star_Trek:_The_Next_Generation_(1993_video_game)'),
  ('Q7659348', 'Swords and Serpents is a 1990 fantasy role-playing video game developed by Interplay Productions and published by Acclaim Entertainment for the Nintendo Entertainment System. In this game, the player controls a party of four adventurers on a dungeon-crawling quest to destroy a terrible serpent. Along the way, the party encounters an onslaught of fantasy monsters and collects gold and treasure while gaining experience points needed to raise their individual attributes, as well as purchasing equipment from shops within the dungeon. Swords and Serpents focuses mainly on gameplay and contains very little plot development.', 'https://en.wikipedia.org/wiki/Swords_and_Serpents'),
  ('Q7642253', 'Super Chinese 3 is an action RPG video game released in 1991 for the Family Computer. It is the last of the Famicom Super Chinese games and was not released outside Japan.', 'https://en.wikipedia.org/wiki/Super_Chinese_3'),
  ('Q7605306', 'Stealth ATF is a stealth fighter video game released by Activision in 1989 for the Nintendo Entertainment System. The object of the game is to take out aircraft that are trying to destroy the player''s stealth fighter. The game supports up to two players.', 'https://en.wikipedia.org/wiki/Stealth_ATF'),
  ('Q7628783', 'Camerica was a Canadian video game company founded in 1988. It released various unlicensed video games and accessories for the Nintendo Entertainment System, such as the Game Genie and Aladdin Deck Enhancer, and was the North American publisher for British developer Codemasters.', 'https://en.wikipedia.org/wiki/Camerica'),
  ('Q7673504', 'Taboo: The Sixth Sense is a tarot card reading simulation developed by Rare and published by Tradewest for the Nintendo Entertainment System (NES) in 1989.

Taboo gives users a tarot reading where the "dealer" automatically shuffles the cards. It is the only NES game to carry two warnings: that it is for players ages fourteen and older and is also for entertainment purposes only. Taboo was marketed as a party game that multiple adults could enjoy simultaneously.', 'https://en.wikipedia.org/wiki/Taboo:_The_Sixth_Sense'),
  ('Q7653353', 'Swamp Thing is a platform video game for the NES and Game Boy. Based on the animated series of the same name, of the DC Comics superhero character Swamp Thing. It was published by THQ and released in December 1992.

A Swamp Thing title was also in development by Microsmiths for the Sega Mega Drive/Genesis but was canceled. It would have been published by NuVision Entertainment.', 'https://en.wikipedia.org/wiki/Swamp_Thing_(video_game)'),
  ('Q7642814', 'Super Star Force: Jikūreki no Himitsu is a vertically-scrolling shoot ''em up adventure video game developed and published by Tecmo on November 11, 1986 for the Family Computer only in Japan.

The game was featured in episode 111 (14th Season) of GameCenter CX.

While this video game was originally assigned by Hudson Soft to be the publisher, Tecmo (then known as Tehkan) decided to both develop and publish the game as they were the official copyright owners.', 'https://en.wikipedia.org/wiki/Super_Star_Force:_Jik%C5%ABreki_no_Himitsu'),
  ('Q7687216', 'Tashiro Masashi no Princess ga Ippai is a Japanese video game for the MSX2 home computer system and Family Computer featuring former comedian Masashi Tashiro released in 1989.', 'https://en.wikipedia.org/wiki/Tashiro_Masashi_no_Princess_ga_Ippai'),
  ('Q7602422', 'Starship Hector, originally released as Hector ''87, is a scrolling shooter developed and published by Hudson Soft for the Nintendo Entertainment System. The game contains both horizontally and vertically scrolling segments. The player''s starship has two modes of fire: one to tackle flying enemies and one for ground-based ones.

Starship Hector is a follow-up to Hudson Soft''s earlier shooter Star Soldier, itself inspired by Tecmo''s Star Force, an arcade game that Hudson had ported to the Famicom in 1985. The background music of Starship Hector was reused as background music in Super Star Soldier. The theme also appears in the Wii game Kororinpa, which itself has many themes from older Hudson Soft games.', 'https://en.wikipedia.org/wiki/Starship_Hector'),
  ('Q7684223', 'Nintendo is one of the world''s biggest video game development companies, having created several successful franchises. Because of its storied history, the developer employs a methodical system of software and hardware development that is mainly centralized within its offices in Kyoto and Tokyo, in cooperation with its division Nintendo of America in Redmond, Washington. The company also owns several worldwide subsidiaries and funds partner affiliates that contribute technology and software for the Nintendo brand.', 'https://en.wikipedia.org/wiki/List_of_Nintendo_development_teams'),
  ('Q7718243', 'The Black Bass is a 1984 fishing video game developed and published by Gamu (later known as HOT・B). It was released for the PC-88 in 1984; a version for the Family Computer was released on March 18, 1987, in Japan. It is the first game in The Black Bass series and was not released outside of Japan.', 'https://en.wikipedia.org/wiki/The_Black_Bass_(1984_video_game)'),
  ('Q7706929', 'Astro Boy, known in Japan as Mighty Atom, is a Japanese manga series written and illustrated by Osamu Tezuka. It was serialized in Kobunsha''s Shōnen from 1952 to 1968, with its 112 chapters collected in 23 tankōbon volumes by Akita Shoten. Dark Horse Comics published an English translation in 2002. The story follows the eponymous Astro Boy, an android young boy with human emotions who is created by scientist Umataro Tenma in the likeness of his son Tobio after the latter''s death in an accident. Eventually, Astro is sold to a robot circus run by ringleader Hamegg, but is saved from his servitude by Professor Ochanomizu. Astro becomes a surrogate son to Ochanomizu who creates a robotic family for Astro and helps him to live a normal life like an average human boy, while accompanying him on his adventures.', 'https://en.wikipedia.org/wiki/Astro_Boy'),
  ('Q7718244', 'The Black Bass, known in Japan as The Black Bass II, is a NES fishing video game, developed by HOT・B and released in June 1989. It is the sequel to the Japan-exclusive The Black Bass on MSX and Family Computer. It is the second entry in the Black Bass series and the first to be released outside Japan. The game is sometimes referred to as The Black Bass USA, which is the name used on the North American version''s title screen. It was re-released in 2016 as a built-in game for the Retro-Bit Generations retro video game console.', 'https://en.wikipedia.org/wiki/The_Black_Bass_(1988_video_game)'),
  ('Q7737140', 'The Golf ''92 is a Family Computer video game that involves golfing with popular Japanese golf pros.', 'https://en.wikipedia.org/wiki/The_Golf_%2792'),
  ('Q7715623', 'The Bard''s Tale II: The Destiny Knight (or The Bard''s Tale 2) is a fantasy role-playing video game created by Interplay Productions in 1986. It is the first sequel to The Bard''s Tale, and the last game of the series that was designed and programmed by Michael Cranford.

The game features Dungeons & Dragons-style characters and follows in the footsteps of its predecessor, The Bard''s Tale, also created by Michael Cranford. The Bard''s Tale II takes place on a larger scale with an explorable wilderness, six cities, and multiple dungeons that give this game its dungeon crawl character. The game has new features such as casinos and banks, and introduces a new magic user called an Archmage, among other changes from the first game in the series.', 'https://en.wikipedia.org/wiki/The_Bard%27s_Tale_II:_The_Destiny_Knight'),
  ('Q7699897', 'Tenkaichi Bushi Keru Nagūru is a fighting video game developed by Game Studio and published by Namco. It was released for the Famicom on July 21, 1989, only in Japan. It is one of the earliest versus fighting games with role-playing video game elements.', 'https://en.wikipedia.org/wiki/Tenkaichi_Bushi_Keru_Nag%C5%ABru'),
  ('Q7718794', 'The Blue Marlin is a 1991 fishing video game developed and published by Hot-B for the Nintendo Entertainment System (NES). Following in the tradition of its predecessors, The Black Bass for MSX and The Black Bass for NES, the objective is to win a tournament by catching the largest fish in the time allotted. The Blue Marlin features four tournament rounds (one in Florida and the other three in Hawaii). It was re-released in 2016 as a built-in game for the Retro-Bit Generations retro video game console.', 'https://en.wikipedia.org/wiki/The_Blue_Marlin'),
  ('Q7748086', 'The Lone Ranger is a 1991 action-adventure game developed and published by Konami for the Nintendo Entertainment System (NES). Released only in North America, it is based on The Lone Ranger radio and TV franchise, the latter which was still rerunning in syndication when the game was released. The player takes the role of the Lone Ranger himself as he engages against outlaws in side-scrolling, overhead, and even first-person segments. The Lone Ranger theme music is played prominently during the game, which includes a DPCM-coded voice clip of the ranger shouting his catch-phrase "Hi Yo Silver".', 'https://en.wikipedia.org/wiki/The_Lone_Ranger_(video_game)'),
  ('Q7692738', 'Tecmo World Cup Soccer is a sports video game released in 1990 by Tecmo for the Nintendo Entertainment System. It is a port of Tehkan World Cup, released in the arcades in 1985. As its name suggests, it is a soccer game focusing on the World Cup.

Although the two games appear virtually identical, Tecmo World Cup Soccer lacks some of the speed and fluidity of its arcade progenitor. While the gameplay is ostensibly unchanged, the lack of support for analog control in the NES version renders it a digital-control-only game that requires almost completely different tactics.

Tecmo World Cup Soccer is not to be confused with Nintendo World Cup (released the same year), nor Tecmo Cup Soccer Game (known as Captain Tsubasa in Japan).', 'https://en.wikipedia.org/wiki/Tecmo_World_Cup_Soccer'),
  ('Q7805036', 'Time Lord is a side-scrolling action-platform video game developed by Rare and published by Milton Bradley for the Nintendo Entertainment System. It was released in North America in September 1990 and in Europe in 1991.

The game opens with a military conflict between the planets Earth and Drakkon in the year 2999. In an attempt to alter the course of human history, the Drakkon forces launch time-traveling alien invasions into four different eras of the past. An unnamed Time Lord travels into the past to face the invaders. The four battles take place in the years 1250, 1650, 1860, and 1943. The respective locations for these battles are Medieval England, the Western United States shortly before the American Civil War, the Caribbean, and France during World War II.', 'https://en.wikipedia.org/wiki/Time_Lord_(video_game)'),
  ('Q7751991', 'The Money Game: LSU is an American docuseries that followed LSU Tiger student athletes Jayden Daniels, Angel Reese, Flau''jae Johnson, Livvy Dunne, Alia Armstrong, and Trace Young through their 2023–24 sports season and the impact of name, image, and likeness (NIL) contracts. The series premiered on Amazon Prime Video on September 10, 2024. The Money Game was nominated for Outstanding Documentary Series (Serialized) at the 46th Sports Emmy Awards.', 'https://en.wikipedia.org/wiki/The_Money_Game:_LSU'),
  ('Q7759056', 'The Quest of Ki is a 1988 platform video game developed by Game Studio and published by Namco for the Family Computer. Only released in Japan, it is the third game in Babylonian Castle Saga series which started with the 1984 arcade game, The Tower of Druaga. An arcade port for the Nintendo VS. System titled VS. The Quest of Ki was released in 1988.', 'https://en.wikipedia.org/wiki/The_Quest_of_Ki'),
  ('Q7775129', 'The Wing of Madoola is a platform video game developed and published by Sunsoft. It was published in 1986 for the Family Computer. The game stars Lucia, a magic-wielding warrior of the Rameru clan. Darutos, a descendant of the Rameru line, found the Wing of Madoola statue and used it to build a demonic fortress and summon demons to conquer the world. Lucia must retrieve the statue and stop Darutos. Throughout the journey, the player explores and search for items and power-ups to increase Lucia''s attributes, while fighting enemies and defeating bosses.

The Wing of Madoola was designed by Kenji Sada, being his first project at Sunsoft after joining the company in 1986, and developed over the course of six months. Sada acted as the game''s main programmer, planner, and team lead. He intended to make an action game and choose a female lead for the game, a decision he felt gave character to the title. Artist Kenji "Moriken" Mori acted as character designer. The music was composed by Naoki Kodaka, with assistance by sound programmer Naohisa Morota.', 'https://en.wikipedia.org/wiki/The_Wing_of_Madoola'),
  ('Q7757819', 'The Portopia Serial Murder Case is a 1983 adventure game designed by Yuji Horii and published by Enix. It was first released on the NEC PC-6001 and has since been ported to other personal computers, the Family Computer (Famicom), mobile phone services, and most recently, Windows as Square Enix demonstrates their natural language processing technology.

In the game, the player must resolve a murder mystery by searching for clues, exploring different areas, interacting with characters, and solving item-based puzzles. The game features first-person graphics, nonlinear gameplay, an open world, conversations with non-player characters, branching dialogue choices, suspect interrogations, nonlinear storytelling, and plot twists. The Famicom version also features a command menu system, point-and-click interface, and 3D dungeon maze.', 'https://en.wikipedia.org/wiki/The_Portopia_Serial_Murder_Case'),
  ('Q7761289', 'The Rocketeer is a 1991 platform game developed by Realtime Associates and Ironwind Software, and published by Bandai for the Nintendo Entertainment System. It is based on the 1991 film of the same name. Another game based on the film was released the following year for the Super Nintendo Entertainment System, and for Personal computer systems.', 'https://en.wikipedia.org/wiki/The_Rocketeer_(NES_video_game)'),
  ('Q7751994', 'Wall Street Kid, released in Japan as The Money Game II: Kabutochou no Kiseki is a video game released by SOFEL for the NES. The game is a western spinoff of The Money Game series.

The player must prove the stockbroker''s worth by taking $500,000 in seed money and growing it to $1,000,000 in order to gain a six-hundred-billion-dollar inheritance (equal to $1479 billion today) from the extremely wealthy Benedict family. Successfully investing it in the American stock market results in rewards like going shopping on the weekend and being able to acquire expensive items such as a house. The names of the companies listed in the stock market are slight variants on actual U.S. companies in operation at the time of the game''s release. The player is also encouraged to spoil the stockbroker''s girlfriend. The game ends if the player is unable to raise the money needed for a key item, such as a boat or the house, causing the stockbroker to be disowned by the family.', 'https://en.wikipedia.org/wiki/Wall_Street_Kid'),
  ('Q7850240', 'Tsuppari Wars is an action video game for the Family Computer. The object is to acquire all of the enemies'' territory and defeat the evil gang leaders. Even though this game was only released in Japan, the gangsters fight without any weapons and the violence level is mild compared to later gang-related games.', 'https://en.wikipedia.org/wiki/Tsuppari_Wars'),
  ('Q7858149', 'Twin Eagle: Revenge Joe''s Brother is a vertically scrolling shooter arcade game which was published in 1988. It was developed by SETA Corporation and licensed to Taito. It was one of the first arcade to use extensive digital sampling, from digitized photos to a digitized soundtrack. Controlling a helicopter, the player shoots aircraft and other attackers to earn points. If certain buildings are destroyed, hostages are found and extra points are received for saving them. A NES port was published a year later by Romstar.

Twin Eagle was followed by a sequel in 1994, Twin Eagle II: The Rescue Mission, also by SETA.', 'https://en.wikipedia.org/wiki/Twin_Eagle'),
  ('Q7836711', 'Treasure Master is a platform game released by ASC Games in 1991 for the Nintendo Entertainment System as part of a contest involving MTV.

As this contest was only open to American participants, the game was released exclusively in the United States.', 'https://en.wikipedia.org/wiki/Treasure_Master'),
  ('Q7818702', 'Tombs & Treasure, known in Japan as Asteka II: Templo del Sol, is an adventure game originally developed by Falcom in 1986 for the PC-8801, PC-9801, FM-7, MSX 2 and X1 Japanese computer systems. A NES version, released in 1988, was altered to be more story-based, and features new music and role-playing elements; an English-language NES version was published by Infocom in 1991. Japanese enhanced remakes were released for the Saturn and Windows systems in 1998 and 1999, respectively.

The game takes place in the ancient Mayan city of Chichen Itza on the Yucatán Peninsula. It alternates between using a three-quarters overhead view for travelling from ruin to ruin, and switching to a first-person perspective upon entering a specific location.', 'https://en.wikipedia.org/wiki/Tombs_%26_Treasure'),
  ('Q7829879', 'T&C Surf Designs II: Thrilla''s Surfari is a sequel to Town & Country Surf Designs: Wood & Water Rage for the Nintendo Entertainment System (NES) video game system.', 'https://en.wikipedia.org/wiki/Town_%26_Country_II:_Thrilla%27s_Surfari'),
  ('Q7829883', 'Town & Country Surf Designs: Wood & Water Rage is a skateboarding and surfing game published by LJN for the Nintendo Entertainment System in February 1988. The game shares its name with the surfboard manufacturer, Town & Country Surf Designs, and features the company''s mascot characters, known as "Da Boys".', 'https://en.wikipedia.org/wiki/Town_%26_Country_Surf_Designs:_Wood_%26_Water_Rage'),
  ('Q7858062', 'TwinBee 3: Poko Poko Daimaō is a 1989 vertically scrolling shooter video game developed and published by Konami for the Family Computer. It was the third game in the TwinBee series released for the Famicom, following the home version of the original TwinBee and the Famicom-exclusive Moero TwinBee. Unlike Moero, which was released in North America as Stinger, TwinBee 3 was a Japan-only release. It was re-released on April 14, 2006 as part of the i-Revo downloadable game service.

TwinBee 3 ditches the side-scrolling stages from Stinger and only features top-scrolling ones similar to the original. Moreover, the game lacks the 3-Player mode from Moero, allowing only up to two players. The game is considerably easier than its predecessors due to an option mode that allows players to adjust the difficulty and number of ships, as well as the inclusion of the new "soul reviving system", which allows players to recover their power-ups after losing a ship.', 'https://en.wikipedia.org/wiki/TwinBee_3:_Poko_Poko_Daima%C5%8D'),
  ('Q7806576', 'Times of Lore is an action role-playing game developed and published by Origin Systems. It was released in 1988 for Amiga, Atari ST, and Commodore 64, followed by conversions to MS-DOS, ZX Spectrum, Amstrad CPC, Apple II, and the Nintendo Entertainment System.', 'https://en.wikipedia.org/wiki/Times_of_Lore'),
  ('Q7808645', 'Tiny Toon Adventures: Cartoon Workshop is an educational entertainment video game for the Nintendo Entertainment System based on Tiny Toon Adventures. It was developed by Novotrade and released by Konami on August 17, 1992.', 'https://en.wikipedia.org/wiki/Tiny_Toon_Adventures:_Cartoon_Workshop'),
  ('Q7993125', 'Where''s Waldo? is a hidden object game developed by Bethesda Softworks and published by THQ for the Nintendo Entertainment System in 1991. It was the first video game loosely based on Martin Handford''s 1987 book of the same name. Mostly similar to the books, players must help Waldo get to the Moon by finding him in each of the eight levels in the game.

The game was panned by critics, who criticized the game for its graphics, which made it more difficult to find Waldo in each of the levels.', 'https://en.wikipedia.org/wiki/Where%27s_Waldo%3F_(video_game)'),
  ('Q7975976', 'Wayne''s World is a platform game based on the film of the same name and published in 1993 by THQ. Different versions of the game were released. The NES and Game Boy games were developed by Radical Entertainment and have Wayne and Garth as playable characters. The Super NES and Genesis/Mega Drive games were developed by Gray Matter with only Wayne as a playable character.', 'https://en.wikipedia.org/wiki/Wayne%27s_World_(video_game)'),
  ('Q7884786', 'Hydlide is an action role-playing game developed and published by T&E Soft. It was originally released for the NEC PC-6001 and PC-8801 computers in 1984, in Japan only; ports for the MSX, MSX2, FM-7 and NEC PC-9801 were released the following year. A Nintendo Switch port based on the PC-8801 version was released on December 21, 2023 by D4 Enterprise.

A Famicom version was released under the name Hydlide Special in Japan in 1986. Three years later, it was localized and released in English regions for the Nintendo Entertainment System by Fujisankei Communications International, known as simply Hydlide. The game sold two million copies in Japan across all platforms.', 'https://en.wikipedia.org/wiki/Hydlide'),
  ('Q7862685', 'Firework Thrower Kantaro''s 53 Stations of the Tokaido is an action-adventure game developed and published by Sunsoft for the Famicom. The game was released in Japan on July 3, 1986 and has been re-released for several other platforms in video game compilations.

The first re-release was made on June 29, 2001 for the Microsoft Windows operating system as part of the Ultra 2000 Sunsoft Classic Games 2 compilation. The game was also coupled with Ikki, and its value version release, YuYu Sunsoft Kessaku-shu 2 (released on July 2, 2004), and Memorial Series Sunsoft Vol. 3 for the PlayStation (released on December 27, 2001) which also included The Wing of Madoola, another Sunsoft game. It was released for the Virtual Console only in Japan on October 14, 2008 for the Wii and on September 18, 2013 for the Nintendo 3DS. The game was released outside of Japan for the first time through SUNSOFT is Back! Retro Game Selection, under its translated name and including a new English localization. Hamster Corporation released the game as part of their Console Archives series for the Nintendo Switch 2 and PlayStation 5 in June 2026.', 'https://en.wikipedia.org/wiki/Firework_Thrower_Kantaro%27s_53_Stations_of_the_Tokaido'),
  ('Q7918301', 'Vegas Connection: Casino Kara Ai wo Komete is a 1989 Nintendo Family Computer video game that was released exclusively in Japan.', 'https://en.wikipedia.org/wiki/Vegas_Connection:_Casino_Kara_Ai_wo_Komete'),
  ('Q7997235', 'Who Framed Roger Rabbit is a 1989 action-adventure video game developed by Rare and published by LJN for the Nintendo Entertainment System. It is loosely based on the 1988 film of the same name, and combines elements of graphic adventure computer games with some more traditional action-adventure gameplay. A different version of the game had been released for various computer systems in 1988.', 'https://en.wikipedia.org/wiki/Who_Framed_Roger_Rabbit_(1989_video_game)'),
  ('Q7918305', 'Vegas Dream, released in Japan as Viva! Las Vegas is a gambling video game developed by HAL Laboratory for the Nintendo Entertainment System. A sequel, Vegas Stakes, was released for the Super Nintendo Entertainment System in 1993.', 'https://en.wikipedia.org/wiki/Vegas_Dream'),
  ('Q7928030', 'Videomation is a North America-exclusive art application for the Nintendo Entertainment System that was released in 1991.

Videomation saw official release outside North America, by BIC, who sold it in Asian cartridge. They give the official license to a well known, regional famiclone distributors like BiT Argentina (known from Bitgame, Super Bitgame and Video Racer), BobMark Int. Poland (known from Pegasus) and others.', 'https://en.wikipedia.org/wiki/Videomation'),
  ('Q7880118', 'Ultimate Air Combat (known as Aces: Iron Eagle III in Japan) is a semi-realistic combat flight simulator developed and published by Activision for the Nintendo Entertainment System. Having relatively good graphics for the console, Ultimate Air Combat differs from other similar games by having both a cockpit view and an isometric view throughout the missions. The game seems to be set in the near future due to some of the highly advanced weapons systems but modern-day planes. In Japan, the game is known as Aces: Iron Eagle III and is barely based on the film of the same name (as both involved aircraft).', 'https://en.wikipedia.org/wiki/Ultimate_Air_Combat'),
  ('Q7880124', 'Ultimate Basketball is an NES basketball video game. It was released in September 1990 by American Sammy. The game was later licensed by Taito and released in Japan as Taito Basketball. This video game is completely unrelated to the Amiga video game of the same title and was represented on the American television series Video Power.', 'https://en.wikipedia.org/wiki/Ultimate_Basketball'),
  ('Q7911777', 'The Adventure of Valkyrie: The Legend of the Key of Time is a 1986 action-adventure role-playing video game developed and published by Namco for the Family Computer. It was released only in Japan on August 1, 1986. It was also released for arcades through the Nintendo VS. System on the same year. A sequel, The Legend of Valkyrie, was released in arcades in 1989.', 'https://en.wikipedia.org/wiki/The_Adventure_of_Valkyrie'),
  ('Q7998722', 'Widget is an action-platform video game series created for the Nintendo Entertainment System in the 1990s by Atlus. It was based on the cartoon series Widget the World Watcher, which stars a purple alien named Widget. The original game came out in 1992, followed by the sequel Super Widget on the Super NES in 1993.', 'https://en.wikipedia.org/wiki/Widget_(video_game)'),
  ('Q8028765', 'Wizardry III: Legacy of Llylgamyn (originally known as Wizardry: Legacy of Llylgamyn - The Third Scenario) is the third scenario in the Wizardry series of role-playing video games. It was published in 1983 by Sir-Tech.', 'https://en.wikipedia.org/wiki/Wizardry_III:_Legacy_of_Llylgamyn'),
  ('Q7997606', 'Whomp ''Em, also known in Japan as Saiyūki World 2: Tenjōkai no Majin is a platform game released by Jaleco for the Nintendo Entertainment System in December 1990 in Japan and March 1991 in North America. It is named after Wampum.', 'https://en.wikipedia.org/wiki/Whomp_%27Em'),
  ('Q8033696', 'Woody Poco is a Japan-exclusive video game released for the Family Computer in addition to various other systems. It is a side-scrolling action role-playing game similar to Mystical Ninja.', 'https://en.wikipedia.org/wiki/Woody_Poco'),
  ('Q8028773', 'Wizards & Warriors III: Kuros – Visions of Power is a platforming and adventure video game for the Nintendo Entertainment System (NES). It was developed by UK-based company Zippo Games for Rare; it was published by Acclaim Entertainment and released in North America in March 1992. It is the third and final installment in the Wizards & Warriors series and is the sequel to the 1989 title Ironsword: Wizards & Warriors II; it also follows the 1990 Game Boy release Wizards & Warriors X: The Fortress of Fear.

The game picks up immediately from the events at the end of Ironsword where the knight warrior Kuros had just defeated the evil wizard Malkil from the peak of IceFire Mountain. Unaware that Malkil''s spirit is still intact, Kuros gets struck by a bolt of magic from the spirit, causing him to lose his armor, memory, and honor. Malkil then flees to the city of Piedup and seizes the throne from Good King James. Meanwhile, Kuros, after wandering for months in the wilderness without weapons, armor, or food, arrives at the city of Piedup, where he must build strength and utilize various disguises and abilities in order to take on Malkil. The game is nonlinear and requires players to explore various areas to pick up items and gain abilities to unlock different parts of the city in order to progress.', 'https://en.wikipedia.org/wiki/Wizards_%26_Warriors_III:_Kuros:_Visions_of_Power'),
  ('Q8030537', 'Wolverine is a 1991 action-platform video game developed by Software Creations and published by LJN for the NES. It is a licensed game based on the Marvel Comics superhero of the same name, as well as the X-Men.', 'https://en.wikipedia.org/wiki/Wolverine_(1991_video_game)'),
  ('Q8039296', 'Wurm: Journey to the Center of the Earth, released in Japan as Vazolder: The Underground Battle Space, is a multi-genre video game developed by Cyclone System and published by Asmik and SOFEL for the Nintendo Entertainment System in 1991.', 'https://en.wikipedia.org/wiki/Wurm:_Journey_to_the_Center_of_the_Earth'),
  ('Q9089201', 'Totally Rad, known in Japan as Magic John, is an action-adventure game developed by Aicom and published by Jaleco for the Nintendo Entertainment System. The game was released in Japan on September 28, 1990, in North America in March 1991, and in Europe the same year.', 'https://en.wikipedia.org/wiki/Totally_Rad'),
  ('Q8963433', 'Ganbare Goemon! Karakuri Dōchū is a video game produced by Konami. It is the second game in the Ganbare Goemon series (sometimes known in English as Mystical Ninja) and the first to be released on a video game console and home computer. It was initially released for the Family Computer on July 30, 1986 and later released for the MSX2 a year later. The Famicom version was re-released in Japan only for the Game Boy Advance under the Famicom Mini label and for the Wii, Nintendo 3DS and Wii U under the Virtual Console service. The game is set to be re-released in 2026 via the Ganbare Goemon! Daishūgō compilation. A direct sequel, Ganbare Goemon 2, was released for the Famicom on January 4, 1989.', 'https://en.wikipedia.org/wiki/Ganbare_Goemon!_Karakuri_D%C5%8Dch%C5%AB'),
  ('Q8763111', 'Ganbare Goemon, known as Goemon and Mystical Ninja internationally, is a video game series created and produced by Konami. Etsunobu Ebisu was the joint producer of the franchise.

These games revolve around the main character, Goemon, and his exploits. The games are notable for their humorous tone and parodies of many aspects of pop culture, as well as of other video games. The main character is loosely based on Ishikawa Goemon, the noble thief of Japanese folklore. While the early games emphasized Goemon as a noble thief, he eventually becomes more of a standard video game hero character. His trademarks are his blue bushy hair and weapon of choice, the kiseru. The games are set in a cartoonlike, mystical Feudal Japan, with many references to Japanese folklore. Although the series has its roots in action-adventure, the Ganbare Goemon series has features from genres including role-playing, puzzle video games and board games. Ganbare Goemon is popular in Japan. The series consists of video games, with its success spawning a wide series of merchandise and an anime and manga series.', 'https://en.wikipedia.org/wiki/Ganbare_Goemon'),
  ('Q8762678', 'New Ghostbusters II is an action video game for the Nintendo Entertainment System and Game Boy, both developed and published by HAL Laboratory in 1990 in Japan and in 1991 in the PAL region. The NES version was never released in North America due to licensing issues with Activision. As a result, NES players in North America only received Activision''s Ghostbusters II game. HAL also developed a Game Boy version of New Ghostbusters II, titled simply Ghostbusters II, which they also published in Japan, while Activision published it in North America and PAL regions.', 'https://en.wikipedia.org/wiki/New_Ghostbusters_II'),
  ('Q8037625', 'Wrath of the Black Manta is a side-scrolling action game published by Taito for the Nintendo Entertainment System in North America in 1990 and in the PAL region in 1991. It is a localized version of Ninja Cop Saizou, a Family Computer game developed by A.I and published by Kyugo in 1989, but with drastic changes to the game''s graphics, soundtrack and level designs.', 'https://en.wikipedia.org/wiki/Wrath_of_the_Black_Manta'),
  ('Q8075312', 'The Nintendo Entertainment System has a library of 1370 officially licensed games released during their lifespans, plus 7 official multicarts and 2 championship cartridges. Of these, 672 were released exclusively in Japan, 187 were released exclusively in North America, and 19 were released exclusively in Phase Alternating Line (PAL) countries. Worldwide, 521 games were released.

Its launch games for the Famicom were Donkey Kong, Donkey Kong Jr., and Popeye. Only first-party titles were available upon launch, but Nintendo started a licensing program the following year that allowed third-party companies such as Namco, Hudson Soft, Taito, Konami, Bandai, and Capcom to create titles and produce their own cartridges for the Famicom in exchange for royalty payments; Nintendo later revised the program to mandate itself as the manufacturer of all cartridges while carrying it with the console outside Japan. The launch games for North America were: 10-Yard Fight, Baseball, Clu Clu Land, Duck Hunt, Excitebike, Golf, Gyromite, Hogan''s Alley, Ice Climber, Kung Fu, Pinball, Soccer, Stack-Up, Super Mario Bros., Tennis, Wild Gunman, and Wrecking Crew. The final licensed game released is the PAL-exclusive The Lion King on May 25, 1995.', 'https://en.wikipedia.org/wiki/List_of_Nintendo_Entertainment_System_games'),
  ('Q9358285', 'The Ultimate Stuntman is a 1990 video game developed by Codemasters and published by Camerica for the Nintendo Entertainment System (NES), featuring action game elements. The Ultimate Stuntman is one of 14 video games published by Camerica for the NES without proper licensing. The company had to create their own cartridges that would bypass Nintendo''s lock-out chip and break the 10NES "code".

Another unusual aspect of Camerica games released for the NES is their distinctive color cartridges. The Ultimate Stuntman, like all Codemasters games, was released as a gold cartridge in the U.S. and a black cartridge in Europe.', 'https://en.wikipedia.org/wiki/The_Ultimate_Stuntman'),
  ('Q11278253', 'The Krion Conquest or more simply Magical Doropie, is a side-scrolling action-adventure video game for the Nintendo Entertainment System, developed by Vic Tokai in 1990. Later, Genki Mobile ported the game to Japanese mobile phones.', 'https://en.wikipedia.org/wiki/The_Krion_Conquest'),
  ('Q11268587', 'Sanma no Meitantei is a 1987 adventure game made by Namco for the Family Computer (Famicom). The game is a comedic murder mystery featuring real-world comedians from Japan such as Sanma Akashiya. In the game, the players teams up with Sanma to solve a murder and diamond heist that occurred at the president of Yoshimoto Kogyo''s home.

On Sanma no Meitantei release, it topped the sales charts for Famicom games in Famicom Hisshoubon . The game received positive reviews in Famicom Hisshoubo and Famicom Tsūshin. Hardcore Gaming 101 said that the game had "something of a cult reputation" in Japan, leading to it being referenced in later games such as Super Mario RPG (1996) and Atsushi no Meitantei (2022).', 'https://en.wikipedia.org/wiki/Sanma_no_Meitantei'),
  ('Q11233573', 'Uncharted Waters is a 1990 video game published by Koei. It is the first game in the Uncharted Waters series and was released in Japan under the name Daikōkai Jidai.', 'https://en.wikipedia.org/wiki/Uncharted_Waters_(video_game)'),
  ('Q10856190', 'Nobunaga''s Ambition is a 1986 strategy video game developed and published by Koei. It was released for several platforms such as IBM PC compatibles, Amiga, Nintendo Entertainment System, Super NES, and Sega Genesis. A part of Koei''s "Historical Simulation" line of titles, it is focused in the Sengoku period of the history of Japan. It is the second game in the Nobunaga''s Ambition series and the first Nobunaga''s Ambition title to be released in English. The player has the objective of unifying Japan as Oda Nobunaga or as any of the other daimyos present in the game. Several revisions were made to the gameplay since the first game, as well as a 50-province mode which expanded the game''s map to feature all of Japan.', 'https://en.wikipedia.org/wiki/Nobunaga%27s_Ambition_(video_game)'),
  ('Q11319329', 'Tetris 2, known in Japan as Tetris Flash, is a 1993 puzzle video game developed by Tose and published by Nintendo for the Nintendo Entertainment System. It was ported to the Game Boy in 1993 and the Super Nintendo Entertainment System in 1994.', 'https://en.wikipedia.org/wiki/Tetris_2_(1993_video_game)'),
  ('Q11332081', 'Family Tennis is a 1987 tennis video game developed and published by Namco for the Family Computer. It was released only in Japan in December 1987. An arcade version for the Nintendo VS. System titled VS. Family Tennis was released the same month. It spawned a franchise of the same name, which was renamed World Court for numerous sequels. It was followed by Smash Tennis for the Super Nintendo Entertainment System and Family Tennis Advance for the Game Boy Advance.

While the original game remained exclusive to Japan, Hamster Corporation re-released the VS. System arcade version globally as part of their Arcade Archives series for the Nintendo Switch and PlayStation 4 in January 2025.', 'https://en.wikipedia.org/wiki/Family_Tennis'),
  ('Q11322994', 'Dragon Slayer IV: Drasle Family, released outside Japan as Legacy of the Wizard, is a 1987 action role-playing platform video game developed and published by Nihon Falcom for the MSX2. A port for the Nintendo Entertainment System was released in Japan in July 1987 by Namco and internationally in 1989 by Broderbund. It is the fourth installment of the Dragon Slayer series, and one of only five Dragon Slayer games that were localized outside Japan. The game was an early example of an open-world, non-linear action RPG, combining action-RPG gameplay with what would later be called "Metroidvania"-style action-adventure elements.', 'https://en.wikipedia.org/wiki/Legacy_of_the_Wizard'),
  ('Q10334191', 'Mystery Quest is a platform game developed by Carry Lab. It was published in Japan by Square in 1987, and in North America by Taxan in 1989. The game follows the journey of Hao on his quest to become a wizard.', 'https://en.wikipedia.org/wiki/Mystery_Quest_(video_game)'),
  ('Q11704278', 'Tecmo NBA Basketball is a basketball video game that was released by Tecmo for the Nintendo Entertainment System.

Like Tecmo Super Bowl and Tecmo Bowl before it, the game features cinema-style cutscenes during gameplay. There is an option to play an all-star game, but unlike with Tecmo Super Bowl, there is no option to select the players on the All-Star teams. Tecmo also released a version of the game for the Super NES and Genesis, titled Tecmo Super NBA Basketball. This is the first basketball video game to feature an official license from both the NBA and the NBPA players union (however, it was not the first basketball video game to have a license from the NBA; that distinction went to Intellivision''s NBA Basketball in 1980).', 'https://en.wikipedia.org/wiki/Tecmo_NBA_Basketball'),
  ('Q11673876', 'Pirate Ship Higemaru is a 1984 maze video game developed and published by Capcom for arcades. The gameplay is similar to that of Sega''s 1982 game Pengo, but with the arctic theme replaced with that of a pirate ship.

The game was later included in the 1998 compilation Capcom Generations: The First Generation for the PlayStation (in Japan and Europe) and Sega Saturn (Japan only). Like the other games in the Capcom Generations titles, it was included in the 2005 compilation Capcom Classics Collection for the PlayStation 2 and Xbox, and in the PlayStation Portable version Capcom Classics Collection: Reloaded, which was the first time the game was released for home consoles in North America.', 'https://en.wikipedia.org/wiki/Pirate_Ship_Higemaru'),
  ('Q11611160', 'Seikima II Akuma no Gyakushū! is a video game that was released in Japan in 1986.

In 1987, the game was re-released for the MSX2 under the title Seikima II Special with more detailed sprites and backgrounds. It also featured actual Seikima-II music.', 'https://en.wikipedia.org/wiki/Seikima_II_Akuma_no_Gyakush%C5%AB!'),
  ('Q11634489', 'Kaijū Monogatari is a role-playing video game developed by Birthday and published by Namco for the Family Computer, in November 1988 in Japan. It was followed up by Daikaijū Monogatari on the Super Famicom.', 'https://en.wikipedia.org/wiki/Kaij%C5%AB_Monogatari'),
  ('Q11537004', 'Momotarō Dentetsu is a board game-themed video game published by Hudson Soft for the Family Computer on December 2, 1988. The game has players control trains as they travel through Japan. The player can buy properties, with the winner being the player with the highest value in properties owned at the end of the game.

The game was conceived as a parody of the role-playing game Momotarō Densetsu from the same development team. Reviews in Marukatsu Famicom found the game enjoyable for all audiences, but said players who sought out more strategic gameplay may find themselves disappointed. The series had a sequel in Japan and spawned a series that continued into the 2020s.', 'https://en.wikipedia.org/wiki/Momotar%C5%8D_Dentetsu_(video_game)'),
  ('Q11525055', 'The Adventures of Gilligan''s Island (also known as Gilligan''s Island: The Video Game) is a single-player Nintendo Entertainment System video game by Bandai that is based on the 1960s sitcom Gilligan''s Island.', 'https://en.wikipedia.org/wiki/The_Adventures_of_Gilligan%27s_Island'),
  ('Q11372574', 'The Nintendo Entertainment System has a library of 1370 officially licensed games released during their lifespans, plus 7 official multicarts and 2 championship cartridges. Of these, 672 were released exclusively in Japan, 187 were released exclusively in North America, and 19 were released exclusively in Phase Alternating Line (PAL) countries. Worldwide, 521 games were released.

Its launch games for the Famicom were Donkey Kong, Donkey Kong Jr., and Popeye. Only first-party titles were available upon launch, but Nintendo started a licensing program the following year that allowed third-party companies such as Namco, Hudson Soft, Taito, Konami, Bandai, and Capcom to create titles and produce their own cartridges for the Famicom in exchange for royalty payments; Nintendo later revised the program to mandate itself as the manufacturer of all cartridges while carrying it with the console outside Japan. The launch games for North America were: 10-Yard Fight, Baseball, Clu Clu Land, Duck Hunt, Excitebike, Golf, Gyromite, Hogan''s Alley, Ice Climber, Kung Fu, Pinball, Soccer, Stack-Up, Super Mario Bros., Tennis, Wild Gunman, and Wrecking Crew. The final licensed game released is the PAL-exclusive The Lion King on May 25, 1995.', 'https://en.wikipedia.org/wiki/List_of_Nintendo_Entertainment_System_games'),
  ('Q11407621', 'Spy vs. Spy II: The Island Caper is a 1985 video game developed by First Star Software. It is the sequel to Spy vs. Spy. It can be played as both single-player and multiplayer', 'https://en.wikipedia.org/wiki/Spy_vs._Spy_II:_The_Island_Caper'),
  ('Q11317186', 'Rally Bike is a racing arcade video game originally developed by Toaplan but published and distributed by Taito at its release in May 1988. In Rally Bike, players compete against computer-controlled opponents in races across locations in the United States. Initially released in arcades, the game was ported to the Nintendo Entertainment System and X68000 by different developers.

Rally Bike was met with mixed reception from video game magazines and dedicated outlets that reviewed the game when it launched in arcades and its ports. As of 2019, the rights to the title is owned by Tatsujin, a company founded in 2017 by former Toaplan member Masahiro Yuge and now-affiliate of Japanese arcade manufacturer exA-Arcadia alongside many other Toaplan IPs.', 'https://en.wikipedia.org/wiki/Rally_Bike'),
  ('Q11301528', 'Ninja Kid, known in Japan as GeGeGe no Kitaro - Yōkai Daimakyō, is an action video game developed by Tose and published by Bandai for the Nintendo Entertainment System.

The Japanese version was based on the 1985 television series GeGeGe no Kitarō itself based on the manga series of the same name, but the game was changed to the generic "Ninja Kid" and all references to Kitaro were removed for the American version due to the source material being not well-known outside Japan.

This game was followed by a sequel titled Gegege no Kitarou 2: Youkai Gundan no Chousen, which was released the following year only in Japan also by Bandai; however, that title was a role-playing video game and its plot is unrelated to the original.', 'https://en.wikipedia.org/wiki/Ninja_Kid'),
  ('Q11286214', 'Puyo Puyo is a 1991 puzzle video game developed and published by Compile for the MSX2. It is the first installment of the Puyo Puyo series, and uses characters from Compile''s 1990 role-playing game Madō Monogatari. The game was produced by Compile founder Masamitsu "Moo" Niitani, who was inspired by certain elements from the Tetris and Dr. Mario series of games.

The game was released for the Famicom Disk System by Tokuma Shoten on the same day of the MSX2 release under the name Famimaga Disk Vol. 5: Puyo Puyo and as part of the Famimaga Disk series. A year after the MSX2 and FDS versions, Sega released an arcade version that heavily expanded upon the original versions by including a one-player story mode and a two-player competitive mode.', 'https://en.wikipedia.org/wiki/Puyo_Puyo_(video_game)'),
  ('Q11302009', 'Cocoron is a 1991 action-platform video game developed by K2 and published by Sur Dé Wave for the Family Computer. It was the final game to be developed by Akira Kitamura, creator of the Mega Man series at Capcom, before his retirement until 2024. A version for the PC Engine was announced, but was not released.', 'https://en.wikipedia.org/wiki/Cocoron'),
  ('Q17014280', 'Flying Dragon: The Secret Scroll is a 1987 side-scrolling platform video game, which includes some role-playing elements, developed by Culture Brain for the NES. It is the second title in the Hiryū no Ken series.', 'https://en.wikipedia.org/wiki/Flying_Dragon:_The_Secret_Scroll'),
  ('Q16683360', 'Willow is a 1989 2D action role-playing game developed and published by Capcom for the Nintendo Entertainment System. It is loosely inspired by the 1988 film of the same name and is the second title Capcom released based on Willow that year, the first being an unrelated side scrolling arcade game. The version of Willow released for the Nintendo Entertainment System and the Famicom is an adventure game in the vein of The Legend of Zelda.', 'https://en.wikipedia.org/wiki/Willow_(NES_video_game)'),
  ('Q16913800', 'Super Hydlide is an action role-playing game released by T&E Soft for the Genesis/Mega Drive. It was originally released in 1987 in Japan only under the title Hydlide 3: The Space Memories for the MSX, MSX2, and PC-8801mkII SR. It''s the third game in the Hydlide series. Ports were also released for the X1, Famicom, X68000, Windows, and Nintendo Switch. The game was developed by Hydlide series veterans T&E Soft and released worldwide on the Sega Genesis / Mega Drive on October 6, 1989, in Japan, early 1990 in the United States, and 1991 in Europe. This remake evidences substantial graphical upgrades to the original Hydlide 3, though the gameplay remains largely identical. Before its release, it was called Hollo Fighter in some Sega advertising material and was one of the first third party published titles to be released in the U.S., the other being Air Diver.', 'https://en.wikipedia.org/wiki/Super_Hydlide'),
  ('Q17190863', 'Genghis Khan, original full title Aoki Ōkami to Shiroki Mejika: Genghis Khan, is a turn-based strategy game developed by Koei, originally released for the PC-98 in 1987, MSX and X68000 in 1988, MS-DOS and NES in 1990, and Amiga in 1990. It is the second game in the series, after a 1985 Aoki Ōkami to Shiroki Mejika for PC-88, PC-98 and MSX.', 'https://en.wikipedia.org/wiki/Genghis_Khan_(video_game)'),
  ('Q17177267', 'TaleSpin is a scrolling shooter video game based on the Disney television series TaleSpin. The game was developed by Capcom for the NES in 1991. A stripped down port for the Game Boy released in 1992.

The NES version of the game was included in The Disney Afternoon Collection compilation for PC, PlayStation 4, and Xbox One in April 2017, as well as its Nintendo Switch and Switch 2 release in 2026.', 'https://en.wikipedia.org/wiki/TaleSpin_(Capcom_video_game)'),
  ('Q16266997', 'Power Punch II is a 1992 boxing video game developed by Beam Software and published by American Softworks for the Nintendo Entertainment System. The game puts the player in the role of Mark Tyler, an undefeated heavyweight champion on Earth who is invited by an outer space boxing federation to fight the toughest challengers in the universe. Gameplay consists of the player battling each computer-controlled opponent in up to three one-minute rounds and a scoring system based on the player''s performance. Training sessions between opponents allow the player to improve stats prior to an upcoming bout.', 'https://en.wikipedia.org/wiki/Power_Punch_II'),
  ('Q16267492', 'Goal!, released in Japan as Super Cup Soccer and Europe as Super Goal!, is a 1992 association football video game developed by Tose and published by Jaleco for the Super Nintendo Entertainment System. Goal! Two is Tose''s first sequel to 1988''s Goal! (released in Japan as Moero !! Pro Soccer). It was later ported to the Nintendo Entertainment System as Goal!!, with the game being titled Goal! Two in North America and Goal! 2 in Europe.

For the French release of the NES version, Jaleco secured an endorsement from French international footballer Eric Cantona, who had just transferred to Manchester United F.C. The French packaging bears the name and likeness of Cantona, with the prefixed title Eric Cantona Football Challenge: Goal! 2. It is otherwise unrelated to Eric Cantona Football Challenge, which is a port of Striker from Rage Software in 1992.', 'https://en.wikipedia.org/wiki/Goal!_(1992_video_game)'),
  ('Q16267446', 'Skull & Crossbones is a pirate-themed beat ''em up developed by Atari Games and released as an arcade video game in 1989. Developer Tengen ported the game to the Amiga, Amstrad CPC, Atari ST, Commodore 64, MS-DOS, Nintendo Entertainment System, and ZX Spectrum.

The game is playable in single and co-op modes, where the objective of both players is to rescue their kidnapped princess from the antagonist, a wizard. Player one controls One-Eye, and player two controls Red Dog. Gameplay consists of players fighting through waves of enemies and level bosses, such as Medusa and Ship Captains, collecting weapons and booty to become increasingly powerful. Collectable items are centred around the pirate theme, such as the cutlass or flintlock pistol.', 'https://en.wikipedia.org/wiki/Skull_%26_Crossbones_(video_game)'),
  ('Q16266827', 'Star Voyager, released in Japan as Cosmo Genesis, is an action video game developed and published by ASCII Corporation for the Nintendo Entertainment System in 1986. The North American version was published by Acclaim Entertainment in 1987. The gameplay is a first-person shooter from inside the cockpit of a spaceship. The player navigates "sub spaces" of a larger "world map." Gameplay takes place between different subspaces.', 'https://en.wikipedia.org/wiki/Star_Voyager'),
  ('Q16266830', 'Faria: A World of Mystery and Danger!, known in Japan as Faria Fuuin no Tsurugi, is an action role-playing game (RPG) for the Nintendo Entertainment System. It was developed by Game Arts, published in Japan by Hi-Score in 1989 and by Nexoft in North America in 1991.', 'https://en.wikipedia.org/wiki/Faria:_A_World_of_Mystery_and_Danger!'),
  ('Q16267515', 'Wayne Gretzky Hockey is an ice hockey-themed sports video game developed by Bethesda Softworks, and first published in 1988.', 'https://en.wikipedia.org/wiki/Wayne_Gretzky_Hockey'),
  ('Q16267185', 'Moero!! Jūdō Warriors is a Family Computer video game that was released in 1990.', 'https://en.wikipedia.org/wiki/Moero!!_J%C5%ABd%C5%8D_Warriors'),
  ('Q16267477', 'Hottāman no Chitei Tanken is a Japan-exclusive video game that was released for the Family Computer in 1986.', 'https://en.wikipedia.org/wiki/Hott%C4%81man_no_Chitei_Tanken'),
  ('Q16267432', 'Sword Master is a 1990 side-scrolling action game developed by Athena and published by Activision for the Nintendo Entertainment System. The game is set in a medieval fantasy setting and focuses primarily on strategic fighting using shield and sword. The game is also one of the NES games to include parallax scrolling.', 'https://en.wikipedia.org/wiki/Sword_Master_(video_game)'),
  ('Q16611924', 'Ninja-kun: Adventure of Devil Castle is a 1984 platform video game developed by UPL and published by Taito for arcades. It was later ported to the Famicom and MSX in 1984. Initially released only in Japan, a MSX version developed by Jaleco was released in Europe under the name Ninja.', 'https://en.wikipedia.org/wiki/Ninja-Kid'),
  ('Q18945737', 'Jaleco Ltd. was a corporate brand name that was used by two previously connected video game developers and publishers based in Japan. The original Jaleco company was founded in 1974 as Japan Leisure Company, founded by Yoshiaki Kanazawa, before being renamed to simply Jaleco in the early 1980s. This company was later acquired in 2000 by Hong Kong company PCCW, who rebranded it as its Japanese game division, PCCW Japan, before reverting it to Jaleco in 2002. In 2006, Jaleco became independent from PCCW and renamed to Jaleco Holding, having its video game operations spun off into a new company, also called Jaleco. This new spin-off company was sold to mobile developer Game Yarou in 2009, with Jaleco Holding renaming itself to Encom Holdings shortly after.', 'https://en.wikipedia.org/wiki/Jaleco'),
  ('Q17508441', 'Beauty and the Beast is a platform game developed by Probe Software and published by Hudson Soft for the Nintendo Entertainment System. It was released in Europe in 1994.', 'https://en.wikipedia.org/wiki/Beauty_and_the_Beast_(1994_video_game)'),
  ('Q21273066', 'Magicland Dizzy is a 1990 platform adventure game developed by Big Red Software and published by Codemasters for the Amstrad CPC, ZX Spectrum, Commodore 64, Atari ST and Amiga platforms and initially only available as part of The Dizzy Collection. By 1992 the game was sold by itself and an MS-DOS version was available. It is the sixth game in the Dizzy series, and the fourth adventure-based Dizzy title. The story, set in a fantasy world called Magicland, follows on from the events of Fantasy World Dizzy, the previous adventure title. In Magicland Dizzy the player controls Dizzy, an egg-shaped character, who is trying to save six of his friends who have been placed under spells by the Evil Wizard Zaks.', 'https://en.wikipedia.org/wiki/Magicland_Dizzy'),
  ('Q20995205', 'Top Gun is a shoot ''em up combat flight simulation game based on the 1986 film of the same name. It was developed and published by Konami for the Nintendo Entertainment System. It was released in North America in November 1987, Japan in December 1987, and then in Europe a year later. It is an adaptation of VS. Top Gun, a 1987 Nintendo VS. System arcade game also by Konami. As the second game to establish the Top Gun game series, it was followed by Top Gun: The Second Mission. It is known for its extremely high difficulty.', 'https://en.wikipedia.org/wiki/Top_Gun_(1987_video_game)'),
  ('Q21473303', 'Ghostbusters II is a 1990 action game for the NES, developed by Imagineering and published by Activision. It is based on the 1989 film of the same name, and was released in the United States in April 1990, followed by a United Kingdom release in March 1991.

In Europe and Japan, HAL Laboratory released its own Ghostbusters II game called New Ghostbusters II.', 'https://en.wikipedia.org/wiki/Ghostbusters_II_(NES_video_game)'),
  ('Q17494453', 'Disney''s Aladdin is a 1993 platform game developed by Virgin Games and published by Sega for the Genesis. It adapts the 1992 Walt Disney Animation Studios film Aladdin. Players control Aladdin as he navigates side-scrolling levels incorporating the film settings and scenarios.

Aladdin was the first Disney video game adaptation developed with Disney''s direct involvement. Disney, dissatisfied with the quality of previous adaptations, wanted to match Aladdin''s artistic quality. After canceling an initial attempt with BlueSky Software, Disney partnered with Virgin Games, with Sega handling marketing and distribution. Virgin developed digitization techniques to convert Disney''s hand-drawn animation to sprites and reproduce Aladdin''s style within the technical limits of 16-bit hardware.', 'https://en.wikipedia.org/wiki/Disney%27s_Aladdin_(Genesis_video_game)'),
  ('Q18907829', 'Double Dragon III: The Sacred Stones, released in Japan as Double Dragon III: The Rosetta Stone, is a 1991 beat ''em up video game developed by Technōs Japan for the Nintendo Entertainment System. It was the third Double Dragon game for the NES, and was published in North America and Europe by Acclaim Entertainment. Although it loosely based on the similarly titled arcade game Double Dragon 3: The Rosetta Stone, it is not a port, but a parallel project that was developed at the same time.', 'https://en.wikipedia.org/wiki/Double_Dragon_III:_The_Sacred_Stones'),
  ('Q20874773', 'Double Dragon II: The Revenge is a 1989 beat ''em up video game developed and published by Technōs Japan for the Nintendo Entertainment System. It is the second Double Dragon game for the NES, and was published in North America by Acclaim Entertainment, who took over publishing duties from Tradewest. Acclaim also published it in PAL regions.

The game shares its title with the 1988 arcade sequel to the original Double Dragon, using the same promotional artwork for its packaging and having a similar plot, but the content of the two games are otherwise drastically different. The NES version of Double Dragon II was directed by Hiroyuki Sekimoto (co-director of River City Ransom), with the arcade version''s director Yoshihisa Kishimoto taking a supervisory role in the game''s development.', 'https://en.wikipedia.org/wiki/Double_Dragon_II:_The_Revenge_(NES_video_game)'),
  ('Q21039932', 'Super Turrican is a 1992 run and gun video game developed by Rainbow Arts and published by Imagineer for the Nintendo Entertainment System. It is the third game in the Turrican series.', 'https://en.wikipedia.org/wiki/Super_Turrican_(1992_video_game)'),
  ('Q16205201', 'Where in Time Is Carmen Sandiego? is a multiplatform video game where players have to travel through time to collect clues and the warrants necessary to capture Carmen Sandiego or her henchmen. The goal is to track Carmen''s villains through history and arrest them and ultimately arrest Carmen.

Similar to the 1985 game Where in the World Is Carmen Sandiego?, the player plays as a secret agent for the ACME Detective Agency, and has to use research books to crack the clues given to them on which location (and time period) the crook went, and also decode the physical attributes or interests of the crook based on other clues. They must achieve these objectives in order to secure an arrest warrant, which allows them to identify the person at the end of the case as the crook. The player travels through time and space with a device known within the Carmen Sandiego universe as the Chronoskimmer. The game is time limited, and every action one takes uses up some of that time; the player needs to solve the case within the allotted time in order to be successful. As well as teaching the player about both geography and history it also provides practice with using a research book – a copy of the New American Desk Encyclopedia came with the game for assistance. The people, events, and inventions featured in the game hail from period in history ranging from 400 AD to the 1950s – the past 1500 years of human history. The game also comes with a 28-page instruction manual.', 'https://en.wikipedia.org/wiki/Where_in_Time_Is_Carmen_Sandiego%3F_(video_game)'),
  ('Q15111504', 'Spartan X 2 is a 1991 beat ''em up video game developed by Tamtex and published by Irem exclusively in Japan for the Family Computer. It is a sequel to Irem''s 1984 coin-operated video game Spartan X (released internationally by Data East under the title of Kung-Fu Master), which was later ported to the Family Computer by Nintendo in 1985. In turn, Spartan X was originally a tie-in to the 1984 Jackie Chan film Wheels on Meals (released as Spartan X in Japan).

It was originally planned to be released in North America as Kung Fu II in the fall of 1991, but ended up not being released there. Spartan X 2 did not receive a North American release until 2016, when it was included as a built-in title for the Retro-Bit Generations retro video game console under the name Kung-Fu Master 2.', 'https://en.wikipedia.org/wiki/Spartan_X_2'),
  ('Q16266784', 'NFL is a 1989 American football video game developed by Atlus and published by LJN for the Nintendo Entertainment System.', 'https://en.wikipedia.org/wiki/NFL_(video_game)'),
  ('Q15036792', 'Hudson Hawk is a platform game developed by Special FX Software for the Amstrad CPC, Amiga, Atari ST, Commodore 64 and ZX Spectrum based on the film of the same name. It was released in 1991 and published by Ocean Software. Sony Imagesoft released it in the US for the Game Boy and NES.

This was the final game completed by Special FX Software, before Ocean and Special FX Software broke apart.', 'https://en.wikipedia.org/wiki/Hudson_Hawk_(video_game)'),
  ('Q16266754', 'Utsurun Desu: Kawauso Hawaii e Iku!!! is a video game for the Nintendo Famicom based on the popular Japanese manga character from the 1980s "the otter man", Kawauso-kun from Sensya Yoshida''s series Uturun Desu. The game was published in 1992 by Takara.', 'https://en.wikipedia.org/wiki/Utsurun_Desu:_Kawauso_Hawaii_e_Iku!!!'),
  ('Q15036778', 'Mini-Putt is a simulation of miniature golf developed by Artech Digital Entertainment and released by Accolade for the Commodore 64, MS-DOS, Family Computer (Famicom) and ZX Spectrum in 1987, and Apple IIGS in 1988. A version for the Nintendo Entertainment System based on the Famicom port was planned to be published by JVC Musical Industries in North America with a release in 1992, but it ultimately did not materialize.', 'https://en.wikipedia.org/wiki/Mini-Putt_(video_game)'),
  ('Q16147744', 'Indiana Jones and the Temple of Doom is an action game released in 1988 for the Nintendo Entertainment System. The game is based on the 1985 arcade game and 1984 film of the same name. The resulting product differed from the arcade version in several aspects, but kept the same underlying premise and style.

The game was originally released by Mindscape in December 1988. The publishing rights reverted to Tengen the following year and it announced plans to re-release the game that October. Indiana Jones and the Temple of Doom gives the player control of Indiana Jones as he makes his way through the temple in a series of 12 levels or "waves". In the final wave, the player must defeat the villain of the film, Mola Ram, on a rope bridge that recreates the final scene in the movie. Reception of the game was generally negative.', 'https://en.wikipedia.org/wiki/Indiana_Jones_and_the_Temple_of_Doom_(1988_video_game)'),
  ('Q15036769', 'Shanghai is a 1986 mahjong solitaire video game developed and published by Activision. It has been released for the Amiga, Atari ST, Atari 8-bit computers, Commodore 64, MS-DOS, classic Mac OS, Apple IIGS, and Master System. Shanghai was originally programmed by Brodie Lockard. It was released as an arcade video game by Sunsoft in 1988, with Sunsoft releasing sequels under license from Activision.', 'https://en.wikipedia.org/wiki/Shanghai_(video_game)'),
  ('Q16163195', 'Nadia: The Secret of Blue Water is a Japan-exclusive multiplatform video game released from 1991 to 1993. It is based on the anime series Nadia: The Secret of Blue Water.', 'https://en.wikipedia.org/wiki/Nadia:_The_Secret_of_Blue_Water_(video_game)'),
  ('Q16266810', 'International Cricket is a cricket video game developed by Beam Software and released under their Laser Beam publishing arm for the Nintendo Entertainment System in 1992. Aussie Rules Footy shares the same presentation style as this game. Like Aussie Rules Footy, the game was distributed exclusively by Mattel''s Australian operation.

There were no attempts to release a cricket video game to the North American, Japanese, or European markets. The reason is that baseball games dominated the North American and Japanese markets, while football dominated the European market during that era. Two buttons are used to control the action; one for hitting the cricket ball while the other allows the player to slog around.', 'https://en.wikipedia.org/wiki/International_Cricket_(video_game)'),
  ('Q16259540', 'Flying Warriors is a 1991 action video game in the Hiryū no Ken series. It was developed and published by Culture Brain for the NES.', 'https://en.wikipedia.org/wiki/Flying_Warriors'),
  ('Q67198438', 'Pro Baseball: Family Stadium, released as Pro Yakyū: Family Stadium in Japan and R.B.I. Baseball in North America, is a 1986 baseball video game developed and published by Namco for the Family Computer console and Nintendo VS. System arcade unit. In North America, it was published by Tengen as R.B.I. Baseball for the Nintendo Entertainment System. It was also released in arcades through the Nintendo VS. System. It is the first game in the Family Stadium and R.B.I. Baseball franchises. The game was a critical and commercial success in Japan and North America.', 'https://en.wikipedia.org/wiki/Pro_Baseball:_Family_Stadium'),
  ('Q67387683', 'Tetris is a 1989 puzzle video game developed and published by Nintendo for the Nintendo Entertainment System (NES). Based on Tetris (1985) by Alexey Pajitnov, it was released after a legal battle between Nintendo and Atari Games, who had previously released a console port outside of the terms of their Tetris license. Bullet-Proof Software had previously released Tetris for the Family Computer in December 1988, while Nintendo had released Tetris for the Game Boy earlier in 1989.

Nintendo licensed exclusive home console rights for the Tetris intellectual property from Soviet authorities, leaving Atari Games unaware that they did not possess these rights from their own license. Being forced to quickly recall their version of Tetris for the NES was a major setback to Atari Games and their involved subsidiary Tengen. American reviewers held Nintendo''s version to be an inferior product to the recalled Atari Games version.', 'https://en.wikipedia.org/wiki/Tetris_(NES_video_game)'),
  ('Q28452235', 'Monopoly is a 1991 video game based on the board game of the same name, released on Game Boy, Sega Genesis, NES, and Super NES. Developed by Sculptured Software and published by Parker Brothers (the Game Boy version was published by Majesco), this title was one of many inspired by the property.

It is not to be confused with the 1993 Monopoly game, which was released in Japan only.', 'https://en.wikipedia.org/wiki/Monopoly_(1991_video_game)'),
  ('Q27017214', 'The Young Indiana Jones Chronicles is an action video game developed by Chris Gray Enterprises, Jaleco and published by Jaleco for the Nintendo Entertainment System (NES) in December 1992. It is based on the 1990s television series The Young Indiana Jones Chronicles.', 'https://en.wikipedia.org/wiki/The_Young_Indiana_Jones_Chronicles_(video_game)'),
  ('Q55522172', 'Jaleco Ltd. was a corporate brand name that was used by two previously connected video game developers and publishers based in Japan. The original Jaleco company was founded in 1974 as Japan Leisure Company, founded by Yoshiaki Kanazawa, before being renamed to simply Jaleco in the early 1980s. This company was later acquired in 2000 by Hong Kong company PCCW, who rebranded it as its Japanese game division, PCCW Japan, before reverting it to Jaleco in 2002. In 2006, Jaleco became independent from PCCW and renamed to Jaleco Holding, having its video game operations spun off into a new company, also called Jaleco. This new spin-off company was sold to mobile developer Game Yarou in 2009, with Jaleco Holding renaming itself to Encom Holdings shortly after.', 'https://en.wikipedia.org/wiki/Jaleco'),
  ('Q63865490', 'Zen: Intergalactic Ninja is a 1993 video game from Konami. The game is based on the fictional character of the same name.', 'https://en.wikipedia.org/wiki/Zen:_Intergalactic_Ninja_(video_game)'),
  ('Q28464434', 'Bomberman is an action video game developed and published by Hudson Soft for the Nintendo Entertainment System. Part of the Bomberman franchise, it was first released in Japan on December 20, 1985, and published in North America in January 1989. The player controls the titular character through maze-like levels. The objective is to reach the exit while fighting enemies and destroying blockade with bombs.

Bomberman is an enhanced port of an earlier computer game Bakudan Otoko (1983). Bomberman was programmed by Hudson director Shinichi Nakamoto, who saw potential in Bakudan Otoko and wanted to expand its formula for the console video game market. Bomberman retains the basic gameplay of its predecessor, but has many new elements not found in the original version, including a power-up system that allows the player to accumulate firepower by collecting items and a soundtrack composed by Jun Chikuma.', 'https://en.wikipedia.org/wiki/Bomberman_(1985_video_game)'),
  ('Q100152614', 'Family Feud is a video game series based on the Family Feud TV game show. It began with ShareData''s 1987 release on the Apple II and Commodore 64 consoles. In 1990, GameTek released a version on the Nintendo Entertainment System. GameTek later released four more Feud games for the Super NES, Sega Genesis, 3DO, and MS-DOS between 1993 and 1995. Hasbro Interactive, Global Star and Ubisoft have also released versions starting in 2000.', 'https://en.wikipedia.org/wiki/Family_Feud_(video_game_series)'),
  ('Q76912032', 'Terminator 2: Judgment Day is an action game released for several 8-bit consoles, including the Nintendo Entertainment System (NES) and Sega''s Game Gear and Master System. It is based on the 1991 film of the same name. The NES version was developed by Software Creations and published by LJN in February 1992. The Sega versions were published in late 1993 by Flying Edge.', 'https://en.wikipedia.org/wiki/Terminator_2_(8-bit_video_game)'),
  ('Q98545429', 'Justice Duel is a platform game developed and published by Mega Cat Studios. It was released on the Nintendo Entertainment System in 2017. Players battle one another while riding cybernetically enhanced eagles. The game plays similarly to Joust.', 'https://en.wikipedia.org/wiki/Justice_Duel'),
  ('Q97332611', 'Log Jammers is a sports video game published and developed by Mega Cat Studios. It was released on the Nintendo Entertainment System and is scheduled to be released for Microsoft Windows, PlayStation 4, Nintendo Switch, and Xbox One in 2020. The game features a lumberjack theme, silly humor, and fast-paced action in the style of arcade games. The objective of the game is to toss an axe past the opponent and into their goal. The game''s name is an allusion to Windjammers, which the developers cite as an inspiration. It also refers to a log jam, which relates to the games lumberjack theme, as well as the aquatic, log-based levels.', 'https://en.wikipedia.org/wiki/Log_Jammers'),
  ('Q105095027', 'Hollywood Squares is a quiz game based on the television game show Hollywood Squares. Versions were released for the Nintendo Entertainment System, MS-DOS, Commodore 64, and Apple II. The game is based on the 1986-1989 version hosted by John Davidson. The photo of the set is from the 1985 series pilot (the actual show had no gold stars on the studio floor and more elaborate risers for the cars).', 'https://en.wikipedia.org/wiki/Hollywood_Squares_(video_game)'),
  ('Q108884799', 'Warpman is a 1985 multidirectional shooter video game developed and published by Namco for the Family Computer. It is a sequel to the 1981 arcade game Warp & Warp. It was one of the last games to be programmed by Shouichi Fukatani, programmer of Dig Dug, who died during development. It was released outside Japan for the first time as part of Namco Museum Archives.', 'https://en.wikipedia.org/wiki/Warpman'),
  ('Q110670687', 'Itadaki Street: Watashi no Omise ni Yotte tte is a 1991 board game-themed video game developed by Login Soft and published by ASCII Corporation for the Family Computer. It is played with four players with any non-human players being controlled by the computer. The players roll a dice to move across the board and can purchase, invest as well as pay for goods at shops.

The game was designed by Yuji Horii, who was known for his work in the Dragon Quest video game series. The game was influenced by the board game Monopoly programmed predominantly by sole programmer Fukashi Omorita who spent three year developing the game. Omorita created the computer-controlled players personality based on the designed provided by illustrator Arai Kiyokazu.', 'https://en.wikipedia.org/wiki/Itadaki_Street_(1991_video_game)'),
  ('Q135013312', 'Streemerz is a retro-style fan remake of the platformer video game of the same name, originally released as part of the notorious Action 52 compilation for NES. It was developed by Arthur Lee, a.k.a. Mr. Podunkian, for the "Action 52 Owns" game jam he organized, released in 2010 for both NES and Flash. The main character, Streemerz operative Superb Joe (a parody of Super Joe) has placed an explosive device in the core of the flying fortress of the evil Master Y., and must escape to the top of the fortress solely using his grappling hook and the ability to walk back and forth. If he touches any of the glowing orbs in the level (dubbed "Master Y.''s balls"), the protagonist will perish. Additional threats include pie-throwing clown guards. The game was critically well-received for both its comedic story, which is purposely written in Engrish as a reference to poor NES localizations, and gameplay, and seen as a tremendous improvement compared to the source material.', 'https://en.wikipedia.org/wiki/Streemerz'),
  ('Q125963936', 'Dezaemon is a 1991 vertically scrolling shooter video game and game creation system developed and published by Athena for the Family Computer. It was released only in Japan on September 13, 1991. An enhanced version was released for the Super Famicom on September 20, 1994 and the PlayStation as Dezaemon Plus on May 24, 1996.

Despite its expensive price and entry barrier, the game has maintained a small but dedicated community of level creators, with new games such as Devil Blade Reboot being developed to this day. It is one of the earliest game creation systems easily accessible to console players, paving the way to similar systems such as Blast Works and Super Mario Maker. It was followed by a sequel, Dezaemon 2 for the Sega Saturn, as well as spin-offs, Dezaemon 3D for the Nintendo 64 and Dezaemon Kids! for the PlayStation.', 'https://en.wikipedia.org/wiki/Dezaemon'),
  ('Q54320', 'Star Wars is an action-platform video game based on the 1977 film of the same name. It was released by Victor Musical Industries for the Family Computer in Japan on November 15, 1991, and by JVC Musical Industries for the Nintendo Entertainment System in North America in November 1991, and in Europe on March 26, 1992. An official mail order "Hint Book" was available for the game upon its release.

Two versions for handheld game consoles were released. The Game Boy port was developed by NMS Software and published by Capcom, and released shortly less than a year later in 1992. The Game Gear port was developed by Tiertex and published by U.S. Gold, and released in 1993. A Master System version was also released, which was also developed by Tiertex. The game was followed by Star Wars: The Empire Strikes Back in 1992. An NES game adaptation of Return of the Jedi never came into fruition. A counterpart of the game for the Super NES, titled Super Star Wars, was released in 1992. On June 28, 2019, the NES and Game Boy versions of Star Wars were re-released as part of both standard and "Collector''s Edition" sets in limited quantities on unlicensed replica game cartridges by Limited Run Games.', 'https://en.wikipedia.org/wiki/Star_Wars_(1991_video_game)'),
  ('Q55532', '1942 is a 1984 vertically scrolling shooter video game developed and published by Capcom for arcades. Designed by Yoshiki Okamoto, it was the first game in the 194X series, and was followed by 1943: The Battle of Midway.

1942 is set in the Pacific Theater of World War II, and is loosely based on the Battle of Midway. Despite the game being created by Japanese developers, the goal is to reach Tokyo and destroy the Japanese air fleet. This was due to being the first Capcom game designed with Western markets in mind. It went on to be a commercial success in arcades, becoming Japan''s fifth highest-grossing table arcade game of 1986 and one of top five highest-grossing arcade conversion kits that year in the United States. It was ported to the Nintendo Entertainment System, selling over one million copies worldwide, along with other home systems.', 'https://en.wikipedia.org/wiki/1942_(video_game)'),
  ('Q54319', 'Star Wars is a Family Computer video game released in 1987 by Namco. It is the first platform game based on the Star Wars franchise. Despite being based on the first Star Wars film, some levels are based on the later two Star Wars films. It is one of only two games in the Star Wars franchise that were released exclusively in Japan, the other being Star Wars: Attack on the Death Star. The player controls Luke Skywalker as he travels to join the Rebellion against the Empire.

While domestically Star Wars was No. 99 out of the 100 top-selling Famicom games in 1987 according to Famicom Hisshōbon, the game is remembered abroad—often negatively—for its steep difficulty and bizarre deviations from the source material.', 'https://en.wikipedia.org/wiki/Star_Wars_(1987_video_game)'),
  ('Q27296', 'Bio Miracle Bokutte Upa is a Konami video game that was first released for a Japan-exclusive market in 1988 for the Family Computer Disk System. It was later released as a cartridge in 1993 for the Family Computer itself.

It was released on the Wii''s Virtual Console in 2008, for Japan and North America in June, and in Europe on August 29. It was released for the Nintendo 3DS''s and Wii U''s Virtual Console in Japan in February 2014 and July 2015, respectively. The Wii Virtual Console release was the only official release of the game outside Japan.', 'https://en.wikipedia.org/wiki/Bio_Miracle_Bokutte_Upa'),
  ('Q54329', 'Star Wars: The Empire Strikes Back is an action-platform game based on the 1980 film The Empire Strikes Back, released for the Nintendo Entertainment System in 1992. It is the sequel to the original Star Wars game released the previous year, also on the NES.

It is the second of three video games released under the Empire Strikes Back title that were developed directly for home video game systems. It was preceded by a version for the Atari 2600 and succeeded by Super Star Wars: The Empire Strikes Back for the Super NES.', 'https://en.wikipedia.org/wiki/Star_Wars:_The_Empire_Strikes_Back_(1992_video_game)'),
  ('Q11168', 'Super Mario Bros. is a 1985 platform game developed and published by Nintendo for the Nintendo Entertainment System (NES). Directed and produced by Shigeru Miyamoto, it is the successor to the 1983 arcade game Mario Bros. and the first game in the Super Mario series. Players control Mario, or his brother Luigi in the multiplayer mode, to traverse the Mushroom Kingdom to rescue Princess Toadstool from King Koopa (later named Bowser). They traverse side-scrolling stages while avoiding hazards such as enemies and pits and collecting power-ups such as the Super Mushroom, Fire Flower, and Starman.

Miyamoto and Takashi Tezuka designed Super Mario Bros. as a culmination of the team''s experience working on Devil World and the side-scrollers Excitebike and Kung Fu. Miyamoto wanted to create a more colorful platform game with a scrolling screen and larger characters. The team designed the first level, World 1-1, as a tutorial for platform gameplay. Koji Kondo''s soundtrack is one of the earliest in video games, making music a centerpiece of the design.', 'https://en.wikipedia.org/wiki/Super_Mario_Bros.'),
  ('Q12395', 'The Legend of Zelda is a 1986 action-adventure game developed and published by Nintendo for the Family Computer Disk System. It is the first game in the Legend of Zelda series. It is set in the fantasy land of Hyrule and centers on an elf-like boy named Link, who aims to collect the eight fragments of the Triforce of Wisdom to rescue Princess Zelda from Ganon. The player controls Link from a top-down perspective and navigates the overworld and dungeons, collecting weapons, defeating enemies and uncovering secrets. It was designed and directed by Shigeru Miyamoto and Takashi Tezuka, being in development alongside Super Mario Bros., which was released on September 13, 1985.', 'https://en.wikipedia.org/wiki/The_Legend_of_Zelda_(video_game)'),
  ('Q24170', 'Doki! Doki! Yūenchi: Crazy Land Daisakusen is a Nintendo Family Computer video game developed by KID and first released in 1991 by VAP. Its later European release for the Nintendo Entertainment System was called The Trolls in Crazyland, with its graphics and story adapted to feature the Troll doll characters, which were a very popular toy at that time.

The Japanese term Doki! Doki! is onomatopoeia for a beating heart, as a common expression referring to excitement.', 'https://en.wikipedia.org/wiki/Doki!_Doki!_Y%C5%ABenchi:_Crazy_Land_Daisakusen'),
  ('Q12384', 'Donkey Kong is a 1981 platform game developed and published by Nintendo for arcades. As Mario (occasionally referred to as "Jumpman" at the time), the player runs and jumps onto platforms and climbs ladders to ascend a construction site and rescue Pauline (occasionally referred to as "The Lady" at the time) from the giant gorilla Donkey Kong. It is the first game in the Donkey Kong series and Mario''s first appearance in a video game.

Donkey Kong was created to salvage unsold arcade cabinets following the failure of Nintendo''s Radar Scope (1980), and was designed for Nintendo of America''s audience. Hiroshi Yamauchi, Nintendo''s president at the time, assigned the project to first-time video game designer Shigeru Miyamoto. Drawing inspiration from "Beauty and the Beast" and American media such as Popeye and King Kong, Miyamoto developed the characters and scenario and designed the game alongside chief engineer Gunpei Yokoi. Donkey Kong was the most complex arcade game released at that point, using graphics for characterization, including cutscenes to illustrate a plot, and integrating multiple unique stages into the gameplay. The game pioneered the platform genre before the term existed, is the first to feature jumping, and is one of the first video games with a damsel in distress narrative, after Sheriff. It had a limited release in Japan on July 9, 1981, before receiving a wide release in the region some weeks later.', 'https://en.wikipedia.org/wiki/Donkey_Kong_(1981_video_game)'),
  ('Q55605', 'Boulder Dash is a maze-based puzzle video game released in 1984 by First Star Software for Atari 8-bit computers. It was created by Canadian developers Peter Liepa and Chris Gray. The player controls Rockford, who tunnels through dirt to collect diamonds. Boulders and other objects remain fixed until the dirt beneath them is removed, then they fall and become a hazard. Puzzles are designed around collecting diamonds without being crushed and exploiting the interactions between objects (such as a butterfly turning into diamonds when hit with a falling rock). The game''s name is a pun on balderdash.', 'https://en.wikipedia.org/wiki/Boulder_Dash_(video_game)'),
  ('Q55622', 'Bionic Commando, originally released as Hitler''s Resurrection: Top Secret in Japan, is a 1988 platform game developed and published by Capcom for the Nintendo Entertainment System. It is based on the 1987 arcade game Bionic Commando.

As Ladd, a member of the FF Battalion, the player explores each stage and obtains the necessary equipment to progress. Ladd is equipped with a mechanical arm featuring a grappling gun, allowing him to pull himself forward or swing from the ceiling. As such, the series is one of few instances of a platformer in which the player cannot jump. To cross gaps or climb ledges, Ladd must use his bionic arm.', 'https://en.wikipedia.org/wiki/Bionic_Commando_(1988_video_game)'),
  ('Q55535', '1943: The Battle of Midway is a 1987 vertically scrolling shooter video game developed and published by Capcom for arcades. It was the first follow-up to Capcom''s earlier 1942. Like 1942, the player controls Americans attacking the Japanese air fleet; this was due to being one of the first Capcom games designed with Western markets in mind. The game''s name is a reference to the Battle of Midway, which occurred in June 1942.', 'https://en.wikipedia.org/wiki/1943:_The_Battle_of_Midway'),
  ('Q55815', 'Elite is a space trading video game. It was written and developed by David Braben and Ian Bell and was originally published by Acornsoft for the BBC Micro computer in September 1984. Elite''s open-ended game model, and revolutionary 3D graphics led to it being ported to virtually every contemporary home computer system and earned it a place as a classic and a genre maker in gaming history. The game''s title derives from one of the player''s goals of raising their combat rating to the exalted heights of "Elite".

Elite was one of the first home computer games to use wire-frame 3D graphics with hidden-line removal. It added graphics and twitch gameplay aspects to the genre established by the 1974 game Star Trader. Another novelty was the inclusion of The Dark Wheel, a novella by Robert Holdstock which gave players insight into the moral and legal codes to which they might aspire.', 'https://en.wikipedia.org/wiki/Elite_(video_game)'),
  ('Q55610', 'Athena is a 1986 platform video game developed and published by SNK for arcades. Ports were later released for the NES console and ZX Spectrum and Commodore 64 home computers.

The game''s protagonist, Princess Athena, has gone on to appear in later fighting games by SNK as a secret character or assistant to her descendant Athena Asamiya, a prominent character in SNK''s titles.', 'https://en.wikipedia.org/wiki/Athena_(video_game)'),
  ('Q141379776', 'Hercules no Eikō II: Titan no Metsubō is a 1989 role-playing video game developed and published by Data East for the Family Computer. It is the second game of the Glory of Heracles series. It was one in numerous games that was acquired by Paon DP after Data East went bankrupt. It is noted for its tragic and dramatic storyline written by Kazushige Nojima, who would later be known for his work in Square Enix''s Final Fantasy series.

Though the game is set to take place directly after the events of the original Hercules no Eikō, the game''s plot creates several inconsistencies in the series timeline. The portable spinoff, Hercules no Eikō: Ugokidashita Kamigami, was released in 1992 to fill the gap between the two games.', 'https://en.wikipedia.org/wiki/Hercules_no_Eik%C5%8D_II:_Titan_no_Metsub%C5%8D'),
  ('Q11338868', 'Tetris 2 + BomBliss is a 1991 puzzle video game developed by Chunsoft and published by Bullet-Proof Software for the Family Computer. It is the final game Chunsoft developed for the Famicom.', 'https://en.wikipedia.org/wiki/Tetris_2_%2B_BomBliss'),
  ('Q5024016', 'Caltron 6 in 1 is a multicart developed and published in 1992 for the NES in North America by Caltron Industries, Inc. (credited as Caltron Ind. Inc.), a Taiwan-based video game company which was either closely related to, or simply a pseudonym for, NTDEC. In Australia, it was published under the title Real Player‘s Pak by HES. Dynacom released the cartridge as Multi Ação 6-in-1 for the Brazilian market. All the featured games, except Porter, were released as single game cartridges in Spain by Gluk Video.

As its title suggests, 6 in 1 consists of six different games in various genres, which mostly are popular clones of the era. It is composed of: Cosmos Cop, Adam & Eve, Magic Carpet 1001, Balloon Monster, Porter, and Bookyman. These titles were all previously released as stand-alone Famicom format by NTDEC, often under their U.S. brand Mega Soft.', 'https://en.wikipedia.org/wiki/Caltron_6_in_1'),
  ('Q3504227', 'The Nintendo Entertainment System has a library of 1370 officially licensed games released during their lifespans, plus 7 official multicarts and 2 championship cartridges. Of these, 672 were released exclusively in Japan, 187 were released exclusively in North America, and 19 were released exclusively in Phase Alternating Line (PAL) countries. Worldwide, 521 games were released.

Its launch games for the Famicom were Donkey Kong, Donkey Kong Jr., and Popeye. Only first-party titles were available upon launch, but Nintendo started a licensing program the following year that allowed third-party companies such as Namco, Hudson Soft, Taito, Konami, Bandai, and Capcom to create titles and produce their own cartridges for the Famicom in exchange for royalty payments; Nintendo later revised the program to mandate itself as the manufacturer of all cartridges while carrying it with the console outside Japan. The launch games for North America were: 10-Yard Fight, Baseball, Clu Clu Land, Duck Hunt, Excitebike, Golf, Gyromite, Hogan''s Alley, Ice Climber, Kung Fu, Pinball, Soccer, Stack-Up, Super Mario Bros., Tennis, Wild Gunman, and Wrecking Crew. The final licensed game released is the PAL-exclusive The Lion King on May 25, 1995.', 'https://en.wikipedia.org/wiki/List_of_Nintendo_Entertainment_System_games'),
  ('Q1989599', 'The Addams Family is a 1992 action-adventure platform game based on the 1991 film of the same name. Developed and published by Ocean Software, it was released for home consoles such as the Super Nintendo Entertainment System, computers such as the Amiga, and handheld consoles such as the Game Boy.

The player assumes the role of Gomez Addams. His mission is to rescue other members of the Addams family from the clutches of Abigail Craven, who, alongside The Judge and the family attorney Tully Alford, is attempting to seize the Addams'' wealth. The game is non-linear, with the player moving throughout the mansion''s many inside and outside areas, some of which are hidden. Enemies include bosses each holding a member of the Addams Family hostage, making them necessary to defeat. Power-ups, extra lives, and money are also obtainable.', 'https://en.wikipedia.org/wiki/The_Addams_Family_(video_game)'),
  ('Q1255124', 'DragonStrike is a 1990 flight simulator based on the Dungeons & Dragons fantasy tabletop role-playing game. It is set in the Dragonlance campaign setting.', 'https://en.wikipedia.org/wiki/DragonStrike_(video_game)'),
  ('Q388929', 'After Burner is a 1987 combat flight simulation video game developed by Studio 128 and published by Sega for arcades. The player controls an American F-14 Tomcat fighter jet and must clear each of the game''s 18 stages by destroying enemies. The plane is equipped with a machine gun and a limited supply of heat-seeking missiles. The game uses a third-person perspective, as in Sega''s earlier Space Harrier (1985) and Out Run (1986). It runs on the Sega X Board arcade system which is capable of surface and sprite rotation. It is the fourth Sega game to use a hydraulic "taikan" motion simulator arcade cabinet, one that is more elaborate than their earlier "taikan" simulator games. The cabinet simulates an aircraft cockpit, with flight stick controls, a chair with seatbelt, and hydraulic motion technology that moves, tilts, rolls and rotates the cockpit in sync with the on-screen action.', 'https://en.wikipedia.org/wiki/After_Burner'),
  ('Q4853816', 'Banana is a fixed screen puzzle video game produced by Victor Musical Industries that was released exclusively for the Family Computer in Japan in 1986.', 'https://en.wikipedia.org/wiki/Banana_(1986_video_game)'),
  ('Q3986143', 'The Bugs Bunny Crazy Castle, also known as simply Bugs Bunny, is a 1989 puzzle video game developed by Kemco for the Nintendo Entertainment System and Game Boy. It is the first puzzle game in Kemco''s Crazy Castle series.

Both the NES and Game Boy versions are Bugs Bunny reskins of Kemco''s Roger Rabbit for the Family Computer Disk System and Mickey Mouse for the Game Boy. The Bugs Bunny version would be released in Japan in 1997 through Bugs Bunny Collection, a Game Boy compilation containing this game and its 1991 sequel The Bugs Bunny Crazy Castle 2.

Each version of the game features different cartoon characters based on their respective titles: Bugs Bunny, Roger Rabbit, or Mickey Mouse. The object of the game is to go through a series of rooms collecting items to advance to higher levels while avoiding related cartoon characters.', 'https://en.wikipedia.org/wiki/The_Bugs_Bunny_Crazy_Castle'),
  ('Q948387', 'Captain America and the Avengers is a 1991 beat ''em up video game developed and published by Data East for arcades. It features the Avengers team of Marvel Comics characters in a side-scrolling brawling and shooting adventure to defeat the evil Red Skull. The game received ports for the Sega Genesis/Mega Drive, Super Nintendo Entertainment System, Game Boy and Game Gear. A different Data East game was released for the Nintendo Entertainment System.', 'https://en.wikipedia.org/wiki/Captain_America_and_The_Avengers'),
  ('Q2648118', 'Cosmo Police Galivan is a 1985 platform video game developed and published by Nichibutsu for arcades. The game is a homage to the Japanese tokusatsu shows Space Sheriff Gavan and Space Sheriff Sharivan. It was later ported to Commodore 64, Amstrad CPC, ZX Spectrum, and Famicom. The game spawned a sequel for the Super Nintendo Entertainment System called, Cosmo Police Galivan II: Arrow of Justice. Hamster Corporation acquired the rights to the game alongside Nichibutsu''s intellectual property; the company released the game as part of the Arcade Archives series for the PlayStation 4 in 2015 and Nintendo Switch in 2021.', 'https://en.wikipedia.org/wiki/Cosmo_Police_Galivan'),
  ('Q11435459', 'Daikaiju Deburasu is a 1990 strategy video game for the Family Computer. The game involves has a kaiju-movie theme, where the player assists the military in guiding a giant egg through a large city and then protecting it from a huge monster that rises from the sea.

The idea of the game developed when Hiromichi Nakamoto of Data East met Haruki Kamiya of Bandai met and developed the idea for the game. It was published by Data East and released on January 21, 1990. While it did not receive an official English release, the game received a partial fan translation in the 1990s and a full translation in 2023.', 'https://en.wikipedia.org/wiki/Daikaiju_Deburasu'),
  ('Q5223679', 'Darkman is a video game that was developed by Ocean Software (Painting By Numbers on the NES version, Twilight on the Commodore 64 and ZX Spectrum versions) and published by Ocean Software in 1991. It was released for the Amiga, ZX Spectrum, Amstrad CPC, Commodore 64 and Atari ST. Darkman had two different games of the same name, one for the Nintendo Entertainment System and the other for Game Boy. The game''s plot is loosely based on the film of the same name.', 'https://en.wikipedia.org/wiki/Darkman_(video_game)'),
  ('Q3061894', 'Savage Bees, released as Super Floating Fortress Exed Exes in Japan, is a 1985 vertically scrolling shooter video game developed and published by Capcom for arcades. It was released on the Family Computer by Tokuma Shoten the same year as simply Exed Exes.', 'https://en.wikipedia.org/wiki/Savage_Bees'),
  ('Q11332072', 'Family Circuit is a 1988 top-down racing video game developed by Game Studio and published by Namco for the Family Computer. The game was designed by Masanobu Endō, who previously developed Xevious and The Tower of Druaga, and his company Game Studio.

A sequel titled Family Circuit ''91 was released for the Family Computer in 1991.

Super Family Circuit was released for the Super Famicom on October 21, 1994.', 'https://en.wikipedia.org/wiki/Family_Circuit'),
  ('Q734758', 'Gauntlet is a 1985 dungeon crawl maze video game developed and published by Atari Games for arcades. It is one of the first multiplayer dungeon crawl arcade games. The core design of Gauntlet comes from the 1983 game Dandy for the Atari 8-bit computers, which resulted in a threat of legal action. It also has similarities to the 1983 maze game Time Bandit.

The arcade version of Gauntlet was released in October 1985, initially available only as a dedicated four-player cabinet. Atari distributed a total of 7,848 arcade units. In Japan, the game was released by Namco in February 1986. Atari later released a two-player cabinet variant in June 1986, aimed at operators who could not afford or did not have sufficient space for the four-player version.', 'https://en.wikipedia.org/wiki/Gauntlet_(1985_video_game)'),
  ('Q3101570', 'George Foreman''s KO Boxing is a sports video game produced by Acclaim, featuring boxer George Foreman, released in 1992. Three years later, Acclaim released another game with Foreman: Foreman For Real.', 'https://en.wikipedia.org/wiki/George_Foreman%27s_KO_Boxing'),
  ('Q3389134', 'Pirate Ship Higemaru is a 1984 maze video game developed and published by Capcom for arcades. The gameplay is similar to that of Sega''s 1982 game Pengo, but with the arctic theme replaced with that of a pirate ship.

The game was later included in the 1998 compilation Capcom Generations: The First Generation for the PlayStation (in Japan and Europe) and Sega Saturn (Japan only). Like the other games in the Capcom Generations titles, it was included in the 2005 compilation Capcom Classics Collection for the PlayStation 2 and Xbox, and in the PlayStation Portable version Capcom Classics Collection: Reloaded, which was the first time the game was released for home consoles in North America.', 'https://en.wikipedia.org/wiki/Pirate_Ship_Higemaru'),
  ('Q11403080', 'Hokkaido Rensa Satsujin: Ohotsuku ni Kiyu is a 1984 adventure game. The game has a mystery-theme where a man''s body is discovered floating in Tokyo Bay, and the ongoing investigation pulls various isolated story points into the reveal of the culprit.

The game was part of a trilogy of mystery games by Yuji Horii, with the first being The Portopia Serial Murder Case (1983) and the latter being Karuizawa Yūkai Annai (1985). Rather than having players type out their commands such as "Open the Window" as seen in the original version of The Portopia Serial Murder Case, players can choose menu options to select specific commands in Hokkaido Rensa Satsujin. The game was first released for the PC-6001 and PC-88 in December 1984 and for various other Japanese home computers in 1985. The game sold 15,000 copies across all home computer models.', 'https://en.wikipedia.org/wiki/Hokkaido_Rensa_Satsujin:_Ohotsuku_ni_Kiyu'),
  ('Q3140325', 'There have been several video games based on the 1991 film Hook. A side-scrolling platform game for the Nintendo Entertainment System and Game Boy was released in the United States in April 1992. Subsequent side-scrolling platform games were released for the Commodore 64 and Super NES and an arcade beat ‘em up by Irem later in 1992, followed by versions for the Sega CD, Genesis, and handheld Game Gear console in 1993.

A point-and-click graphic adventure, developed and published by Ocean Software, was released for Amiga, Atari ST, and MS-DOS in 1992.', 'https://en.wikipedia.org/wiki/Hook_(video_game)'),
  ('Q102315102', 'Infiltrator II (shown as Infiltrator Part II: The Next Day in-game and published as Infiltrator on the NES) is a video game developed by Chris Gray Enterprises and released in 1987 by Mindscape.', 'https://en.wikipedia.org/wiki/Infiltrator_II'),
  ('Q351926', 'Labyrinth: The Computer Game is a graphic adventure game developed by Lucasfilm Games and published in 1986 by Activision. Based on the fantasy film Labyrinth, it tasks the player with navigating a maze while solving puzzles and evading dangers. The player''s goal is to find and defeat the main antagonist, Jareth, within 13 real-time hours. Unlike other adventure games of the period, Labyrinth does not feature a command-line interface. Instead, the player uses two scrolling "word wheel" menus on the screen to construct basic sentences.

Labyrinth was the first adventure game created by Lucasfilm. The project was led by designer David Fox, who invented its word wheels to avoid the text parsers and syntax guessing typical of text-based adventure games. Early in development, the team collaborated with author Douglas Adams in a week-long series of brainstorming sessions, which inspired much of the final product. Labyrinth received positive reviews and, in the United States, was a bigger commercial success than the film upon which it was based. Its design influenced Lucasfilm''s subsequent adventure title, the critically acclaimed Maniac Mansion.', 'https://en.wikipedia.org/wiki/Labyrinth:_The_Computer_Game'),
  ('Q1665169', 'Uridium (released for the NES as The Last Starfighter) is a horizontally scrolling shooter designed by Andrew Braybrook for the Commodore 64 and published by Hewson Consultants in 1986. The game consists of fifteen levels, each named after a metal element, with the last level being the fictional metallic element Uridium. The manual quotes Robert Orchard, who invented the name, as saying "I really thought it existed".

Uridium was ported to the Amstrad CPC, Atari ST, BBC Micro, MS-DOS, and ZX Spectrum. A version was released for the Nintendo Entertainment System in 1990 by Mindscape. The company purchased a license based on the film The Last Starfighter, but decided to recycle an existing game. The title screen, sprites, and soundtrack were modified, but the levels and gameplay are identical.', 'https://en.wikipedia.org/wiki/Uridium'),
  ('Q2780270', 'Lethal Weapon is a video game based on the film series of the same name created by Shane Black. It was developed by Ocean Software and Eurocom. It was released in 1992 and 1993 by Ocean and Nintendo. It was released in conjunction with Lethal Weapon 3, the third installment of the series.', 'https://en.wikipedia.org/wiki/Lethal_Weapon_(video_game)'),
  ('Q3277744', 'Mah-Jong is a 1983 mahjong video game developed and published by Nintendo for the Family Computer. It was released on August 27, 1983 in Japan alongside Gomoku Narabe Renju. It was followed by a port to Nintendo VS. System arcades titled VS. Mah-Jong released in February 1984 as well as the Famicom Disk System on February 21, 1986. The game also released in Hong Kong sometime in 1987 for the Nintendo Entertainment System. It was followed by a series of sequels, beginning with 4 Nin Uchi Mahjong in 1984 for the Famicom.', 'https://en.wikipedia.org/wiki/Mah-Jong'),
  ('Q3303109', 'The Maze of Galious is a 1987 action-adventure game developed and published by Konami for the MSX home computer. A reworked conversion was released for the Family Computer. Both versions were re-released digitally for Microsoft Windows. The second entry in the Knightmare trilogy, it follows the respective hero and former damsel in distress of the previous game, Popolon and Aphrodite, as they embark on a journey through Castle Greek to free their unborn child Pampas from the evil priest Galious. The player explores each map in search for items and power-ups to progress, while also fighting enemies and bosses.', 'https://en.wikipedia.org/wiki/The_Maze_of_Galious'),
  ('Q10856189', 'Nobunaga''s Ambition II, released in Japan as Nobunaga''s Ambition: Sengoku Gunyuuden, is a 1988 strategy video game developed and published by Koei. It was released for several platforms such as IBM PC compatibles, Nintendo Entertainment System, PlayStation and Sega Saturn. It is the third game in the Nobunaga''s Ambition series.

Hamster Corporation released the NES version as part of their Console Archives series for the Nintendo Switch 2 and PlayStation 5 in September 2026.', 'https://en.wikipedia.org/wiki/Nobunaga%27s_Ambition_II'),
  ('Q4900082', 'Beyond the Black Hole is a computer game developed by The Software Toolworks and published in 1989 for the Commodore 64, Commodore 128, and MS-DOS, as well as for the Nintendo Entertainment System in 1990 under the name Orb-3D.', 'https://en.wikipedia.org/wiki/Beyond_the_Black_Hole_(video_game)'),
  ('Q99522908', 'RoboCop 3 is a video game based on the 1993 film of the same name. Amiga, Atari ST, and MS-DOS versions were developed by Digital Image Design and published by Ocean Software in December 1991. The Digital Image Design version includes multiple gameplay styles. During 1992 and 1993, other versions consisting of side-scrolling platform gameplay were released for the Commodore 64, ZX Spectrum, NES, Super NES, Game Gear, Master System, and Genesis.', 'https://en.wikipedia.org/wiki/RoboCop_3_(video_game)'),
  ('Q3440991', 'Romance of the Three Kingdoms, known as Sangokushi in Japan, is a turn-based strategy video game published in 1985 by Koei. It is the first game in the Romance of the Three Kingdoms series. Originally released on the PC-88, it was ported to numerous platforms, including the PC-98, MSX, Nintendo Entertainment System (1988), Amiga, MS-DOS, FM-7, Sharp X1, X68000, WonderSwan, and Windows (2003).', 'https://en.wikipedia.org/wiki/Romance_of_the_Three_Kingdoms_(video_game)'),
  ('Q3283029', 'Route-16 is a 1981 maze video game developed and published by Sun Electronics for arcades. The game was released by Tehkan (not yet a video game developer by its release) in Europe and Centuri in North America. It was ported to the Arcadia 2001 console. An enhanced version was released in Japan as Route-16 Turbo for the Famicom in 1985.', 'https://en.wikipedia.org/wiki/Route-16'),
  ('Q11269649', 'Sugoro Quest: Dice Heroes is a 1991 role-playing video game developed and published by Technōs Japan for the Family Computer. It was released on June 28, 1991 in Japan. In the game, four heroes set out to free a land that has been invaded by monsters. The game was released was re-released digitally for various Nintendo consoles and handhelds in Japan, it received an English-language for the Western market on February 7, 2025, for the Nintendo Switch, PlayStation 4, PlayStation 5, Xbox One, and Xbox Series X and Series S.

The gameplay in Sugoro Quest: Dice Heroes is based around role-playing video game mechanics such as turn-based battles involving using items, battling and magic, as well as talking with non-player characters, and player characters using characters with different strengths and weaknesses. The game is based on the Japanese board game sugoroku. Gameplay involves movement across the board, and the in-game battles are all controlled by rolling an in-game dice.', 'https://en.wikipedia.org/wiki/Sugoro_Quest:_Dice_Heroes'),
  ('Q1523333', 'Sweet Home is a 1989 role-playing video game developed and published by Capcom for the Family Computer. It was developed alongside the horror film Sweet Home, and tells the story of a team of five filmmakers exploring an old mansion in search of precious frescos hidden there. As they explore the mysterious mansion, they encounter hostile ghosts and other supernatural enemies. The player must navigate the intricately laid out mansion, battling with the enemies, and the five main characters with the limited weapons and health restorative items available. The narrative moves forward regardless of whether the characters stay alive, and leads to its five different endings.', 'https://en.wikipedia.org/wiki/Sweet_Home_(video_game)'),
  ('Q17212955', 'Tantei Jingūji Saburō: Yokohama-kō Renzoku Satsujin Jiken is a 1988 adventure video game developed and published by Data East for the Famicom. It was the second release in the Tantei Jingūji Saburō series, known as the Jake Hunter series in English territories.

On its release, it received positive reviews in Japanese video game magazines Famicom Tsūshin and Famicom Hisshoubon . It would be listed among the top ten best-selling Famicom games in Japan in April 1988, according to Famicom Tsūshin'' sales charts.

The game has since been re-released in compilations, digital forms and remade for feature phones.', 'https://en.wikipedia.org/wiki/Tantei_Jing%C5%ABji_Sabur%C5%8D:_Yokohama-k%C5%8D_Renzoku_Satsujin_Jiken'),
  ('Q7809721', 'Titan is a 1988 block breaker video game developed and published by Titus France.. It was converted to the Famicom in 1990 by SOFEL, before Naxat Soft then converted the game for the PC Engine in 1991.', 'https://en.wikipedia.org/wiki/Titan_(1988_video_game)'),
  ('Q60738895', 'Total Recall is a 1990 platform game developed and published by Ocean Software that was released for the Commodore 64, Amiga, Amstrad CPC, ZX Spectrum, Atari ST, and Nintendo Entertainment System. Total Recall is based on the 1990 film of the same name.', 'https://en.wikipedia.org/wiki/Total_Recall_(video_game)'),
  ('Q1886140', 'Wizardry: Proving Grounds of the Mad Overlord is the first game in the Wizardry series of role-playing video games. It was developed by Andrew C. Greenberg and Robert Woodhead. In 1980, Norman Sirotek formed Sir-Tech Software and launched a beta version of the product at the 1980 Boston Computer Convention. The final version of the game was released in 1981.

The game was one of the first Dungeons & Dragons-style role-playing games to be written for computer play, and the first such game to offer color graphics. It was also the first true party-based role-playing video game. It is now listed among the best video games of all time.', 'https://en.wikipedia.org/wiki/Wizardry:_Proving_Grounds_of_the_Mad_Overlord'),
  ('Q343608', 'Action 52 is an unlicensed multicart video game compilation developed by Active Enterprises for the Nintendo Entertainment System in 1992 and by FarSight Technologies for the Sega Genesis in 1993. It consists of 52 games in a variety of genres, mostly scrolling shooters and platformers. The games include The Cheetahmen, which was part of Active''s failed attempt to create a franchise similar to the Teenage Mutant Ninja Turtles. It initially retailed for the comparatively high price of US$199 (equivalent to $470 in 2025).

The NES version of Action 52 sold poorly and became infamous among gamers for the poor quality and functionality of its games; it is often considered to be one of the worst video games of all time. The Genesis version, although considered an improvement, was also negatively received. Many video game collectors value Action 52 for its notoriety and rarity.', 'https://en.wikipedia.org/wiki/Action_52'),
  ('Q1089369', 'The Adventures of Captain Comic is a platform game written by Michael Denio for MS-DOS compatible operating systems and released as shareware in 1988. It was one of the first side-scrolling games for IBM PC compatibles comparable to those on the Nintendo Entertainment System, and it presaged a trend of shareware platform games in the early 1990s. A version for the NES was later published by Color Dreams as an unlicensed title.

A sequel, Captain Comic II: Fractured Reality, was released in 1990.', 'https://en.wikipedia.org/wiki/The_Adventures_of_Captain_Comic'),
  ('Q940168', 'Chiller is a light gun arcade game released in 1986 by Exidy. An unlicensed port was released for the Nintendo Entertainment System in 1990 by American Game Cartridges in the US, and in Australia by HES (Home Entertainment Suppliers), with the option of using either the standard controller or the NES Zapper.

In the game, the player takes on the role of an unseen torturer who must maim, mutilate, and murder restrained non-player characters in a variety of dungeon settings.', 'https://en.wikipedia.org/wiki/Chiller_(video_game)'),
  ('Q2579468', 'Crystal Mines II is a puzzle video game developed by Color Dreams and published by Atari Corporation in 1992 for the Atari Lynx handheld console. The game is a sequel to Crystal Mines for the Nintendo Entertainment System. Both releases are similar to Boulder Dash, a genre which has since become known as "rocks and diamonds" games.', 'https://en.wikipedia.org/wiki/Crystal_Mines_II'),
  ('Q279938', 'Dizzy: Prince of the Yolkfolk is a 1991 adventure video game developed by Big Red Software and published by Codemasters for the Amstrad CPC, Atari ST, Commodore 64, ZX Spectrum, MS-DOS, NES and Amiga. It was the sixth game in the Dizzy adventure series. Initially it was only released as part of the Dizzy''s Excellent Adventures compilation. The creators of the series, the Oliver Twins, outsourced the video game company Big Red Software to design and develop the game. The game interface and mechanics resemble those of Magicland Dizzy, discarding changes introduced in the fifth game.

The game was enhanced and re-released in November 1992 with the Aladdin Deck Enhancer under the title Dizzy the Adventurer. The title was then released in 1993 as part of The Excellent Dizzy Collection. An HD remake of this game was released on the Android and iOS platforms in December 2011.', 'https://en.wikipedia.org/wiki/Dizzy:_Prince_of_the_Yolkfolk'),
  ('Q591978', 'Fantastic Dizzy (The Fantastic Adventures of Dizzy on NES) is a 1991 video game developed by Codemasters. It is part of the Dizzy series. It was published on several platforms, including Mega Drive/Genesis, Master System, Game Gear, Nintendo Entertainment System, Amiga, and MS-DOS.

The game was planned to be released in time for Christmas in 1990. However, because of a legal action between Codemasters and Nintendo over the Game Genie the title was released in April 1991; as a result, the game missed the Christmas rush it was originally slated for. It sold 125,000 units instead of the expected 500,000. The game was awarded the "NES Adventure Game of the Year 1991" by Game Players Magazine and given the Parents Choice Award. Almost all of puzzles are from the previous games. The game is one of the seven games released for the Aladdin Deck Enhancer.', 'https://en.wikipedia.org/wiki/Fantastic_Dizzy'),
  ('Q5516990', 'Gaiapolis is a 1993 action role-playing video game developed and released for arcades by Konami. The plot follows prince Gerard Himerce, whose country was destroyed by Mordred, an evil god summoned by the king Darkness of the Zah Harc empire. Gerard embarks on an adventure joined by the half-fairy Elaine Shee and the dragon archduke Galahad to exact revenge. Throughout the journey, the player explores searching for keys and items, fighting enemies and bosses to increase the character''s attributes.

Gaiapolis was created by the arcade division at Konami, in conjunction with Lethal Enforcers and Mystic Warriors. It was directed by Hiroyuki Ashida, who previously worked on Gradius II and Detana!! TwinBee. Animator Shūjirō Hamakawa, who also worked on Detana!! TwinBee, served as planner and character designer. Music and sound were produced by Satoko Miyawaki, Seiichi Fukami, and Yuji Takenouchi. The game was supplemented with a manga adaptation by Hamakawa and a two-CD album from King Records.', 'https://en.wikipedia.org/wiki/Gaiapolis'),
  ('Q887280', 'Kart Fighter is an unlicensed 2D fighting game produced for the Family Computer by Taiwanese studio Hummer Team. The game features unauthorized appearances by Nintendo''s mascot Mario and the rest of the cast of Super Mario Kart in a port of Street Fighter II. Kart Fighter has received some media attention, including mostly positive reviews, in part because of its perceived similarity to the later Super Smash Bros. series.', 'https://en.wikipedia.org/wiki/Kart_Fighter'),
  ('Q126194', 'Minesweeper is a logic puzzle video game genre generally played on personal computers. The game features a grid of clickable tiles, with hidden "mines" (depicted as naval mines in the original game) dispersed throughout the board. The objective is to clear the board without detonating any mines, using clues about the number of neighboring mines in each field.

The origin of Minesweeper is unclear. According to TechRadar, the first version of the game was 1990''s Microsoft Minesweeper, but Eurogamer states Mined-Out (1983) by Ian Andrew was the first Minesweeper game. Curt Johnson, the creator of Microsoft Minesweeper, acknowledges that his game''s design was borrowed from another game, but denies that it was Mined-Out.', 'https://en.wikipedia.org/wiki/Minesweeper_(video_game)'),
  ('Q15036953', 'Quattro is a series of video game compilations (each with four games) released in the 1990s. They consisted of games developed by Codemasters. The NES versions were released as multicarts and were published by Camerica without a license by Nintendo.', 'https://en.wikipedia.org/wiki/Quattro_compilations'),
  ('Q7339401', 'Road Runner is a racing video game based on the Wile E. Coyote and Road Runner shorts. It was released in arcades by Atari Games in 1985.', 'https://en.wikipedia.org/wiki/Road_Runner_(video_game)'),
  ('Q5094488', 'Chew Man Fu is a 1990 action video game developed by Now Production and published in Japan by Hudson Soft and in North America by NEC for the TurboGrafx-16.

Chew Man Fu was created by Now Production, an Osaka-based game development company founded in 1986 by Toshiaki Awamura, who would later work on future projects such as Adventure Island II and Rolling Thunder 3. First released on the TurboGrafx-16, the game has since been ported for mobile phones, with new visuals and level design, and re-released through digital platforms like the Virtual Console and the Japanese cloud gaming service G-cluster, in addition to being included on the PC Engine Mini console.', 'https://en.wikipedia.org/wiki/Chew_Man_Fu'),
  ('Q887292', 'Somari the Adventurer (commonly known as simply Somari is an unauthorized side-scrolling platform video game for the Family Computer. An unlicensed remake of Sega''s 1991 Sega Genesis/Mega Drive game Sonic the Hedgehog, the game was sold primarily around Asia, Russia, Eastern Europe, and other regions where bootleg NES and Famicom cartridges were distributed. Like the original, players venture to defeat the mad scientist Dr. Robotnik, who plots to turn the animal population of the fictional South Island into evil robots. Unlike the original, the game features Nintendo''s mascot Mario as the main character rather than Sonic. The title is a portmanteau of "Sonic" and "Mario".', 'https://en.wikipedia.org/wiki/Somari'),
  ('Q2405612', 'Spiritual Warfare is a 1992 Christian video game developed by Wisdom Tree for the Nintendo Entertainment System, it was later ported to MS-DOS, Game Boy, and Sega Genesis, and re-released as a part of the Spiritual Warfare & Wisdom Tree Collection in 2017 on Steam for Microsoft Windows, Mac OS X, and Linux. The game was not officially licensed by Nintendo for the NES, so it was mostly sold in Christian bookstores instead of traditional video game retailers.', 'https://en.wikipedia.org/wiki/Spiritual_Warfare_(video_game)'),
  ('Q853143', 'Super Mario World is a 1990 platform game developed and published by Nintendo for the Super Nintendo Entertainment System (SNES). It was released in Japan in 1990, in North America in 1991 and PAL territories in 1992. The player controls Mario on his quest to save Princess Peach and Dinosaur Land from the series'' antagonist Bowser and the Koopalings. The gameplay is similar to that of earlier Super Mario games; players control Mario through a series of levels in which the goal is to reach the goalpost at the end. Super Mario World introduces Yoshi, a rideable dinosaur who can eat enemies and spit some of them out as projectiles.', 'https://en.wikipedia.org/wiki/Super_Mario_World'),
  ('Q1276594', 'Pang, originally released in Japan as Pomping World and known in North America as Buster Bros., is a 1989 action game developed and published by Mitchell Corporation for arcades. It was released in North America by Capcom, which most of the developers had previously worked for. The basic gameplay is identical to a 1983 Japanese MSX computer game called Cannon Ball (also released in 1983 on the ZX Spectrum as Bubble Buster) by Hudson Soft.

In the game, players must finish a round-the-world quest to destroy bouncing balloons that are terrorising several of Earth''s landmarks and cities. The fight to save the Earth begins on Mount Fuji, Japan, where the players must pass all three stages before moving on to the next location.', 'https://en.wikipedia.org/wiki/Buster_Bros.');

insert into import_summary (wikidata_id, summary, source) values
  ('Q2257053', 'Super Buster Bros., released as Super Pang outside of North America, is a cooperative two-player shooting puzzle arcade video game developed by Mitchell and released in the United States in 1990 by Capcom. It is the second game in the Pang series and was ported to the Super Nintendo Entertainment System in 1992. It is also featured in the compilations Buster Bros. Collection for the original PlayStation and Capcom Puzzle World for PlayStation Portable.', 'https://en.wikipedia.org/wiki/Super_Buster_Bros.'),
  ('Q4050885', 'Tetris (stylized as TETЯIS) is a puzzle video game developed by Atari Games and originally released for arcades in February 1989. It is based on Alexey Pajitnov''s 1985 Tetris, and has the same gameplay as the computer editions. Players must stack differently shaped falling blocks to form and eliminate horizontal lines from the playing field. It has several difficulty levels and two-player simultaneous play.

In May 1989, a conversion of the arcade version was released for the Nintendo Entertainment System under Atari''s Tengen brand, which was not licensed by Nintendo. Issues arose with the publishing rights for Tetris, and after much legal wrangling, Nintendo gained the exclusive rights to publish console versions, leaving Atari with only the rights to arcade versions. As a result, the Tengen game was at retail for only four weeks, with fewer than 100,000 copies sold, until Atari was legally required to recall and destroy any remaining inventory of its NES version.', 'https://en.wikipedia.org/wiki/Tetris_(Atari_Games)'),
  ('Q16267247', 'Time Diver: Eon Man is a Nintendo Entertainment System video game developed by A.I. for Taito. Despite being completed in 1993, it was never commercially released. The game is completely finished, receiving a four-page strategy guide and review in issue 45 (February 1993) of Nintendo Power. Despite this, the game eventually disappeared from the Pak Watch section and was subsequently unproduced. Time Diver: Eon Man started life as a sequel to Wrath of the Black Manta, according to an interview the Game Developer Research Institute conducted with the game''s planner.', 'https://en.wikipedia.org/wiki/Time_Diver:_Eon_Man'),
  ('Q2829467', 'Aladdin is a 1993 platform game developed and published by Capcom for the Super Nintendo Entertainment System, based on the 1992 animated Disney film of the same name. Disney''s Aladdin is a 2D side-scrolling video game in which the player controls Aladdin and his monkey Abu. It was designed by Shinji Mikami.

The game was released in November 1993, the same month that another game with the same title was released by Virgin Games for the Sega Genesis. The two games vary in some respects; in the Genesis game, Aladdin wields a scimitar, which is not the case in the Capcom game. The Capcom game was ported to the Game Boy Advance (GBA) in Japan on August 1, 2003, in Europe on March 19, 2004, and in North America on September 28, 2004.', 'https://en.wikipedia.org/wiki/Disney%27s_Aladdin_(SNES_video_game)'),
  ('Q3141541', 'Bomberman ''94 is an action maze video game in the Bomberman series developed and published by Hudson Soft for the PC Engine and released on December 10, 1993, in Japan. It was later re-developed by Westone and re-published by Sega as Mega Bomberman on the Sega Mega Drive/Genesis in 1994 in other areas. The PC Engine Bomberman ''94 was later released outside Japan through the Virtual Console and the PlayStation Network.

The game supports single-player and multi-player modes. In single player, the player navigates several levels of mazes, destroying creatures with bombs. In multiplayer mode, players defeat each other with bombs.', 'https://en.wikipedia.org/wiki/Bomberman_%2794'),
  ('Q2910422', 'Boogerman: A Pick and Flick Adventure is a platform video game developed and published by Interplay Productions. It was released for the Sega Genesis in 1994 and on the Super NES in 1995. The Genesis version was also released on the Wii Virtual Console in North America on November 24, 2008, and in Europe on December 12, 2008. The game''s lead character also appears as a playable character and the rival of Earthworm Jim in Interplay''s ClayFighter 63⅓.', 'https://en.wikipedia.org/wiki/Boogerman:_A_Pick_and_Flick_Adventure'),
  ('Q1368099', 'Contra III: The Alien Wars is a 1992 run and gun video game developed and published by Konami for the Super Nintendo Entertainment System (SNES). It is the third home console entry in the Contra series after Contra (1988) and Super C (1990) for the Nintendo Entertainment System (NES). In PAL regions, it was retitled Super Probotector: Alien Rebels and the player characters were replaced with robots. The player is tasked with fighting off an alien invasion of Earth across six stages. Four stages feature side-scrolling action traditional to the series while two are presented from an overhead perspective. It is the first Contra title to have been directed by Nobuya Nakazato who later directed other games in the series. He designed Contra III to feature more comical elements, a more cinematic soundtrack, and tighter stage design than its predecessors.', 'https://en.wikipedia.org/wiki/Contra_III:_The_Alien_Wars'),
  ('Q518987', 'Donkey Kong Country, known in Japan as Super Donkey Kong, is a 1994 platform game developed by Rare and published by Nintendo for the Super Nintendo Entertainment System (SNES). It follows the gorilla Donkey Kong and his nephew Diddy Kong as they set out to recover their stolen banana hoard from the crocodile King K. Rool and his army, the Kremlings. The player traverses 40 side-scrolling levels as it jump between platforms and avoid obstacles. It collect items, ride minecarts and animals, defeat enemies and bosses, and find secret bonus stages. In multiplayer modes, two players work cooperatively or race.', 'https://en.wikipedia.org/wiki/Donkey_Kong_Country'),
  ('Q2358727', 'Dragon: The Bruce Lee Story is a fighting video game developed and originally published by Virgin Interactive Entertainment in Europe for the Sega Genesis in 1994. It is based on the 1993 film of the same name, which is a semi-fictionalized account of the life of Hong Kong-American actor and martial artist Bruce Lee. Following the events of the movie, players take control of Bruce Lee across several stages that takes places in different time periods of his life and fight against some of his adversaries.

Initially released for Sega platforms, Dragon: The Bruce Lee Story was later ported to the Atari Jaguar and Super Nintendo Entertainment System, each one featuring several changes and additions compared with the original version while both the Game Gear and Master System versions, which were released in 1995, feature an entirely different gameplay format.', 'https://en.wikipedia.org/wiki/Dragon:_The_Bruce_Lee_Story_(video_game)'),
  ('Q727139', 'Earthworm Jim is a 1994 run and gun video game developed by Shiny Entertainment and published by Playmates Interactive Entertainment. The game was released for the Sega Genesis and Super Nintendo Entertainment System, before being subsequently ported to several other video game consoles.

It had a positive reception from critics and received a sequel, Earthworm Jim 2, in 1995. In 2009, Gameloft developed and released a remake for mobile phones and Nintendo DSi which was later ported to PlayStation 3 and Xbox 360 as Earthworm Jim HD. In February 2018, Gameloft''s contract with Interplay ended and all of the ports developed by Gameloft were removed from digital stores.', 'https://en.wikipedia.org/wiki/Earthworm_Jim_(video_game)'),
  ('Q2601047', 'Final Fight 3, released in Japan as Final Fight Tough, is a 1995 beat ''em up video game developed and published by Capcom for the Super Nintendo Entertainment System. It is the second sequel to Final Fight released for the Super NES, following Final Fight 2. Like its predecessor, it was produced by Capcom''s consumer division with no preceding arcade version released.

The game features the return of the protagonist Guy along with Haggar and also introduces new characters Lucia and Dean. The game''s plot takes them through their efforts to rid Metro City of the new Skull Cross gang. Final Fight 3 introduced new moves, as well as branching paths during gameplay and multiple endings. Also available is the option to fight alongside a CPU-controlled partner. However, most critics felt these changes did too little in the way of expanding and improving upon the original Final Fight, and the game was released to little fanfare.', 'https://en.wikipedia.org/wiki/Final_Fight_3'),
  ('Q1074369', 'Fatal Fury Special is a 1993 fighting game developed and published by SNK for the Neo Geo arcade and home platforms. The third installment of the Fatal Fury series, it is an updated version of Fatal Fury 2 (1992), adding four CPU-only bosses as playable characters, featuring three characters from its predecessor, and introducing combos while further balancing the gameplay. In addition, it featured Ryo Sakazaki as a secret boss character at the end of the single-player mode; the inclusion of Ryo inspired SNK to create The King of Fighters series.', 'https://en.wikipedia.org/wiki/Fatal_Fury_Special'),
  ('Q2747904', 'Mighty Morphin Power Rangers is the title of five different video games based on the first season of the television series of the same name, one for each of the following game platforms: Sega Genesis, Super Nintendo Entertainment System, Game Boy, and Game Gear. The Nintendo versions of the game were released by Bandai, while the Sega versions were published by Sega itself and the production of the cartridge versions was carried by Banpresto, a pseudonym of Bandai. Despite the character''s popularity and being a regular cast member by 1994, for unknown reasons, Tommy, the Green Ranger is only playable on the Genesis and Game Gear versions of the game.', 'https://en.wikipedia.org/wiki/Mighty_Morphin_Power_Rangers_(video_game)'),
  ('Q150294', 'Mortal Kombat is a 1992 fighting game developed and published by Midway for arcades. It is the first main installment in the Mortal Kombat franchise, and was subsequently released by Acclaim Entertainment for nearly every home platform of the time. The game presents a martial arts tournament in which ten characters (including a choice of seven player characters) contend with the fate of Earth at stake. It introduced many key aspects of the Mortal Kombat series, including the unique five-button control scheme and gory finishing moves called Fatalities.

Mortal Kombat is considered by critics to be one of the greatest video games ever made. It spawned numerous sequels and spin-offs, beginning with Mortal Kombat II in 1993. Both games were the subject of a film adaptation in 1995. However, it also sparked much controversy for its depiction of extreme violence and gore using realistic digitized graphics and, along with the home releases of Night Trap and Lethal Enforcers, prompted the formation of the Entertainment Software Rating Board (ESRB), a U.S. government-backed organization that set descriptor ratings for video games.', 'https://en.wikipedia.org/wiki/Mortal_Kombat_(1992_video_game)'),
  ('Q3392932', 'Pocahontas is a 1996 platform game based on the 1995 animated film of the same name. The Genesis / Mega Drive version was developed by Funcom on contract with Disney and was released in March 1996. It was followed by a later version for the Game Boy developed by Tiertex Design Studios and released on June 10, 1996, nearly a year after the film''s premiere. A Super Nintendo Entertainment System version of the game was under development, but was canceled due to development being too far behind to coincide with the Genesis release.', 'https://en.wikipedia.org/wiki/Disney%27s_Pocahontas_(video_game)'),
  ('Q5575485', 'Street Fighter II: Champion Edition, released as Street Fighter II Dash (stylized as Street Fighter II′ with a prime symbol) in Japan, is a 1992 fighting game developed and published by Capcom for arcades. It is the first of several updated versions of Street Fighter II: The World Warrior (1991), and part of the Street Fighter series. The main changes are the addition of the four grand masters (the final four computer-controlled opponents in the single-player mode) as playable characters and mirror matches. The fighting techniques of the eight main characters from the original game were further balanced for competitive play.', 'https://en.wikipedia.org/wiki/Street_Fighter_II:_Champion_Edition'),
  ('Q2638825', 'Shinobi III: Return of the Ninja Master, released in Japan as The Super Shinobi II, is a 1993 hack and slash platform game developed and published by Sega for the Sega Genesis. It is the direct sequel to the previous The Revenge of Shinobi. Shinobi III received critical acclaim and has been ranked among the greatest Genesis games.', 'https://en.wikipedia.org/wiki/Shinobi_III:_Return_of_the_Ninja_Master'),
  ('Q4051517', 'Tiny Toon Adventures: Babs'' Big Break is a 1992 platformer video game for the Game Boy. It is based on the animated series Tiny Toon Adventures which had debuted in 1990. The game features the character Babs Bunny who sets out to Acme Theatre to become a big star. Unknown to Babs, Montana Max plans to demolish the theatre, which leads Buster Bunny, Plucky Duck and Hamton J. Pig to keep after her and make sure she does not get into any trouble.

The game was developed and published by Konami, and was one of the many games the company had based on the series. On its release, it received reviews that complimented its graphics. A number of reviews found the game too slow paced or that it may have been a bit too easy.', 'https://en.wikipedia.org/wiki/Tiny_Toon_Adventures:_Babs%27_Big_Break'),
  ('Q4020896', 'World Heroes 2 is a 1993 fighting video game developed by ADK and published by SNK for the Neo Geo arcade and home platforms. It is the sequel to the 1992 fighting arcade game World Heroes, as well as the second title of the World Heroes series. It was the first game with the ADK logo labeled within the game after the developer changed from its previous name Alpha Denshi; however, the "Alpha" logo was last used on one of the arcade flyers of World Heroes 2.

It was followed by a sequel released a year later, titled World Heroes 2 Jet.', 'https://en.wikipedia.org/wiki/World_Heroes_2'),
  ('Q2892913', 'Beat ''Em and Eat ''Em is a pornographic video game for the Atari 2600 made by American Multiple Industries in 1982. Players control two nude women; the goal is to catch semen in their mouths, which is falling from a masturbating man on a rooftop, without missing. Its gameplay has been compared to the Atari game Kaboom!. There is also a gender-reversed version of the game titled Philly Flasher that features identical gameplay. Beat ''Em & Eat ''Em has received negative reviews since its release and is an oft-cited example of pornographic Atari 2600 games.', 'https://en.wikipedia.org/wiki/Beat_%27Em_%26_Eat_%27Em'),
  ('Q1060323', 'The Legend of Zelda: Link''s Awakening is a 1993 action-adventure game developed and published by Nintendo for the Game Boy. It is the first installment in The Legend of Zelda series to be released on a handheld game console. Link''s Awakening is one of the few Zelda games not to take place in the land of Hyrule, and it does not feature Princess Zelda or the Triforce relic. Instead, the protagonist Link begins the game stranded on Koholint Island, a place guarded by a whale-like deity called the Wind Fish. Assuming the role of Link, the player fights monsters and solves puzzles while searching for eight musical instruments that will awaken the sleeping Wind Fish and allow him to escape from the island.', 'https://en.wikipedia.org/wiki/The_Legend_of_Zelda:_Link%27s_Awakening'),
  ('Q2647594', 'Final Fantasy VII is an unlicensed "Shanzhai" demake of SquareSoft''s role-playing video game Final Fantasy VII, originally released for PlayStation in 1997. The two-dimensional "port" was developed and published by Chinese company Shenzhen Nanjing Technology for Subor, a Famiclone. The cartridge itself is unique, as it is structurally different from licensed Famicom cartridges in terms of hardware and programming.

The title features many gameplay elements of the original counterpart, including a three-member party structure and adaptations of the game''s subsystems. Items, spells and equipment available to the player are based upon those in the original game, and although a large number have been omitted along with optional characters and some side quests, the original story was reproduced in very minute detail. Its reception was mixed, cited as an impressive achievement but at the same time criticized for the difficulty and choice of a target console.', 'https://en.wikipedia.org/wiki/Final_Fantasy_VII_(NES_video_game)'),
  ('Q104878190', 'Micro Mages is a platform game for the Nintendo Entertainment System that was published on April 30, 2019 by Morphcat Games. The game raised over €150,000 on Kickstarter. The game was published as a physical cartridge for the NES, and later as a digital download, bundled with an emulator, on Steam and Itch.io.', 'https://en.wikipedia.org/wiki/Micro_Mages'),
  ('Q474798', 'The Legend of Zelda: The Minish Cap is a 2004 action-adventure game developed by Capcom and Flagship and published by Nintendo for the Game Boy Advance. The twelfth entry in The Legend of Zelda series, The Minish Cap was released for the Game Boy Advance in Japan and Europe in 2004 and in North America and Australia the following year.

The Minish Cap serves as a prequel to Four Swords, telling the origins of the titular Four Sword and the villain Vaati. The game retains many elements common to previous Zelda games, especially top-down predecessors such as A Link to the Past, and includes new features and mechanics. Chiefly, the protagonist Link acquires a magical talking cap named Ezlo, who can shrink Link to the diminutive size of a Minish.', 'https://en.wikipedia.org/wiki/The_Legend_of_Zelda:_The_Minish_Cap'),
  ('Q23911', 'Magicland Dizzy is a 1990 platform adventure game developed by Big Red Software and published by Codemasters for the Amstrad CPC, ZX Spectrum, Commodore 64, Atari ST and Amiga platforms and initially only available as part of The Dizzy Collection. By 1992 the game was sold by itself and an MS-DOS version was available. It is the sixth game in the Dizzy series, and the fourth adventure-based Dizzy title. The story, set in a fantasy world called Magicland, follows on from the events of Fantasy World Dizzy, the previous adventure title. In Magicland Dizzy the player controls Dizzy, an egg-shaped character, who is trying to save six of his friends who have been placed under spells by the Evil Wizard Zaks.', 'https://en.wikipedia.org/wiki/Magicland_Dizzy'),
  ('Q370055', 'The Legend of Zelda: A Link to the Past is a 1991 action-adventure game developed and published by Nintendo for the Super Nintendo Entertainment System (SNES). It is the third game in The Legend of Zelda series, following Zelda II: The Adventure of Link (1987). It was released in Japan in 1991, and in North America and Europe in 1992.

The story is set many years before the events of the first two Zelda games. The player assumes the role of Link as he journeys to save Hyrule, defeat the Demon King Ganon, and rescue the descendants of the Seven Sages. It returns to a top-down perspective similar to the original The Legend of Zelda, dropping the side-scrolling gameplay of The Adventure of Link. It also introduced series staples such as parallel worlds and items including the Master Sword.', 'https://en.wikipedia.org/wiki/The_Legend_of_Zelda:_A_Link_to_the_Past');

update public.game g
set summary_en = i.summary, summary_en_source = i.source
from import_summary i
where g.wikidata_id = i.wikidata_id
  and g.summary_en is null;

drop table import_summary;
